// Leviathan Spine: the skeleton of a colossal sky creature lying across rooms (4..9, 1..2)
// under an aurora. One shared world; this room samples it at its grid offset.
const GOFF: vec3f = vec3f(84.0, 0.0, 24.0);
const AUR_A: vec3f = vec3f(0.16, 1.0, 0.58);
const AUR_B: vec3f = vec3f(0.5, 0.34, 1.0);
const HORIZON: vec3f = vec3f(0.03, 0.045, 0.1);
const BONE: vec3f = vec3f(0.97, 0.86, 0.64);

fn breath() -> f32 { return 0.5 + 0.5 * sin(time() * 0.75); }

fn sd_cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

fn sd_ell(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / max(k1, 1e-4);
}

// Spine path in the xz plane: tail tip (46,28) north to (46,20), quarter arc to (54,12), then east to the skull at x=104.
// Returns (u along the spine from the tail tip, signed lateral offset).
fn spine_frame(w: vec2f) -> vec2f {
    if (w.x >= 54.0) { return vec2f(20.566 + (w.x - 54.0), w.y - 12.0); }
    if (w.y <= 20.0) {
        let d = w - vec2f(54.0, 20.0);
        var a = atan2(d.y, d.x);
        if (a < 0.0) { a = a + TAU; }
        a = clamp(a, PI, 1.5 * PI);
        return vec2f(8.0 + 8.0 * (a - PI), length(d) - 8.0);
    }
    return vec2f(28.0 - w.y, w.x - 46.0);
}

fn spine_h(u: f32) -> f32 {
    return mix(0.72, 2.4, smoothstep(0.0, 22.0, u)) + 0.07 * sin(u * 0.31 - time() * 0.75) - 0.15 * smoothstep(64.0, 71.0, u);
}

fn spine_s(u: f32) -> f32 {
    return mix(0.33, 1.0, smoothstep(0.0, 30.0, u)) * (1.0 + 0.04 * breath());
}

fn vert_q(w: vec3f, f: vec2f) -> vec4f {
    let k = clamp(round(f.x / 0.8), 1.0, 88.0);
    let uk = k * 0.8;
    return vec4f(f.x - uk, w.y - spine_h(uk), f.y, uk);
}

fn vertebrae(w: vec3f, f: vec2f) -> f32 {
    let bound = abs(f.y) - 1.4;
    if (bound > 0.4) { return bound; }
    let vq = vert_q(w, f);
    let s = spine_s(vq.w);
    let q = vq.xyz;
    let r = 0.27 * s + 0.03;
    let dc = vec2f(length(q.yz) - r, abs(q.x) - 0.29);
    let cent = min(max(dc.x, dc.y), 0.0) + length(max(dc, vec2f(0.0))) - 0.04;
    let ns = sd_box(vec3f(q.x + 0.28 * (q.y - 0.3 * s), q.y - 0.6 * s, q.z), vec3f(0.05 + 0.04 * s, 0.48 * s, 0.045)) - 0.025;
    let tp = sd_box(vec3f(q.x, q.y + 0.04 + 0.1 * q.z * q.z, q.z), vec3f(0.055, 0.045, 0.66 * s)) - 0.02;
    let hm = sd_box(vec3f(q.x, q.y + 0.42 * s, q.z), vec3f(0.04, 0.2 * s, 0.035));
    return smin(cent, min(min(ns, tp), hm), 0.07);
}

fn ribs(w: vec3f, f: vec2f) -> f32 {
    let bx = max(57.0 - w.x, w.x - 103.0);
    if (bx > 0.3) { return bx; }
    let xk = clamp(0.75 + 1.5 * round((w.x - 0.75) / 1.5), 57.75, 102.75);
    let dx = w.x - xk;
    let sr = (0.7 + 0.3 * smoothstep(57.0, 74.0, xk)) * (1.0 - 0.28 * smoothstep(93.0, 103.0, xk));
    let br = 0.5 + 0.5 * sin(time() * 0.75 - xk * 0.06);
    let a = (4.45 + 0.4 * br) * sr;
    let b = 2.8 * mix(0.92, 1.0, sr);
    let q2 = vec2f(f.y, w.y + 0.32);
    let k0 = length(q2 / vec2f(a, b));
    let k1 = length(q2 / vec2f(a * a, b * b));
    let de = k0 * (k0 - 1.0) / max(k1, 1e-4);
    let th = mix(0.06, 0.13, clamp(w.y / 2.3, 0.0, 1.0));
    return max(length(vec2f(de, dx * 1.25)) - th, -w.y - 0.05);
}

fn skull(w: vec3f) -> f32 {
    let p = w - vec3f(108.0, 0.0, 12.0);
    let bb = sd_box(p - vec3f(0.0, 2.0, 0.0), vec3f(6.4, 2.1, 2.6));
    if (bb > 0.4) { return bb; }
    let pz = vec3f(p.x, p.y, abs(p.z));
    let cran = sd_ell(p - vec3f(-2.6, 2.25, 0.0), vec3f(2.3, 1.25, 1.75));
    let ros = sd_ell(p - vec3f(1.9, 1.95, 0.0), vec3f(4.3, 0.42, 0.98));
    var d = smin(cran, ros, 0.5);
    let eye = sd_sphere(pz - vec3f(-1.5, 2.45, 1.45), 0.62);
    d = max(d, -eye);
    let nost = sd_ell(pz - vec3f(-0.9, 2.4, 0.35), vec3f(0.6, 0.3, 0.18));
    d = max(d, -nost);
    let jaw = sd_cap(pz, vec3f(-4.1, 1.45, 1.15), vec3f(5.9, 0.16, 0.5), 0.16);
    d = min(d, jaw);
    if (p.x > -0.6 && p.x < 5.6) {
        let c = p.x - 0.32 * round(p.x / 0.32);
        let wdt = 0.9 * sqrt(max(1.0 - pow((p.x - 1.9) / 4.3, 2.0), 0.0));
        let tooth = sd_cap(vec3f(c, p.y, abs(p.z)), vec3f(0.0, 1.75, wdt * 0.8), vec3f(0.0, 1.32, wdt * 0.72), 0.035);
        d = min(d, tooth);
    }
    return d;
}

fn fin(w: vec3f) -> f32 {
    let bb = sd_box(w - vec3f(84.0, 1.2, 21.0), vec3f(4.5, 1.4, 8.5));
    if (bb > 0.4) { return bb; }
    let br = breath();
    var d = sd_cap(w, vec3f(84.0, 2.1, 13.2), vec3f(84.0, 0.62, 19.6), 0.24);
    d = smin(d, sd_sphere(w - vec3f(84.0, 0.62, 19.6), 0.36), 0.15);
    let wz = vec3f(abs(w.x - 84.0), w.y, w.z);
    d = min(d, sd_cap(wz, vec3f(0.28, 0.58, 19.8), vec3f(0.36, 0.32, 22.5), 0.15));
    for (var i = 0; i < 5; i = i + 1) {
        let fi = f32(i) - 2.0;
        let ang = fi * (0.3 + 0.05 * br);
        let dir = vec3f(sin(ang), 0.0, cos(ang));
        let base = vec3f(84.0 + fi * 0.28, 0.3, 22.6);
        let len = 5.5 - 0.55 * abs(fi);
        for (var j = 0; j < 4; j = j + 1) {
            let fj = f32(j);
            let a = base + dir * len * fj * 0.25 + vec3f(0.0, 0.06 * fj, 0.0);
            let b = base + dir * len * (fj + 0.88) * 0.25 + vec3f(0.0, 0.06 * fj, 0.0);
            let r = 0.12 * (1.0 - 0.17 * fj);
            d = min(d, sd_cap(w, a, b, r));
        }
    }
    return d;
}

fn fluke(w: vec3f) -> f32 {
    let bb = sd_box(w - vec3f(46.0, 0.5, 28.6), vec3f(3.2, 0.7, 1.6));
    if (bb > 0.4) { return bb; }
    let base = vec3f(46.0, 0.42, 28.15);
    var d = 1e3;
    for (var i = 0; i < 9; i = i + 1) {
        let t = (f32(i) - 4.0) / 4.0;
        let ang = t * 1.45;
        let len = 1.5 + 1.25 * abs(t);
        let dir = vec3f(sin(ang), 0.06, cos(ang) * 0.75);
        d = min(d, sd_cap(w, base, base + dir * len, 0.07 - 0.02 * abs(t)));
    }
    return d;
}

// Fallen ribs half-buried in the snow of the southern rooms.
fn fallen(w: vec3f) -> f32 {
    let cell = floor(w.xz / 12.0 + 0.5);
    if (cell.y < 1.5 || cell.x < 4.5) { return 1e3; }
    let cc = vec3f(cell.x * 12.0, 0.0, cell.y * 12.0);
    var d = 1e3;
    for (var i = 0; i < 3; i = i + 1) {
        let h = hash33(vec3f(cell, f32(i) * 7.13));
        if (cell.x > 6.5 && cell.x < 7.5 && i > 0) { break; }
        let R = 1.8 + 1.5 * h.z;
        let c = cc + vec3f((h.x - 0.5) * 6.0 + select(-2.6, 2.6, h.x > 0.5), -R * 0.38, (h.y - 0.5) * 5.0);
        var p = w - c;
        let rx = rot2(h.x * 5.0 + h.y * 3.0) * p.xz;
        p = vec3f(rx.x, p.y, rx.y);
        let q = vec2f(length(p.xy) - R, p.z);
        d = min(d, length(q * vec2f(1.0, 0.8)) - 0.1 - 0.04 * h.y);
    }
    return d;
}

fn map(w: vec3f) -> f32 {
    let f = spine_frame(w.xz);
    var d = vertebrae(w, f);
    d = min(d, ribs(w, f));
    d = min(d, skull(w));
    d = min(d, fin(w));
    d = min(d, fluke(w));
    d = min(d, fallen(w));
    return d;
}

fn aur_tint(w: vec3f) -> vec3f {
    return mix(AUR_A, AUR_B, 0.5 + 0.5 * sin(w.x * 0.045 + w.z * 0.03 + time() * 0.12));
}

// Light that pools in the gaps between vertebrae and in the skull's eyes: a pulse runs head to tail as it breathes.
fn glow_at(w: vec3f) -> vec3f {
    let f = spine_frame(w.xz);
    var g = vec3f(0.0);
    if (abs(f.y) < 1.2) {
        let vq = vert_q(w, f);
        let gap = length(vec3f(abs(vq.x) - 0.4, vq.y, vq.z));
        let pulse = 0.25 + 2.2 * pow(0.5 + 0.5 * sin(vq.w * 0.22 + time() * 1.5), 8.0);
        g += aur_tint(w) * exp(-gap * 7.0) * pulse * (0.6 + 0.6 * breath());
    }
    let pe = vec3f(w.x - 106.5, w.y - 2.45, abs(w.z - 12.0) - 1.45);
    g += vec3f(0.25, 1.0, 0.7) * exp(-length(pe) * 3.2) * (0.6 + 0.8 * breath());
    return g;
}

fn calc_normal(p: vec3f) -> vec3f {
    let e = vec2f(0.0025, -0.0025);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn curtains(rd: vec3f) -> vec3f {
    if (rd.y < 0.01) { return vec3f(0.0); }
    var acc = vec3f(0.0);
    let steps = i32(mix(6.0, 14.0, quality()));
    for (var i = 0; i < 18; i = i + 1) {
        if (i >= steps) { break; }
        let fi = f32(i) / f32(steps);
        let h = 0.6 + fi * 0.9;
        let p = rd.xz * (h / rd.y);
        let warp = noise3(vec3f(p * 0.12, time() * 0.05)) * 6.0;
        let band = pow(0.5 + 0.5 * sin(p.x * 0.33 + p.y * 0.12 + warp + time() * 0.15), 6.0);
        let fade = noise3(vec3f(p * 0.4 + vec2f(time() * 0.07, 0.0), fi));
        acc += mix(AUR_A, AUR_B, fi) * band * fade * (1.0 - fi) * (2.9 / f32(steps));
    }
    return acc * smoothstep(0.01, 0.2, rd.y) * (0.8 + 0.3 * breath());
}

fn sky(rd: vec3f) -> vec3f {
    var col = mix(vec3f(0.03, 0.045, 0.1), vec3f(0.003, 0.006, 0.022), clamp(rd.y * 1.5, 0.0, 1.0));
    let q = rd * 160.0;
    let h = hash13(floor(q));
    if (h > 0.995 && rd.y > 0.0) { col += vec3f(0.85) * smoothstep(0.35, 0.0, length(fract(q) - 0.5)) * (0.6 + 0.4 * sin(time() * 2.0 + h * 90.0)); }
    return col + curtains(rd);
}

fn ground(ro: vec3f, rd: vec3f, tg: f32) -> vec3f {
    let w = ro + rd * tg + GOFF;
    let n = fbm3(vec3f(w.xz * 0.35, 0.0));
    var col = vec3f(0.15, 0.18, 0.26) * (0.75 + 0.5 * n);
    col += curtains(reflect(rd, vec3f(0.0, 1.0, 0.0))) * 0.3 * step(tg, 14.0);
    let sp = floor(w.xz * 30.0);
    if (hash12(sp) > 0.993) { col += vec3f(0.7, 0.8, 1.0) * (0.5 + 0.5 * sin(dot(rd, vec3f(31.0, 17.0, 23.0)) + hash12(sp) * 50.0)); }
    let occ = clamp(map(w + vec3f(0.0, 0.3, 0.0)) / 0.3, 0.0, 1.0);
    col *= 0.35 + 0.65 * occ;
    col += glow_at(w + vec3f(0.0, 0.5, 0.0)) * 0.25;
    return mix(col, HORIZON, 1.0 - exp(-tg * 0.02));
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let tg = plane_y(ro, rd, 0.0);
    var tend = tmax;
    if (tg > 0.0) { tend = min(tg, tmax); }
    var t = tmin;
    let steps = i32(mix(36.0, 96.0, quality()));
    var hit = false;
    var glow = vec3f(0.0);
    for (var i = 0; i < 96; i = i + 1) {
        if (i >= steps) { break; }
        let w = ro + rd * t + GOFF;
        let d = map(w);
        glow += glow_at(w) * clamp(d, 0.03, 0.35);
        if (d < 0.0015 * t + 0.002) { hit = true; break; }
        t += d * 0.95;
        if (t > tend) { break; }
    }
    if (hit) {
        let w = ro + rd * t + GOFF;
        let n = calc_normal(w);
        let l = normalize(vec3f(0.35, 1.0, -0.45));
        let dif = clamp(dot(n, l), 0.0, 1.0);
        let ao = clamp(0.35 + 0.65 * map(w + n * 0.22) / 0.22, 0.0, 1.0);
        let tint = aur_tint(w);
        let grain = 0.85 + 0.3 * noise3(w * 6.0);
        let bounce = vec3f(0.42, 0.44, 0.52) * (0.6 - 0.4 * n.y);
        let fill = vec3f(0.3, 0.27, 0.24) * clamp(dot(n, -rd), 0.0, 1.0);
        var col = BONE * grain * (vec3f(0.05, 0.06, 0.09) + dif * vec3f(0.95, 0.86, 0.72) + bounce + fill + tint * (0.05 + 0.08 * max(n.y, 0.0)));
        col *= ao;
        let rim = pow(1.0 - clamp(dot(-rd, n), 0.0, 1.0), 3.0);
        col += tint * rim * 0.12;
        col += glow * 0.6;
        col = mix(col, HORIZON, 1.0 - exp(-t * 0.012));
        return Hit(tone(col * 1.25), t);
    }
    if (tg > 0.0) {
        let gc = ground(ro, rd, tg) + glow * 0.6;
        return Hit(tone(gc * 1.2), min(tg, horizon_t(tmax)));
    }
    return Hit(tone(sky(rd) * 1.2 + glow * 0.6), horizon_t(tmax));
}

fn jelly_glow(ro: vec3f, rd: vec3f, i: i32, t: f32) -> vec3f {
  let fi = f32(i);
  let h = hash33(vec3f(fi * 7.31, 3.7, 1.9));
  var c = vec3f((h.x - 0.5) * 9.0, 1.4 + h.y * 2.2, (h.z - 0.5) * 9.0);
  c.x += sin(t * 0.13 + fi * 2.1) * 1.4;
  c.z += cos(t * 0.11 + fi * 1.3) * 1.4;
  let pulse = sin(t * 1.4 + fi * 1.7);
  c.y += pulse * 0.25 + sin(t * 0.07 + fi) * 0.5;
  let sc = 0.75 + h.y * 0.5;
  let s0 = max(dot(c - vec3f(0.0, 0.5 * sc, 0.0) - ro, rd), 0.0);
  var acc = vec3f(0.0);
  let hue = fract(0.5 + h.x * 0.45);
  let col = palette(hue, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67));
  for (var k = 0; k < 3; k++) {
    let s = max(s0 + (f32(k) - 1.0) * 0.35 * sc, 0.0);
    let q = (ro + rd * s - c) / sc;
    let r = length(vec3f(q.x, q.y * 1.6, q.z)) / (1.0 + 0.1 * pulse);
    let shell = exp(-pow(r - 0.5, 2.0) * 70.0) * smoothstep(-0.2, 0.15, q.y) * (1.0 - smoothstep(0.35, 0.55, q.y));
    let core = exp(-r * r * 9.0) * 0.5 * smoothstep(-0.2, 0.1, q.y);
    let rad = length(q.xz);
    let w = sin(q.y * 5.0 - t * 2.0 + fi) * 0.07;
    let ten = exp(-pow(rad - 0.3 - w, 2.0) * 260.0) * smoothstep(-1.9, -0.1, q.y) * (1.0 - smoothstep(-0.15, 0.0, q.y))
              * (0.45 + 0.55 * sin(q.y * 22.0 - t * 3.0));
    let fil = exp(-rad * rad * 700.0) * smoothstep(-2.2, -0.1, q.y) * (1.0 - smoothstep(-0.2, 0.0, q.y)) * 0.8;
    acc += col * (shell * 1.1 + core * 0.9 + ten * 0.35 + fil * 0.3);
    acc += vec3f(0.9, 1.0, 1.0) * shell * 0.15;
  }
  return acc * 0.55;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
  let t = time();
  let up = clamp(rd.y, -1.0, 1.0);
  var col = mix(vec3f(0.0, 0.012, 0.03), vec3f(0.0, 0.05, 0.09), smoothstep(-0.3, 1.0, up));

  if (rd.y > 0.03) {
    let tp = (9.0 - ro.y) / rd.y;
    let p = ro + rd * tp;
    let a = p.x * 0.33 + sin(p.z * 0.21 + t * 0.07) * 1.6 + t * 0.04;
    let b = p.z * 0.27 + cos(p.x * 0.19 - t * 0.05) * 1.4;
    var ray = pow(0.5 + 0.5 * sin(a * 3.0), 3.0) * (0.5 + 0.5 * sin(b * 2.0 + 1.0));
    ray += 0.4 * pow(0.5 + 0.5 * sin(a * 7.0 + b), 4.0);
    col += vec3f(0.05, 0.28, 0.36) * ray * smoothstep(0.03, 0.55, rd.y) * 0.5;
  }
  col += vec3f(0.0, 0.05, 0.07) * pow(max(up, 0.0), 2.0);

  if (rd.y < -0.01) {
    let tf = -ro.y / rd.y;
    let p = ro + rd * tf;
    let n = fbm3(vec3f(p.x * 0.5, 0.0, p.z * 0.5));
    let fog = exp(-tf * 0.09);
    var f = vec3f(0.01, 0.03, 0.04) * (0.4 + n);
    let cell = floor(p.xz * 2.5);
    let hh = hash12(cell);
    let lf = length(fract(p.xz * 2.5) - 0.5);
    let spot = step(0.9, hh) * exp(-lf * lf * 80.0) * (0.5 + 0.5 * sin(t * 1.5 + hh * 60.0));
    f += vec3f(0.1, 0.9, 0.7) * spot * 0.7;
    col = mix(col, f, fog);
  }

  var glow = vec3f(0.0);
  let nj = 4 + i32(quality() * 3.0);
  for (var i = 0; i < nj; i++) { glow += jelly_glow(ro, rd, i, t); }
  col += glow;

  let g = rd * 26.0 + vec3f(0.0, -t * 0.25, t * 0.05) + ro * 0.5;
  let hs = hash33(floor(g));
  let d = length(fract(g) - hs);
  col += vec3f(0.5, 0.8, 0.9) * step(0.8, hs.x) * exp(-d * d * 120.0) * 0.25;

  return Hit(tone(col), horizon_t(tmax));
}

// The Long Clock VI: Orrery Train - part of one machine spanning 8 rooms; all motion derives from one escape wheel.
const GX: f32 = -1.0;
const GY: f32 = -2.0;

var<private> TE: f32;
var<private> TW: f32;
var<private> MAT: i32;
var<private> EID: i32;

fn clock_init() {
    TW = time() - (GX * 7.0 + GY * 13.0);
    let k = floor(TW);
    let fr = TW - k;
    TE = (k + smoothstep(0.0, 0.14, fr)) * TAU / 60.0;
}
fn sd2box(p: vec2f, b: vec2f) -> f32 {
    let q = abs(p) - b;
    return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0);
}
fn ext(d: f32, z: f32, w: f32) -> f32 {
    let e = vec2f(d, abs(z) - w);
    return min(max(e.x, e.y), 0.0) + length(max(e, vec2f(0.0)));
}
fn gear2(q: vec2f, R: f32, N: f32, ang: f32, spokes: f32) -> f32 {
    let m = R / N;
    let r = length(q);
    let a = atan2(q.y, q.x) - ang;
    let seg = TAU / N;
    let fa = (fract(a / seg + 0.5) - 0.5) * seg;
    let u = r - R;
    let tw = mix(0.29, 0.15, clamp((u + m) / (2.0 * m), 0.0, 1.0)) * seg * R;
    var d = min(r - (R - 0.95 * m), sd2box(vec2f(u, fa * r), vec2f(m, tw)));
    if (spokes > 0.0) {
        let ring = max(r - (R - 2.6 * m), 0.32 * R - r);
        let ss = TAU / spokes;
        let sa = (fract(a / ss + 0.5) - 0.5) * ss * r;
        d = max(d, -max(ring, 0.05 * R + 0.03 - abs(sa)));
    }
    return d;
}
fn gearz(q: vec3f, R: f32, N: f32, ang: f32, w: f32, sp: f32) -> f32 {
    let g = ext(gear2(q.xy, R, N, ang, sp), q.z, w);
    let hub = ext(length(q.xy) - max(0.09, 0.12 * R), q.z, w * 1.9);
    return min(g, hub);
}
fn cylz(q: vec3f, r: f32, h: f32) -> f32 { return ext(length(q.xy) - r, q.z, h); }
fn capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a; let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn pend_ang() -> f32 { return 0.13 * cos(PI * TW); }
fn DIALC(P: vec3f) -> vec3f { return vec3f(0.0, 0.0, 0.0); }
fn map(P: vec3f) -> f32 {
    var d = 1e5;
    { let q = (P - vec3f(0.0, 3.7, 0.0)); let g = min(cylz(q, 0.075, 6.0), max(cylz(vec3f(q.xy, (fract(q.z * 0.8) - 0.5) / 0.8), 0.11, 0.035), abs(q.z) - 6.0)); if (g < d) { d = g; MAT = 1; EID = 0; } }
    { let g = sd_box(P - vec3f(0.0, 3.7, -5.86), vec3f(0.22, 0.22, 0.14)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 1; } }
    { let g = sd_box(P - vec3f(0.0, 3.7, 5.86), vec3f(0.22, 0.22, 0.14)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 2; } }
    { let q = (P - vec3f(3.0, 3.0, 0.0)).zyx; let g = min(cylz(q, 0.065, 3.0), max(cylz(vec3f(q.xy, (fract(q.z * 0.8) - 0.5) / 0.8), 0.1, 0.035), abs(q.z) - 3.0)); if (g < d) { d = g; MAT = 1; EID = 3; } }
    { let g = sd_box(P - vec3f(5.86, 3.0, 0.0), vec3f(0.14, 0.2, 0.2)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 4; } }
    { let g = sd_box(P - vec3f(0.0, 3.35, 0.0), vec3f(0.32, 0.5, 0.32)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 5; } }
    { let q = (P - vec3f(0.0, 3.34, 0.0)).xzy; if (max(length(q) - 0.42, abs(q.z) - 0.105) < d) { let g = gearz(q, 0.36, 9.0, (4.0 * TE + 0.0), 0.05, 0.0); if (g < d) { d = g; MAT = 0; EID = 6; } } }
    { let q = (P - vec3f(0.0, 3.7, -3.5)); if (max(length(q) - 0.68, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.6, 10.0, (4.0 * TE + 0.0), 0.07, 0.0); if (g < d) { d = g; MAT = 3; EID = 7; } } }
    { let q = (P - vec3f(1.3244, 2.9958, -3.5)); if (max(length(q) - 0.98, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.9, 15.0, (-2.6667 * TE + 2.5365), 0.07, 5.0); if (g < d) { d = g; MAT = 0; EID = 8; } } }
    { let q = (P - vec3f(3.025, 1.5688, -3.5)); if (max(length(q) - 1.4, abs(q.z) - 0.143) < d) { let g = gearz(q, 1.32, 22.0, (1.8182 * TE + 0.3808), 0.07, 5.0); if (g < d) { d = g; MAT = 0; EID = 9; } } }
    { let q = (P - vec3f(4.9159, 1.9022, -3.5)); if (max(length(q) - 0.68, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.6, 10.0, (-4.0 * TE + 3.1765), 0.07, 5.0); if (g < d) { d = g; MAT = 3; EID = 10; } } }
    { let g = sd_box(P - vec3f(3.025, 0.7844, -3.67), vec3f(0.09, 0.7844, 0.06)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 11; } }
    { let g = sd_box(P - vec3f(3.025, 0.06, -3.67), vec3f(0.32, 0.06, 0.22)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 12; } }
    { let g = sd_box(P - vec3f(4.9159, 0.9511, -3.67), vec3f(0.09, 0.9511, 0.06)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 13; } }
    { let g = sd_box(P - vec3f(4.9159, 0.06, -3.67), vec3f(0.32, 0.06, 0.22)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 14; } }
    { let q = (P - vec3f(-1.3051, 3.0914, -3.5)); if (max(length(q) - 0.92, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.84, 14.0, (-2.8571 * TE + 3.2164), 0.07, 5.0); if (g < d) { d = g; MAT = 0; EID = 15; } } }
    { let q = (P - vec3f(-3.2173, 1.8497, -3.5)); if (max(length(q) - 1.52, abs(q.z) - 0.143) < d) { let g = gearz(q, 1.44, 24.0, (1.6667 * TE + 3.6172), 0.07, 5.0); if (g < d) { d = g; MAT = 0; EID = 16; } } }
    { let q = (P - vec3f(-4.8259, 3.1995, -3.5)); if (max(length(q) - 0.74, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.66, 11.0, (-3.6364 * TE + 3.3098), 0.07, 5.0); if (g < d) { d = g; MAT = 3; EID = 17; } } }
    { let g = sd_box(P - vec3f(-3.2173, 0.9248, -3.67), vec3f(0.09, 0.9248, 0.06)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 18; } }
    { let g = sd_box(P - vec3f(-3.2173, 0.06, -3.67), vec3f(0.32, 0.06, 0.22)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 19; } }
    { let g = sd_box(P - vec3f(-4.8259, 1.5998, -3.67), vec3f(0.09, 1.5998, 0.06)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 20; } }
    { let g = sd_box(P - vec3f(-4.8259, 0.06, -3.67), vec3f(0.32, 0.06, 0.22)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 21; } }
    { let q = (P - vec3f(0.0, 3.7, 3.5)); if (max(length(q) - 0.68, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.6, 10.0, (4.0 * TE + 0.0), 0.07, 0.0); if (g < d) { d = g; MAT = 3; EID = 22; } } }
    { let q = (P - vec3f(-1.3244, 2.9958, 3.5)); if (max(length(q) - 0.98, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.9, 15.0, (-2.6667 * TE + 3.1183), 0.07, 5.0); if (g < d) { d = g; MAT = 0; EID = 23; } } }
    { let q = (P - vec3f(-3.025, 1.5688, 3.5)); if (max(length(q) - 1.4, abs(q.z) - 0.143) < d) { let g = gearz(q, 1.32, 22.0, (1.8182 * TE + 3.332), 0.07, 5.0); if (g < d) { d = g; MAT = 0; EID = 24; } } }
    { let q = (P - vec3f(-4.9159, 1.9022, 3.5)); if (max(length(q) - 0.68, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.6, 10.0, (-4.0 * TE + 5.62), 0.07, 5.0); if (g < d) { d = g; MAT = 3; EID = 25; } } }
    { let g = sd_box(P - vec3f(-3.025, 0.7844, 3.67), vec3f(0.09, 0.7844, 0.06)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 26; } }
    { let g = sd_box(P - vec3f(-3.025, 0.06, 3.67), vec3f(0.32, 0.06, 0.22)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 27; } }
    { let g = sd_box(P - vec3f(-4.9159, 0.9511, 3.67), vec3f(0.09, 0.9511, 0.06)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 28; } }
    { let g = sd_box(P - vec3f(-4.9159, 0.06, 3.67), vec3f(0.32, 0.06, 0.22)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 29; } }
    {
        let q = P - vec3f(3.5, 1.0, 3.5);
        if (length(q) - 2.2 < d) {
            var g = gearz(q.xzy, 0.5, 20.0, TE * 2.0, 0.04, 4.0);
            var m = 0;
            g = min(g, length(q - vec3f(0.0, 0.55, 0.0)) - 0.32);
            for (var i = 0; i < 4; i = i + 1) {
                let fi = f32(i);
                let orb = 0.75 + 0.33 * fi;
                let a = TE * (1.6 / (1.0 + fi)) + fi * 1.7;
                let pc = vec3f(cos(a) * orb, 0.0, sin(a) * orb);
                g = min(g, capsule(q, vec3f(0.0, 0.08 + 0.05 * fi, 0.0), pc + vec3f(0.0, 0.08 + 0.05 * fi, 0.0), 0.018));
                g = min(g, capsule(q, pc + vec3f(0.0, 0.08 + 0.05 * fi, 0.0), pc + vec3f(0.0, 0.3 + 0.1 * fi, 0.0), 0.018));
                let pl = length(q - pc - vec3f(0.0, 0.42 + 0.1 * fi, 0.0)) - (0.08 + 0.04 * fract(fi * 0.618 + 0.3));
                if (pl < g) { m = 10 + i; }
                g = min(g, pl);
            }
            if (g < d) { d = g; MAT = m; EID = 30; }
        }
    }
    { let g = sd_box(P - vec3f(3.5, 0.47, 3.5), vec3f(1.7, 0.47, 1.6)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 31; } }
    return d;
}

fn matcol(P: vec3f, m: i32, eid: i32) -> vec3f {
    var col = vec3f(0.78, 0.56, 0.26);
    switch m {
        case 1: { col = vec3f(0.62, 0.64, 0.68); }
        case 2: { col = vec3f(0.16, 0.15, 0.15); }
        case 3: { col = vec3f(0.80, 0.42, 0.24); }
        case 4: { col = vec3f(0.95, 0.78, 0.38); }
        case 5: { col = vec3f(0.93, 0.90, 0.80); }
        case 6: { col = vec3f(0.08, 0.08, 0.12); }
        case 10: { col = vec3f(0.35, 0.55, 0.95); }
        case 11: { col = vec3f(0.9, 0.35, 0.2); }
        case 12: { col = vec3f(0.85, 0.8, 0.6); }
        case 13: { col = vec3f(0.5, 0.85, 0.75); }
        default: { }
    }
    if (m == 5) {
        // dial face: hour ticks
        let q = P - DIALC(P);
        let a = atan2(q.x, q.y);
        let r = length(q.xy);
        let tk = abs(fract(a / TAU * 60.0 + 0.5) - 0.5);
        let big = abs(fract(a / TAU * 12.0 + 0.5) - 0.5);
        if ((tk < 0.08 && r > 1.32 && r < 1.48) || (big < 0.035 && r > 1.08 && r < 1.48)) { col = vec3f(0.1); }
        if (abs(r - 0.6) < 0.01) { col = vec3f(0.5, 0.35, 0.15); }
    }
    switch eid {
        case 0: { let q = (P - vec3f(0.0, 3.7, 0.0)); col *= 0.75 + 0.35 * step(0.0, sin(atan2(q.y, q.x) * 2.0 - (4.0 * TE + 0.0) * 2.0)); }
        case 3: { let q = (P - vec3f(3.0, 3.0, 0.0)).zyx; col *= 0.75 + 0.35 * step(0.0, sin(atan2(q.y, q.x) * 2.0 - (4.0 * TE + 0.0) * 2.0)); }
        default: { }
    }
    return col;
}

fn calc_normal(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn light(P: vec3f, n: vec3f, rd: vec3f, base: vec3f, metal: f32) -> vec3f {
    let lp = vec3f(0.0, 4.3, 0.0);
    let lv = lp - P;
    let ld = normalize(lv);
    let att = 3.2 / (1.0 + 0.04 * dot(lv, lv));
    let dif = max(dot(n, ld), 0.0);
    let key = normalize(vec3f(-0.5, 0.9, 0.35));
    let dif2 = max(dot(n, key), 0.0);
    let h = normalize(ld - rd);
    let sp = pow(max(dot(n, h), 0.0), 40.0);
    let fre = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let amb = 0.22 + 0.12 * n.y;
    var c = base * (amb + dif * att * vec3f(1.0, 0.85, 0.62) + dif2 * 0.35 * vec3f(0.6, 0.7, 0.9));
    c += mix(vec3f(0.25), base * 1.4, metal) * (sp * att * 1.6 + fre * 0.25);
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    clock_init();
    var tend = tmax;
    let tf = plane_y(ro, rd, 0.0);
    let floor_hit = tf >= tmin && tf <= tmax + 0.005;
    if (floor_hit) { tend = tf; }
    let steps = i32(mix(32.0, 80.0, quality()));
    var t = tmin;
    var hit = false;
    for (var i = 0; i < steps; i = i + 1) {
        let d = map(ro + rd * t);
        if (d < 0.0008 + 0.0012 * t) { hit = true; break; }
        t += d * 0.8;
        if (t > tend) { break; }
    }
    if (hit && t <= tmax) {
        let P = ro + rd * t;
        let m = MAT; let eid = EID;
        let n = calc_normal(P);
        let base = matcol(P, m, eid);
        let ao = clamp(map(P + n * 0.12) / 0.12, 0.25, 1.0);
        var metal = 1.0;
        if (m == 5 || m == 6 || m >= 10) { metal = 0.2; }
        var c = light(P, n, rd, base, metal) * ao;
        c = mix(c, vec3f(0.05, 0.035, 0.02), clamp(t / 30.0, 0.0, 0.5));
        return Hit(tone(c * 1.3), t);
    }
    if (floor_hit) {
        let P = ro + rd * tf;
        let W = P + vec3f(GX * 12.0, 0.0, GY * 12.0);
        var c = FLOOR(P, W, rd);
        let occ = clamp(map(P + vec3f(0.0, 0.35, 0.0)) / 0.35, 0.3, 1.0);
        c *= occ;
        return Hit(tone(c * 1.3), min(tf, tmax));
    }
    return no_hit();
}

fn FLOOR(P: vec3f, W: vec3f, rd: vec3f) -> vec3f {
    // dark oak boards running north-south, brass inlay under every line shaft (continuous through rooms)
    let bw = 0.3;
    let bi = floor(W.x / bw);
    let along = W.z + hash12(vec2f(bi, 3.0)) * 7.0;
    let joint = min(abs(fract(W.x / bw) - 0.5), abs(fract(along / 2.4) - 0.5) * 8.0);
    var c = vec3f(0.17, 0.10, 0.06) * (0.75 + 0.5 * hash12(vec2f(bi, floor(along / 2.4))));
    c *= 0.8 + 0.2 * noise3(vec3f(W.x * 30.0, 0.0, W.z * 1.5));
    c *= mix(0.55, 1.0, smoothstep(0.42, 0.47, 0.5 - joint));
    let lx = abs(P.x);
    let lz = abs(P.z);
    if (lx < 0.06 || (lz < 0.06 && ((GX > -0.5 && P.x < 0.0) || (GX < -0.5 && P.x > 0.0) || (GX > -1.5 && GX < -0.5 && GY > -3.5 && GY < -2.5)))) { c = vec3f(0.7, 0.5, 0.22); }
    // engraved dial ring in each room, with 60 ticks; the tick under the second hand lights
    let r = length(P.xz);
    let a = atan2(P.x, -P.z);
    let ring = abs(r - 2.6);
    if (ring < 0.03) { c = vec3f(0.6, 0.42, 0.18); }
    let tk = fract(a / TAU * 60.0 + 0.5) - 0.5;
    if (abs(tk) < 0.07 && r > 2.66 && r < 2.9) {
        let idx = floor(a / TAU * 60.0 + 0.5);
        let sec = floor(TE / TAU * 60.0 + 0.5);
        let on = abs(fract((idx - sec) / 60.0 + 0.5) - 0.5) < 0.005;
        c = select(vec3f(0.55, 0.4, 0.17), vec3f(1.4, 0.9, 0.4), on);
    }
    let l = 3.0 / (1.0 + 0.05 * dot(P - vec3f(0.0, 4.3, 0.0), P - vec3f(0.0, 4.3, 0.0)));
    return c * (0.3 + l);
}

// Catoid Sweep: one knob, swept down a corridor of rooms, from Hot-dog Kitty to Jimothy.
// A catoid sculpted from signed distance fields (round cones, capsules, smooth unions) on a black
// plinth in a dark gallery, walking in place. param(0).x is where this room sits on the sweep (0 long
// and thin, 1 round), param(1) its coat, param(2) its rim light. Catoid week, the simcluster, Oct 2026.

const S: f32 = 1.35;                  // sculpture scale: catoid units to metres
const CAT_Z: f32 = -2.4;              // the plinth runs along the north side, the walk along the middle
const PLINTH_H: f32 = 0.3;

var<private> cL: f32;      // half body length
var<private> cR: f32;      // body radius
var<private> cLeg: f32;    // leg length
var<private> cHead: f32;   // head radius
var<private> cTail: f32;   // tail length
var<private> cH: f32;      // body height
var<private> cPh: f32;     // gait phase
var<private> mat: f32;     // 0 coat, 1 eye, 2 nose, 3 inner ear

fn sweep() -> f32 { return clamp(param(0u).x, 0.0, 1.0); }

fn set_cat() {
    let t = sweep();
    cL = mix(1.3, 0.3, t);
    cR = mix(0.19, 0.62, t);
    cLeg = mix(0.62, 0.24, t);
    cHead = mix(0.23, 0.33, t);
    cTail = mix(1.05, 0.5, t);
    cH = max(cLeg + cR * 0.5, cR + 0.1);
    cPh = time() * mix(4.2, 2.6, t);
}

// Inigo Quilez's ellipsoid bound.
fn sd_ellipsoid(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}

fn sd_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

// Inigo Quilez's round cone between two points.
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

fn head_c() -> vec3f { return vec3f(cL + cR * 0.45 + cHead * 0.75, cH + cR * 0.55 + cHead * 0.45, 0.0); }

// The catoid in its own units: x from tail to head, y up from the plinth, z across.
fn cat(p: vec3f) -> f32 {
    let t = sweep();
    // body: a round cone, chest a little higher, with a belly that sags as it gets round
    var d = sd_round_cone(p, vec3f(-cL, cH, 0.0), vec3f(cL, cH + 0.05, 0.0), cR, cR * 0.9);
    d = smin(d, sd_ellipsoid(p - vec3f(0.0, cH - cR * 0.2, 0.0), vec3f(cL * 0.85 + cR * 0.5, cR * 0.92, cR * 1.02)), 0.12);
    // legs walk in place: front and back pairs in counter-phase
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-1.0, 1.0, i < 2);
        let side = select(-1.0, 1.0, (i & 1) == 0);
        let ph = cPh + select(0.0, PI, (i == 1) || (i == 2));
        let hip = vec3f(fx * cL * 0.82, cH - cR * 0.2, side * max(cR * 0.55, 0.11));
        let swing = sin(ph) * cLeg * 0.32;
        let lift = max(cos(ph), 0.0) * cLeg * 0.14;
        let paw = vec3f(hip.x + swing, 0.075 + lift, hip.z);
        d = smin(d, sd_round_cone(p, paw, hip, 0.07, mix(0.1, 0.17, t)), 0.08);
        d = smin(d, sd_ellipsoid(p - paw - vec3f(0.035, -0.015, 0.0), vec3f(0.1, 0.06, 0.08)), 0.04);
    }
    // tail: six segments curling up and back, swishing
    var a = vec3f(-cL - cR * 0.6, cH + cR * 0.3, 0.0);
    var ang = 2.35;
    let seg = cTail / 6.0;
    for (var i = 0; i < 6; i = i + 1) {
        let fi = f32(i);
        ang = ang - 0.32 + sin(time() * 1.7 - fi * 0.7) * 0.12;
        let b = a + vec3f(cos(ang), sin(ang), sin(time() * 1.1 - fi * 0.5) * 0.06) * seg;
        d = smin(d, sd_capsule(p, a, b, mix(0.075, 0.035, fi / 5.0) * (1.0 + t * 0.6)), 0.05);
        a = b;
    }
    // head, cheeks, muzzle
    let hc = head_c() + vec3f(0.0, sin(cPh * 2.0) * 0.012, 0.0);
    var h = length(p - hc) - cHead;
    h = smin(h, sd_ellipsoid(p - hc - vec3f(0.02, -cHead * 0.28, 0.0), cHead * vec3f(0.8, 0.62, 1.08)), 0.06);
    let mz = hc + vec3f(cHead * 0.82, -cHead * 0.3, 0.0);
    h = smin(h, sd_ellipsoid(p - mz, cHead * vec3f(0.3, 0.26, 0.38)), 0.06);
    d = smin(d, h, 0.16);
    // ears: flattened round cones
    var ear = 1e5;
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let base = hc + vec3f(-cHead * 0.1, cHead * 0.62, s * cHead * 0.52);
        let tip = base + vec3f(-0.04, cHead * 0.72, s * cHead * 0.26);
        var q = p - base;
        q.x = q.x * 1.7;
        ear = min(ear, sd_round_cone(q, vec3f(0.0), (tip - base) * vec3f(1.7, 1.0, 1.0), cHead * 0.42, 0.02) / 1.7);
    }
    d = smin(d, ear, 0.03);
    // materials, by the nearest feature
    mat = 0.0;
    let eyeL = length(p - (hc + vec3f(cHead * 0.72, cHead * 0.18, cHead * 0.4))) - cHead * 0.16;
    let eyeR = length(p - (hc + vec3f(cHead * 0.72, cHead * 0.18, -cHead * 0.4))) - cHead * 0.16;
    if (min(eyeL, eyeR) < 0.012) { mat = 1.0; }
    if (length(p - (mz + vec3f(cHead * 0.24, cHead * 0.12, 0.0))) < cHead * 0.13) { mat = 2.0; }
    return d;
}

fn to_cat(p: vec3f) -> vec3f { return (p - vec3f(0.0, PLINTH_H, CAT_Z)) / S; }
fn cat_w(p: vec3f) -> f32 { return cat(to_cat(p)) * S; }

fn cat_n(p: vec3f) -> vec3f {
    let e = vec2f(0.004, 0.0);
    return normalize(vec3f(cat_w(p + e.xyy) - cat_w(p - e.xyy), cat_w(p + e.yxy) - cat_w(p - e.yxy), cat_w(p + e.yyx) - cat_w(p - e.yyx)));
}

fn cat_box_min() -> vec3f { return vec3f(-cL - cR - cTail - 0.15, 0.0, -cR - 0.45) * S + vec3f(0.0, PLINTH_H, CAT_Z); }
fn cat_box_max() -> vec3f { return vec3f(cL + cR + cHead * 2.6 + 0.1, cH + cR + cHead * 2.4 + max(cTail * 0.7, 0.4), cR + 0.45) * S + vec3f(0.0, PLINTH_H, CAT_Z); }

const LIGHT: vec3f = vec3f(0.35, 0.85, 0.4);

fn soft_shadow(p: vec3f) -> f32 {
    let l = normalize(LIGHT);
    let b = box_span(p, l, cat_box_min(), cat_box_max());
    if (b.x > b.y || b.y < 0.0) { return 1.0; }
    var t = max(b.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 20; i = i + 1) {
        if (t > b.y) { break; }
        let h = cat_w(p + l * t);
        res = min(res, 10.0 * h / t);
        if (res < 0.02) { break; }
        t += clamp(h, 0.03, 0.4);
    }
    return clamp(res, 0.0, 1.0);
}

fn rim_col() -> vec3f { return param(2u).rgb; }

fn shade_cat(p: vec3f, rd: vec3f) -> vec3f {
    let n = cat_n(p);
    let m = mat;
    let cp = to_cat(p);
    let t = sweep();
    // coat: tabby stripes across the back, a pale belly and muzzle
    var base = param(1u).rgb;
    let stripe = smoothstep(0.35, 0.6, sin(cp.x * mix(13.0, 7.0, t) + fbm3(cp * 3.0) * 2.4)) * smoothstep(-0.2, 0.4, n.y);
    base = mix(base, base * 0.35, stripe * 0.75);
    base = mix(base, vec3f(0.92, 0.88, 0.8), smoothstep(-0.25, -0.7, n.y) * 0.8);
    if (m == 1.0) { base = vec3f(0.05, 0.25, 0.12); }
    if (m == 2.0) { base = vec3f(0.85, 0.45, 0.5); }
    let l = normalize(LIGHT);
    let diff = max(dot(n, l), 0.0) * (0.35 + 0.65 * soft_shadow(p + n * 0.01));
    let ao = clamp(0.5 + 0.5 * cat_w(p + n * 0.12) / 0.12, 0.0, 1.0);
    let rim = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let back = max(dot(n, normalize(vec3f(-0.6, 0.3, -0.8))), 0.0);
    let spec = pow(max(dot(reflect(rd, n), l), 0.0), select(24.0, 90.0, m == 1.0)) * select(0.25, 1.2, m == 1.0);
    var col = base * (0.08 + diff * 1.1) * ao + rim_col() * (rim * 0.6 + back * 0.25) + vec3f(spec);
    return col;
}

fn led_wall(p: vec3f) -> vec3f {
    // the north wall: a dark field, faint grid, and the sweep as a bar of LEDs above the catoid
    var col = vec3f(0.018, 0.016, 0.03);
    let g = abs(fract(p.xy * 2.0) - 0.5);
    col += vec3f(0.02, 0.03, 0.05) * smoothstep(0.47, 0.5, max(g.x, g.y));
    if (abs(p.y - 3.75) < 0.12 && abs(p.x) < 4.0) {
        let cell = floor((p.x + 4.0) / 8.0 * 24.0);
        let lit = cell < floor(sweep() * 23.0 + 0.5) + 1.0;
        let f = fract((p.x + 4.0) / 8.0 * 24.0);
        let inside = step(0.12, f) * step(f, 0.88) * step(abs(p.y - 3.75), 0.085);
        let here = abs(cell - floor(sweep() * 23.0 + 0.5)) < 0.5;
        col = mix(col, select(rim_col() * 0.12, select(rim_col(), vec3f(1.0), here), lit), inside);
    }
    return col;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    set_cat();
    var best = tmax;
    var kind = 0; // 0 wall/ceiling, 1 floor, 2 plinth, 3 catoid
    // the catoid
    let cb = box_span(ro, rd, cat_box_min(), cat_box_max());
    if (cb.x < cb.y && cb.y > tmin) {
        var t = max(cb.x, tmin);
        let steps = select(60, 90, quality() > 0.6);
        for (var i = 0; i < 90; i = i + 1) {
            if (i >= steps || t > cb.y) { break; }
            let d = cat_w(ro + rd * t);
            if (d < 0.002 * t + 0.002) { best = t; kind = 3; break; }
            t += d * 0.9;
        }
    }
    // the plinth: black glass with a neon edge
    let pmin = vec3f(-4.4, 0.0, CAT_Z - 1.1);
    let pmax = vec3f(4.4, PLINTH_H, CAT_Z + 1.1);
    let pb = box_span(ro, rd, pmin, pmax);
    if (pb.x < pb.y && pb.x > tmin && pb.x < best) { best = pb.x; kind = 2; }
    let tf = plane_y(ro, rd, 0.0);
    if (tf > 0.0 && tf < best) { best = tf; kind = 1; }

    let p = ro + rd * best;
    if (kind == 3) {
        let c = shade_cat(p, rd);
        return Hit(tone(c * 1.3), best);
    }
    if (kind == 2) {
        var c = vec3f(0.012, 0.012, 0.018);
        let edge = min(min(abs(p.x - pmin.x), abs(p.x - pmax.x)), min(abs(p.z - pmin.z), abs(p.z - pmax.z)));
        let top = p.y > PLINTH_H - 0.002;
        if (top) {
            c += vec3f(0.05) * pow(max(dot(reflect(rd, vec3f(0.0, 1.0, 0.0)), normalize(LIGHT)), 0.0), 40.0);
            c *= 0.4 + 0.6 * soft_shadow(p);
            c += rim_col() * smoothstep(0.035, 0.0, edge) * 1.6;
        } else {
            c += rim_col() * smoothstep(0.02, 0.0, abs(p.y - PLINTH_H + 0.02)) * 1.2;
        }
        return Hit(tone(c), best);
    }
    if (kind == 1) {
        // polished dark floor, a lit pool by the plinth, a faint grid, the rim colour bleeding
        var c = vec3f(0.02, 0.02, 0.028);
        let g = abs(fract(p.xz * 1.0) - 0.5);
        c += vec3f(0.035, 0.04, 0.06) * smoothstep(0.485, 0.5, max(g.x, g.y));
        let pool = exp(-pow(max(abs(p.x) - 3.5, 0.0), 2.0) * 0.6 - pow(p.z - CAT_Z - 1.6, 2.0) * 0.9);
        c += rim_col() * pool * 0.12;
        c += vec3f(0.06) * pow(max(dot(reflect(rd, vec3f(0.0, 1.0, 0.0)), normalize(vec3f(0.0, 1.0, -0.4))), 0.0), 30.0);
        return Hit(tone(c), best);
    }
    // walls and ceiling: painted dark; the north wall carries the sweep
    let w = ro + rd * horizon_t(tmax);
    var c = vec3f(0.016, 0.015, 0.024);
    if (w.z < -ROOM_HALF + 0.05) { c = led_wall(w); }
    else if (w.y > ROOM_HEIGHT - 0.05) {
        // ceiling: a strip of light over the plinth
        c = vec3f(0.01) + vec3f(0.5) * smoothstep(0.25, 0.0, abs(w.z - CAT_Z)) * step(abs(w.x), 4.2);
    } else {
        // a neon line where the walls meet the floor
        c += rim_col() * smoothstep(0.04, 0.0, abs(w.y - 0.06)) * 0.8;
    }
    return Hit(tone(c), horizon_t(tmax));
}

// Catoid Forms: the catoid in six schools of mathematical sculpture. param(0).x picks the form:
//   0 gyroid lattice (after Bathsheba Grossman)      1 umbilic torus, curled asleep (after Helaman Ferguson)
//   2 endless ribbon, a one-sided cat (after Max Bill) 3 linear construction in string (after Naum Gabo)
//   4 hanging looped-wire lobes (after Ruth Asawa)    5 a polished form in space (after Constantin Brancusi)
// param(1) is the material colour, param(2) the room's light. Catoid week, the simcluster, Oct 2026.

const PLINTH_H: f32 = 0.5;
const LIGHT: vec3f = vec3f(0.3, 0.9, 0.35);

fn form() -> i32 { return i32(param(0u).x + 0.5); }
fn mat_col() -> vec3f { return param(1u).rgb; }
fn rim_col() -> vec3f { return param(2u).rgb; }

fn sd_ellipsoid(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}
fn sd_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

// A cat's head with ears and muzzle, facing +x, centred at c (shared by several forms).
fn cat_head(p: vec3f, c: vec3f, r: f32) -> f32 {
    var h = length(p - c) - r;
    h = smin(h, sd_ellipsoid(p - c - vec3f(0.02, -r * 0.28, 0.0), r * vec3f(0.8, 0.62, 1.08)), r * 0.25);
    h = smin(h, sd_ellipsoid(p - c - vec3f(r * 0.82, -r * 0.3, 0.0), r * vec3f(0.3, 0.26, 0.38)), r * 0.25);
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let base = c + vec3f(-r * 0.1, r * 0.62, s * r * 0.52);
        var q = p - base;
        q.x = q.x * 1.7;
        h = smin(h, sd_round_cone(q, vec3f(0.0), vec3f(-0.07, r * 0.72, s * r * 0.26), r * 0.42, r * 0.06) / 1.7, r * 0.12);
    }
    return h;
}

// ---- 0: the gyroid catoid. A standing cat, its volume replaced by a gyroid sheet that drifts through it.
fn cat_body(p: vec3f) -> f32 {
    // the sweet-spot proportions of the Catoid Sweep, standing on the plinth, 1.15 m to a catoid unit
    let q = (p - vec3f(0.0, PLINTH_H, 0.0)) / 1.15;
    let L = 0.75; let R = 0.38; let leg = 0.45; let H = leg + R * 0.5;
    var d = sd_round_cone(q, vec3f(-L, H, 0.0), vec3f(L, H + 0.05, 0.0), R, R * 0.9);
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-1.0, 1.0, i < 2);
        let side = select(-1.0, 1.0, (i & 1) == 0);
        let hip = vec3f(fx * L * 0.8, H - R * 0.2, side * R * 0.55);
        d = smin(d, sd_round_cone(q, vec3f(hip.x + 0.04, 0.07, hip.z), hip, 0.07, 0.13), 0.08);
    }
    var a = vec3f(-L - R * 0.6, H + R * 0.3, 0.0);
    var ang = 2.35;
    for (var i = 0; i < 5; i = i + 1) {
        ang = ang - 0.36 + sin(time() * 0.9 - f32(i) * 0.7) * 0.1;
        let b = a + vec3f(cos(ang), sin(ang), 0.0) * 0.17;
        d = smin(d, sd_capsule(q, a, b, mix(0.07, 0.04, f32(i) / 4.0)), 0.05);
        a = b;
    }
    d = smin(d, cat_head(q, vec3f(L + R * 0.45 + 0.21, H + R * 0.55 + 0.13, 0.0), 0.28), 0.14);
    return d * 1.15;
}
fn gyroid_cat(p: vec3f) -> f32 {
    let k = 12.0;
    let q = p * k + vec3f(0.0, time() * 0.25, time() * 0.1);
    let g = abs(sin(q.x) * cos(q.y) + sin(q.y) * cos(q.z) + sin(q.z) * cos(q.x)) / k * 0.55 - 0.014;
    return max(cat_body(p), g);
}

// ---- 1: the umbilic catoid. Curled asleep: a torus whose three-lobed section turns a third of a turn
// on the way round, so one edge runs round it three times, with the head tucked onto the coil.
fn umbilic(p: vec3f) -> f32 {
    let c = vec3f(0.0, PLINTH_H + 0.42, 0.0);
    let q = p - c;
    let th = atan2(q.z, q.x);
    let breathe = 1.0 + 0.012 * sin(time() * 1.3);
    let Rm = 0.78 * breathe;
    var s = vec2f(length(q.xz) - Rm, q.y);
    let tw = th / 3.0 + time() * 0.05;
    s = rot2(tw) * s;
    let ph = atan2(s.y, s.x);
    let r = 0.36 * breathe * (1.0 + 0.2 * cos(3.0 * ph));
    var d = (length(s) - r) * 0.8;
    // the head rests on the coil, nose towards the tail
    let hc = c + vec3f(cos(0.5) * Rm, 0.42, sin(0.5) * Rm);
    let hp = p - hc;
    let hr = vec3f(rot2(-0.5 - PI * 0.5) * hp.xz, hp.y);
    d = smin(d, cat_head(vec3f(hr.x, hr.z, hr.y), vec3f(0.0), 0.36), 0.1);
    return d;
}
fn umbilic_edge(p: vec3f) -> f32 {
    let q = p - vec3f(0.0, PLINTH_H + 0.42, 0.0);
    let th = atan2(q.z, q.x);
    var s = rot2(th / 3.0 + time() * 0.05) * vec2f(length(q.xz) - 0.78, q.y);
    return cos(3.0 * atan2(s.y, s.x));
}

// ---- 2: the endless-ribbon catoid. A cat whose body is a Möbius band: back, belly and back again, one side.
fn ribbon(p: vec3f) -> f32 {
    let c = vec3f(0.0, PLINTH_H + 1.05, 0.0);
    var q = p - c;
    q.x = q.x / 1.55;
    let th = atan2(q.y, q.x);
    var s = vec2f(length(q.xy) - 0.62, q.z);
    s = rot2(th * 0.5 + time() * 0.08) * s;
    let band = vec2f(0.3, 0.028);
    let e = abs(s) - band;
    var d = (length(max(e, vec2f(0.0))) + min(max(e.x, e.y), 0.0) - 0.01) * 0.62;
    // legs down to the plinth, head and tail out of the band
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-0.55, 0.55, i < 2);
        let side = select(-0.14, 0.14, (i & 1) == 0);
        d = min(d, sd_round_cone(p, vec3f(fx + 0.03, PLINTH_H + 0.06, side), vec3f(fx, PLINTH_H + 0.62, side), 0.055, 0.08));
    }
    d = smin(d, cat_head(p, c + vec3f(1.12, 0.38, 0.0), 0.27), 0.1);
    d = smin(d, sd_capsule(p, c + vec3f(-0.98, 0.1, 0.0), c + vec3f(-1.35, 0.75 + 0.06 * sin(time()), 0.0), 0.045), 0.06);
    return d;
}

// ---- 3: the linear construction. Two perspex plates cut to a cat's outline, strung with taut threads
// from each point of one to a point further round the other: a ruled surface that twists as the shift drifts.
const NP: i32 = 24;
fn outline(i: i32) -> vec2f {
    // a standing cat in profile, clockwise from the tip of the tail, metres
    var pts = array<vec2f, 24>(
        vec2f(-1.45, 1.6), vec2f(-1.28, 1.08), vec2f(-1.05, 0.98), vec2f(-0.45, 1.02), vec2f(0.25, 1.04),
        vec2f(0.68, 1.12), vec2f(0.84, 1.38), vec2f(0.84, 1.66), vec2f(0.92, 1.9), vec2f(1.04, 1.7),
        vec2f(1.17, 1.88), vec2f(1.22, 1.62), vec2f(1.45, 1.43), vec2f(1.3, 1.28), vec2f(1.0, 1.18),
        vec2f(0.86, 0.9), vec2f(0.8, 0.0), vec2f(0.6, 0.0), vec2f(0.58, 0.68), vec2f(-0.6, 0.68),
        vec2f(-0.68, 0.0), vec2f(-0.9, 0.0), vec2f(-1.02, 0.82), vec2f(-1.3, 1.12));
    return pts[((i % NP) + NP) % NP] + vec2f(0.0, PLINTH_H + 0.06);
}
fn outline_at(s: f32) -> vec2f {
    let f = fract(s / f32(NP)) * f32(NP);
    let i = i32(floor(f));
    return mix(outline(i), outline(i + 1), fract(f));
}
// distance between the ray and segment a-b, and the ray distance there
fn ray_seg(ro: vec3f, rd: vec3f, a: vec3f, b: vec3f) -> vec2f {
    let ba = b - a;
    let oa = ro - a;
    let bb = dot(ba, ba);
    let rb = dot(rd, ba);
    let den = bb - rb * rb;
    var u = clamp((dot(oa, ba) - dot(oa, rd) * rb) / max(den, 1e-6), 0.0, 1.0);
    let t = max(dot(a + ba * u - ro, rd), 0.0);
    u = clamp(dot(ro + rd * t - a, ba) / bb, 0.0, 1.0);
    return vec2f(length(ro + rd * t - (a + ba * u)), t);
}

// ---- 4: looped wire. A sitting cat as lobes of woven brass, one inside another, hung from the ceiling.
fn lobe_r(y: f32) -> f32 {
    // the sitting cat's radius at height y: haunches, waist, chest, neck, head
    let base = PLINTH_H + 0.35;
    let h = y - base;
    var r = 0.52 * exp(-pow((h - 0.25) / 0.32, 2.0));
    r = max(r, 0.38 * exp(-pow((h - 0.85) / 0.28, 2.0)));
    r = max(r, 0.3 * exp(-pow((h - 1.45) / 0.2, 2.0)));
    return r;
}
fn wire_shell(p: vec3f, scale: f32) -> f32 {
    let c = vec3f(0.0, 0.0, 0.0);
    let r = lobe_r(p.y) * scale;
    let th = atan2(p.z, p.x);
    // ears: the head lobe rises into two points
    let ear = select(0.0, max(cos(th * 2.0), 0.0) * 0.18 * smoothstep(1.55, 1.75, p.y - PLINTH_H - 0.35 + 0.35), scale > 0.9);
    let shell = abs(length(p.xz - c.xz) - r) - 0.006;
    let top = PLINTH_H + 0.35 + 1.72 + ear;
    let bounded = max(shell, max(p.y - top, PLINTH_H + 0.36 - p.y));
    // a diamond weave: two helical families of wire
    let u = th * 8.0 / PI;
    let v = p.y * 9.0;
    let w1 = abs(fract(u + v) - 0.5);
    let w2 = abs(fract(u - v) - 0.5);
    let weave = (min(w1, w2) - 0.06) / 11.0 * max(r, 0.08) * 3.0;
    return max(bounded, weave);
}
fn asawa(p: vec3f) -> f32 {
    var d = wire_shell(p, 1.0);
    d = min(d, wire_shell(p, 0.55));
    d = min(d, sd_capsule(p, vec3f(0.0, PLINTH_H + 2.05, 0.0), vec3f(0.0, ROOM_HEIGHT, 0.0), 0.006));
    // ears: two triangles of the same wire on the head lobe
    let hy = PLINTH_H + 0.35 + 1.5;
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let a = vec3f(0.0, hy + 0.12, s * 0.08);
        let b = vec3f(0.0, hy + 0.08, s * 0.26);
        let t = vec3f(0.03, hy + 0.42, s * 0.22);
        d = min(d, min(sd_capsule(p, a, t, 0.007), min(sd_capsule(p, b, t, 0.007), sd_capsule(p, a, b, 0.007))));
    }
    // a tail of wire wrapped round the haunches, its tip lifting
    var prev = vec3f(-0.5, PLINTH_H + 0.45, 0.0);
    for (var i = 1; i < 9; i = i + 1) {
        let a = PI + f32(i) * 0.38;
        let next = vec3f(cos(a) * 0.56, PLINTH_H + 0.45 + f32(i) * f32(i) * 0.006 + sin(time() * 1.2) * 0.01 * f32(i), -sin(a) * 0.56);
        d = min(d, sd_capsule(p, prev, next, 0.014));
        prev = next;
    }
    return d;
}

// ---- 5: a form in space. One bent, polished ovoid that is a cat only in its ears and the flick of a tail.
fn brancusi(p: vec3f) -> f32 {
    let c = vec3f(0.0, 1.55, 0.0);
    var q = p - c;
    // bend the long axis into a curve
    q = vec3f(q.x, q.y + 0.15 * q.x * q.x - 0.05, q.z);
    var d = sd_ellipsoid(q, vec3f(1.15, 0.32, 0.26));
    d = smin(d, sd_ellipsoid(q - vec3f(1.0, 0.18, 0.0), vec3f(0.3, 0.24, 0.22)), 0.18);
    // two ear ridges and a tail that lifts off the far end
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        d = smin(d, sd_round_cone(q, vec3f(1.0, 0.3, s * 0.1), vec3f(0.98, 0.52, s * 0.15), 0.08, 0.012), 0.05);
    }
    d = smin(d, sd_capsule(q, vec3f(-1.05, 0.05, 0.0), vec3f(-1.45, 0.45 + 0.04 * sin(time() * 0.7), 0.0), 0.04), 0.1);
    return d * 0.85;
}

// ---- the dispatcher, normals, light
fn sdf(p: vec3f) -> f32 {
    let f = form();
    if (f == 0) { return gyroid_cat(p); }
    if (f == 1) { return umbilic(p); }
    if (f == 2) { return ribbon(p); }
    if (f == 4) { return asawa(p); }
    return brancusi(p);
}
fn nrm(p: vec3f) -> vec3f {
    let e = vec2f(0.002, 0.0);
    return normalize(vec3f(sdf(p + e.xyy) - sdf(p - e.xyy), sdf(p + e.yxy) - sdf(p - e.yxy), sdf(p + e.yyx) - sdf(p - e.yyx)));
}
fn bmin() -> vec3f {
    let f = form();
    if (f == 4) { return vec3f(-0.62, PLINTH_H + 0.3, -0.62); }
    if (f == 5) { return vec3f(-1.6, 1.0, -0.4); }
    if (f == 1) { return vec3f(-1.3, PLINTH_H, -1.3); }
    return vec3f(-1.75, PLINTH_H, -0.55);
}
fn bmax() -> vec3f {
    let f = form();
    if (f == 4) { return vec3f(0.62, ROOM_HEIGHT, 0.62); }
    if (f == 5) { return vec3f(1.55, 2.25, 0.4); }
    if (f == 1) { return vec3f(1.3, PLINTH_H + 1.25, 1.3); }
    return vec3f(1.75, PLINTH_H + 2.05, 0.55);
}
fn soft_shadow(p: vec3f) -> f32 {
    let l = normalize(LIGHT);
    let b = box_span(p, l, bmin(), bmax());
    if (b.x > b.y || b.y < 0.0 || form() == 3) { return 1.0; }
    var t = max(b.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 24; i = i + 1) {
        if (t > b.y) { break; }
        let h = sdf(p + l * t);
        res = min(res, 12.0 * h / t);
        if (res < 0.02) { break; }
        t += clamp(h, 0.01, 0.25);
    }
    return clamp(res, 0.0, 1.0);
}
fn env(r: vec3f) -> vec3f {
    // what a polished surface sees: the dark room, its ceiling light, two strips of the room's colour
    var c = vec3f(0.01, 0.01, 0.016) + vec3f(0.6) * smoothstep(0.9, 0.97, r.y);
    c += rim_col() * (smoothstep(0.06, 0.0, abs(r.y - 0.05)) * 0.9 + smoothstep(0.05, 0.0, abs(r.x - 0.7)) * 0.5);
    return c;
}

fn shade_form(p: vec3f, rd: vec3f) -> vec3f {
    let f = form();
    let n = nrm(p);
    let l = normalize(LIGHT);
    let diff = max(dot(n, l), 0.0) * (0.3 + 0.7 * soft_shadow(p + n * 0.01));
    let ao = clamp(0.4 + 0.6 * sdf(p + n * 0.06) / 0.06, 0.0, 1.0);
    let fres = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let r = reflect(rd, n);
    var base = mat_col();
    var col = vec3f(0.0);
    if (f == 0) {
        // patinated bronze: darker deep in the lattice
        col = base * (0.06 + diff * 1.2) * ao * ao + env(r) * base * 0.6 + rim_col() * fres * 0.5;
    } else if (f == 1) {
        // granite, the umbilic edge polished bright
        let grain = noise3(p * 40.0) * 0.5 + noise3(p * 9.0) * 0.5;
        let edge = smoothstep(0.92, 0.99, umbilic_edge(p));
        base = base * (0.7 + 0.5 * grain);
        col = base * (0.06 + diff) * ao + env(r) * (0.04 + edge * 0.5) + rim_col() * edge * 0.25 + rim_col() * fres * 0.3;
    } else if (f == 2) {
        // white marble with grey veins
        let vein = smoothstep(0.02, 0.0, abs(fbm3(p * 2.5) - 0.5));
        base = mix(base, base * 0.45, vein * 0.7);
        col = base * (0.1 + diff * 1.05) * ao + env(r) * 0.08 + rim_col() * fres * 0.4;
    } else if (f == 4) {
        // brass wire
        col = base * (0.1 + diff * 1.3) + env(r) * base * 0.8 + rim_col() * fres * 0.6;
    } else {
        // mirror-polished bronze
        col = env(r) * mix(base, vec3f(1.0), fres) * 1.2 + base * diff * 0.25;
    }
    return col;
}

// the room: dark floor with the form's shadow, a plinth, dark walls with a line of the room's light
fn background(ro: vec3f, rd: vec3f, tmax: f32) -> Hit {
    let f = form();
    let ph = select(PLINTH_H, 0.95, f == 5);
    let pw = select(vec2f(1.85, 0.75), vec2f(0.55, 0.55), f == 1 || f == 4 || f == 5);
    let pmin = vec3f(-pw.x, 0.0, -pw.y);
    let pmax = vec3f(pw.x, ph, pw.y);
    let pb = box_span(ro, rd, pmin, pmax);
    let tf = plane_y(ro, rd, 0.0);
    if (pb.x < pb.y && pb.x > 0.0 && (tf < 0.0 || pb.x < tf)) {
        let p = ro + rd * pb.x;
        var c = select(vec3f(0.012, 0.012, 0.018), vec3f(0.55, 0.52, 0.46) * (0.8 + 0.2 * noise3(p * 30.0)), f == 5);
        if (p.y > ph - 0.002) { c *= 0.35 + 0.65 * soft_shadow(p); }
        let top = p.y > ph - 0.002;
        // the edge line: round the top face, and along the top of each side
        let edge = select(ph - p.y, min(min(abs(p.x - pmin.x), abs(p.x - pmax.x)), min(abs(p.z - pmin.z), abs(p.z - pmax.z))), top);
        if (f != 5) { c += rim_col() * smoothstep(0.02, 0.0, edge) * 1.4; }
        return Hit(tone(c * (0.5 + 0.8 * max(dot(vec3f(0.0, 1.0, 0.0), normalize(LIGHT)), 0.0))), pb.x);
    }
    if (tf > 0.0 && tf <= tmax + 0.01) {
        let p = ro + rd * tf;
        var c = vec3f(0.02, 0.02, 0.028);
        let g = abs(fract(p.xz) - 0.5);
        c += vec3f(0.03, 0.035, 0.05) * smoothstep(0.485, 0.5, max(g.x, g.y));
        c += rim_col() * 0.1 * exp(-dot(p.xz, p.xz) * 0.25);
        c *= 0.35 + 0.65 * soft_shadow(p);
        return Hit(tone(c), tf);
    }
    let w = ro + rd * horizon_t(tmax);
    var c = vec3f(0.016, 0.015, 0.024);
    if (w.y > ROOM_HEIGHT - 0.05) {
        c = vec3f(0.01) + vec3f(0.6) * smoothstep(0.6, 0.0, length(w.xz)) ;
    } else {
        c += rim_col() * smoothstep(0.04, 0.0, abs(w.y - 0.06)) * 0.8;
    }
    return Hit(tone(c), horizon_t(tmax));
}

fn strings(ro: vec3f, rd: vec3f, bg: Hit) -> Hit {
    // threads between the plates, glowing so the thinnest still reads at a distance
    let shift = 5.0 + 4.0 * sin(time() * 0.12);
    var glow = vec3f(0.0);
    var near = bg.t;
    let px = 0.0016;
    for (var i = 0; i < 44; i = i + 1) {
        let s = f32(i) * f32(NP) / 44.0;
        let a2 = outline_at(s);
        let b2 = outline_at(s + shift);
        let h = ray_seg(ro, rd, vec3f(a2, 0.42), vec3f(b2, -0.42));
        if (h.y < bg.t) {
            let w = max(px * h.y, 0.004);
            let k = exp(-pow(h.x / w, 2.0));
            glow += mix(mat_col(), rim_col(), f32(i) / 44.0) * k;
            if (k > 0.5) { near = min(near, h.y); }
        }
    }
    // the plates' edges
    for (var i = 0; i < NP; i = i + 1) {
        for (var z = -1.0; z < 2.0; z = z + 2.0) {
            let h = ray_seg(ro, rd, vec3f(outline(i), z * 0.42), vec3f(outline(i + 1), z * 0.42));
            if (h.y < bg.t) {
                let w = max(px * h.y, 0.006);
                let k = exp(-pow(h.x / w, 2.0));
                glow += vec3f(0.7, 0.85, 1.0) * k * 0.7;
                if (k > 0.5) { near = min(near, h.y); }
            }
        }
    }
    return Hit(clamp(bg.color + glow, vec3f(0.0), vec3f(1.0)), near);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let f = form();
    let bg = background(ro, rd, tmax);
    if (f == 3) { return strings(ro, rd, bg); }
    let b = box_span(ro, rd, bmin(), bmax());
    if (b.x < b.y && b.y > tmin) {
        var t = max(b.x, tmin);
        let steps = select(80, 120, quality() > 0.6);
        let far = min(b.y, bg.t);
        for (var i = 0; i < 120; i = i + 1) {
            if (i >= steps || t > far) { break; }
            let d = sdf(ro + rd * t);
            if (d < 0.0008 * t + 0.001) { return Hit(tone(shade_form(ro + rd * t, rd) * 1.3), t); }
            t += d * select(0.9, 0.7, f == 0 || f == 4);
        }
    }
    return bg;
}

// Catoid Sweep: one knob, swept down a corridor of rooms, from Hot-dog Kitty to Jimothy.
// A catoid sculpted from signed distance fields (round cones, capsules, smooth unions) on a black
// plinth in a dark gallery, walking in place. param(0).x is where this room sits on the sweep (0 long
// and thin, 1 round), param(1) its coat, param(2) its rim light. Catoid week, the simcluster, Oct 2026.

const S: f32 = 1.35;                  // sculpture scale: catoid units to metres
const CAT_Z: f32 = -2.4;              // the plinth runs along the north side, the walk along the middle
const PLINTH_H: f32 = 0.3;

var<private> cL: f32;      // half body length
var<private> cR: f32;      // body radius
var<private> cLeg: f32;    // leg length
var<private> cHead: f32;   // head radius
var<private> cTail: f32;   // tail length
var<private> cH: f32;      // body height
var<private> cPh: f32;     // gait phase
var<private> mat: f32;     // 0 coat, 1 eye, 2 nose, 3 inner ear

fn sweep() -> f32 { return clamp(param(0u).x, 0.0, 1.0); }

fn set_cat() {
    let t = sweep();
    cL = mix(1.3, 0.3, t);
    cR = mix(0.19, 0.62, t);
    cLeg = mix(0.62, 0.24, t);
    cHead = mix(0.23, 0.33, t);
    cTail = mix(1.05, 0.5, t);
    cH = max(cLeg + cR * 0.5, cR + 0.1);
    cPh = time() * mix(4.2, 2.6, t);
}

// Inigo Quilez's ellipsoid bound.
fn sd_ellipsoid(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}

fn sd_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

// Inigo Quilez's round cone between two points.
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

fn head_c() -> vec3f { return vec3f(cL + cR * 0.45 + cHead * 0.75, cH + cR * 0.55 + cHead * 0.45, 0.0); }

// The catoid in its own units: x from tail to head, y up from the plinth, z across.
fn cat(p: vec3f) -> f32 {
    let t = sweep();
    // body: a round cone, chest a little higher, with a belly that sags as it gets round
    var d = sd_round_cone(p, vec3f(-cL, cH, 0.0), vec3f(cL, cH + 0.05, 0.0), cR, cR * 0.9);
    d = smin(d, sd_ellipsoid(p - vec3f(0.0, cH - cR * 0.2, 0.0), vec3f(cL * 0.85 + cR * 0.5, cR * 0.92, cR * 1.02)), 0.12);
    // legs walk in place: front and back pairs in counter-phase
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-1.0, 1.0, i < 2);
        let side = select(-1.0, 1.0, (i & 1) == 0);
        let ph = cPh + select(0.0, PI, (i == 1) || (i == 2));
        let hip = vec3f(fx * cL * 0.82, cH - cR * 0.2, side * max(cR * 0.55, 0.11));
        let swing = sin(ph) * cLeg * 0.32;
        let lift = max(cos(ph), 0.0) * cLeg * 0.14;
        let paw = vec3f(hip.x + swing, 0.075 + lift, hip.z);
        d = smin(d, sd_round_cone(p, paw, hip, 0.07, mix(0.1, 0.17, t)), 0.08);
        d = smin(d, sd_ellipsoid(p - paw - vec3f(0.035, -0.015, 0.0), vec3f(0.1, 0.06, 0.08)), 0.04);
    }
    // tail: six segments curling up and back, swishing
    var a = vec3f(-cL - cR * 0.6, cH + cR * 0.3, 0.0);
    var ang = 2.35;
    let seg = cTail / 6.0;
    for (var i = 0; i < 6; i = i + 1) {
        let fi = f32(i);
        ang = ang - 0.32 + sin(time() * 1.7 - fi * 0.7) * 0.12;
        let b = a + vec3f(cos(ang), sin(ang), sin(time() * 1.1 - fi * 0.5) * 0.06) * seg;
        d = smin(d, sd_capsule(p, a, b, mix(0.075, 0.035, fi / 5.0) * (1.0 + t * 0.6)), 0.05);
        a = b;
    }
    // head, cheeks, muzzle
    let hc = head_c() + vec3f(0.0, sin(cPh * 2.0) * 0.012, 0.0);
    var h = length(p - hc) - cHead;
    h = smin(h, sd_ellipsoid(p - hc - vec3f(0.02, -cHead * 0.28, 0.0), cHead * vec3f(0.8, 0.62, 1.08)), 0.06);
    let mz = hc + vec3f(cHead * 0.82, -cHead * 0.3, 0.0);
    h = smin(h, sd_ellipsoid(p - mz, cHead * vec3f(0.3, 0.26, 0.38)), 0.06);
    d = smin(d, h, 0.16);
    // ears: flattened round cones
    var ear = 1e5;
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let base = hc + vec3f(-cHead * 0.1, cHead * 0.62, s * cHead * 0.52);
        let tip = base + vec3f(-0.04, cHead * 0.72, s * cHead * 0.26);
        var q = p - base;
        q.x = q.x * 1.7;
        ear = min(ear, sd_round_cone(q, vec3f(0.0), (tip - base) * vec3f(1.7, 1.0, 1.0), cHead * 0.42, 0.02) / 1.7);
    }
    d = smin(d, ear, 0.03);
    // materials, by the nearest feature
    mat = 0.0;
    let eyeL = length(p - (hc + vec3f(cHead * 0.72, cHead * 0.18, cHead * 0.4))) - cHead * 0.16;
    let eyeR = length(p - (hc + vec3f(cHead * 0.72, cHead * 0.18, -cHead * 0.4))) - cHead * 0.16;
    if (min(eyeL, eyeR) < 0.012) { mat = 1.0; }
    if (length(p - (mz + vec3f(cHead * 0.24, cHead * 0.12, 0.0))) < cHead * 0.13) { mat = 2.0; }
    return d;
}

fn to_cat(p: vec3f) -> vec3f { return (p - vec3f(0.0, PLINTH_H, CAT_Z)) / S; }
fn cat_w(p: vec3f) -> f32 { return cat(to_cat(p)) * S; }

fn cat_n(p: vec3f) -> vec3f {
    let e = vec2f(0.004, 0.0);
    return normalize(vec3f(cat_w(p + e.xyy) - cat_w(p - e.xyy), cat_w(p + e.yxy) - cat_w(p - e.yxy), cat_w(p + e.yyx) - cat_w(p - e.yyx)));
}

fn cat_box_min() -> vec3f { return vec3f(-cL - cR - cTail - 0.15, 0.0, -cR - 0.45) * S + vec3f(0.0, PLINTH_H, CAT_Z); }
fn cat_box_max() -> vec3f { return vec3f(cL + cR + cHead * 2.6 + 0.1, cH + cR + cHead * 2.4 + max(cTail * 0.7, 0.4), cR + 0.45) * S + vec3f(0.0, PLINTH_H, CAT_Z); }

const LIGHT: vec3f = vec3f(0.35, 0.85, 0.4);

fn soft_shadow(p: vec3f) -> f32 {
    let l = normalize(LIGHT);
    let b = box_span(p, l, cat_box_min(), cat_box_max());
    if (b.x > b.y || b.y < 0.0) { return 1.0; }
    var t = max(b.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 20; i = i + 1) {
        if (t > b.y) { break; }
        let h = cat_w(p + l * t);
        res = min(res, 10.0 * h / t);
        if (res < 0.02) { break; }
        t += clamp(h, 0.03, 0.4);
    }
    return clamp(res, 0.0, 1.0);
}

fn rim_col() -> vec3f { return param(2u).rgb; }

fn shade_cat(p: vec3f, rd: vec3f) -> vec3f {
    let n = cat_n(p);
    let m = mat;
    let cp = to_cat(p);
    let t = sweep();
    // coat: tabby stripes across the back, a pale belly and muzzle
    var base = param(1u).rgb;
    let stripe = smoothstep(0.35, 0.6, sin(cp.x * mix(13.0, 7.0, t) + fbm3(cp * 3.0) * 2.4)) * smoothstep(-0.2, 0.4, n.y);
    base = mix(base, base * 0.35, stripe * 0.75);
    base = mix(base, vec3f(0.92, 0.88, 0.8), smoothstep(-0.25, -0.7, n.y) * 0.8);
    if (m == 1.0) { base = vec3f(0.05, 0.25, 0.12); }
    if (m == 2.0) { base = vec3f(0.85, 0.45, 0.5); }
    let l = normalize(LIGHT);
    let diff = max(dot(n, l), 0.0) * (0.35 + 0.65 * soft_shadow(p + n * 0.01));
    let ao = clamp(0.5 + 0.5 * cat_w(p + n * 0.12) / 0.12, 0.0, 1.0);
    let rim = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let back = max(dot(n, normalize(vec3f(-0.6, 0.3, -0.8))), 0.0);
    let spec = pow(max(dot(reflect(rd, n), l), 0.0), select(24.0, 90.0, m == 1.0)) * select(0.25, 1.2, m == 1.0);
    var col = base * (0.08 + diff * 1.1) * ao + rim_col() * (rim * 0.6 + back * 0.25) + vec3f(spec);
    return col;
}

fn led_wall(p: vec3f) -> vec3f {
    // the north wall: a dark field, faint grid, and the sweep as a bar of LEDs above the catoid
    var col = vec3f(0.018, 0.016, 0.03);
    let g = abs(fract(p.xy * 2.0) - 0.5);
    col += vec3f(0.02, 0.03, 0.05) * smoothstep(0.47, 0.5, max(g.x, g.y));
    if (abs(p.y - 3.75) < 0.12 && abs(p.x) < 4.0) {
        let cell = floor((p.x + 4.0) / 8.0 * 24.0);
        let lit = cell < floor(sweep() * 23.0 + 0.5) + 1.0;
        let f = fract((p.x + 4.0) / 8.0 * 24.0);
        let inside = step(0.12, f) * step(f, 0.88) * step(abs(p.y - 3.75), 0.085);
        let here = abs(cell - floor(sweep() * 23.0 + 0.5)) < 0.5;
        col = mix(col, select(rim_col() * 0.12, select(rim_col(), vec3f(1.0), here), lit), inside);
    }
    return col;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    set_cat();
    var best = tmax;
    var kind = 0; // 0 wall/ceiling, 1 floor, 2 plinth, 3 catoid
    // the catoid
    let cb = box_span(ro, rd, cat_box_min(), cat_box_max());
    if (cb.x < cb.y && cb.y > tmin) {
        var t = max(cb.x, tmin);
        let steps = select(60, 90, quality() > 0.6);
        for (var i = 0; i < 90; i = i + 1) {
            if (i >= steps || t > cb.y) { break; }
            let d = cat_w(ro + rd * t);
            if (d < 0.002 * t + 0.002) { best = t; kind = 3; break; }
            t += d * 0.9;
        }
    }
    // the plinth: black glass with a neon edge
    let pmin = vec3f(-4.4, 0.0, CAT_Z - 1.1);
    let pmax = vec3f(4.4, PLINTH_H, CAT_Z + 1.1);
    let pb = box_span(ro, rd, pmin, pmax);
    if (pb.x < pb.y && pb.x > tmin && pb.x < best) { best = pb.x; kind = 2; }
    let tf = plane_y(ro, rd, 0.0);
    if (tf > 0.0 && tf < best) { best = tf; kind = 1; }

    let p = ro + rd * best;
    if (kind == 3) {
        let c = shade_cat(p, rd);
        return Hit(tone(c * 1.3), best);
    }
    if (kind == 2) {
        var c = vec3f(0.012, 0.012, 0.018);
        let edge = min(min(abs(p.x - pmin.x), abs(p.x - pmax.x)), min(abs(p.z - pmin.z), abs(p.z - pmax.z)));
        let top = p.y > PLINTH_H - 0.002;
        if (top) {
            c += vec3f(0.05) * pow(max(dot(reflect(rd, vec3f(0.0, 1.0, 0.0)), normalize(LIGHT)), 0.0), 40.0);
            c *= 0.4 + 0.6 * soft_shadow(p);
            c += rim_col() * smoothstep(0.035, 0.0, edge) * 1.6;
        } else {
            c += rim_col() * smoothstep(0.02, 0.0, abs(p.y - PLINTH_H + 0.02)) * 1.2;
        }
        return Hit(tone(c), best);
    }
    if (kind == 1) {
        // polished dark floor, a lit pool by the plinth, a faint grid, the rim colour bleeding
        var c = vec3f(0.02, 0.02, 0.028);
        let g = abs(fract(p.xz * 1.0) - 0.5);
        c += vec3f(0.035, 0.04, 0.06) * smoothstep(0.485, 0.5, max(g.x, g.y));
        let pool = exp(-pow(max(abs(p.x) - 3.5, 0.0), 2.0) * 0.6 - pow(p.z - CAT_Z - 1.6, 2.0) * 0.9);
        c += rim_col() * pool * 0.12;
        c += vec3f(0.06) * pow(max(dot(reflect(rd, vec3f(0.0, 1.0, 0.0)), normalize(vec3f(0.0, 1.0, -0.4))), 0.0), 30.0);
        return Hit(tone(c), best);
    }
    // walls and ceiling: painted dark; the north wall carries the sweep
    let w = ro + rd * horizon_t(tmax);
    var c = vec3f(0.016, 0.015, 0.024);
    if (w.z < -ROOM_HALF + 0.05) { c = led_wall(w); }
    else if (w.y > ROOM_HEIGHT - 0.05) {
        // ceiling: a strip of light over the plinth
        c = vec3f(0.01) + vec3f(0.5) * smoothstep(0.25, 0.0, abs(w.z - CAT_Z)) * step(abs(w.x), 4.2);
    } else {
        // a neon line where the walls meet the floor
        c += rim_col() * smoothstep(0.04, 0.0, abs(w.y - 0.06)) * 0.8;
    }
    return Hit(tone(c), horizon_t(tmax));
}

// Catoid Sweep: one knob, swept down a corridor of rooms, from Hot-dog Kitty to Jimothy.
// A catoid sculpted from signed distance fields (round cones, capsules, smooth unions) on a black
// plinth in a dark gallery, walking in place. param(0).x is where this room sits on the sweep (0 long
// and thin, 1 round), param(1) its coat, param(2) its rim light. Catoid week, the simcluster, Oct 2026.

const S: f32 = 1.35;                  // sculpture scale: catoid units to metres
const CAT_Z: f32 = -2.4;              // the plinth runs along the north side, the walk along the middle
const PLINTH_H: f32 = 0.3;

var<private> cL: f32;      // half body length
var<private> cR: f32;      // body radius
var<private> cLeg: f32;    // leg length
var<private> cHead: f32;   // head radius
var<private> cTail: f32;   // tail length
var<private> cH: f32;      // body height
var<private> cPh: f32;     // gait phase
var<private> mat: f32;     // 0 coat, 1 eye, 2 nose, 3 inner ear

fn sweep() -> f32 { return clamp(param(0u).x, 0.0, 1.0); }

fn set_cat() {
    let t = sweep();
    cL = mix(1.3, 0.3, t);
    cR = mix(0.19, 0.62, t);
    cLeg = mix(0.62, 0.24, t);
    cHead = mix(0.23, 0.33, t);
    cTail = mix(1.05, 0.5, t);
    cH = max(cLeg + cR * 0.5, cR + 0.1);
    cPh = time() * mix(4.2, 2.6, t);
}

// Inigo Quilez's ellipsoid bound.
fn sd_ellipsoid(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}

fn sd_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

// Inigo Quilez's round cone between two points.
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

fn head_c() -> vec3f { return vec3f(cL + cR * 0.45 + cHead * 0.75, cH + cR * 0.55 + cHead * 0.45, 0.0); }

// The catoid in its own units: x from tail to head, y up from the plinth, z across.
fn cat(p: vec3f) -> f32 {
    let t = sweep();
    // body: a round cone, chest a little higher, with a belly that sags as it gets round
    var d = sd_round_cone(p, vec3f(-cL, cH, 0.0), vec3f(cL, cH + 0.05, 0.0), cR, cR * 0.9);
    d = smin(d, sd_ellipsoid(p - vec3f(0.0, cH - cR * 0.2, 0.0), vec3f(cL * 0.85 + cR * 0.5, cR * 0.92, cR * 1.02)), 0.12);
    // legs walk in place: front and back pairs in counter-phase
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-1.0, 1.0, i < 2);
        let side = select(-1.0, 1.0, (i & 1) == 0);
        let ph = cPh + select(0.0, PI, (i == 1) || (i == 2));
        let hip = vec3f(fx * cL * 0.82, cH - cR * 0.2, side * max(cR * 0.55, 0.11));
        let swing = sin(ph) * cLeg * 0.32;
        let lift = max(cos(ph), 0.0) * cLeg * 0.14;
        let paw = vec3f(hip.x + swing, 0.075 + lift, hip.z);
        d = smin(d, sd_round_cone(p, paw, hip, 0.07, mix(0.1, 0.17, t)), 0.08);
        d = smin(d, sd_ellipsoid(p - paw - vec3f(0.035, -0.015, 0.0), vec3f(0.1, 0.06, 0.08)), 0.04);
    }
    // tail: six segments curling up and back, swishing
    var a = vec3f(-cL - cR * 0.6, cH + cR * 0.3, 0.0);
    var ang = 2.35;
    let seg = cTail / 6.0;
    for (var i = 0; i < 6; i = i + 1) {
        let fi = f32(i);
        ang = ang - 0.32 + sin(time() * 1.7 - fi * 0.7) * 0.12;
        let b = a + vec3f(cos(ang), sin(ang), sin(time() * 1.1 - fi * 0.5) * 0.06) * seg;
        d = smin(d, sd_capsule(p, a, b, mix(0.075, 0.035, fi / 5.0) * (1.0 + t * 0.6)), 0.05);
        a = b;
    }
    // head, cheeks, muzzle
    let hc = head_c() + vec3f(0.0, sin(cPh * 2.0) * 0.012, 0.0);
    var h = length(p - hc) - cHead;
    h = smin(h, sd_ellipsoid(p - hc - vec3f(0.02, -cHead * 0.28, 0.0), cHead * vec3f(0.8, 0.62, 1.08)), 0.06);
    let mz = hc + vec3f(cHead * 0.82, -cHead * 0.3, 0.0);
    h = smin(h, sd_ellipsoid(p - mz, cHead * vec3f(0.3, 0.26, 0.38)), 0.06);
    d = smin(d, h, 0.16);
    // ears: flattened round cones
    var ear = 1e5;
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let base = hc + vec3f(-cHead * 0.1, cHead * 0.62, s * cHead * 0.52);
        let tip = base + vec3f(-0.04, cHead * 0.72, s * cHead * 0.26);
        var q = p - base;
        q.x = q.x * 1.7;
        ear = min(ear, sd_round_cone(q, vec3f(0.0), (tip - base) * vec3f(1.7, 1.0, 1.0), cHead * 0.42, 0.02) / 1.7);
    }
    d = smin(d, ear, 0.03);
    // materials, by the nearest feature
    mat = 0.0;
    let eyeL = length(p - (hc + vec3f(cHead * 0.72, cHead * 0.18, cHead * 0.4))) - cHead * 0.16;
    let eyeR = length(p - (hc + vec3f(cHead * 0.72, cHead * 0.18, -cHead * 0.4))) - cHead * 0.16;
    if (min(eyeL, eyeR) < 0.012) { mat = 1.0; }
    if (length(p - (mz + vec3f(cHead * 0.24, cHead * 0.12, 0.0))) < cHead * 0.13) { mat = 2.0; }
    return d;
}

fn to_cat(p: vec3f) -> vec3f { return (p - vec3f(0.0, PLINTH_H, CAT_Z)) / S; }
fn cat_w(p: vec3f) -> f32 { return cat(to_cat(p)) * S; }

fn cat_n(p: vec3f) -> vec3f {
    let e = vec2f(0.004, 0.0);
    return normalize(vec3f(cat_w(p + e.xyy) - cat_w(p - e.xyy), cat_w(p + e.yxy) - cat_w(p - e.yxy), cat_w(p + e.yyx) - cat_w(p - e.yyx)));
