fn cat_box_min() -> vec3f { return vec3f(-cL - cR - cTail - 0.15, 0.0, -cR - 0.45) * S + vec3f(0.0, PLINTH_H, CAT_Z); }
fn cat_box_max() -> vec3f { return vec3f(cL + cR + cHead * 2.6 + 0.1, cH + cR + cHead * 2.4 + max(cTail * 0.7, 0.4), cR + 0.45) * S + vec3f(0.0, PLINTH_H, CAT_Z); }

const LIGHT: vec3f = vec3f(0.35, 0.85, 0.4);

fn soft_shadow(p: vec3f) -> f32 {
    let l = normalize(LIGHT);
    let b = box_span(p, l, cat_box_min(), cat_box_max());
    if (b.x > b.y || b.y < 0.0) { return 1.0; }
    var t = max(b.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 20; i = i + 1) {
        if (t > b.y) { break; }
        let h = cat_w(p + l * t);
        res = min(res, 10.0 * h / t);
        if (res < 0.02) { break; }
        t += clamp(h, 0.03, 0.4);
    }
    return clamp(res, 0.0, 1.0);
}

fn rim_col() -> vec3f { return param(2u).rgb; }

fn shade_cat(p: vec3f, rd: vec3f) -> vec3f {
    let n = cat_n(p);
    let m = mat;
    let cp = to_cat(p);
    let t = sweep();
    // coat: tabby stripes across the back, a pale belly and muzzle
    var base = param(1u).rgb;
    let stripe = smoothstep(0.35, 0.6, sin(cp.x * mix(13.0, 7.0, t) + fbm3(cp * 3.0) * 2.4)) * smoothstep(-0.2, 0.4, n.y);
    base = mix(base, base * 0.35, stripe * 0.75);
    base = mix(base, vec3f(0.92, 0.88, 0.8), smoothstep(-0.25, -0.7, n.y) * 0.8);
    if (m == 1.0) { base = vec3f(0.05, 0.25, 0.12); }
    if (m == 2.0) { base = vec3f(0.85, 0.45, 0.5); }
    let l = normalize(LIGHT);
    let diff = max(dot(n, l), 0.0) * (0.35 + 0.65 * soft_shadow(p + n * 0.01));
    let ao = clamp(0.5 + 0.5 * cat_w(p + n * 0.12) / 0.12, 0.0, 1.0);
    let rim = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let back = max(dot(n, normalize(vec3f(-0.6, 0.3, -0.8))), 0.0);
    let spec = pow(max(dot(reflect(rd, n), l), 0.0), select(24.0, 90.0, m == 1.0)) * select(0.25, 1.2, m == 1.0);
    var col = base * (0.08 + diff * 1.1) * ao + rim_col() * (rim * 0.6 + back * 0.25) + vec3f(spec);
    return col;
}

fn led_wall(p: vec3f) -> vec3f {
    // the north wall: a dark field, faint grid, and the sweep as a bar of LEDs above the catoid
    var col = vec3f(0.018, 0.016, 0.03);
    let g = abs(fract(p.xy * 2.0) - 0.5);
    col += vec3f(0.02, 0.03, 0.05) * smoothstep(0.47, 0.5, max(g.x, g.y));
    if (abs(p.y - 3.75) < 0.12 && abs(p.x) < 4.0) {
        let cell = floor((p.x + 4.0) / 8.0 * 24.0);
        let lit = cell < floor(sweep() * 23.0 + 0.5) + 1.0;
        let f = fract((p.x + 4.0) / 8.0 * 24.0);
        let inside = step(0.12, f) * step(f, 0.88) * step(abs(p.y - 3.75), 0.085);
        let here = abs(cell - floor(sweep() * 23.0 + 0.5)) < 0.5;
        col = mix(col, select(rim_col() * 0.12, select(rim_col(), vec3f(1.0), here), lit), inside);
    }
    return col;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    set_cat();
    var best = tmax;
    var kind = 0; // 0 wall/ceiling, 1 floor, 2 plinth, 3 catoid
    // the catoid
    let cb = box_span(ro, rd, cat_box_min(), cat_box_max());
    if (cb.x < cb.y && cb.y > tmin) {
        var t = max(cb.x, tmin);
        let steps = select(60, 90, quality() > 0.6);
        for (var i = 0; i < 90; i = i + 1) {
            if (i >= steps || t > cb.y) { break; }
            let d = cat_w(ro + rd * t);
            if (d < 0.002 * t + 0.002) { best = t; kind = 3; break; }
            t += d * 0.9;
        }
    }
    // the plinth: black glass with a neon edge
    let pmin = vec3f(-4.4, 0.0, CAT_Z - 1.1);
    let pmax = vec3f(4.4, PLINTH_H, CAT_Z + 1.1);
    let pb = box_span(ro, rd, pmin, pmax);
    if (pb.x < pb.y && pb.x > tmin && pb.x < best) { best = pb.x; kind = 2; }
    let tf = plane_y(ro, rd, 0.0);
    if (tf > 0.0 && tf < best) { best = tf; kind = 1; }

    let p = ro + rd * best;
    if (kind == 3) {
        let c = shade_cat(p, rd);
        return Hit(tone(c * 1.3), best);
    }
    if (kind == 2) {
        var c = vec3f(0.012, 0.012, 0.018);
        let edge = min(min(abs(p.x - pmin.x), abs(p.x - pmax.x)), min(abs(p.z - pmin.z), abs(p.z - pmax.z)));
        let top = p.y > PLINTH_H - 0.002;
        if (top) {
            c += vec3f(0.05) * pow(max(dot(reflect(rd, vec3f(0.0, 1.0, 0.0)), normalize(LIGHT)), 0.0), 40.0);
            c *= 0.4 + 0.6 * soft_shadow(p);
            c += rim_col() * smoothstep(0.035, 0.0, edge) * 1.6;
        } else {
            c += rim_col() * smoothstep(0.02, 0.0, abs(p.y - PLINTH_H + 0.02)) * 1.2;
        }
        return Hit(tone(c), best);
    }
    if (kind == 1) {
        // polished dark floor, a lit pool by the plinth, a faint grid, the rim colour bleeding
        var c = vec3f(0.02, 0.02, 0.028);
        let g = abs(fract(p.xz * 1.0) - 0.5);
        c += vec3f(0.035, 0.04, 0.06) * smoothstep(0.485, 0.5, max(g.x, g.y));
        let pool = exp(-pow(max(abs(p.x) - 3.5, 0.0), 2.0) * 0.6 - pow(p.z - CAT_Z - 1.6, 2.0) * 0.9);
        c += rim_col() * pool * 0.12;
        c += vec3f(0.06) * pow(max(dot(reflect(rd, vec3f(0.0, 1.0, 0.0)), normalize(vec3f(0.0, 1.0, -0.4))), 0.0), 30.0);
        return Hit(tone(c), best);
    }
    // walls and ceiling: painted dark; the north wall carries the sweep
    let w = ro + rd * horizon_t(tmax);
    var c = vec3f(0.016, 0.015, 0.024);
    if (w.z < -ROOM_HALF + 0.05) { c = led_wall(w); }
    else if (w.y > ROOM_HEIGHT - 0.05) {
        // ceiling: a strip of light over the plinth
        c = vec3f(0.01) + vec3f(0.5) * smoothstep(0.25, 0.0, abs(w.z - CAT_Z)) * step(abs(w.x), 4.2);
    } else {
        // a neon line where the walls meet the floor
        c += rim_col() * smoothstep(0.04, 0.0, abs(w.y - 0.06)) * 0.8;
    }
    return Hit(tone(c), horizon_t(tmax));
}

// Catoid Forms: the catoid in six schools of mathematical sculpture. param(0).x picks the form:
//   0 gyroid lattice (after Bathsheba Grossman)      1 umbilic torus, curled asleep (after Helaman Ferguson)
//   2 endless ribbon, a one-sided cat (after Max Bill) 3 linear construction in string (after Naum Gabo)
//   4 hanging looped-wire lobes (after Ruth Asawa)    5 a polished form in space (after Constantin Brancusi)
// param(1) is the material colour, param(2) the room's light. Catoid week, the simcluster, Oct 2026.

const PLINTH_H: f32 = 0.5;
const LIGHT: vec3f = vec3f(0.3, 0.9, 0.35);

fn form() -> i32 { return i32(param(0u).x + 0.5); }
fn mat_col() -> vec3f { return param(1u).rgb; }
fn rim_col() -> vec3f { return param(2u).rgb; }

fn sd_ellipsoid(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}
fn sd_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

// A cat's head with ears and muzzle, facing +x, centred at c (shared by several forms).
fn cat_head(p: vec3f, c: vec3f, r: f32) -> f32 {
    var h = length(p - c) - r;
    h = smin(h, sd_ellipsoid(p - c - vec3f(0.02, -r * 0.28, 0.0), r * vec3f(0.8, 0.62, 1.08)), r * 0.25);
    h = smin(h, sd_ellipsoid(p - c - vec3f(r * 0.82, -r * 0.3, 0.0), r * vec3f(0.3, 0.26, 0.38)), r * 0.25);
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let base = c + vec3f(-r * 0.1, r * 0.62, s * r * 0.52);
        var q = p - base;
        q.x = q.x * 1.7;
        h = smin(h, sd_round_cone(q, vec3f(0.0), vec3f(-0.07, r * 0.72, s * r * 0.26), r * 0.42, r * 0.06) / 1.7, r * 0.12);
    }
    return h;
}

// ---- 0: the gyroid catoid. A standing cat, its volume replaced by a gyroid sheet that drifts through it.
fn cat_body(p: vec3f) -> f32 {
    // the sweet-spot proportions of the Catoid Sweep, standing on the plinth, 1.15 m to a catoid unit
    let q = (p - vec3f(0.0, PLINTH_H, 0.0)) / 1.15;
    let L = 0.75; let R = 0.38; let leg = 0.45; let H = leg + R * 0.5;
    var d = sd_round_cone(q, vec3f(-L, H, 0.0), vec3f(L, H + 0.05, 0.0), R, R * 0.9);
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-1.0, 1.0, i < 2);
        let side = select(-1.0, 1.0, (i & 1) == 0);
        let hip = vec3f(fx * L * 0.8, H - R * 0.2, side * R * 0.55);
        d = smin(d, sd_round_cone(q, vec3f(hip.x + 0.04, 0.07, hip.z), hip, 0.07, 0.13), 0.08);
    }
    var a = vec3f(-L - R * 0.6, H + R * 0.3, 0.0);
    var ang = 2.35;
    for (var i = 0; i < 5; i = i + 1) {
        ang = ang - 0.36 + sin(time() * 0.9 - f32(i) * 0.7) * 0.1;
        let b = a + vec3f(cos(ang), sin(ang), 0.0) * 0.17;
        d = smin(d, sd_capsule(q, a, b, mix(0.07, 0.04, f32(i) / 4.0)), 0.05);
        a = b;
    }
    d = smin(d, cat_head(q, vec3f(L + R * 0.45 + 0.21, H + R * 0.55 + 0.13, 0.0), 0.28), 0.14);
    return d * 1.15;
}
fn gyroid_cat(p: vec3f) -> f32 {
    let k = 12.0;
    let q = p * k + vec3f(0.0, time() * 0.25, time() * 0.1);
    let g = abs(sin(q.x) * cos(q.y) + sin(q.y) * cos(q.z) + sin(q.z) * cos(q.x)) / k * 0.55 - 0.014;
    return max(cat_body(p), g);
}

// ---- 1: the umbilic catoid. Curled asleep: a torus whose three-lobed section turns a third of a turn
// on the way round, so one edge runs round it three times, with the head tucked onto the coil.
fn umbilic(p: vec3f) -> f32 {
    let c = vec3f(0.0, PLINTH_H + 0.42, 0.0);
    let q = p - c;
    let th = atan2(q.z, q.x);
    let breathe = 1.0 + 0.012 * sin(time() * 1.3);
    let Rm = 0.78 * breathe;
    var s = vec2f(length(q.xz) - Rm, q.y);
    let tw = th / 3.0 + time() * 0.05;
    s = rot2(tw) * s;
    let ph = atan2(s.y, s.x);
    let r = 0.36 * breathe * (1.0 + 0.2 * cos(3.0 * ph));
    var d = (length(s) - r) * 0.8;
    // the head rests on the coil, nose towards the tail
    let hc = c + vec3f(cos(0.5) * Rm, 0.42, sin(0.5) * Rm);
    let hp = p - hc;
    let hr = vec3f(rot2(-0.5 - PI * 0.5) * hp.xz, hp.y);
    d = smin(d, cat_head(vec3f(hr.x, hr.z, hr.y), vec3f(0.0), 0.36), 0.1);
    return d;
}
fn umbilic_edge(p: vec3f) -> f32 {
    let q = p - vec3f(0.0, PLINTH_H + 0.42, 0.0);
    let th = atan2(q.z, q.x);
    var s = rot2(th / 3.0 + time() * 0.05) * vec2f(length(q.xz) - 0.78, q.y);
    return cos(3.0 * atan2(s.y, s.x));
}

// ---- 2: the endless-ribbon catoid. A cat whose body is a Möbius band: back, belly and back again, one side.
fn ribbon(p: vec3f) -> f32 {
    let c = vec3f(0.0, PLINTH_H + 1.05, 0.0);
    var q = p - c;
    q.x = q.x / 1.55;
    let th = atan2(q.y, q.x);
    var s = vec2f(length(q.xy) - 0.62, q.z);
    s = rot2(th * 0.5 + time() * 0.08) * s;
    let band = vec2f(0.3, 0.028);
    let e = abs(s) - band;
    var d = (length(max(e, vec2f(0.0))) + min(max(e.x, e.y), 0.0) - 0.01) * 0.62;
    // legs down to the plinth, head and tail out of the band
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-0.55, 0.55, i < 2);
        let side = select(-0.14, 0.14, (i & 1) == 0);
        d = min(d, sd_round_cone(p, vec3f(fx + 0.03, PLINTH_H + 0.06, side), vec3f(fx, PLINTH_H + 0.62, side), 0.055, 0.08));
    }
    d = smin(d, cat_head(p, c + vec3f(1.12, 0.38, 0.0), 0.27), 0.1);
    d = smin(d, sd_capsule(p, c + vec3f(-0.98, 0.1, 0.0), c + vec3f(-1.35, 0.75 + 0.06 * sin(time()), 0.0), 0.045), 0.06);
    return d;
}

// ---- 3: the linear construction. Two perspex plates cut to a cat's outline, strung with taut threads
// from each point of one to a point further round the other: a ruled surface that twists as the shift drifts.
const NP: i32 = 24;
fn outline(i: i32) -> vec2f {
    // a standing cat in profile, clockwise from the tip of the tail, metres
    var pts = array<vec2f, 24>(
        vec2f(-1.45, 1.6), vec2f(-1.28, 1.08), vec2f(-1.05, 0.98), vec2f(-0.45, 1.02), vec2f(0.25, 1.04),
        vec2f(0.68, 1.12), vec2f(0.84, 1.38), vec2f(0.84, 1.66), vec2f(0.92, 1.9), vec2f(1.04, 1.7),
        vec2f(1.17, 1.88), vec2f(1.22, 1.62), vec2f(1.45, 1.43), vec2f(1.3, 1.28), vec2f(1.0, 1.18),
        vec2f(0.86, 0.9), vec2f(0.8, 0.0), vec2f(0.6, 0.0), vec2f(0.58, 0.68), vec2f(-0.6, 0.68),
        vec2f(-0.68, 0.0), vec2f(-0.9, 0.0), vec2f(-1.02, 0.82), vec2f(-1.3, 1.12));
    return pts[((i % NP) + NP) % NP] + vec2f(0.0, PLINTH_H + 0.06);
}
fn outline_at(s: f32) -> vec2f {
    let f = fract(s / f32(NP)) * f32(NP);
    let i = i32(floor(f));
    return mix(outline(i), outline(i + 1), fract(f));
}
// distance between the ray and segment a-b, and the ray distance there
fn ray_seg(ro: vec3f, rd: vec3f, a: vec3f, b: vec3f) -> vec2f {
    let ba = b - a;
    let oa = ro - a;
    let bb = dot(ba, ba);
    let rb = dot(rd, ba);
    let den = bb - rb * rb;
    var u = clamp((dot(oa, ba) - dot(oa, rd) * rb) / max(den, 1e-6), 0.0, 1.0);
    let t = max(dot(a + ba * u - ro, rd), 0.0);
    u = clamp(dot(ro + rd * t - a, ba) / bb, 0.0, 1.0);
    return vec2f(length(ro + rd * t - (a + ba * u)), t);
}

// ---- 4: looped wire. A sitting cat as lobes of woven brass, one inside another, hung from the ceiling.
fn lobe_r(y: f32) -> f32 {
    // the sitting cat's radius at height y: haunches, waist, chest, neck, head
    let base = PLINTH_H + 0.35;
    let h = y - base;
    var r = 0.52 * exp(-pow((h - 0.25) / 0.32, 2.0));
    r = max(r, 0.38 * exp(-pow((h - 0.85) / 0.28, 2.0)));
    r = max(r, 0.3 * exp(-pow((h - 1.45) / 0.2, 2.0)));
    return r;
}
fn wire_shell(p: vec3f, scale: f32) -> f32 {
    let c = vec3f(0.0, 0.0, 0.0);
    let r = lobe_r(p.y) * scale;
    let th = atan2(p.z, p.x);
    // ears: the head lobe rises into two points
    let ear = select(0.0, max(cos(th * 2.0), 0.0) * 0.18 * smoothstep(1.55, 1.75, p.y - PLINTH_H - 0.35 + 0.35), scale > 0.9);
    let shell = abs(length(p.xz - c.xz) - r) - 0.006;
    let top = PLINTH_H + 0.35 + 1.72 + ear;
    let bounded = max(shell, max(p.y - top, PLINTH_H + 0.36 - p.y));
    // a diamond weave: two helical families of wire
    let u = th * 8.0 / PI;
    let v = p.y * 9.0;
    let w1 = abs(fract(u + v) - 0.5);
    let w2 = abs(fract(u - v) - 0.5);
    let weave = (min(w1, w2) - 0.06) / 11.0 * max(r, 0.08) * 3.0;
    return max(bounded, weave);
}
fn asawa(p: vec3f) -> f32 {
    var d = wire_shell(p, 1.0);
    d = min(d, wire_shell(p, 0.55));
    d = min(d, sd_capsule(p, vec3f(0.0, PLINTH_H + 2.05, 0.0), vec3f(0.0, ROOM_HEIGHT, 0.0), 0.006));
    // ears: two triangles of the same wire on the head lobe
    let hy = PLINTH_H + 0.35 + 1.5;
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let a = vec3f(0.0, hy + 0.12, s * 0.08);
        let b = vec3f(0.0, hy + 0.08, s * 0.26);
        let t = vec3f(0.03, hy + 0.42, s * 0.22);
        d = min(d, min(sd_capsule(p, a, t, 0.007), min(sd_capsule(p, b, t, 0.007), sd_capsule(p, a, b, 0.007))));
    }
    // a tail of wire wrapped round the haunches, its tip lifting
    var prev = vec3f(-0.5, PLINTH_H + 0.45, 0.0);
    for (var i = 1; i < 9; i = i + 1) {
        let a = PI + f32(i) * 0.38;
        let next = vec3f(cos(a) * 0.56, PLINTH_H + 0.45 + f32(i) * f32(i) * 0.006 + sin(time() * 1.2) * 0.01 * f32(i), -sin(a) * 0.56);
        d = min(d, sd_capsule(p, prev, next, 0.014));
        prev = next;
    }
    return d;
}

// ---- 5: a form in space. One bent, polished ovoid that is a cat only in its ears and the flick of a tail.
fn brancusi(p: vec3f) -> f32 {
    let c = vec3f(0.0, 1.55, 0.0);
    var q = p - c;
    // bend the long axis into a curve
    q = vec3f(q.x, q.y + 0.15 * q.x * q.x - 0.05, q.z);
    var d = sd_ellipsoid(q, vec3f(1.15, 0.32, 0.26));
    d = smin(d, sd_ellipsoid(q - vec3f(1.0, 0.18, 0.0), vec3f(0.3, 0.24, 0.22)), 0.18);
    // two ear ridges and a tail that lifts off the far end
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        d = smin(d, sd_round_cone(q, vec3f(1.0, 0.3, s * 0.1), vec3f(0.98, 0.52, s * 0.15), 0.08, 0.012), 0.05);
    }
    d = smin(d, sd_capsule(q, vec3f(-1.05, 0.05, 0.0), vec3f(-1.45, 0.45 + 0.04 * sin(time() * 0.7), 0.0), 0.04), 0.1);
    return d * 0.85;
}

// ---- the dispatcher, normals, light
fn sdf(p: vec3f) -> f32 {
    let f = form();
    if (f == 0) { return gyroid_cat(p); }
    if (f == 1) { return umbilic(p); }
    if (f == 2) { return ribbon(p); }
    if (f == 4) { return asawa(p); }
    return brancusi(p);
}
fn nrm(p: vec3f) -> vec3f {
    let e = vec2f(0.002, 0.0);
    return normalize(vec3f(sdf(p + e.xyy) - sdf(p - e.xyy), sdf(p + e.yxy) - sdf(p - e.yxy), sdf(p + e.yyx) - sdf(p - e.yyx)));
}
fn bmin() -> vec3f {
    let f = form();
    if (f == 4) { return vec3f(-0.62, PLINTH_H + 0.3, -0.62); }
    if (f == 5) { return vec3f(-1.6, 1.0, -0.4); }
    if (f == 1) { return vec3f(-1.3, PLINTH_H, -1.3); }
    return vec3f(-1.75, PLINTH_H, -0.55);
}
fn bmax() -> vec3f {
    let f = form();
    if (f == 4) { return vec3f(0.62, ROOM_HEIGHT, 0.62); }
    if (f == 5) { return vec3f(1.55, 2.25, 0.4); }
    if (f == 1) { return vec3f(1.3, PLINTH_H + 1.25, 1.3); }
    return vec3f(1.75, PLINTH_H + 2.05, 0.55);
}
fn soft_shadow(p: vec3f) -> f32 {
    let l = normalize(LIGHT);
    let b = box_span(p, l, bmin(), bmax());
    if (b.x > b.y || b.y < 0.0 || form() == 3) { return 1.0; }
    var t = max(b.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 24; i = i + 1) {
        if (t > b.y) { break; }
        let h = sdf(p + l * t);
        res = min(res, 12.0 * h / t);
        if (res < 0.02) { break; }
        t += clamp(h, 0.01, 0.25);
    }
    return clamp(res, 0.0, 1.0);
}
fn env(r: vec3f) -> vec3f {
    // what a polished surface sees: the dark room, its ceiling light, two strips of the room's colour
    var c = vec3f(0.01, 0.01, 0.016) + vec3f(0.6) * smoothstep(0.9, 0.97, r.y);
    c += rim_col() * (smoothstep(0.06, 0.0, abs(r.y - 0.05)) * 0.9 + smoothstep(0.05, 0.0, abs(r.x - 0.7)) * 0.5);
    return c;
}

fn shade_form(p: vec3f, rd: vec3f) -> vec3f {
    let f = form();
    let n = nrm(p);
    let l = normalize(LIGHT);
    let diff = max(dot(n, l), 0.0) * (0.3 + 0.7 * soft_shadow(p + n * 0.01));
    let ao = clamp(0.4 + 0.6 * sdf(p + n * 0.06) / 0.06, 0.0, 1.0);
    let fres = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let r = reflect(rd, n);
    var base = mat_col();
    var col = vec3f(0.0);
    if (f == 0) {
        // patinated bronze: darker deep in the lattice
        col = base * (0.06 + diff * 1.2) * ao * ao + env(r) * base * 0.6 + rim_col() * fres * 0.5;
    } else if (f == 1) {
        // granite, the umbilic edge polished bright
        let grain = noise3(p * 40.0) * 0.5 + noise3(p * 9.0) * 0.5;
        let edge = smoothstep(0.92, 0.99, umbilic_edge(p));
        base = base * (0.7 + 0.5 * grain);
        col = base * (0.06 + diff) * ao + env(r) * (0.04 + edge * 0.5) + rim_col() * edge * 0.25 + rim_col() * fres * 0.3;
    } else if (f == 2) {
        // white marble with grey veins
        let vein = smoothstep(0.02, 0.0, abs(fbm3(p * 2.5) - 0.5));
        base = mix(base, base * 0.45, vein * 0.7);
        col = base * (0.1 + diff * 1.05) * ao + env(r) * 0.08 + rim_col() * fres * 0.4;
    } else if (f == 4) {
        // brass wire
        col = base * (0.1 + diff * 1.3) + env(r) * base * 0.8 + rim_col() * fres * 0.6;
    } else {
        // mirror-polished bronze
        col = env(r) * mix(base, vec3f(1.0), fres) * 1.2 + base * diff * 0.25;
    }
    return col;
}

// the room: dark floor with the form's shadow, a plinth, dark walls with a line of the room's light
fn background(ro: vec3f, rd: vec3f, tmax: f32) -> Hit {
    let f = form();
    let ph = select(PLINTH_H, 0.95, f == 5);
    let pw = select(vec2f(1.85, 0.75), vec2f(0.55, 0.55), f == 1 || f == 4 || f == 5);
    let pmin = vec3f(-pw.x, 0.0, -pw.y);
    let pmax = vec3f(pw.x, ph, pw.y);
    let pb = box_span(ro, rd, pmin, pmax);
    let tf = plane_y(ro, rd, 0.0);
    if (pb.x < pb.y && pb.x > 0.0 && (tf < 0.0 || pb.x < tf)) {
        let p = ro + rd * pb.x;
        var c = select(vec3f(0.012, 0.012, 0.018), vec3f(0.55, 0.52, 0.46) * (0.8 + 0.2 * noise3(p * 30.0)), f == 5);
        if (p.y > ph - 0.002) { c *= 0.35 + 0.65 * soft_shadow(p); }
        let top = p.y > ph - 0.002;
        // the edge line: round the top face, and along the top of each side
        let edge = select(ph - p.y, min(min(abs(p.x - pmin.x), abs(p.x - pmax.x)), min(abs(p.z - pmin.z), abs(p.z - pmax.z))), top);
        if (f != 5) { c += rim_col() * smoothstep(0.02, 0.0, edge) * 1.4; }
        return Hit(tone(c * (0.5 + 0.8 * max(dot(vec3f(0.0, 1.0, 0.0), normalize(LIGHT)), 0.0))), pb.x);
    }
    if (tf > 0.0 && tf <= tmax + 0.01) {
        let p = ro + rd * tf;
        var c = vec3f(0.02, 0.02, 0.028);
        let g = abs(fract(p.xz) - 0.5);
        c += vec3f(0.03, 0.035, 0.05) * smoothstep(0.485, 0.5, max(g.x, g.y));
        c += rim_col() * 0.1 * exp(-dot(p.xz, p.xz) * 0.25);
        c *= 0.35 + 0.65 * soft_shadow(p);
        return Hit(tone(c), tf);
    }
    let w = ro + rd * horizon_t(tmax);
    var c = vec3f(0.016, 0.015, 0.024);
    if (w.y > ROOM_HEIGHT - 0.05) {
        c = vec3f(0.01) + vec3f(0.6) * smoothstep(0.6, 0.0, length(w.xz)) ;
    } else {
        c += rim_col() * smoothstep(0.04, 0.0, abs(w.y - 0.06)) * 0.8;
    }
    return Hit(tone(c), horizon_t(tmax));
}

fn strings(ro: vec3f, rd: vec3f, bg: Hit) -> Hit {
    // threads between the plates, glowing so the thinnest still reads at a distance
    let shift = 5.0 + 4.0 * sin(time() * 0.12);
    var glow = vec3f(0.0);
    var near = bg.t;
    let px = 0.0016;
    for (var i = 0; i < 44; i = i + 1) {
        let s = f32(i) * f32(NP) / 44.0;
        let a2 = outline_at(s);
        let b2 = outline_at(s + shift);
        let h = ray_seg(ro, rd, vec3f(a2, 0.42), vec3f(b2, -0.42));
        if (h.y < bg.t) {
            let w = max(px * h.y, 0.004);
            let k = exp(-pow(h.x / w, 2.0));
            glow += mix(mat_col(), rim_col(), f32(i) / 44.0) * k;
            if (k > 0.5) { near = min(near, h.y); }
        }
    }
    // the plates' edges
    for (var i = 0; i < NP; i = i + 1) {
        for (var z = -1.0; z < 2.0; z = z + 2.0) {
            let h = ray_seg(ro, rd, vec3f(outline(i), z * 0.42), vec3f(outline(i + 1), z * 0.42));
            if (h.y < bg.t) {
                let w = max(px * h.y, 0.006);
                let k = exp(-pow(h.x / w, 2.0));
                glow += vec3f(0.7, 0.85, 1.0) * k * 0.7;
                if (k > 0.5) { near = min(near, h.y); }
            }
        }
    }
    return Hit(clamp(bg.color + glow, vec3f(0.0), vec3f(1.0)), near);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let f = form();
    let bg = background(ro, rd, tmax);
    if (f == 3) { return strings(ro, rd, bg); }
    let b = box_span(ro, rd, bmin(), bmax());
    if (b.x < b.y && b.y > tmin) {
        var t = max(b.x, tmin);
        let steps = select(80, 120, quality() > 0.6);
        let far = min(b.y, bg.t);
        for (var i = 0; i < 120; i = i + 1) {
            if (i >= steps || t > far) { break; }
            let d = sdf(ro + rd * t);
            if (d < 0.0008 * t + 0.001) { return Hit(tone(shade_form(ro + rd * t, rd) * 1.3), t); }
            t += d * select(0.9, 0.7, f == 0 || f == 4);
        }
    }
    return bg;
}

// Standing on the surface of a star: boiling granulation, drifting sunspots,
// a twisted prominence arcing overhead, flares bursting along a burning horizon.
fn fire(h: f32) -> vec3f {
    let x = max(h, 0.0);
    return vec3f(2.8 * x, 1.9 * x * x, 1.0 * x * x * x * x);
}

fn spinA() -> f32 { return time() * 0.06; }

fn toLocal(p: vec3f) -> vec3f {
    let xz = rot2(spinA()) * p.xz;
    return vec3f(xz.x, p.y, xz.y);
}

fn gran(x: vec2f, t: f32) -> vec2f {
    let i = floor(x);
    let f = fract(x);
    var f1 = 8.0;
    var f2 = 8.0;
    for (var j = -1; j <= 1; j = j + 1) {
        for (var k = -1; k <= 1; k = k + 1) {
            let g = vec2f(f32(k), f32(j));
            let c = i + g;
            let h = vec2f(hash12(c), hash12(c + vec2f(17.3, 4.1)));
            let o = vec2f(0.5) + 0.38 * sin(t * (vec2f(0.25) + 0.2 * h.yx) + TAU * h);
            let d = length(g + o - f);
            if (d < f1) { f2 = f1; f1 = d; } else if (d < f2) { f2 = d; }
        }
    }
    return vec2f(f1, f2);
}

fn surface(w: vec2f, dist: f32) -> vec3f {
    let t = time();
    let detail = exp(-dist * 0.05);
    var heat = 0.62;
    if (detail > 0.05) {
        let g = gran(w * 1.25, t);
        let seam = smoothstep(0.0, 0.2, g.y - g.x);
        let cellb = 1.0 - smoothstep(0.0, 0.85, g.x);
        let hg = 0.38 + 0.52 * seam * (0.45 + 0.55 * cellb);
        heat = mix(heat, hg, detail);
    }
    heat *= 0.85 + 0.3 * noise3(vec3f(w * 0.3, t * 0.12));
    for (var i = 0; i < 3; i = i + 1) {
        let fi = f32(i);
        let c = vec2f(3.4 * cos(t * 0.045 + fi * 2.1), 3.0 * sin(t * 0.033 + fi * 2.1 + 1.0));
        let q = w - c;
        let r = length(q);
        let rs = 0.55 + 0.1 * fi;
        let fil = 0.5 + 0.5 * sin(atan2(q.y, q.x) * 38.0 + r * 3.0);
        let pen = 1.0 - smoothstep(rs * 1.9, rs * 2.2, r);
        let umb = 1.0 - smoothstep(rs * 0.85, rs, r);
        heat = mix(heat, 0.3 + 0.12 * fil, pen);
        heat = mix(heat, 0.1, umb);
    }
    let n = noise3(vec3f(w * 0.06, 3.0));
    heat = mix(heat, 0.3, smoothstep(0.66, 0.7, n));
    heat = mix(heat, 0.1, smoothstep(0.72, 0.75, n));
    return fire(heat);
}

fn sky(rd: vec3f) -> vec3f {
    let t = time();
    let y = max(rd.y, 0.0);
    let turb = fbm3(vec3f(rd.x * 3.0, rd.y * 6.0 - t * 0.25, rd.z * 3.0));
    var h = (0.95 * exp(-y * 7.0) + 0.16 * exp(-y * 1.8)) * (0.75 + 0.5 * turb);
    let hd = normalize(vec2f(rd.x, rd.z) + vec2f(1e-5, 0.0));
    for (var k = 0; k < 5; k = k + 1) {
        let fk = f32(k);
        let cyc = t * 0.11 + hash12(vec2f(fk, 7.0));
        let life = fract(cyc);
        let ak = hash12(vec2f(fk, floor(cyc))) * TAU;
        let da = acos(clamp(dot(hd, vec2f(cos(ak), sin(ak))), -1.0, 1.0));
        let top = 0.04 + life * 0.75;
        let w = 0.04 + 0.15 * y + life * 0.04;
        let plume = exp(-da * da / (w * w)) * (1.0 - smoothstep(top * 0.5, top, y));
        h += plume * 0.85 * pow(1.0 - life, 1.3) * (0.5 + turb);
    }
    return fire(h);
}

fn prom(p: vec3f, t: f32) -> f32 {
    let u = vec2f(p.x / 1.8, (p.y + 0.3) / 3.6);
    let e = (length(u) - 1.0) * 1.8;
    let ang = atan2(u.y, u.x);
    let c = rot2(ang * 4.0 - t * 0.9) * vec2f(e, p.z);
    let thick = 0.12 + 0.05 * sin(ang * 3.0 + t * 0.5) + 0.07 * max(sin(ang), 0.0);
    let s1 = length(c - vec2f(0.17, 0.0));
    let s2 = length(c + vec2f(0.17, 0.0));
    let dd = min(s1, s2) / thick;
    let n = noise3(vec3f(p.x * 4.0, p.y * 1.5 + t * 1.4, p.z * 4.0));
    var dens = exp(-dd * dd) * (2.0 + 3.0 * n);
    dens += exp(-length(vec2f(e, p.z)) * 4.0) * 0.5 * (0.5 + n);
    let drip = smoothstep(0.6, 0.85, n) * exp(-p.z * p.z * 25.0) * smoothstep(-1.2, -0.15, e) * smoothstep(0.05, -0.1, e);
    dens += drip * 2.5;
    return dens;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let t = time();
    let flick = 1.0 + 0.06 * sin(t * 9.0 + 2.0 * sin(t * 3.1)) + 0.03 * sin(t * 23.0);
    var bg = vec3f(0.0);
    var tb = horizon_t(tmax);
    let tf = plane_y(ro, rd, 0.0);
    if (tf > tmin) {
        let p = ro + rd * tf;
        var c = surface(p.xz, tf);
        let lp = toLocal(p);
        let d1 = length(lp.xz - vec2f(1.79, 0.0));
        let d2 = length(lp.xz + vec2f(1.79, 0.0));
        c += vec3f(2.0, 0.6, 0.1) * (0.7 / (1.0 + d1 * d1 * 2.0) + 0.7 / (1.0 + d2 * d2 * 2.0));
        c = mix(c, fire(0.95), 1.0 - exp(-tf * 0.015));
        bg = c;
        tb = min(tf, horizon_t(tmax));
    } else {
        bg = sky(rd);
    }
    let lro = toLocal(ro);
    let lrd = toLocal(rd);
    let sp = box_span(lro, lrd, vec3f(-2.5, 0.0, -1.0), vec3f(2.5, 3.9, 1.0));
    var L = vec3f(0.0);
    var T = 1.0;
    let t0 = max(sp.x, tmin);
    let t1 = min(sp.y, tb);
    if (sp.x <= sp.y && t1 > t0) {
        let n = i32(mix(20.0, 44.0, quality()));
        let dt = (t1 - t0) / f32(n);
        var s = t0 + dt * hash13(rd * 731.0);
        for (var i = 0; i < 44; i = i + 1) {
            if (i >= n) { break; }
            let p = lro + lrd * s;
            let d = prom(p, t);
            if (d > 0.01) {
                let em = fire(0.28 + 0.4 * min(d * 0.35, 1.0));
                L += T * em * d * dt * 1.1;
                T *= exp(-d * dt * 1.3);
                if (T < 0.02) { break; }
            }
            s += dt;
        }
    }
    let col = (bg * T + L) * flick;
    return Hit(tone(col), tb);
}

// The Tater Tot Canopy: a kitschy plastic-jungle lounge, a family table under lanterns,
// a waitress silhouette with tater tots, and a wind-up toucan snapping on the beat.
var<private> MAT: f32;
var<private> LOC: vec3f;
var<private> T: f32;
var<private> PULSE: f32;
var<private> SQ: f32;
const TOUCAN: vec3f = vec3f(0.75, 3.045, 0.0);
const TS: f32 = 1.5;
const WAIT: vec3f = vec3f(2.5, 0.0, 0.3);
var<private> FAM: array<vec4f, 5> = array<vec4f, 5>(vec4f(-1.45, -0.84, 1.0, 0.0), vec4f(-0.45, -0.84, 0.72, 1.0), vec4f(0.55, -0.84, 1.0, 2.0), vec4f(-1.0, 0.84, 0.95, 3.0), vec4f(0.15, 0.84, 0.68, 4.0));
var<private> FCOL: array<vec3f, 5> = array<vec3f, 5>(vec3f(0.85, 0.6, 0.15), vec3f(0.1, 0.55, 0.55), vec3f(0.9, 0.38, 0.3), vec3f(0.22, 0.32, 0.78), vec3f(0.62, 0.42, 0.78));

fn sd_cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn sd_ell(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / max(k1, 1e-5);
}
fn sd_cyl(p: vec3f, r: f32, h: f32) -> f32 {
    let d = vec2f(length(p.xz) - r, abs(p.y) - h);
    return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}
fn rx(p: vec3f, a: f32) -> vec3f {
    let yz = rot2(a) * p.yz;
    return vec3f(p.x, yz.x, yz.y);
}
fn lantern_c(i: i32) -> vec3f {
    let fi = f32(i);
    return vec3f(-1.4 + 1.4 * fi + sin(T * 0.8 + fi * 2.1) * 0.03, 2.25, cos(T * 0.7 + fi * 1.3) * 0.03);
}

fn palm(p: vec3f, ph: f32) -> vec2f {
    let L = vec2f(-0.7071, -0.7071);
    let y = clamp(p.y, 0.0, 3.6);
    let off = L * (0.045 * y * y);
    let ring = smoothstep(0.3, 0.5, abs(fract(p.y * 3.0) - 0.5));
    let r = 0.2 - 0.025 * y + 0.02 * ring;
    var d = max(length(p.xz - off) - r, max(-p.y, p.y - 3.6)) * 0.8;
    var m = 12.0;
    let c = p - vec3f(L.x * 0.583, 3.58, L.y * 0.583);
    let hub = length(c) - 0.24;
    if (hub < d) { d = hub; m = 12.5; }
    let a = atan2(c.z, c.x) + sin(T * 0.6 + ph) * 0.1;
    let sec = TAU / 8.0;
    let id = floor(a / sec + 0.5);
    let idm = (id + 8.0) % 8.0;
    let fa = a - id * sec;
    let rr = length(c.xz);
    let fx = rr * cos(fa);
    let fz = rr * sin(fa);
    let hs = hash12(vec2f(idm, ph * 3.0 + 1.0));
    let wob = 0.06 * sin(T * 1.2 + idm * 1.7 + ph);
    let fy = c.y - ((0.45 + 0.2 * hs) * fx - (0.28 + wob) * fx * fx);
    let w = 0.36 * (0.6 + 0.4 * abs(sin(fx * 11.0)));
    let fr = sd_ell(vec3f(fx - 1.25, fy, fz), vec3f(1.25, 0.03, w)) * 0.5;
    if (fr < d) { d = fr; m = 13.0; }
    return vec2f(d, m);
}

fn toucan(pw: vec3f) -> vec2f {
    let q = (pw - TOUCAN) / TS;
    var m = 9.0;
    let b = rx(q - vec3f(0.0, 0.16, 0.0), 0.25);
    var d = sd_ell(b, vec3f(0.085, 0.15, 0.08));
    let tl = rx(q - vec3f(0.0, 0.05, -0.06), -0.45);
    d = smin(d, sd_box(tl - vec3f(0.0, -0.1, 0.0), vec3f(0.035, 0.1, 0.012)) - 0.006, 0.02);
    let fq = vec3f(abs(q.x) - 0.035, q.y, q.z);
    d = min(d, sd_cap(fq, vec3f(0.0, 0.06, 0.0), vec3f(0.0, 0.0, 0.03), 0.012));
    LOC = q;
    let bolt = length(vec3f(abs(q.x) - 0.08, q.y - 0.2, q.z + 0.01)) - 0.022;
    if (bolt < d) { d = bolt; m = 14.0; }
    let h = rx(q - vec3f(0.0, 0.31, 0.04), SQ * 0.45);
    let head = length(h) - 0.075;
    if (head < d) { d = head; m = 11.0; LOC = h; }
    let gape = SQ * 0.3 + 0.02;
    let hb = h - vec3f(0.0, 0.0, 0.04);
    let hu = rx(hb, gape);
    let upper = max(sd_ell(hu - vec3f(0.0, 0.0, 0.14), vec3f(0.042, 0.05, 0.16)), -hu.y);
    let hl = rx(hb, -gape);
    let lower = max(sd_ell(hl - vec3f(0.0, 0.0, 0.12), vec3f(0.034, 0.036, 0.13)), hl.y);
    let bk = min(upper, lower);
    if (bk < d) { d = bk; m = 10.0; LOC = h; }
    return vec2f(d * TS * 0.85, m);
}

fn waitress(pw: vec3f) -> vec2f {
    var q = pw - WAIT;
    q.x -= 0.025 * sin(T * 1.6 * PI) * clamp(q.y, 0.0, 1.7) / 1.7;
    var d = sd_ell(q - vec3f(0.0, 0.6, 0.0), vec3f(0.27, 0.45, 0.22));
    d = smin(d, sd_cap(q, vec3f(0.0, 0.85, 0.0), vec3f(0.0, 1.36, 0.0), 0.13), 0.12);
    d = min(d, sd_cap(vec3f(abs(q.x) - 0.08, q.y, q.z), vec3f(0.0, 0.03, 0.0), vec3f(0.0, 0.4, 0.0), 0.045));
    d = smin(d, sd_cap(q, vec3f(0.0, 1.36, 0.0), vec3f(0.0, 1.55, 0.0), 0.05), 0.04);
    d = smin(d, length(q - vec3f(0.0, 1.64, 0.0)) - 0.12, 0.03);
    d = smin(d, length(q - vec3f(0.07, 1.75, -0.02)) - 0.075, 0.03);
    d = min(d, sd_cap(q, vec3f(-0.12, 1.34, 0.05), vec3f(-0.34, 1.24, 0.08), 0.042));
    d = min(d, sd_cap(q, vec3f(-0.34, 1.24, 0.08), vec3f(-0.46, 1.6, 0.05), 0.038));
    d = min(d, sd_cap(q, vec3f(0.13, 1.32, -0.02), vec3f(0.28, 1.06, -0.04), 0.042));
    d = min(d, sd_cap(q, vec3f(0.28, 1.06, -0.04), vec3f(0.14, 0.9, 0.02), 0.038));
    var m = 5.0;
    let tp = q - vec3f(-0.52, 1.64, 0.05);
    let tray = sd_cyl(tp, 0.32, 0.01) - 0.006;
    if (tray < d) { d = tray; m = 6.0; }
    if (length(tp) < 0.5) {
        for (var i = 0; i < 12; i = i + 1) {
            let fi = f32(i);
            let h = hash12(vec2f(fi, 4.0));
            let top = i >= 9;
            let k = select(fi, fi - 9.0, top);
            let n = select(9.0, 3.0, top);
            let rad = select(0.23, 0.08, top) * sqrt((k + 0.5) / n);
            let ang = k * 2.4 + select(0.0, 1.0, top);
            var c = tp - vec3f(cos(ang) * rad, select(0.063, 0.13, top), sin(ang) * rad);
            let xz = rot2(h * 6.28) * c.xz;
            c = vec3f(xz.x, c.y, xz.y);
            let tt = sd_cyl(vec3f(c.y, c.x, c.z), 0.035, 0.05) - 0.012;
            if (tt < d) { d = tt; m = 8.0; }
        }
    }
    return vec2f(d, m);
}

fn family(p: vec3f, dIn: f32) -> f32 {
    var d = dIn;
    for (var i = 0; i < 5; i = i + 1) {
        let f = FAM[i];
        let q = p - vec3f(f.x, 0.0, f.y);
        if (length(q.xz) - 0.6 > d) { continue; }
        let s = f.z;
        let fz = -sign(f.y);
        let stool = sd_cyl(q - vec3f(0.0, 0.25, 0.0), 0.2, 0.25) - 0.01;
        if (stool < d) { d = stool; MAT = 16.0; }
        let bob = sin(T * 2.3 + f32(i) * 1.9) * 0.025 * s;
        let y0 = 0.52;
        let sh = y0 + 0.5 * s;
        var b = sd_cap(q, vec3f(0.0, y0 + 0.1, 0.0), vec3f(0.0, sh, 0.0), 0.17 * s);
        b = smin(b, sd_cap(vec3f(abs(q.x), q.y, q.z), vec3f(0.15 * s, sh - 0.02, 0.0), vec3f(0.14, 0.86, fz * 0.36), 0.05 * s), 0.05);
        b = smin(b, length(q - vec3f(0.0, sh + 0.25 * s + bob, fz * 0.02)) - 0.13 * s, 0.06);
        if (b < d) { d = b; MAT = 4.0 + f32(i) * 0.1; }
    }
    return d;
}

fn map(p: vec3f) -> f32 {
    MAT = 0.0;
    var d = 1e5;
    let pm = vec3f(abs(p.x), p.y, abs(p.z)) - vec3f(4.4, 0.0, 4.4);
    let pb = length(pm.xz + vec2f(0.4)) - 3.0;
    if (pb > 0.4) { d = pb; } else {
        let ph = select(0.0, 1.7, p.x > 0.0) + select(0.0, 3.1, p.z > 0.0);
        let r = palm(pm, ph);
        d = r.x; MAT = r.y;
    }
    let cb = sd_box(p - vec3f(0.15, 2.25, 0.0), vec3f(2.9, 2.3, 1.4));
    if (cb > 0.3) { return min(d, cb); }
    let top = sd_box(p - vec3f(0.0, 0.76, 0.0), vec3f(2.0, 0.035, 0.55)) - 0.02;
    if (top < d) { d = top; MAT = 1.0; }
    let leg = sd_box(vec3f(abs(p.x) - 1.8, p.y - 0.38, abs(p.z) - 0.4), vec3f(0.05, 0.38, 0.05));
    if (leg < d) { d = leg; MAT = 1.0; }
    let side = p.z > 0.0;
    let k = select(clamp(round(p.x + 1.45), 0.0, 2.0), clamp(round((p.x + 1.0) / 1.15), 0.0, 1.0), side);
    let pxc = select(-1.45 + k, -1.0 + k * 1.15, side);
    let pl = sd_cyl(vec3f(p.x - pxc, p.y - 0.815, abs(p.z) - 0.3), 0.15, 0.008) - 0.006;
    if (pl < d) { d = pl; MAT = 3.0; }
    let cup = sd_cyl(vec3f(p.x - pxc - 0.25, p.y - 0.88, abs(p.z) - 0.36), 0.04, 0.07);
    if (cup < d) { d = cup; MAT = 17.0; }
    d = family(p, d);
    let wb = sd_box(p - WAIT - vec3f(-0.25, 0.95, 0.0), vec3f(0.65, 0.95, 0.45));
    if (wb < d) { let w = waitress(p); if (w.x < d) { d = w.x; MAT = w.y; } }
    let bar = sd_cap(p, vec3f(-2.3, 3.0, 0.0), vec3f(2.3, 3.0, 0.0), 0.045);
    if (bar < d) { d = bar; MAT = 15.0; }
    let rope = sd_cap(vec3f(abs(p.x) - 2.2, p.y, p.z), vec3f(0.0, 3.0, 0.0), vec3f(0.0, 4.5, 0.0), 0.015);
    if (rope < d) { d = rope; MAT = 15.0; }
    for (var i = 0; i < 3; i = i + 1) {
        let c = lantern_c(i);
        let st = sd_cap(p, vec3f(c.x, 3.0, 0.0), c + vec3f(0.0, 0.2, 0.0), 0.008);
        if (st < d) { d = st; MAT = 15.0; }
        let l = sd_ell(p - c, vec3f(0.2, 0.24, 0.2));
        if (l < d) { d = l; MAT = 7.0 + f32(i) * 0.1; }
    }
    let tb = length(p - TOUCAN - vec3f(0.0, 0.35, 0.15)) - 0.75;
    if (tb < d) { let r = toucan(p); if (r.x < d) { d = r.x; MAT = r.y; } }
    return d;
}

fn calc_n(p: vec3f) -> vec3f {
    let e = vec2f(0.002, -0.002);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn shadow(p: vec3f, l: vec3f) -> f32 {
    let v = l - p;
    let len = length(v);
    let maxd = len - 0.28;
    let dir = v / len;
    var s = 1.0;
    var t = 0.03;
    for (var i = 0; i < 14; i = i + 1) {
        if (t > maxd) { break; }
        let h = map(p + dir * t);
        s = min(s, 10.0 * h / t);
        if (s < 0.02) { break; }
        t += clamp(h, 0.03, 0.4);
    }
    return clamp(s, 0.0, 1.0);
}

fn lit(P: vec3f, n: vec3f, rd: vec3f, base: vec3f, spec: f32, doSh: bool) -> vec3f {
    let lp = vec3f(clamp(P.x, -1.4, 1.4), 2.25, 0.0);
    let v = lp - P;
    let d2 = max(dot(v, v), 1e-4);
    let l = v * inverseSqrt(d2);
    let LI = vec3f(1.0, 0.6, 0.28) * (2.4 + 1.6 * PULSE);
    let att = 1.0 / (1.0 + 0.35 * d2);
    var sh = 1.0;
    if (doSh) { sh = shadow(P + n * 0.01, lp); }
    let dif = max(dot(n, l), 0.0);
    let hv = normalize(l - rd);
    let sp = pow(max(dot(n, hv), 0.0), 48.0) * spec;
    let amb = vec3f(0.16, 0.3, 0.16) * (0.6 + 0.4 * n.y) + vec3f(0.18, 0.1, 0.04) * (0.5 - 0.5 * n.y);
    return base * (amb + LI * dif * att * sh) + LI * sp * att * sh * 0.8;
}

fn floor_col(P: vec3f) -> vec3f {
    let g = P.xz / 0.75;
    let id = floor(g);
    let f = abs(fract(g) - 0.5);
    let grout = smoothstep(0.46, 0.49, max(f.x, f.y));
    let par = fract((id.x + id.y) * 0.5);
    let c = select(vec3f(0.58, 0.25, 0.11), vec3f(0.12, 0.34, 0.2), par > 0.25) * (0.8 + 0.3 * hash12(id));
    return mix(c, vec3f(0.1, 0.08, 0.06), grout);
}

fn leaf_layer(uv: vec2f, s: f32, seed: f32, tint: vec3f, cin: vec3f) -> vec3f {
    let g = uv * s;
    let id = floor(g);
    let h = hash12(id + vec2f(seed, seed * 1.7));
    let h2 = hash12(id + vec2f(seed * 2.3 + 5.0, 11.0));
    let cl = fract(g) - 0.5;
    let lc = rot2(h * TAU + sin(T * 0.5 + h * 9.0) * 0.12) * cl;
    let xn = lc.x / 0.47;
    let edge = 0.22 * (1.0 - xn * xn) - abs(lc.y);
    let a = smoothstep(0.0, 0.015, edge) * step(0.12, h);
    var leaf = tint * (0.7 + 0.6 * h2);
    leaf *= 0.7 + 0.6 * smoothstep(-0.2, 0.2, lc.y);
    leaf *= 0.85 + 0.15 * sin(lc.x * 35.0 + abs(lc.y) * 35.0);
    leaf = mix(leaf, leaf * 1.8 + vec3f(0.05, 0.08, 0.0), smoothstep(0.012, 0.0, abs(lc.y)));
    var c = mix(cin, leaf, a);
    if (h2 > 0.82) {
        let fp = cl - vec2f(0.28 * sign(h - 0.5), -0.26);
        let ang = atan2(fp.y, fp.x);
        let fr = length(fp);
        let petal = 0.1 * (0.75 + 0.25 * cos(ang * 5.0 + h * 6.0));
        let fa = smoothstep(petal, petal - 0.01, fr);
        var fcol = mix(vec3f(1.0, 0.15, 0.35), vec3f(1.0, 0.55, 0.2), h);
        fcol = mix(fcol, vec3f(1.0, 0.9, 0.3), smoothstep(0.03, 0.015, fr));
        c = mix(c, fcol, fa);
    }
    return c;
}

fn jungle(pe: vec3f) -> vec3f {
    var uv: vec2f;
    var col: vec3f;
    if (pe.y > ROOM_HEIGHT - 0.05) {
        uv = pe.xz * 0.45;
        col = vec3f(0.03, 0.07, 0.03) + vec3f(0.5, 0.32, 0.1) * smoothstep(0.6, 0.85, noise3(vec3f(pe.xz * 0.9, T * 0.1))) * 0.6;
    } else {
        var u = pe.x + select(10.0, 70.0, pe.z > 0.0);
        if (abs(pe.x) > abs(pe.z)) { u = pe.z + select(30.0, 50.0, pe.x > 0.0); }
        uv = vec2f(u, pe.y) * 0.5;
        col = mix(vec3f(0.36, 0.2, 0.07), vec3f(0.03, 0.09, 0.04), smoothstep(0.2, 4.3, pe.y));
    }
    col = leaf_layer(uv, 2.3, 1.0, vec3f(0.04, 0.15, 0.06), col);
    col = leaf_layer(uv + vec2f(0.37, 0.11), 1.55, 7.0, vec3f(0.06, 0.28, 0.09), col);
    col = leaf_layer(uv + vec2f(0.71, 0.53), 1.05, 13.0, vec3f(0.1, 0.48, 0.13), col);
    return col * (0.7 + 0.35 * PULSE);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    T = time();
    let fb = fract(T * 1.6);
    PULSE = exp(-fb * 5.0);
    SQ = smoothstep(0.0, 0.07, fb) * exp(-fb * 4.0);
    let q = quality();
    let tf = plane_y(ro, rd, 0.0);
    let floor_ok = tf > tmin && tf < tmax;
    let tend = select(tmax, tf, floor_ok);
    var t = tmin;
    var hit = false;
    let steps = i32(mix(40.0, 90.0, q));
    for (var i = 0; i < steps; i = i + 1) {
        let d = map(ro + rd * t);
        if (d < 0.0015 + 0.0008 * t) { hit = true; break; }
        t += d;
        if (t > tend) { break; }
    }
    var col = vec3f(0.0);
    var th = horizon_t(tmax);
    if (hit) {
        let P = ro + rd * t;
        let m = MAT;
        let loc = LOC;
        let n = calc_n(P);
        var base = vec3f(0.5);
        var spec = 0.3;
        var emit = vec3f(0.0);
        var rim = 0.15;
        var emissive = false;
        if (m < 1.5) {
            let grain = noise3(vec3f(P.x * 2.0, P.y * 40.0, P.z * 40.0));
            base = vec3f(0.36, 0.15, 0.07) * (0.75 + 0.5 * grain); spec = 0.5;
        } else if (m < 3.5) {
            base = vec3f(0.92, 0.86, 0.74); spec = 0.8;
        } else if (m < 4.9) {
            let idx = clamp(i32(round((m - 4.0) * 10.0)), 0, 4);
            base = FCOL[idx]; spec = 0.35; rim = 0.3;
        } else if (m < 5.5) {
            base = vec3f(0.16, 0.05, 0.12); spec = 0.2; rim = 1.0;
        } else if (m < 6.5) {
            base = vec3f(0.75, 0.75, 0.78); spec = 1.5;
        } else if (m < 7.5) {
            let idx = i32(round((m - 7.0) * 10.0));
            let c = lantern_c(idx);
            let rib = 0.75 + 0.25 * abs(sin(atan2(P.z - c.z, P.x - c.x) * 6.0));
            emit = vec3f(1.6, 0.85, 0.35) * (1.0 + 0.8 * PULSE) * rib;
            emissive = true;
        } else if (m < 8.5) {
            base = vec3f(0.9, 0.55, 0.14) * (0.75 + 0.5 * noise3(P * 60.0)); spec = 0.6;
        } else if (m < 9.5) {
            base = vec3f(0.03, 0.03, 0.04); spec = 0.9;
            if (loc.z > 0.02 && loc.y > 0.17) { base = vec3f(1.0, 0.82, 0.15); }
        } else if (m < 10.5) {
            let tb = clamp((loc.z - 0.05) / 0.28, 0.0, 1.0);
            base = mix(vec3f(0.45, 0.8, 0.15), vec3f(1.0, 0.72, 0.05), smoothstep(0.0, 0.35, tb));
            base = mix(base, vec3f(1.0, 0.3, 0.03), smoothstep(0.45, 0.8, tb));
            base = mix(base, vec3f(0.05), smoothstep(0.88, 0.95, tb));
            spec = 1.2;
        } else if (m < 11.5) {
            base = vec3f(0.03, 0.03, 0.04); spec = 0.9;
            if (loc.z > 0.02 && loc.y < 0.01) { base = vec3f(1.0, 0.9, 0.4); }
            let ed = length(vec3f(abs(loc.x) - 0.065, loc.y - 0.02, loc.z - 0.02));
            if (ed < 0.035) { base = vec3f(0.2, 0.5, 1.0); }
            if (ed < 0.017) { base = vec3f(0.02); emit = vec3f(1.0, 0.25, 0.1) * PULSE * 3.0; }
        } else if (m < 12.25) {
            let ring = smoothstep(0.3, 0.5, abs(fract(P.y * 3.0) - 0.5));
            base = mix(vec3f(0.42, 0.28, 0.14), vec3f(0.2, 0.12, 0.06), ring); spec = 0.4;
        } else if (m < 12.75) {
            base = vec3f(0.3, 0.18, 0.08); spec = 0.6;
        } else if (m < 13.5) {
            base = mix(vec3f(0.07, 0.42, 0.12), vec3f(0.3, 0.65, 0.1), noise3(P * 2.0)); spec = 1.2;
        } else if (m < 14.5) {
            base = vec3f(0.85, 0.6, 0.25); spec = 1.5;
        } else if (m < 15.5) {
            base = vec3f(0.6, 0.48, 0.22) * (0.7 + 0.3 * smoothstep(0.0, 0.05, abs(fract(P.x * 2.0) - 0.5))); spec = 0.5;
        } else if (m < 16.5) {
            base = vec3f(0.05, 0.3, 0.14); spec = 0.9;
        } else {
            base = vec3f(0.2, 0.75, 0.7); spec = 1.2;
        }
        if (emissive) {
            col = emit;
        } else {
            let ao = clamp(map(P + n * 0.12) / 0.12, 0.35, 1.0);
            col = lit(P, n, rd, base, spec, q > 0.4) * ao + emit;
            col += vec3f(1.0, 0.6, 0.25) * pow(1.0 - max(dot(n, -rd), 0.0), 3.0) * rim;
        }
        th = min(t, tmax);
    } else if (floor_ok) {
        let P = ro + rd * tf;
        let fc = floor_col(P);
        col = lit(P, vec3f(0.0, 1.0, 0.0), rd, fc, 0.25, q > 0.4);
        let dap = smoothstep(0.5, 0.75, noise3(vec3f(P.xz * 1.3, T * 0.15)));
        col += fc * vec3f(0.25, 0.45, 0.15) * dap;
        th = tf;
    } else {
        col = jungle(ro + rd * horizon_t(tmax));
    }
    var glow = vec3f(0.0);
    for (var i = 0; i < 3; i = i + 1) {
        let c = lantern_c(i);
        let tc = clamp(dot(c - ro, rd), tmin, th);
        let dd = length(ro + rd * tc - c);
        glow += vec3f(1.0, 0.55, 0.2) * (0.012 + 0.012 * PULSE) / (dd * dd + 0.02);
    }
    col += glow;
    col = mix(col, vec3f(0.2, 0.13, 0.06), 1.0 - exp(-th * 0.025));
    return Hit(tone(col * 1.3), th);
}

// Campfire: a ring of stones, a small breathing fire, embers rising into a blue night among pines.
var<private> FL: f32;
var<private> LP: vec3f;

fn warm() -> vec3f { return vec3f(1.0, 0.55, 0.22); }

fn fire_init() {
    let t = time();
    FL = 0.88 + 0.07 * sin(t * 9.1) + 0.05 * sin(t * 15.7 + 1.3) + 0.12 * (noise3(vec3f(t * 3.5, 0.0, 0.0)) - 0.5);
    LP = vec3f(0.06 * sin(t * 3.1), 0.55 + 0.05 * sin(t * 5.3), 0.06 * cos(t * 2.7));
}

// The stones all lie within 0.27 m of the ring r = 0.78 and below y = 0.3 (from their sizes and jitter).
fn stones_bound(p: vec3f) -> f32 {
    return max(abs(length(p.xz) - 0.78) - 0.27, p.y - 0.3);
}

fn stones(p: vec3f) -> f32 {
    let sec = TAU / 11.0;
    let a = atan2(p.z, p.x);
    let id = floor(a / sec + 0.5);
    let q2 = rot2(-id * sec) * p.xz;
    let ii = f32((i32(id) + 11) % 11);
    let h = hash33(vec3f(ii, 4.0, 9.0));
    var q = vec3f(q2.x - (0.78 + (h.x - 0.5) * 0.08), p.y - 0.05, q2.y);
    let tw = rot2(h.z * 0.8 - 0.4) * q.xz;
    q = vec3f(tw.x, q.y, tw.y);
    let r = vec3f(0.15 + 0.05 * h.y, 0.16 + 0.07 * h.z, 0.18 + 0.04 * h.x);
    let k0 = length(q / r);
    let k1 = max(length(q / (r * r)), 1e-4);
    return k0 * (k0 - 1.0) / k1;
}

fn capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

fn logs(p: vec3f) -> f32 {
    var d = 1e5;
    for (var i = 0; i < 4; i = i + 1) {
        let an = f32(i) * TAU / 4.0 + 0.4;
        let dir = vec3f(cos(an), 0.0, sin(an));
        d = min(d, capsule(p, dir * 0.52 + vec3f(0.0, 0.06, 0.0), dir * 0.06 + vec3f(0.0, 0.34, 0.0), 0.065));
    }
    return d;
}

fn scene(p: vec3f) -> vec2f {
    var s = stones_bound(p);
    if (s < 0.05) { s = stones(p); }
    let l = logs(p);
    return select(vec2f(s, 0.0), vec2f(l, 1.0), l < s);
}

fn calc_n(p: vec3f) -> vec3f {
    let k = vec2f(1.0, -1.0);
    let e = 0.002;
    return normalize(k.xyy * scene(p + k.xyy * e).x + k.yyx * scene(p + k.yyx * e).x + k.yxy * scene(p + k.yxy * e).x + k.xxx * scene(p + k.xxx * e).x);
}

fn stone_shadow(p: vec3f) -> f32 {
    let to = LP - p;
    let dist = length(to);
    let dir = to / dist;
    var res = 1.0;
    var t = 0.02;
    for (var i = 0; i < 12; i = i + 1) {
        let ps = p + dir * t;
        var d = stones_bound(ps);
        if (d < max(0.2, 0.1 * t)) { d = stones(ps); }
        res = min(res, 10.0 * d / t);
        t += clamp(d, 0.02, 0.2);
        if (res < 0.02 || t > dist) { break; }
    }
    return clamp(res, 0.0, 1.0);
}

fn sky(rd: vec3f) -> vec3f {
    let y = max(rd.y, 0.0);
    var col = mix(vec3f(0.04, 0.055, 0.12), vec3f(0.004, 0.008, 0.03), pow(y, 0.5));
    let h = hash13(floor(rd * 220.0));
    let tw = 0.6 + 0.4 * sin(time() * 2.0 + h * 80.0);
    col += vec3f(0.8, 0.85, 1.0) * step(0.997, h) * tw * smoothstep(0.05, 0.3, rd.y);
    return col;
}

fn ground(p: vec3f) -> vec3f {
    let r = length(p.xz);
    let n1 = noise3(vec3f(p.x * 0.9, 0.5, p.z * 0.9));
    let n2 = noise3(vec3f(p.x * 6.0, 2.5, p.z * 6.0));
    var alb = mix(vec3f(0.20, 0.14, 0.09), vec3f(0.08, 0.11, 0.05), smoothstep(0.35, 0.7, n1)) * (0.55 + 0.8 * n2);
    alb = mix(alb, vec3f(0.07, 0.065, 0.06) * (0.6 + 0.8 * n2), 1.0 - smoothstep(0.45, 0.75, r));
    let L = LP - p;
    let d = length(L);
    let cosI = clamp((L.y + 0.25) / d, 0.0, 1.0);
    let I = FL * 2.5 / (1.0 + d * d * 0.35);
    var sh = 1.0;
    if (r > 0.5 && r < 2.6) { sh = stone_shadow(p); }
    var c = alb * (warm() * I * cosI * sh + vec3f(0.03, 0.045, 0.09));
    if (r < 0.68) {
        let e = noise3(vec3f(p.x * 13.0, time() * 0.5, p.z * 13.0));
        c += vec3f(1.0, 0.28, 0.04) * pow(smoothstep(0.5, 0.85, e), 2.0) * 1.8 * (1.0 - smoothstep(0.4, 0.68, r));
    }
    return c;
}

fn trees(ro: vec3f, rd: vec3f, R: f32, N: f32, seed: f32) -> vec4f {
    let miss = vec4f(0.0, 0.0, 0.0, -1.0);
    let a = dot(rd.xz, rd.xz);
    if (a < 1e-6) { return miss; }
    let b = dot(ro.xz, rd.xz);
    let c = dot(ro.xz, ro.xz) - R * R;
    let t = (-b + sqrt(max(b * b - a * c, 0.0))) / a;
    let p = ro + rd * t;
    if (p.y < 0.0 || p.y > 13.0) { return miss; }
    let u = (atan2(p.z, p.x) + PI) / TAU * N;
    let cid = floor(u);
    var hit = 0.0;
    var lat = 0.0;
    var cb = 0.0;
    for (var k = -1; k <= 1; k = k + 1) {
        let id = cid + f32(k);
        let idw = floor(fract(id / N) * N + 0.5);
        let h = hash12(vec2f(idw * 1.37, seed * 7.1));
        let h2 = hash12(vec2f(idw * 2.11 + 5.0, seed * 3.3));
        let du = (u - (id + 0.5 + (h - 0.5) * 0.6)) * TAU / N * R;
        let top = 6.5 + h2 * 5.0;
        let cbot = 1.4 + h * 1.6;
        let tw = 0.13 + 0.09 * h2;
        let layer = fract((top - p.y) * 0.85 + h);
        let cw = (top - p.y) * 0.3 * (0.55 + 0.45 * layer);
        if (abs(du) < tw && p.y < cbot + 0.3) { hit = 2.0; lat = du / tw; cb = cbot; break; }
        if (p.y > cbot && p.y < top && abs(du) < cw) { hit = 1.0; lat = du / max(cw, 0.01); cb = cbot; }
    }
    if (hit < 0.5) { return miss; }
    let L = LP - p;
    let d = length(L);
    let I = FL * 2.5 / (1.0 + d * d * 0.35);
    let facing = sqrt(max(1.0 - lat * lat, 0.0));
    let moon = vec3f(0.03, 0.045, 0.09);
    var col = vec3f(0.0);
    if (hit > 1.5) {
        let bark = 0.8 + 0.4 * noise3(vec3f(lat * 3.0, p.y * 6.0, seed));
        col = vec3f(0.32, 0.22, 0.15) * bark * (warm() * I * 1.6 * facing * exp(-p.y * 0.25) + moon * 0.5);
    } else {
        col = vec3f(0.06, 0.11, 0.07) * (warm() * I * 0.9 * facing * exp(-(p.y - cb) * 0.35) + moon * 0.8);
    }
    return vec4f(col, t);
}

fn flame(p: vec3f, t: f32) -> vec2f {
    let h = p.y - 0.08;
    let rr0 = length(p.xz);
    if (h < 0.0 || h > 1.5 || rr0 > 0.45) { return vec2f(0.0); }
    let sx = sin(t * 1.7 + h * 3.0) * 0.07 * h;
    let sz = cos(t * 1.3 + h * 2.4) * 0.05 * h;
    let q = vec2f(p.x - sx, p.z - sz);
    // the flame's radius is at most 0.375 prof at its tallest (n = 1); outside that, plus the 0.03 fade, it is empty
    let pmax = sqrt(clamp(h * 7.0, 0.0, 1.0)) * clamp(1.0 - h / (1.3 * FL), 0.0, 1.0);
    if (length(q) - 0.375 * pmax >= 0.03) { return vec2f(0.0); }
    let n1 = noise3(vec3f(q.x * 4.0, h * 2.6 - t * 2.4, q.y * 4.0));
    let n2 = noise3(vec3f(q.x * 9.0 + 3.1, h * 5.5 - t * 4.0, q.y * 9.0 + 1.7));
    let n = n1 * 0.65 + n2 * 0.35;
    let hmax = (0.75 + 0.55 * n) * FL;
    let prof = sqrt(clamp(h * 7.0, 0.0, 1.0)) * clamp(1.0 - h / hmax, 0.0, 1.0);
    let rad = 0.3 * prof * (0.75 + 0.5 * n);
    let d = length(q) - rad;
    let dens = 1.0 - smoothstep(-0.07, 0.03, d);
    let core = 1.0 - smoothstep(-0.15, 0.0, d);
    let temp = clamp(clamp(1.0 - h / hmax, 0.0, 1.0) * (0.45 + 0.7 * core), 0.0, 1.0);
    return vec2f(dens, temp);
}

fn fire_col(k: f32) -> vec3f {
    var c = mix(vec3f(0.5, 0.05, 0.01), vec3f(1.0, 0.35, 0.05), smoothstep(0.0, 0.35, k));
    c = mix(c, vec3f(1.0, 0.72, 0.25), smoothstep(0.35, 0.7, k));
    c = mix(c, vec3f(1.0, 0.95, 0.75), smoothstep(0.7, 1.0, k));
    return c * (0.4 + 2.5 * k * k);
}

fn embers(ro: vec3f, rd: vec3f, tlim: f32) -> vec3f {
    var acc = vec3f(0.0);
    // every ember stays in x -0.65..1.15, y 0.35..4.65, z -0.65..0.65; its glow fades out within 0.15 m
    let eb = box_span(ro, rd, vec3f(-0.8, 0.2, -0.8), vec3f(1.3, 4.8, 0.8));
    if (eb.x >= eb.y || eb.y < 0.0 || eb.x > tlim) { return acc; }
    let t = time();
    let n = select(26, 13, quality() < 0.5);
    for (var i = 0; i < n; i = i + 1) {
        let fi = f32(i);
        let h = hash33(vec3f(fi, 3.7, 11.1));
        let life = 3.0 + 3.0 * h.x;
        let ph = fract(t / life + h.y);
        let cyc = floor(t / life + h.y);
        let h2 = hash33(vec3f(fi, cyc, 5.3));
        let y = 0.35 + ph * (2.8 + 1.5 * h2.z);
        let sw = ph * (0.4 + 0.5 * h2.x);
        let c = vec3f((h2.x - 0.5) * 0.4 + sin(t * 1.1 + fi) * sw * 0.5 + ph * 0.5, y, (h2.y - 0.5) * 0.4 + cos(t * 0.9 + fi * 1.7) * sw * 0.5);
        let v = c - ro;
        let tt = dot(v, rd);
        if (tt < 0.0 || tt > tlim) { continue; }
        let d2 = max(dot(v, v) - tt * tt, 0.0);
        let sz = 0.00012 * (1.0 + tt * 0.15);
        // farther than this from the ray it adds under 1/1000
        if (d2 > 48.0 * sz) { continue; }
        let b = pow(1.0 - ph, 1.5) * (0.7 + 0.3 * sin(t * 13.0 + fi * 5.0)) * smoothstep(0.0, 0.05, ph);
        let ec = mix(vec3f(1.0, 0.6, 0.2), vec3f(0.9, 0.2, 0.05), ph);
        acc += ec * b * (exp(-d2 / sz) * 1.6 + 0.35 * exp(-d2 / (sz * 8.0)));
    }
    return acc;
}

fn obj_col(p: vec3f, n: vec3f, m: f32) -> vec3f {
    let L = LP - p;
    let d = length(L);
    let ld = L / d;
    let I = FL * 2.5 / (1.0 + d * d * 0.35);
    let dif = max(dot(n, ld), 0.0);
    let moon = vec3f(0.03, 0.045, 0.09) * (0.6 + 0.4 * n.y);
    if (m < 0.5) {
        let g = noise3(p * 9.0);
        let alb = vec3f(0.30, 0.28, 0.26) * (0.6 + 0.6 * g);
        let ao = clamp(p.y * 5.0 + 0.3, 0.3, 1.0);
        return alb * (warm() * I * dif + moon) * ao;
    }
    let g = noise3(p * 14.0 + vec3f(0.0, time() * 0.3, 0.0));
    let crack = smoothstep(0.58, 0.78, g);
    let pulse = 0.6 + 0.4 * sin(time() * 2.3 + p.x * 9.0 + p.z * 7.0);
    var c = vec3f(0.05, 0.035, 0.025) * (warm() * I * (0.4 + 0.6 * dif) + moon);
    c += vec3f(1.0, 0.3, 0.05) * crack * pulse * 2.0;
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    fire_init();
    let T = time();
    var tObj = -1.0;
    var mObj = 0.0;
    let sp = box_span(ro, rd, vec3f(-1.1, 0.0, -1.1), vec3f(1.1, 0.5, 1.1));
    if (sp.x < sp.y && sp.y > tmin) {
        var t = max(sp.x, tmin);
        let t1 = min(sp.y, tmax);
        let steps = i32(mix(28.0, 56.0, quality()));
        for (var i = 0; i < steps; i = i + 1) {
            let s = scene(ro + rd * t);
            if (s.x < 0.001) { tObj = t; mObj = s.y; break; }
            t += s.x * 0.85;
            if (t > t1) { break; }
        }
    }
    var col = vec3f(0.0);
    var tOut = horizon_t(tmax);
    var tFar = 1e5;
    if (tObj > 0.0) {
        let p = ro + rd * tObj;
        col = obj_col(p, calc_n(p), mObj);
        tOut = tObj;
        tFar = tObj;
    } else {
        let tg = plane_y(ro, rd, 0.0);
        var tc = 1e5;
        if (tg > 0.0) { tc = tg; col = ground(ro + rd * tg); } else { col = sky(rd); }
        let tr2 = trees(ro, rd, 14.0, 44.0, 2.0);
        if (tr2.w > 0.0 && tr2.w < tc) { tc = tr2.w; col = tr2.xyz; }
        let tr1 = trees(ro, rd, 9.0, 36.0, 1.0);
        if (tr1.w > 0.0 && tr1.w < tc) { tc = tr1.w; col = tr1.xyz; }
        if (tc < 1e4) { col = mix(col, vec3f(0.04, 0.055, 0.12), 1.0 - exp(-max(tc - 6.0, 0.0) * 0.03)); }
        tFar = tc;
        tOut = min(tc, horizon_t(tmax));
    }
    // flames
    var trans = 1.0;
    var em = vec3f(0.0);
    let fs = box_span(ro, rd, vec3f(-0.45, 0.05, -0.45), vec3f(0.45, 1.6, 0.45));
    if (fs.x < fs.y && fs.y > tmin) {
        let f0 = max(fs.x, tmin);
        let f1 = min(fs.y, tFar);
        if (f1 > f0) {
            let n = i32(mix(12.0, 26.0, quality()));
            let dt = (f1 - f0) / f32(n);
            var t = f0 + dt * hash12(rd.xy * 937.0 + rd.zx * 311.0);
            for (var i = 0; i < n; i = i + 1) {
                let fd = flame(ro + rd * t, T);
                if (fd.x > 0.001) {
                    em += fire_col(fd.y) * fd.x * dt * 6.0 * trans;
                    trans *= exp(-fd.x * dt * 4.0);
                }
                t += dt;
            }
        }
    }
    col = col * trans + em;
    col += embers(ro, rd, tFar);
    let v = LP - ro;
    let tt = clamp(dot(v, rd), 0.0, tFar);
    let q = ro + rd * tt - LP;
    col += vec3f(1.0, 0.45, 0.15) * FL * 0.025 / (0.06 + dot(q, q));
    return Hit(tone(col * 1.25), clamp(tOut, tmin, tmax));
}

shaders.10132aa02650c10afcd2f12895f2:
// The Fractal Garden, cell (1, 3). A shared stream runs through every room.
const GX: f32 = 1.0;
const GY: f32 = 3.0;
const RESPECT: bool = true;
const MAX_STEPS: f32 = 80.0;
const MAX_ITERS: f32 = 8.0;
const NB: i32 = 4;
const POWER: f32 = 8.0;
const HUE: f32 = 0.92;
const EXTRA: bool = false;
const HEDGE_H: f32 = 2.4;
const SS: i32 = 1;
const DOORS: i32 = 15; // bit per wall N,S,W,E (hedge order): 1 = leave a gap for the doorway
const CENTER: bool = false;
const NBT: i32 = 4 + select(0, 1, false);

fn wpos(p: vec3f) -> vec3f { return p + vec3f(GX * 12.0, 0.0, GY * 12.0); }

// stream centre line in world x as a function of world z; it crosses x = 24 (cell column 2 centre) at every door
fn stream_x(wz: f32) -> f32 {
    return GX * 12.0 + 1.9 * sin(wz * TAU / 12.0) + 0.5 * sin(wz * TAU / 6.0);
}

fn moon_dir() -> vec3f { return normalize(vec3f(-0.35, 0.42, -0.84)); }

fn sky(rd: vec3f) -> vec3f {
    let y = max(rd.y, 0.0);
    var col = mix(vec3f(0.32, 0.16, 0.38), vec3f(0.02, 0.03, 0.10), pow(y, 0.55));
    let m = max(dot(rd, moon_dir()), 0.0);
    col += vec3f(1.0, 0.92, 0.8) * (smoothstep(0.9993, 0.9996, m) * 3.0 + pow(m, 60.0) * 0.4);
    if (rd.y > 0.0) {
        let s = rd * 180.0;
        let h = hash13(floor(s));
        col += vec3f(0.9, 0.9, 1.0) * step(0.9975, h) * (0.6 + 0.4 * sin(time() * 3.0 + h * 90.0)) * y;
        let p = rd.xz / (rd.y + 0.15);
        let cl = fbm3(vec3f(p * 0.7 + vec2f(time() * 0.01, 0.0), 1.0));
        col += palette(cl + HUE, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67)) * smoothstep(0.55, 0.8, cl) * 0.18;
    }
    return col;
}

fn lvl() -> f32 { return select(1.0, quality(), RESPECT); }

// ---- mandelbulb blossom ----
fn bulb(p: vec3f, pw: f32, iters: i32) -> vec2f {
    var z = p;
    var dr = 1.0;
    var r = length(z);
    var trap = 1e9;
    for (var i = 0; i < iters; i = i + 1) {
        r = length(z);
        if (r > 2.0) { break; }
        let th = acos(clamp(z.y / max(r, 1e-6), -1.0, 1.0)) * pw;
        let ph = atan2(z.z, z.x) * pw;
        dr = pow(r, pw - 1.0) * pw * dr + 1.0;
        let zr = pow(r, pw);
        z = zr * vec3f(sin(th) * cos(ph), cos(th), sin(th) * sin(ph)) + p;
        trap = min(trap, dot(z, z));
    }
    r = max(length(z), 1e-6);
    return vec2f(0.5 * log(r) * r / dr, trap);
}

struct Bloom { c: vec3f, s: f32, pw: f32, spin: f32 };

fn bloom_of(i: i32) -> Bloom {
    let fi = f32(i);
    if (i >= NB) {
        // the great central blossom, floating over the stream on the door axis
        return Bloom(vec3f(0.0, 3.05 + 0.08 * sin(time() * 0.5), 0.0), 1.0, POWER + 0.8 * sin(time() * 0.17), time() * 0.1);
    }
    let h = hash12(vec2f(GX * 7.0 + fi * 3.1, GY * 11.0 + fi * 1.7));
    let side = select(-1.0, 1.0, (i % 2) == 0);
    let row = f32(i / 2);
    let nrow = f32((NB + 1) / 2);
    let z = select(0.0, mix(-3.4, 3.4, row / max(nrow - 1.0, 1.0)), nrow > 1.0) + (h - 0.5) * 0.8;
    let x = side * (3.4 + h * 0.6);
    let s = 0.62 + 0.25 * h;
    let y = 1.35 + 0.5 * h + 0.06 * sin(time() * 0.7 + fi);
    let pw = POWER + fi * 0.7 + 0.6 * sin(time() * 0.23 + fi * 1.3);
    return Bloom(vec3f(x, y, z), s, pw, time() * (0.15 + 0.1 * h) + fi);
}

fn bloom_de(p: vec3f, b: Bloom, iters: i32) -> vec2f {
    var q = (p - b.c) / b.s;
    let xz = rot2(b.spin) * q.xz;
    q = vec3f(xz.x, q.y, xz.y);
    let d = bulb(q, b.pw, iters);
    return vec2f(d.x * b.s, d.y);
}

fn bloom_normal(p: vec3f, b: Bloom, iters: i32) -> vec3f {
    let e = 0.0015;
    let k = vec2f(1.0, -1.0);
    return normalize(k.xyy * bloom_de(p + k.xyy * e, b, iters).x + k.yyx * bloom_de(p + k.yyx * e, b, iters).x +
                     k.yxy * bloom_de(p + k.yxy * e, b, iters).x + k.xxx * bloom_de(p + k.xxx * e, b, iters).x);
}

// ---- kaleidoscopic hedge pattern ----
fn kaleido(uv0: vec2f, n: i32) -> vec3f {
    var uv = uv0;
    var acc = 0.0;
    var sc = 1.0;
    for (var i = 0; i < n; i = i + 1) {
        uv = abs(uv) - vec2f(0.55, 0.35);
        uv = rot2(0.7 + 0.08 * sin(time() * 0.2) + HUE) * uv;
        uv *= 1.45;
        sc *= 1.45;
        acc += exp(-abs(length(uv) - 0.8) * 6.0) / f32(i + 1);
    }
    let leaf = palette(acc * 0.6 + HUE * 0.5 + 0.25, vec3f(0.12, 0.35, 0.18), vec3f(0.1, 0.3, 0.15),
                       vec3f(1.0, 1.0, 1.0), vec3f(0.3, 0.2, 0.25));
    let flower = palette(acc + HUE + time() * 0.03, vec3f(0.6), vec3f(0.4), vec3f(1.0), vec3f(0.0, 0.33, 0.67));
    return mix(leaf * (0.5 + acc * 0.35), flower * 1.4, smoothstep(1.5, 2.4, acc));
}

struct Cand { t: f32, col: vec3f };

fn stream_glow(wp: vec3f) -> f32 {
    let d = abs(wp.x - stream_x(wp.z));
    return exp(-max(d - 0.6, 0.0) * 1.2);
}

fn hedge(ro: vec3f, rd: vec3f, tmin: f32, cur: Cand) -> Cand {
    var best = cur;
    let w = 0.7;
    for (var j = 0; j < 8; j = j + 1) {
        let i = j / 2;
        var bmin = vec3f(-6.0, 0.0, -6.0);
        var bmax = vec3f(6.0, HEDGE_H, 6.0);
        if (i == 0) { bmax.z = -6.0 + w; }
        if (i == 1) { bmin.z = 6.0 - w; }
        if (i == 2) { bmax.x = -6.0 + w; }
        if (i == 3) { bmin.x = 6.0 - w; }
        // leave the doorway clear (1.8 m door plus a little margin)
        let gap = ((DOORS >> u32(i)) & 1) == 1;
        if (!gap && (j & 1) == 1) { continue; }
        if (gap) {
            if (i < 2) { if ((j & 1) == 0) { bmax.x = -1.0; } else { bmin.x = 1.0; } }
            else { if ((j & 1) == 0) { bmax.z = -1.0; } else { bmin.z = 1.0; } }
        }
        let sp = box_span(ro, rd, bmin, bmax);
        if (sp.x <= sp.y && sp.y > tmin && sp.x < best.t) {
            let t = max(sp.x, tmin);
            let p = ro + rd * t;
            let wp = wpos(p);
            var uv = select(vec2f(wp.x, p.y), vec2f(wp.z, p.y), i >= 2);
            if (abs(p.y - HEDGE_H) < 0.01) { uv = select(wp.xz, wp.zx, i >= 2); }
            let cell = fract(uv / 1.6) * 2.0 - 1.0;
            let nk = i32(mix(3.0, 7.0, lvl()));
            var c = kaleido(cell * 1.3, nk);
            let fuzz = noise3(wp * 14.0);
            c *= 0.75 + 0.5 * fuzz;
            c *= 0.55 + 0.45 * smoothstep(0.0, HEDGE_H, p.y);
            c += vec3f(0.1, 0.7, 0.8) * stream_glow(wp) * 0.25 * exp(-p.y);
            best = Cand(t, c);
        }
    }
    return best;
}

fn shade1(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let q = lvl();
    var best = Cand(tmax + 1.0, vec3f(0.0));

    // floor: lawn + glowing stream
    let tf = plane_y(ro, rd, 0.0);
    if (tf > tmin && tf < tmax + 0.05) {
        let p = ro + rd * tf;
        let wp = wpos(p);
        let sx = stream_x(wp.z);
        let d = abs(wp.x - sx);
        let flow = fbm3(vec3f(wp.x * 1.5, wp.z * 0.7 - time() * 1.4, time() * 0.2));
        let tile = abs(fract(wp.xz * 0.5) - 0.5);
        let grid = smoothstep(0.47, 0.5, max(tile.x, tile.y));
        var c = mix(vec3f(0.04, 0.09, 0.05), vec3f(0.07, 0.16, 0.08), noise3(wp * 3.0));
        c = mix(c, vec3f(0.25, 0.22, 0.3), grid * 0.4);
        let water = mix(vec3f(0.05, 0.5, 0.75), vec3f(0.6, 1.0, 0.95), flow);
        let wcol = water * (0.35 + 0.7 * pow(flow, 3.0)) + palette(wp.z * 0.05 - time() * 0.1 + HUE, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67)) * 0.3;
        c = mix(c, wcol, smoothstep(0.75, 0.55, d));
        c += vec3f(0.1, 0.6, 0.7) * exp(-max(d - 0.6, 0.0) * 1.5) * 0.35;
        // blossom pools of light
        for (var i = 0; i < NBT; i = i + 1) {
            let b = bloom_of(i);
            let dd = length(p.xz - b.c.xz);
            c += palette(f32(i) * 0.17 + HUE, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67)) * 0.07 / (1.0 + dd * dd * 1.5);
        }
        best = Cand(min(tf, tmax), c);
    }

    best = hedge(ro, rd, tmin, best);

    // stems
    for (var i = 0; i < NB; i = i + 1) {
        let b = bloom_of(i);
        let sp = box_span(ro, rd, vec3f(b.c.x - 0.035, 0.0, b.c.z - 0.035), vec3f(b.c.x + 0.035, b.c.y - b.s * 0.6, b.c.z + 0.035));
        if (sp.x <= sp.y && sp.y > tmin && sp.x < best.t) {
            let t = max(sp.x, tmin);
            let p = ro + rd * t;
            best = Cand(t, vec3f(0.08, 0.3, 0.12) * (0.5 + p.y * 0.3));
        }
    }

    // mandelbulb blossoms, each marched inside its bounding sphere
    let steps = i32(mix(select(MAX_STEPS, 20.0, RESPECT), MAX_STEPS, q));
    let iters = i32(mix(select(MAX_ITERS, 3.0, RESPECT), MAX_ITERS, q));
    for (var i = 0; i < NBT; i = i + 1) {
        let b = bloom_of(i);
        let rad = 1.2 * b.s;
        let oc = ro - b.c;
        let bb = dot(oc, rd);
        let cc = dot(oc, oc) - rad * rad;
        let disc = bb * bb - cc;
        if (disc < 0.0) { continue; }
        let sq = sqrt(disc);
        var t = max(-bb - sq, tmin);
        let t1 = min(-bb + sq, best.t);
        if (t > t1) { continue; }
        var glow = 0.0;
        var hit = false;
        var trap = 0.0;
        for (var s = 0; s < steps; s = s + 1) {
            let d = bloom_de(ro + rd * t, b, iters);
            glow += 0.012 / (0.02 + d.x * d.x * 40.0);
            if (d.x < 0.0008 * t) { hit = true; trap = d.y; break; }
            t += d.x * 0.9;
            if (t > t1) { break; }
        }
        let pal = palette(HUE + f32(i) * 0.17, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67));
        if (hit) {
            let p = ro + rd * t;
            let n = bloom_normal(p, b, iters);
            var c = palette(sqrt(trap) * 0.8 + HUE + f32(i) * 0.17 + time() * 0.02, vec3f(0.55), vec3f(0.45), vec3f(1.0, 1.0, 0.8), vec3f(0.0, 0.25, 0.5));
            let dif = max(dot(n, moon_dir()), 0.0);
            let down = max(-n.y, 0.0);
            var ao = 1.0;
            var sh = 1.0;
            if (EXTRA) {
                ao = 0.0;
                for (var k = 1; k <= 6; k = k + 1) {
                    let h = 0.02 * f32(k);
                    ao += (h - bloom_de(p + n * h, b, iters).x) / f32(k);
                }
                ao = clamp(1.0 - ao * 6.0, 0.2, 1.0);
                var st = 0.01;
                for (var k = 0; k < 32; k = k + 1) {
                    let d = bloom_de(p + moon_dir() * st, b, iters).x;
                    sh = min(sh, 12.0 * d / st);
                    st += max(d, 0.01);
                    if (sh < 0.02 || st > 2.0) { break; }
                }
                sh = clamp(sh, 0.15, 1.0);
            }
            let rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
            c = c * (0.18 + 0.8 * dif * sh) * ao + vec3f(0.1, 0.6, 0.7) * down * 0.4 + pal * rim * 0.9;
            best = Cand(t, c);
        } else if (glow > 0.02) {
            best.col += pal * min(glow, 1.5) * 0.25;
        }
    }

    if (best.t > tmax) {
        // above the hedges: open night sky
        if (rd.y > 0.0 || ro.y > HEDGE_H) {
            return Hit(tone(sky(rd) * 1.4), horizon_t(tmax));
        }
        return no_hit();
    }
    // a little mist toward the stream light
    let col = best.col * 1.6;
    return Hit(tone(col), best.t);
}

// supersampling: SS jittered rays per pixel (rooms that respect quality() drop to 1 when over budget)
fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let n = select(SS, 1, RESPECT && quality() < 0.99);
    var h = shade1(ro, rd, tmin, tmax);
    if (n <= 1) { return h; }
    var acc = h.color;
    for (var k = 1; k < n; k = k + 1) {
        let j = (hash33(rd * 917.0 + f32(k)) - 0.5) * 0.0012;
        acc += shade1(ro, normalize(rd + j), tmin, tmax).color;
    }
    return Hit(acc / f32(n), h.t);
}

shaders.0b22d510e33631106eb247e9c90d:
// Signal, room 1/12 at (1,0). seq 9000. A pulse of light travels down a wire, room to room.
const E: f32 = 0.6000;
const COL: vec3f = vec3f(1.0000, 0.5580, 0.1500);
const TRAIL: vec3f = vec3f(0.5500, 0.4708, 0.0550);
const A_IN: vec3f = vec3f(0.0000, 3.7000, 0.0000);
const A_OUT: vec3f = vec3f(6.0000, 1.3000, 0.0000);
const CEN: vec3f = vec3f(0.0, 1.3, 0.0);
const S0: f32 = 3.600;
const L1: f32 = 2.400;
const KIND: i32 = 1;
const STEPS: i32 = 72;
const VSTEPS: i32 = 28;
const GOFF: vec3f = vec3f(12.0, 0.0, 0.0);

// distance to the wire centreline and global arc length along it
fn wire(p: vec3f) -> vec2f {
    let b1 = CEN - A_IN;
    let h1 = clamp(dot(p - A_IN, b1) / max(dot(b1, b1), 1e-4), 0.0, 1.0);
    let d1 = length(p - A_IN - b1 * h1);
    let b2 = A_OUT - CEN;
    let h2 = clamp(dot(p - CEN, b2) / max(dot(b2, b2), 1e-4), 0.0, 1.0);
    let d2 = length(p - CEN - b2 * h2);
    if (d1 < d2) { return vec2f(d1, S0 + h1 * L1); }
    return vec2f(d2, S0 + L1 + h2 * length(b2));
}

fn spark(s: f32) -> f32 {
    let v = 0.5 + 2.6 * E;
    let f = fract(s * 0.35 - time() * v * 0.35);
    let g = fract(s * 0.9 + time() * 0.21);
    return exp(-pow((f - 0.5) * 9.0, 2.0)) * (0.4 + 1.6 * E) + 0.12 * exp(-pow((g - 0.5) * 14.0, 2.0));
}

fn light_col() -> vec3f { return mix(TRAIL, COL, clamp(E * 1.6, 0.0, 1.0)); }
fn level() -> f32 { return 0.06 + E; }

// solids: 0 none, 1 wire, 2 node, 3 posts/mast, 4 orb
fn map(p: vec3f) -> vec2f {
    let w = wire(p);
    var d = w.x - 0.055;
    var m = 1.0;
    // repeater node in the middle of each room
    var nr = 0.2 + 0.12 * E;
    if (KIND == 2) { nr = 0.85; }
    let dn = length(p - CEN) - nr;
    if (dn < d) { d = dn; m = select(2.0, 4.0, KIND == 2); }
    // insulator posts holding the line, every 3 m on the floor
    let q = vec3f(p.x, p.y, p.z);
    let ax = abs(q.x); let az = abs(q.z);
    var dp = 1e3;
    // posts sit under the wire: the wire runs along x or z through centre
    let px = vec3f(q.x - clamp(round(q.x / 3.0) * 3.0, -3.0, 3.0), q.y, q.z);
    let pz = vec3f(q.x, q.y, q.z - clamp(round(q.z / 3.0) * 3.0, -3.0, 3.0));
    let use_x = abs(A_IN.x) + abs(A_OUT.x) > 0.5;
    let use_z = abs(A_IN.z) + abs(A_OUT.z) > 0.5;
    if (use_x) { dp = min(dp, sd_box(px - vec3f(0.0, 0.62, 0.0), vec3f(0.035, 0.62, 0.035))); }
    if (use_z) { dp = min(dp, sd_box(pz - vec3f(0.0, 0.62, 0.0), vec3f(0.035, 0.62, 0.035))); }
    if (KIND == 1) {
        dp = min(dp, length(p.xz) - 0.09 + 0.02 * p.y);
        dp = max(dp, p.y - 3.7);
        // emitter dish rings around the mast
        let ry = p.y - 3.7;
        let tor = length(vec2f(length(p.xz) - 0.7, ry)) - 0.03;
        let tor2 = length(vec2f(length(p.xz) - 1.2, ry + 0.25)) - 0.025;
        dp = min(dp, min(tor, tor2));
    }
    if (KIND == 2) {
        let rp = p - CEN;
        let r1 = vec3f(rp.x, (rot2(time() * 0.3) * rp.yz));
        let r2 = vec3f((rot2(time() * 0.23) * rp.xy), rp.z);
        let t1 = length(vec2f(length(r1.xy) - 1.4, r1.z)) - 0.03;
        let t2 = length(vec2f(length(r2.xz) - 1.75, r2.y)) - 0.025;
        dp = min(dp, min(t1, t2));
    }
    if (dp < d) { d = dp; m = 3.0; }
    return vec2f(d, m);
}

fn nrm(p: vec3f) -> vec3f {
    let e = vec2f(0.002, 0.0);
    return normalize(vec3f(map(p + e.xyy).x - map(p - e.xyy).x, map(p + e.yxy).x - map(p - e.yxy).x, map(p + e.yyx).x - map(p - e.yyx).x));
}

// light falling on a surface point from the wire and node
fn glow_at(p: vec3f) -> vec3f {
    let w = wire(p);
    let lc = light_col();
    var c = lc * level() * (0.9 + spark(w.y)) * 0.5 / (1.0 + 2.2 * w.x * w.x);
    let dn = length(p - CEN);
    c += lc * level() * 0.75 / (1.0 + 0.8 * dn * dn);
    // shockwave from the node when the pulse is here
    let ph = fract(time() * 0.55);
    let shell = exp(-abs(dn - ph * 8.0) * 3.0) * (1.0 - ph);
    c += COL * shell * E * E * 1.8;
    return c;
}

fn orb(rd: vec3f, ro: vec3f, t0: f32) -> vec3f {
    // volumetric swirling core of the receiver
    var acc = vec3f(0.0);
    var tr = 1.0;
    let n = max(6, i32(f32(VSTEPS) * (0.35 + 0.65 * quality())));
    let span = box_span(ro, rd, CEN - vec3f(0.86), CEN + vec3f(0.86));
    let dt = 1.72 / f32(n);
    var t = max(span.x, t0);
    for (var i = 0; i < n; i = i + 1) {
        let p = ro + rd * t - CEN;
        if (length(p) < 0.85) {
            let q = vec3f(rot2(time() * 0.4) * p.xz, p.y).xzy;
            let den = smoothstep(0.35, 0.75, fbm3(q * 2.6 + vec3f(0.0, time() * 0.5, 0.0))) * (1.0 - length(p) / 0.85);
            let c = mix(TRAIL, COL, 0.5 + 0.5 * sin(length(p) * 9.0 - time() * 3.0));
            acc += tr * c * den * dt * (3.0 + 9.0 * E);
            tr *= exp(-den * dt * 4.0);
        }
        t += dt;
        if (t > span.y) { break; }
    }
    return acc + tr * light_col() * (0.4 + E) * 0.6;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let tf = plane_y(ro, rd, 0.0);
    var tend = horizon_t(tmax);
    var surf = 0;
    if (tf > 0.0 && tf < tend) { tend = tf; surf = 1; }
    var t = max(tmin, 0.0);
    var haze = vec3f(0.0);
    var hit = -1.0;
    var mat = 0.0;
    let lc = light_col();
    for (var i = 0; i < STEPS; i = i + 1) {
        let p = ro + rd * t;
        let m = map(p);
        let w = wire(p);
        // volumetric bloom around the wire
        let sd = max(min(w.x, length(p - CEN)), 0.02);
        haze += lc * level() * (0.15 + spark(w.y)) * 0.0028 / (sd * sd + 0.02) * max(m.x, 0.02);
        if (m.x < 0.0015 * t) { hit = t; mat = m.y; break; }
        t += m.x * 0.9;
        if (t > tend) { break; }
    }
    var col = vec3f(0.0);
    var tout = tend;
    if (hit > 0.0) {
        let p = ro + rd * hit;
        tout = hit;
        let w = wire(p);
        if (mat < 1.5) {
            col = lc * (0.22 + 6.0 * E) * (0.5 + spark(w.y)) + vec3f(1.0) * E * E * spark(w.y);
        } else if (mat < 2.5) {
            let n = nrm(p);
            let rim = pow(1.0 - abs(dot(n, -rd)), 2.0);
            col = lc * (1.0 + 9.0 * E) * (0.6 + 0.4 * sin(time() * 6.0)) + rim * vec3f(1.0) * E;
        } else if (mat < 3.5) {
            let n = nrm(p);
            let g = glow_at(p + n * 0.1);
            let fres = pow(1.0 - abs(dot(n, -rd)), 4.0);
            col = vec3f(0.04, 0.045, 0.06) + g * 0.5 + fres * lc * level() * 1.5;
        } else {
            let n = nrm(p);
            let rim = pow(1.0 - abs(dot(n, -rd)), 3.0);
            col = orb(rd, ro, hit) + rim * mix(lc, vec3f(1.0), 0.5) * (0.6 + E);
        }
    } else {
        let p = ro + rd * tend;
        let g = glow_at(p);
        // world-space position so patterns continue through the doors
        let wp = p + GOFF;
        if (surf == 1) {
            // polished black floor with circuit traces
            let cell = floor(wp.xz / 1.5);
            let f = fract(wp.xz / 1.5) - 0.5;
            let lineg = smoothstep(0.03, 0.0, min(abs(f.x), abs(f.y)));
            let pad = smoothstep(0.09, 0.05, length(f)) * step(0.72, hash12(cell));
            let r = reflect(rd, vec3f(0.0, 1.0, 0.0));
            let rw = wire(p + r * 1.3);
            let refl = lc * level() * (0.3 + spark(rw.y)) * 0.35 / (1.0 + 6.0 * rw.x * rw.x);
            col = vec3f(0.012, 0.014, 0.02) + g * (0.16 + 0.5 * lineg + 1.2 * pad) + refl;
        } else {
            // dark ribbed walls and ceiling
            let ap = abs(p);
            var uv = vec2f(wp.x + wp.z, p.y);
            if (ap.y > 4.45) { uv = wp.xz; }
            let rib = smoothstep(0.02, 0.0, abs(fract(uv.x / 0.75) - 0.5) - 0.46);
            let band = smoothstep(0.03, 0.0, abs(p.y - 1.3) - 0.015) * step(ap.y, 4.45);
            col = vec3f(0.018, 0.02, 0.03) + g * (0.12 + 0.25 * rib) + band * lc * level() * (0.4 + spark(uv.x * 0.5));
        }
    }
    col += haze;
    return Hit(tone(col * 1.15), tout);
}

shaders.0876b8675e94f70770d1894088bb:
// Tidal Cathedral, room (-4,3). A flooded gothic nave continued room to room.
const GX: f32 = -4.0;
const GY: f32 = 3.0;
const MODE: i32 = 3;
const AXIS: i32 = 1;
const END: f32 = 1.0;
const STEPS: f32 = 140.0;
const VSTEPS: f32 = 64.0;
const REFL: f32 = 0.7;
// ---- Tidal Cathedral: shared world. Frame coords: x = world position along the nave axis,
// y = up, z = across the nave (room-local). All rooms sample the same building, so the
// arcades, ribs, light shafts and the slow westward current run on through the doorways.
const WATER: f32 = 0.30;
const ZC: f32 = 3.5;

fn along0() -> f32 { return select(GY, GX, AXIS == 0) * 12.0; }
fn to_frame(v: vec3f) -> vec3f { if (AXIS == 0) { return v; } return vec3f(v.z, v.y, v.x); }
fn sunv() -> vec3f {
    let t = time() * 0.035;
    return normalize(vec3f(0.32 + 0.16 * sin(t), 0.74 + 0.05 * cos(t * 1.3), 1.0));
}

// pointed (two-centred) opening: negative inside. hw = half width at springing ys.
fn opening(u: f32, y: f32, ys: f32, hw: f32, d: f32) -> f32 {
    let au = abs(u);
    let dv = length(vec2f(au + d, y - ys)) - (hw + d);
    return select(dv, au - hw, y < ys);
}
fn bayu(x: f32) -> f32 { return x - 4.0 * round(x / 4.0); }
fn pieru(x: f32) -> f32 { let s = x + 2.0; return s - 4.0 * round(s / 4.0); }

fn pier(pu: f32, y: f32, dz: f32) -> f32 {
    let q = vec2f(pu, dz);
    var d = length(q) - 0.29;
    let a = abs(q);
    d = min(d, min(length(a - vec2f(0.33, 0.0)), length(a - vec2f(0.0, 0.33))) - 0.10);
    d = min(d, sd_box(vec3f(pu, y - 0.15, dz), vec3f(0.5, 0.42, 0.5)) - 0.03);
    let cy = y - 1.62;
    let w = 0.47 + clamp(cy, -0.12, 0.12) * 0.6;
    d = min(d, sd_box(vec3f(pu, cy, dz), vec3f(w, 0.11, w)) - 0.01);
    return d;
}

fn arcade(x: f32, y: f32, z: f32, open_south: bool) -> f32 {
    let dz = abs(z) - ZC;
    var d = pier(pieru(x), y, dz);
    if (open_south && z > 0.0) { return d; }
    let u = bayu(x);
    let op = opening(u, y, 1.72, 1.66, 0.8);
    d = min(d, max(abs(dz) - 0.22, -op));
    let roll = max(abs(op + 0.08) - 0.07, abs(dz) - 0.29);
    d = min(d, max(roll, 1.6 - y));
    d = min(d, sd_box(vec3f(0.0, y - 4.12, dz), vec3f(100.0, 0.05, 0.29)));
    // small trefoil piercings in the spandrels
    let sp = vec2f(abs(u) - 1.95, y - 3.75);
    d = max(d, -max(length(sp) - 0.17, abs(dz) - 0.4));
    return d;
}

fn ribs(x: f32, y: f32, z: f32) -> f32 {
    let pu = pieru(x);
    let m = 1.6;
    let op = opening(z * 0.47, 1.72 + (y - 3.0) * m, 1.72, 1.66, 0.8);
    let ring = (abs(op + 0.09) - 0.09) / m;
    return max(max(ring, abs(pu) - 0.12), 2.95 - y);
}

fn waves(p: vec2f) -> f32 {
    let t = time();
    var h = sin(p.x * 1.1 + p.y * 0.4 + t * 0.9) * 0.5;
    h += sin(p.x * -0.5 + p.y * 1.7 + t * 1.3) * 0.3;
    h += sin(p.x * 2.9 - p.y * 1.3 + t * 2.1) * 0.12;
    h += (noise3(vec3f(p.x * 1.4 + t * 0.45, p.y * 1.4, t * 0.25)) - 0.5) * 0.6;
    return h * 0.035;
}

fn caustic(p: vec2f) -> f32 {
    let t = time();
    let a = noise3(vec3f(p * 2.3 + vec2f(t * 0.3, 0.0), t * 0.4));
    let b = noise3(vec3f(p * 3.1 - vec2f(0.0, t * 0.2), 4.0 + t * 0.5));
    return pow(1.0 - abs(a - b), 9.0);
}

fn glass(u: f32, y: f32, xw: f32) -> vec4f {
    let op = opening(u * 3.69, 1.72 + (y - 3.55) * 3.1, 1.72, 1.66, 0.8);
    if (op > 0.0 || y < 2.75) { return vec4f(0.0); }
    let c = vec2f(u * 7.0, y * 5.5 - xw * 0.3);
    let cell = floor(c + vec2f(floor(xw / 4.0) * 3.0, 0.0));
    let f = fract(c);
    let lead = smoothstep(0.0, 0.12, min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y)));
    let h = hash12(cell);
    var g = vec3f(0.08, 0.2, 0.95);
    if (h > 0.55) { g = vec3f(0.95, 0.12, 0.1); }
    if (h > 0.78) { g = vec3f(1.0, 0.72, 0.15); }
    if (h > 0.92) { g = vec3f(0.15, 0.85, 0.35); }
    let edge = smoothstep(0.0, 0.06, -op / 3.69);
    return vec4f(g, lead * edge);
}

// coloured sunlight reaching frame point p (through the +z windows, past the arcade)
fn shaft(p: vec3f, open_south: bool) -> vec3f {
    let S = sunv();
    if (p.z > 5.9 || p.y < 0.0) { return vec3f(0.0); }
    let q = p + S * ((6.0 - p.z) / S.z);
    let g = glass(bayu(q.x), q.y, q.x);
    if (g.a <= 0.0) { return vec3f(0.0); }
    var k = g.a;
    if (p.z < ZC - 0.22 && !open_south) {
        let qa = p + S * ((ZC - p.z) / S.z);
        let o = opening(bayu(qa.x), qa.y, 1.72, 1.66, 0.8);
        k *= smoothstep(0.05, -0.1, o);
        k *= smoothstep(0.3, 0.5, abs(pieru(qa.x)));
    }
    return g.rgb * k;
}

fn ashlar(p: vec2f) -> f32 {
    let row = floor(p.y / 0.38);
    let off = select(0.0, 0.3, fract(row * 0.5) > 0.25);
    let f = fract(vec2f((p.x + off) / 0.6, p.y / 0.38));
    let e = min(min(f.x, 1.0 - f.x) * 0.6, min(f.y, 1.0 - f.y) * 0.38);
    return 0.82 + 0.18 * smoothstep(0.0, 0.02, e);
}

fn stone_albedo(p: vec3f) -> vec3f {
    let n = noise3(p * 3.0);
    var c = vec3f(0.62, 0.57, 0.5) * (0.75 + 0.35 * n);
    let tide = WATER + 0.55 + 0.25 * noise3(vec3f(p.x * 0.7, 0.0, p.z * 0.7));
    let wet = smoothstep(tide + 0.1, tide - 0.1, p.y);
    c = mix(c, vec3f(0.16, 0.24, 0.2) * (0.7 + 0.6 * n), wet * 0.8);
    c = mix(c, vec3f(0.3, 0.45, 0.32), smoothstep(0.62, 0.8, noise3(p * 7.0)) * wet);
    return c;
}

fn light_stone(p: vec3f, n: vec3f, alb: vec3f, open_south: bool) -> vec3f {
    let S = sunv();
    var l = vec3f(0.035, 0.055, 0.08) * (0.6 + 0.4 * n.y);
    l += vec3f(0.09, 0.07, 0.1) * max(n.z, 0.0) + vec3f(0.02, 0.04, 0.07) * max(-n.z, 0.0);
    l += shaft(p + n * 0.02, open_south) * max(dot(n, S), 0.0) * 4.0;
    let up = exp(-(p.y - WATER) * 0.9) * max(-n.y * 0.6 + 0.4, 0.0);
    l += vec3f(0.2, 0.42, 0.45) * caustic(p.xz * 0.8 + p.y * 0.3) * up * 0.7;
    return alb * l;
}

fn sky_through(rd: vec3f) -> vec3f {
    let y = max(rd.y, 0.0);
    var c = mix(vec3f(0.9, 0.75, 0.55), vec3f(0.35, 0.55, 0.9), y);
    let cl = fbm3(vec3f(rd.xz / (rd.y + 0.2) * 1.3 + vec2f(time() * 0.02, 0.0), 1.0));
    return mix(c, vec3f(1.0, 0.95, 0.9), smoothstep(0.45, 0.75, cl) * 0.7);
}

fn rose(v: vec2f, r0: f32) -> vec4f {
    let r = length(v) / r0;
    if (r > 1.0) { return vec4f(0.0); }
    let a = atan2(v.y, v.x);
    let seg = TAU / 12.0;
    let ai = floor(a / seg);
    let af = a - (ai + 0.5) * seg;
    let pv = vec2f(cos(af), sin(af)) * r;
    let petal = length(pv - vec2f(0.62, 0.0)) - 0.27;
    let hub = r - 0.22;
    let ring = abs(r - 0.93) - 0.035;
    let spokes = abs(pv.y) - 0.02;
    var lead = min(min(abs(petal) - 0.025, abs(hub) - 0.025), ring);
    lead = min(lead, select(1.0, spokes, r > 0.22 && petal > 0.0));
    let h = hash12(vec2f(ai, floor(r * 6.0)));
    var g = mix(vec3f(0.1, 0.18, 0.95), vec3f(0.95, 0.15, 0.25), step(0.5, h));
    if (petal < 0.0) { g = mix(vec3f(1.0, 0.7, 0.2), vec3f(0.2, 0.8, 0.5), step(0.7, h)); }
    if (hub < 0.0) { g = vec3f(1.0, 0.85, 0.4); }
    let m = smoothstep(0.0, 0.02, lead) * smoothstep(1.0, 0.97, r);
    return vec4f(g * (0.8 + 0.4 * fract(h * 7.0)), m);
}

// ---- painted surfaces at the room's box boundary (frame coords) ----
fn paint(p: vec3f, rd: vec3f, os: bool) -> vec3f {
    let lx = p.x - along0();
    let S = sunv();
    if (p.y > ROOM_HEIGHT - 0.01) {
        // star-spangled rib vault
        let bu = bayu(p.x);
        var zc = ZC;
        var zz = p.z;
        if (abs(p.z) > ZC) { zz = abs(p.z) - (ZC + 6.0) * 0.5; zc = (6.0 - ZC) * 0.5; }
        let diag = abs(abs(bu) / 2.0 - abs(zz) / zc);
        var rib = min(diag * 1.6, abs(zz) * 1.5);
        rib = min(rib, min(abs(abs(bu) - 2.0), abs(abs(p.z) - ZC)) * 2.0);
        let sc = p.xz * 9.0;
        let st = hash12(floor(sc));
        let star = smoothstep(0.16, 0.0, length(fract(sc) - 0.5)) * step(0.93, st);
        var c = vec3f(0.03, 0.05, 0.16) + vec3f(0.9, 0.7, 0.3) * star * (0.6 + 0.4 * sin(time() * 2.0 + st * 40.0));
        c = mix(vec3f(0.5, 0.42, 0.3), c, smoothstep(0.03, 0.06, rib));
        c *= 0.5 + 0.5 * caustic(p.xz * 0.6) + 0.15;
        if (MODE == 1) {
            let r = length(vec2f(lx, p.z));
            if (r < 1.3) { return sky_through(rd) * 2.0; }
            c = mix(c, vec3f(0.85, 0.65, 0.3), smoothstep(0.08, 0.0, abs(r - 1.42)));
        }
        return c;
    }
    if (abs(p.z) > 5.99) {
        // side walls: ashlar with lancet windows; the +z wall faces the sun
        let a = ashlar(vec2f(p.x, p.y));
        var c = stone_albedo(p) * a * 0.18;
        c += vec3f(0.15, 0.32, 0.35) * caustic(p.xy * 0.7) * exp(-(p.y - WATER) * 1.2) * 0.4;
        let g = glass(bayu(p.x), p.y, p.x);
        let lit = select(0.22, 2.4, p.z > 0.0);
        c = mix(c, g.rgb * lit, g.a);
        return c;
    }
    // end walls between bays: diaphragm wall with a rose window over the door
    let a = ashlar(vec2f(p.z, p.y));
    var c = stone_albedo(p) * a * 0.2;
    c += vec3f(0.15, 0.32, 0.35) * caustic(p.zy * 0.7) * exp(-(p.y - WATER) * 1.2) * 0.4;
    var rc = vec2f(p.z, p.y - 3.55);
    var rr = 0.8;
    if (MODE == 3 && lx * END > 0.0) { rc = vec2f(p.z, p.y - 2.25); rr = 2.1; }
    let g = rose(rc, rr);
    let face = select(1.0, 1.7, (rd.x > 0.0) == (S.x < 0.0));
    c = mix(c, g.rgb * 1.5 * face, g.a);
    c = mix(c, vec3f(0.4, 0.33, 0.25), smoothstep(0.05, 0.0, abs(length(rc) - rr - 0.06)) * 0.8);
    return c;
}

fn open_s() -> bool { return MODE == 1; }

fn feature(p: vec3f) -> f32 {
    let lx = p.x - along0();
    if (MODE == 1) {
        // the crossing font: a tiered basin, its upper bowl brimming with light
        let r = length(vec2f(lx, p.z));
        var d = max(abs(r - 1.15) - 0.09, p.y - 0.62);
        d = min(d, max(r - 1.24, abs(p.y - 0.12) - 0.12));
        d = min(d, max(r - 0.16 - 0.06 * smoothstep(1.3, 1.6, p.y), p.y - 1.6));
        let bowl = max(abs(length(vec3f(lx, p.y - 1.85, p.z)) - 0.62) - 0.04, p.y - 1.8);
        d = min(d, max(bowl, 1.25 - p.y));
        d = min(d, max(r - 0.58, abs(p.y - 1.66) - 0.02));
        d = min(d, corona(p));
        return d;
    }
    if (MODE == 3) {
        let q = vec3f(lx - END * 3.6, p.y, p.z);
        var d = sd_box(q - vec3f(0.0, 0.2, 0.0), vec3f(1.5, 0.35, 2.0));
        d = min(d, sd_box(q - vec3f(0.0, 0.6, 0.0), vec3f(1.1, 0.25, 1.5)));
        d = min(d, sd_box(q - vec3f(0.0, 1.0, 0.0), vec3f(0.45, 0.35, 0.95)) - 0.02);
        let rq = q - vec3f(0.0, 1.95 + 0.08 * sin(time() * 0.7), 0.0);
        d = min(d, sd_sphere(rq, 0.32));
        return d;
    }
    return 1e5;
}

fn map(p: vec3f) -> f32 {
    var d = arcade(p.x, p.y, p.z, open_s());
    d = min(d, ribs(p.x, p.y, p.z));
    d = min(d, feature(p));
    return d;
}

fn calc_n(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn march(ro: vec3f, rd: vec3f, t0: f32, t1: f32, n: i32) -> f32 {
    var t = t0;
    for (var i = 0; i < 200; i = i + 1) {
        if (i >= n || t > t1) { break; }
        let d = map(ro + rd * t);
        if (d < 0.0008 + 0.0015 * t) { return t; }
        t += d * 0.8;
    }
    return -1.0;
}

fn ao(p: vec3f, n: vec3f) -> f32 {
    var o = 0.0;
    var s = 1.0;
    for (var i = 1; i < 5; i = i + 1) {
        let h = 0.06 * f32(i);
        o += (h - map(p + n * h)) * s;
        s *= 0.6;
    }
    return clamp(1.0 - 2.2 * o, 0.0, 1.0);
}

fn surf(p: vec3f, rd: vec3f, full: bool) -> vec3f {
    let n = calc_n(p);
    var alb = stone_albedo(p);
    let lx = p.x - along0();
    var c = light_stone(p, n, alb, open_s());
    if (full) { c *= ao(p, n); }
    if (MODE == 1) {
        let r = length(vec2f(lx, p.z));
        if (p.y > 1.62 && r < 0.585) {
            let rip = 0.5 + 0.5 * sin(r * 30.0 - time() * 4.0);
            c = vec3f(0.5, 0.9, 0.85) * (0.6 + 0.5 * rip) + vec3f(1.0, 0.8, 0.5) * caustic(vec2f(lx, p.z) * 3.0);
        }
        c += vec3f(1.0, 0.8, 0.5) * 0.35 * max(n.y, 0.0) * smoothstep(1.6, 0.5, r);
        c += alb * candle_light(p, n) + flame(p);
    }
    if (MODE == 3) {
        let rq = vec3f(lx - END * 3.6, p.y - 1.95 - 0.08 * sin(time() * 0.7), p.z);
        if (length(rq) < 0.34) {
            let f = pow(1.0 - max(dot(-rd, n), 0.0), 3.0);
            let band = step(0.5, fract(atan2(rq.z, rq.x) * 1.91 + rq.y * 3.0));
            let env = paint(vec3f(along0() - 6.0 * END, clamp(p.y + n.y * 3.0, 0.1, 4.4), clamp(n.z * 6.0, -5.9, 5.9)), n, false);
            c = vec3f(0.9, 0.6, 0.22) * (0.12 + 0.25 * band + 0.2 * noise3(rq * 9.0 + time())) * (0.4 + max(n.y, 0.0));
            c += env * vec3f(1.0, 0.75, 0.4) * (0.4 + f) + vec3f(1.2, 0.9, 0.5) * pow(f, 2.0) * 0.6;
        }
    }
    return c;
}

fn bmin() -> vec3f { return vec3f(along0() - 6.0, 0.0, -6.0); }
fn bmax() -> vec3f { return vec3f(along0() + 6.0, ROOM_HEIGHT, 6.0); }

// a secondary ray: structures first, then the painted box
fn trace2(ro: vec3f, rd: vec3f, n: i32) -> vec3f {
    let te = box_span(ro, rd, bmin(), bmax()).y;
    let t = march(ro, rd, 0.02, te, n);
    if (t > 0.0) { return surf(ro + rd * t, rd, false); }
    return paint(ro + rd * te, rd, open_s());
}

fn water(pw: vec3f, rd: vec3f, nref: i32) -> vec3f {
    let e = 0.03;
    let h = waves(pw.xz);
    let n = normalize(vec3f(h - waves(pw.xz + vec2f(e, 0.0)), e, h - waves(pw.xz + vec2f(0.0, e))));
    let fres = 0.02 + 0.98 * pow(1.0 - max(dot(-rd, n), 0.0), 5.0);
    let r = reflect(rd, n);
    let refl = trace2(pw + n * 0.01, r, nref);
    // refraction down to the drowned floor
    let rr = refract(rd, n, 0.75);
    let tf = -pw.y / min(rr.y, -0.05);
    let fp = pw + rr * tf;
    let tiles = fract(fp.xz * 0.5);
    let grout = smoothstep(0.0, 0.04, min(min(tiles.x, 1.0 - tiles.x), min(tiles.y, 1.0 - tiles.y)));
    let chk = select(0.7, 1.0, (floor(fp.x * 0.5) + floor(fp.z * 0.5)) % 2.0 == 0.0);
    var fl = vec3f(0.3, 0.32, 0.3) * grout * chk;
    let lit = shaft(fp, open_s()) * 2.0 + vec3f(0.05, 0.1, 0.1);
    fl *= lit + vec3f(0.6, 0.9, 0.85) * caustic(fp.xz) * (0.3 + length(lit));
    let absorb = exp(-tf * vec3f(1.6, 0.55, 0.45) * 1.4);
    var c = mix(fl * absorb + vec3f(0.005, 0.03, 0.035), refl, fres);
    // sun glints where the coloured shafts touch the surface
    let S = sunv();
    c += shaft(pw, open_s()) * (0.25 + 3.0 * pow(max(dot(r, S), 0.0), 60.0));
    if (MODE == 1) {
        let rl = length(vec2f(pw.x - along0(), pw.z));
        c += vec3f(1.0, 0.85, 0.6) * smoothstep(1.35, 1.0, rl) * (0.15 + 0.15 * sin(rl * 14.0 - time() * 3.0));
    }
    return c;
}

fn beams(ro: vec3f, rd: vec3f, t1: f32, n: i32) -> vec3f {
    var acc = vec3f(0.0);
    let dt = t1 / f32(n);
    var t = dt * hash12(rd.xy * 917.0 + fract(time() * 7.13));
    let S = sunv();
    for (var i = 0; i < 160; i = i + 1) {
        if (i >= n) { break; }
        let p = ro + rd * t;
        if (p.y > WATER) {
            var L = shaft(p, open_s());
            if (MODE == 1) {
                let r = length(vec2f(p.x - along0(), p.z));
                L += vec3f(1.0, 0.85, 0.6) * smoothstep(1.3, 1.0, r) * 0.6;
                L += candle_glow(p);
            }
            if (MODE == 3) {
                let rq = vec3f(p.x - along0() - END * 3.6, p.y - 1.95, p.z);
                L += vec3f(1.0, 0.7, 0.3) * 0.25 / (1.0 + dot(rq, rq) * 3.0);
            }
            if (L.x + L.y + L.z > 0.001) {
                let dust = 0.15 + 1.6 * noise3(p * 2.2 + vec3f(-time() * 0.12, time() * 0.05, 0.0));
                let mote = step(0.985, hash13(floor(p * 30.0 + vec3f(0.0, time() * 0.6, 0.0))));
                acc += L * (dust + mote * 3.0) * dt;
            }
        }
        t += dt;
    }
    let ph = 0.35 + 1.6 * pow(max(dot(rd, S), 0.0), 5.0);
    return acc * 0.22 * ph;
}

fn shade(ro0: vec3f, rd0: vec3f, tmin: f32, tmax: f32) -> Hit {
    let ro = to_frame(ro0) + vec3f(along0(), 0.0, 0.0);
    let rd = to_frame(rd0);
    let q = quality();
    let ns = i32(mix(40.0, STEPS, q));
    let tw = plane_y(ro, rd, WATER);
    var tl = tmax;
    if (tw > 0.0) { tl = min(tl, tw); }
    let ts = march(ro, rd, tmin, tl, ns);
    var c: vec3f;
    var t: f32;
    if (ts > 0.0) {
        t = ts;
        c = surf(ro + rd * ts, rd, true);
    } else if (tw > 0.0 && tw < tmax) {
        t = tw;
        c = water(ro + rd * tw, rd, i32(f32(ns) * REFL));
    } else {
        t = horizon_t(tmax);
        c = paint(ro + rd * tmax, rd, open_s());
    }
    c += beams(ro, rd, min(t, tmax), i32(mix(12.0, VSTEPS, q)));
    c = mix(c, vec3f(0.01, 0.035, 0.045), 1.0 - exp(-t * 0.012));
    return Hit(pow(tone(c * 1.5), vec3f(1.25)), t);
}

fn corona(p: vec3f) -> f32 { return 1e5; }
fn candle_light(p: vec3f, n: vec3f) -> vec3f { return vec3f(0.0); }
fn flame(p: vec3f) -> vec3f { return vec3f(0.0); }
fn candle_glow(p: vec3f) -> vec3f { return vec3f(0.0); }

shaders.1fb2a63b2c45b2138285792cb26f:
// Leviathan Spine: the skeleton of a colossal sky creature lying across rooms (4..9, 1..2)
// under an aurora. One shared world; this room samples it at its grid offset.
const GOFF: vec3f = vec3f(72.0, 0.0, 12.0);
const AUR_A: vec3f = vec3f(0.16, 1.0, 0.58);
const AUR_B: vec3f = vec3f(0.5, 0.34, 1.0);
const HORIZON: vec3f = vec3f(0.03, 0.045, 0.1);
const BONE: vec3f = vec3f(0.97, 0.86, 0.64);

fn breath() -> f32 { return 0.5 + 0.5 * sin(time() * 0.75); }

fn sd_cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

fn sd_ell(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / max(k1, 1e-4);
}

// Spine path in the xz plane: tail tip (46,28) north to (46,20), quarter arc to (54,12), then east to the skull at x=104.
// Returns (u along the spine from the tail tip, signed lateral offset).
fn spine_frame(w: vec2f) -> vec2f {
    if (w.x >= 54.0) { return vec2f(20.566 + (w.x - 54.0), w.y - 12.0); }
    if (w.y <= 20.0) {
        let d = w - vec2f(54.0, 20.0);
        var a = atan2(d.y, d.x);
        if (a < 0.0) { a = a + TAU; }
        a = clamp(a, PI, 1.5 * PI);
        return vec2f(8.0 + 8.0 * (a - PI), length(d) - 8.0);
    }
    return vec2f(28.0 - w.y, w.x - 46.0);
}

fn spine_h(u: f32) -> f32 {
    return mix(0.72, 2.4, smoothstep(0.0, 22.0, u)) + 0.07 * sin(u * 0.31 - time() * 0.75) - 0.15 * smoothstep(64.0, 71.0, u);
}

fn spine_s(u: f32) -> f32 {
    return mix(0.33, 1.0, smoothstep(0.0, 30.0, u)) * (1.0 + 0.04 * breath());
}

fn vert_q(w: vec3f, f: vec2f) -> vec4f {
    let k = clamp(round(f.x / 0.8), 1.0, 88.0);
    let uk = k * 0.8;
    return vec4f(f.x - uk, w.y - spine_h(uk), f.y, uk);
}

fn vertebrae(w: vec3f, f: vec2f) -> f32 {
    let bound = abs(f.y) - 1.4;
    if (bound > 0.4) { return bound; }
    let vq = vert_q(w, f);
    let s = spine_s(vq.w);
    let q = vq.xyz;
    let r = 0.27 * s + 0.03;
    let dc = vec2f(length(q.yz) - r, abs(q.x) - 0.29);
    let cent = min(max(dc.x, dc.y), 0.0) + length(max(dc, vec2f(0.0))) - 0.04;
    let ns = sd_box(vec3f(q.x + 0.28 * (q.y - 0.3 * s), q.y - 0.6 * s, q.z), vec3f(0.05 + 0.04 * s, 0.48 * s, 0.045)) - 0.025;
    let tp = sd_box(vec3f(q.x, q.y + 0.04 + 0.1 * q.z * q.z, q.z), vec3f(0.055, 0.045, 0.66 * s)) - 0.02;
    let hm = sd_box(vec3f(q.x, q.y + 0.42 * s, q.z), vec3f(0.04, 0.2 * s, 0.035));
    return smin(cent, min(min(ns, tp), hm), 0.07);
}

fn ribs(w: vec3f, f: vec2f) -> f32 {
    let bx = max(57.0 - w.x, w.x - 103.0);
    if (bx > 0.3) { return bx; }
    let xk = clamp(0.75 + 1.5 * round((w.x - 0.75) / 1.5), 57.75, 102.75);
    let dx = w.x - xk;
    let sr = (0.7 + 0.3 * smoothstep(57.0, 74.0, xk)) * (1.0 - 0.28 * smoothstep(93.0, 103.0, xk));
    let br = 0.5 + 0.5 * sin(time() * 0.75 - xk * 0.06);
    let a = (4.45 + 0.4 * br) * sr;
    let b = 2.8 * mix(0.92, 1.0, sr);
    let q2 = vec2f(f.y, w.y + 0.32);
    let k0 = length(q2 / vec2f(a, b));
    let k1 = length(q2 / vec2f(a * a, b * b));
    let de = k0 * (k0 - 1.0) / max(k1, 1e-4);
    let th = mix(0.06, 0.13, clamp(w.y / 2.3, 0.0, 1.0));
    return max(length(vec2f(de, dx * 1.25)) - th, -w.y - 0.05);
}

fn skull(w: vec3f) -> f32 {
    let p = w - vec3f(108.0, 0.0, 12.0);
    let bb = sd_box(p - vec3f(0.0, 2.0, 0.0), vec3f(6.4, 2.1, 2.6));
    if (bb > 0.4) { return bb; }
    let pz = vec3f(p.x, p.y, abs(p.z));
    let cran = sd_ell(p - vec3f(-2.6, 2.25, 0.0), vec3f(2.3, 1.25, 1.75));
    let ros = sd_ell(p - vec3f(1.9, 1.95, 0.0), vec3f(4.3, 0.42, 0.98));
    var d = smin(cran, ros, 0.5);
    let eye = sd_sphere(pz - vec3f(-1.5, 2.45, 1.45), 0.62);
    d = max(d, -eye);
    let nost = sd_ell(pz - vec3f(-0.9, 2.4, 0.35), vec3f(0.6, 0.3, 0.18));
    d = max(d, -nost);
    let jaw = sd_cap(pz, vec3f(-4.1, 1.45, 1.15), vec3f(5.9, 0.16, 0.5), 0.16);
    d = min(d, jaw);
    if (p.x > -0.6 && p.x < 5.6) {
        let c = p.x - 0.32 * round(p.x / 0.32);
        let wdt = 0.9 * sqrt(max(1.0 - pow((p.x - 1.9) / 4.3, 2.0), 0.0));
        let tooth = sd_cap(vec3f(c, p.y, abs(p.z)), vec3f(0.0, 1.75, wdt * 0.8), vec3f(0.0, 1.32, wdt * 0.72), 0.035);
        d = min(d, tooth);
    }
    return d;
}

fn fin(w: vec3f) -> f32 {
    let bb = sd_box(w - vec3f(84.0, 1.2, 21.0), vec3f(4.5, 1.4, 8.5));
    if (bb > 0.4) { return bb; }
    let br = breath();
    var d = sd_cap(w, vec3f(84.0, 2.1, 13.2), vec3f(84.0, 0.62, 19.6), 0.24);
    d = smin(d, sd_sphere(w - vec3f(84.0, 0.62, 19.6), 0.36), 0.15);
    let wz = vec3f(abs(w.x - 84.0), w.y, w.z);
    d = min(d, sd_cap(wz, vec3f(0.28, 0.58, 19.8), vec3f(0.36, 0.32, 22.5), 0.15));
    for (var i = 0; i < 5; i = i + 1) {
        let fi = f32(i) - 2.0;
        let ang = fi * (0.3 + 0.05 * br);
        let dir = vec3f(sin(ang), 0.0, cos(ang));
        let base = vec3f(84.0 + fi * 0.28, 0.3, 22.6);
        let len = 5.5 - 0.55 * abs(fi);
        for (var j = 0; j < 4; j = j + 1) {
            let fj = f32(j);
            let a = base + dir * len * fj * 0.25 + vec3f(0.0, 0.06 * fj, 0.0);
            let b = base + dir * len * (fj + 0.88) * 0.25 + vec3f(0.0, 0.06 * fj, 0.0);
