}

fn ground(ro: vec3f, rd: vec3f, tg: f32) -> vec3f {
    let w = ro + rd * tg + GOFF;
    let n = fbm3(vec3f(w.xz * 0.35, 0.0));
    var col = vec3f(0.15, 0.18, 0.26) * (0.75 + 0.5 * n);
    col += curtains(reflect(rd, vec3f(0.0, 1.0, 0.0))) * 0.3 * step(tg, 14.0);
    let sp = floor(w.xz * 30.0);
    if (hash12(sp) > 0.993) { col += vec3f(0.7, 0.8, 1.0) * (0.5 + 0.5 * sin(dot(rd, vec3f(31.0, 17.0, 23.0)) + hash12(sp) * 50.0)); }
    let occ = clamp(map(w + vec3f(0.0, 0.3, 0.0)) / 0.3, 0.0, 1.0);
    col *= 0.35 + 0.65 * occ;
    col += glow_at(w + vec3f(0.0, 0.5, 0.0)) * 0.25;
    return mix(col, HORIZON, 1.0 - exp(-tg * 0.02));
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let tg = plane_y(ro, rd, 0.0);
    var tend = tmax;
    if (tg > 0.0) { tend = min(tg, tmax); }
    var t = tmin;
    let steps = i32(mix(36.0, 96.0, quality()));
    var hit = false;
    var glow = vec3f(0.0);
    for (var i = 0; i < 96; i = i + 1) {
        if (i >= steps) { break; }
        let w = ro + rd * t + GOFF;
        let d = map(w);
        glow += glow_at(w) * clamp(d, 0.03, 0.35);
        if (d < 0.0015 * t + 0.002) { hit = true; break; }
        t += d * 0.95;
        if (t > tend) { break; }
    }
    if (hit) {
        let w = ro + rd * t + GOFF;
        let n = calc_normal(w);
        let l = normalize(vec3f(0.35, 1.0, -0.45));
        let dif = clamp(dot(n, l), 0.0, 1.0);
        let ao = clamp(0.35 + 0.65 * map(w + n * 0.22) / 0.22, 0.0, 1.0);
        let tint = aur_tint(w);
        let grain = 0.85 + 0.3 * noise3(w * 6.0);
        let bounce = vec3f(0.42, 0.44, 0.52) * (0.6 - 0.4 * n.y);
        let fill = vec3f(0.3, 0.27, 0.24) * clamp(dot(n, -rd), 0.0, 1.0);
        var col = BONE * grain * (vec3f(0.05, 0.06, 0.09) + dif * vec3f(0.95, 0.86, 0.72) + bounce + fill + tint * (0.05 + 0.08 * max(n.y, 0.0)));
        col *= ao;
        let rim = pow(1.0 - clamp(dot(-rd, n), 0.0, 1.0), 3.0);
        col += tint * rim * 0.12;
        col += glow * 0.6;
        col = mix(col, HORIZON, 1.0 - exp(-t * 0.012));
        return Hit(tone(col * 1.25), t);
    }
    if (tg > 0.0) {
        let gc = ground(ro, rd, tg) + glow * 0.6;
        return Hit(tone(gc * 1.2), min(tg, horizon_t(tmax)));
    }
    return Hit(tone(sky(rd) * 1.2 + glow * 0.6), horizon_t(tmax));
}

