fn calc_normal(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn light(P: vec3f, n: vec3f, rd: vec3f, base: vec3f, metal: f32) -> vec3f {
    let lp = vec3f(0.0, 4.3, 0.0);
    let lv = lp - P;
    let ld = normalize(lv);
    let att = 3.2 / (1.0 + 0.04 * dot(lv, lv));
    let dif = max(dot(n, ld), 0.0);
    let key = normalize(vec3f(-0.5, 0.9, 0.35));
    let dif2 = max(dot(n, key), 0.0);
    let h = normalize(ld - rd);
    let sp = pow(max(dot(n, h), 0.0), 40.0);
    let fre = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let amb = 0.22 + 0.12 * n.y;
    var c = base * (amb + dif * att * vec3f(1.0, 0.85, 0.62) + dif2 * 0.35 * vec3f(0.6, 0.7, 0.9));
    c += mix(vec3f(0.25), base * 1.4, metal) * (sp * att * 1.6 + fre * 0.25);
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    clock_init();
    var tend = tmax;
    let tf = plane_y(ro, rd, 0.0);
    let floor_hit = tf >= tmin && tf <= tmax + 0.005;
    if (floor_hit) { tend = tf; }
    let steps = i32(mix(32.0, 80.0, quality()));
    var t = tmin;
    var hit = false;
    for (var i = 0; i < steps; i = i + 1) {
        let d = map(ro + rd * t);
        if (d < 0.0008 + 0.0012 * t) { hit = true; break; }
        t += d * 0.8;
        if (t > tend) { break; }
    }
    if (hit && t <= tmax) {
        let P = ro + rd * t;
        let m = MAT; let eid = EID;
        let n = calc_normal(P);
        let base = matcol(P, m, eid);
        let ao = clamp(map(P + n * 0.12) / 0.12, 0.25, 1.0);
        var metal = 1.0;
        if (m == 5 || m == 6 || m >= 10) { metal = 0.2; }
        var c = light(P, n, rd, base, metal) * ao;
        c = mix(c, vec3f(0.05, 0.035, 0.02), clamp(t / 30.0, 0.0, 0.5));
        return Hit(tone(c * 1.3), t);
    }
    if (floor_hit) {
        let P = ro + rd * tf;
        let W = P + vec3f(GX * 12.0, 0.0, GY * 12.0);
        var c = FLOOR(P, W, rd);
        let occ = clamp(map(P + vec3f(0.0, 0.35, 0.0)) / 0.35, 0.3, 1.0);
        c *= occ;
        return Hit(tone(c * 1.3), min(tf, tmax));
    }
    return no_hit();
}

fn FLOOR(P: vec3f, W: vec3f, rd: vec3f) -> vec3f {
    // dark oak boards running north-south, brass inlay under every line shaft (continuous through rooms)
    let bw = 0.3;
    let bi = floor(W.x / bw);
    let along = W.z + hash12(vec2f(bi, 3.0)) * 7.0;
    let joint = min(abs(fract(W.x / bw) - 0.5), abs(fract(along / 2.4) - 0.5) * 8.0);
    var c = vec3f(0.17, 0.10, 0.06) * (0.75 + 0.5 * hash12(vec2f(bi, floor(along / 2.4))));
    c *= 0.8 + 0.2 * noise3(vec3f(W.x * 30.0, 0.0, W.z * 1.5));
    c *= mix(0.55, 1.0, smoothstep(0.42, 0.47, 0.5 - joint));
    let lx = abs(P.x);
    let lz = abs(P.z);
    if (lx < 0.06 || (lz < 0.06 && ((GX > -0.5 && P.x < 0.0) || (GX < -0.5 && P.x > 0.0) || (GX > -1.5 && GX < -0.5 && GY > -3.5 && GY < -2.5)))) { c = vec3f(0.7, 0.5, 0.22); }
    // engraved dial ring in each room, with 60 ticks; the tick under the second hand lights
    let r = length(P.xz);
    let a = atan2(P.x, -P.z);
    let ring = abs(r - 2.6);
    if (ring < 0.03) { c = vec3f(0.6, 0.42, 0.18); }
    let tk = fract(a / TAU * 60.0 + 0.5) - 0.5;
    if (abs(tk) < 0.07 && r > 2.66 && r < 2.9) {
        let idx = floor(a / TAU * 60.0 + 0.5);
        let sec = floor(TE / TAU * 60.0 + 0.5);
        let on = abs(fract((idx - sec) / 60.0 + 0.5) - 0.5) < 0.005;
        c = select(vec3f(0.55, 0.4, 0.17), vec3f(1.4, 0.9, 0.4), on);
    }
    let l = 3.0 / (1.0 + 0.05 * dot(P - vec3f(0.0, 4.3, 0.0), P - vec3f(0.0, 4.3, 0.0)));
    return c * (0.3 + l);
}

shaders.1662421148c02b1f0e306044fe35:
// The Long Clock VIII: Engine Heart - part of one machine spanning 8 rooms; all motion derives from one escape wheel.
// v1: a dark engine hall lit by one hanging lamp and the furnace glow of the endless gear abyss under the glass.
// v2 (2026-11-03): the same picture for about 40% of the GPU work. The hall's parts sit in boxes the march steps
// over, the wall trains and posts are mirrored, and the abyss is walked cell by cell. Kept to one plain march loop:
// a march that also tracked where the ray enters each box took software WebGL2 (SwiftShader) 65 s to compile.
const GX: f32 = -1.0;
const GY: f32 = -4.0;

var<private> TE: f32;
var<private> TW: f32;
var<private> MAT: i32;
var<private> EID: i32;

fn clock_init() {
    TW = time() - (GX * 7.0 + GY * 13.0);
    let k = floor(TW);
    let fr = TW - k;
    TE = (k + smoothstep(0.0, 0.14, fr)) * TAU / 60.0;
}
fn sd2box(p: vec2f, b: vec2f) -> f32 {
    let q = abs(p) - b;
    return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0);
}
fn ext(d: f32, z: f32, w: f32) -> f32 {
    let e = vec2f(d, abs(z) - w);
    return min(max(e.x, e.y), 0.0) + length(max(e, vec2f(0.0)));
}
fn gear2(q: vec2f, R: f32, N: f32, ang: f32, spokes: f32) -> f32 {
    let m = R / N;
    let r = length(q);
    let a = atan2(q.y, q.x) - ang;
    let seg = TAU / N;
    let fa = (fract(a / seg + 0.5) - 0.5) * seg;
    let u = r - R;
    let tw = mix(0.29, 0.15, clamp((u + m) / (2.0 * m), 0.0, 1.0)) * seg * R;
    var d = min(r - (R - 0.95 * m), sd2box(vec2f(u, fa * r), vec2f(m, tw)));
    if (spokes > 0.0) {
        let ring = max(r - (R - 2.6 * m), 0.32 * R - r);
        let ss = TAU / spokes;
        let sa = (fract(a / ss + 0.5) - 0.5) * ss * r;
        d = max(d, -max(ring, 0.05 * R + 0.03 - abs(sa)));
    }
    return d;
}
fn gearz(q: vec3f, R: f32, N: f32, ang: f32, w: f32, sp: f32) -> f32 {
    let g = ext(gear2(q.xy, R, N, ang, sp), q.z, w);
    let hub = ext(length(q.xy) - max(0.09, 0.12 * R), q.z, w * 1.9);
    return min(g, hub);
}
fn cylz(q: vec3f, r: f32, h: f32) -> f32 { return ext(length(q.xy) - r, q.z, h); }
fn capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a; let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn pend_ang() -> f32 { return 0.13 * cos(PI * TW); }
fn DIALC(P: vec3f) -> vec3f { return vec3f(0.0, 0.0, 0.0); }

const ACS: vec3f = vec3f(3.0, 2.6, 3.0);
fn abyss_near(p: vec3f, near: f32) -> f32 { return abyss_cell(p, floor(p / ACS), near); }
// the same, in cell id (the normal's four taps all read the hit's own cell)
fn abyss_cell(p: vec3f, id: vec3f, near: f32) -> f32 {
    let q = p - (id + 0.5) * ACS;
    let h = hash13(id);
    let ax = h * 3.0;
    var qq = q;
    if (ax > 2.0) { qq = q.zyx; } else if (ax > 1.0) { qq = q.xzy; }
    let N = 10.0 + floor(h * 14.0);
    let R = N * 0.06;
    var d = min(max(length(q.xz) - 0.06, 0.0), max(length(q.yz) - 0.05, 0.0));
    // the cell's gear lies inside a drum (tooth tips R + R/N, hub 0.19 either side): its teeth are worked out
    // only near the drum (within `near`: occlusion reads distances up to 0.2)
    let drum = ext(length(qq.xy) - R * (1.0 + 1.0 / N), qq.z, 0.19);
    if (drum < near) {
        let par = select(-1.0, 1.0, fract((id.x + id.y + id.z) * 0.5) < 0.25);
        d = min(d, gearz(qq, R, N, par * TE * (24.0 / N) + h * 6.0, 0.1, 5.0));
    } else { d = min(d, drum); }
    return d;
}

// The abyss, walked a cell at a time. A cell holds two axles and one gear, and its own parts are all it shows
// (as when it was sphere-traced): the axles are met exactly (as thick as the march saw them, which stopped
// 0.001 t + 0.001 short), and the gear is traced only inside its drum. Answers (t, 1 for a hit).
fn circle_hit(p: vec2f, v: vec2f, r: f32, len: f32) -> f32 {
    // where a line from p (2D, direction v) first comes within r of the origin, within len (else len)
    let c = dot(p, p) - r * r;
    if (c <= 0.0) { return 0.0; }
    let b = dot(p, v);
    let a = dot(v, v);
    if (b >= 0.0 || a < 1e-12) { return len; }
    let disc = b * b - a * c;
    if (disc < 0.0) { return len; }
    return min((-b - sqrt(disc)) / a, len);
}
fn drum_span(p: vec3f, v: vec3f, r: f32, h: f32) -> vec2f {
    // where a line from p (direction v) is inside the cylinder of radius r round z, |z| < h
    var lo = -1e9;
    var hi = 1e9;
    if (abs(v.z) > 1e-7) {
        let a = (-h - p.z) / v.z;
        let b = (h - p.z) / v.z;
        lo = min(a, b);
        hi = max(a, b);
    } else if (abs(p.z) > h) { return vec2f(1.0, 0.0); }
    let A = dot(v.xy, v.xy);
    let B = dot(p.xy, v.xy);
    let C = dot(p.xy, p.xy) - r * r;
    if (A < 1e-12) {
        if (C > 0.0) { return vec2f(1.0, 0.0); }
    } else {
        let D = B * B - A * C;
        if (D < 0.0) { return vec2f(1.0, 0.0); }
        let q = sqrt(D);
        lo = max(lo, (-B - q) / A);
        hi = min(hi, (-B + q) / A);
    }
    return vec2f(lo, hi);
}
fn abyss_trace(o: vec3f, rd: vec3f, cells: i32, steps: i32) -> vec2f {
    let sg = select(vec3f(-1.0), vec3f(1.0), rd >= vec3f(0.0));
    let inv = 1.0 / (sg * max(abs(rd), vec3f(1e-6)));
    var t = 0.02;
    var id = floor((o + rd * t) / ACS);
    var budget = steps;
    for (var k = 0; k < cells; k = k + 1) {
        let p = o + rd * t - (id + 0.5) * ACS;
        let tw = (sg * ACS * 0.5 - p) * inv;
        let len = max(min(min(tw.x, tw.y), tw.z), 0.0);
        let lim = min(len, 28.0 - t);
        let thr = 0.001 * t + 0.001;
        var s = circle_hit(p.xz, rd.xz, 0.06 + thr, lim);
        s = circle_hit(p.yz, rd.yz, 0.05 + thr, s);
        let h = hash13(id);
        let ax = h * 3.0;
        var pq = p;
        var vq = rd;
        if (ax > 2.0) { pq = p.zyx; vq = rd.zyx; } else if (ax > 1.0) { pq = p.xzy; vq = rd.xzy; }
        let N = 10.0 + floor(h * 14.0);
        let R = N * 0.06;
        let dr = drum_span(pq, vq, R * (1.0 + 1.0 / N) + thr + 0.01, 0.19 + thr + 0.01);
        let u0 = max(dr.x, 0.0);
        if (u0 < min(dr.y, s)) {
            // the hub: a plain drum of its own, 0.19 either side
            let hb = drum_span(pq, vq, max(0.09, 0.12 * R) + thr, 0.19 + thr);
            if (hb.x <= hb.y && hb.y >= 0.0 && hb.x < s) { s = max(hb.x, 0.0); }
            // the wheel (rim, spokes, teeth) lies within 0.1 either side: its faces are met where the ray reaches
            // that slab (with half the march's margin), and its edges by tracing on through it
            var lo = -1e9;
            var hi = 1e9;
            let hw = 0.1 + 0.5 * thr;
            if (abs(vq.z) > 1e-7) { let a = (-hw - pq.z) / vq.z; let b = (hw - pq.z) / vq.z; lo = min(a, b); hi = max(a, b); }
            else if (abs(pq.z) > hw) { hi = -1e9; }
            var u = max(lo, u0);
            let ue = min(min(hi, dr.y), s);
            let par = select(-1.0, 1.0, fract((id.x + id.y + id.z) * 0.5) < 0.25);
            let ang = par * TE * (24.0 / N) + h * 6.0;
            loop {
                if (u >= ue || budget <= 0) { break; }
                budget -= 1;
                let d = gearz(pq + vq * u, R, N, ang, 0.1, 5.0);
                if (d < 0.001 * (t + u) + 0.001) { s = u; break; }
                u += d * 0.8;
            }
        }
        if (s < lim) { return vec2f(t + s, 1.0); }
        t += len;
        if (t >= 28.0) { return vec2f(28.0, 0.0); }
        if (tw.x <= tw.y && tw.x <= tw.z) { id.x += sg.x; } else if (tw.y <= tw.z) { id.y += sg.y; } else { id.z += sg.z; }
    }
    return vec2f(t, 0.0);
}

var<private> FLK: f32;
const LP: vec3f = vec3f(0.0, 4.12, 0.0);
const LAMPC: vec3f = vec3f(1.0, 0.72, 0.42);
const GLOWC: vec3f = vec3f(1.0, 0.46, 0.14);
const HAZEC: vec3f = vec3f(0.035, 0.022, 0.014);

// filmic curve (ACES fit), a soft vignette round the camera's own axis, and a hair of dither so the haze does not band
fn tm(c: vec3f, rd: vec3f) -> vec3f {
    let fw = room.inv_rot_proj * vec4f(0.0, 0.0, 0.5, 1.0);
    let vig = 1.0 - 0.3 * smoothstep(0.97, 0.55, dot(rd, normalize(fw.xyz / fw.w)));
    let x = max(c, vec3f(0.0)) * vig;
    let y = (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14);
    return clamp(y + (hash13(rd * 913.7) - 0.5) / 255.0, vec3f(0.0), vec3f(1.0));
}

// what a polished surface sees: the furnace glow of the glass below, dark iron above, the lamp
fn env(P: vec3f, r: vec3f) -> vec3f {
    var c = mix(vec3f(0.015, 0.012, 0.01), GLOWC * 0.4, smoothstep(0.05, -0.6, r.y));
    let ld = normalize(LP - P);
    c += LAMPC * pow(max(dot(r, ld), 0.0), 90.0) * 6.0 * FLK;
    return c;
}

fn embers(o: vec3f, rd: vec3f) -> vec3f {
    // three thin layers of drifting sparks inside the abyss
    var c = vec3f(0.0);
    for (var k = 0; k < 3; k = k + 1) {
        let fk = f32(k);
        let depth = 1.2 + fk * 2.1;
        let t = -depth / min(rd.y, -0.05);
        let q = (o.xz + rd.xz * t) / 0.9 + vec2f(fk * 3.1, fk * 1.7);
        let id = floor(q);
        let h = hash33(vec3f(id, fk + 4.0));
        // four cells in five hold no spark, and a spark is out half the time
        if (h.x < 0.8) { continue; }
        let life = max(sin(TW * (0.3 + 0.4 * h.y) + h.z * 40.0), 0.0);
        if (life <= 0.0) { continue; }
        let tw = TW * (0.15 + 0.2 * h.z);
        let off = 0.5 + 0.3 * vec2f(sin(tw + h.x * 6.3), cos(tw * 0.8 + h.y * 6.3));
        let d = length(fract(q) - off);
        let spot = exp(-d * d * 2500.0 / (1.0 + t * 0.15)) * life * life;
        c += mix(GLOWC, vec3f(1.0, 0.75, 0.4), h.y) * spot * 3.0 * exp(-t * 0.06);
    }
    return c;
}

fn FLOOR(P: vec3f, W: vec3f, rd: vec3f) -> vec3f {
    let em = max(abs(P.x), abs(P.z));
    let ld = normalize(LP - P);
    let l2 = dot(LP - P, LP - P);
    let pool = 7.0 * FLK / (1.0 + l2);
    if (em > 4.6) {
        // diamond tread plate round the glass, brass trim at the edge
        let g = P.xz * 6.0;
        let dia = abs(fract(g.x + g.y) - 0.5) + abs(fract(g.x - g.y) - 0.5);
        let bump = smoothstep(0.62, 0.7, dia);
        var c = vec3f(0.05, 0.045, 0.04) * (0.75 + 0.5 * noise3(W * 3.0)) * (0.8 + 0.5 * bump);
        c *= pool * 0.6 + 0.08 + GLOWC * 0.5 * exp(-(em - 4.6) * 3.0);
        let trim = abs(em - 4.7);
        if (trim < 0.05) {
            let rr = reflect(rd, vec3f(0.0, 1.0, 0.0));
            c = vec3f(0.85, 0.6, 0.28) * (0.15 + pool * 0.5 + GLOWC * 0.6) + vec3f(0.6, 0.45, 0.25) * env(P, rr) * 0.5;
            c *= 0.7 + 0.3 * smoothstep(0.05, 0.02, trim);
        }
        return c;
    }
    // glass: look down into an endless lattice of gears that turn with the clock
    let o = W + vec3f(0.0, -0.3, 0.0);
    let tr = abyss_trace(o, rd, i32(mix(16.0, 40.0, quality())), i32(mix(30.0, 90.0, quality())));
    let t = tr.x;
    let hit = tr.y > 0.5;
    // the haze deepens and brightens with depth: dark brass near the glass, furnace light far below
    let fogt = 1.0 - exp(-t * 0.11);
    let pe = o + rd * t;
    let hot = (0.45 + 0.8 * noise3(vec3f(pe.xz * 0.11, pe.y * 0.11 + TW * 0.04))) * (0.92 + 0.08 * sin(TW * 0.9));
    let fogc = vec3f(1.0, 0.4, 0.09) * (0.01 + 0.62 * pow(fogt, 2.2) * hot) + vec3f(0.006, 0.002, 0.0);
    var col = fogc;
    if (hit) {
        let p = o + rd * t;
        let e = vec2f(0.002, -0.002);
        let cid = floor(p / ACS);
        let n = normalize(e.xyy * abyss_cell(p + e.xyy, cid, 0.04) + e.yyx * abyss_cell(p + e.yyx, cid, 0.04) + e.yxy * abyss_cell(p + e.yxy, cid, 0.04) + e.xxx * abyss_cell(p + e.xxx, cid, 0.04));
        let depth = -p.y + W.y;
        let brass = vec3f(0.8, 0.55, 0.25);
        let top = exp(-depth * 0.5) * 0.9 * max(n.y * 0.7 + 0.3, 0.0);
        let under = (max(-n.y, 0.0) * 0.5 + 0.05) * (0.3 + fogt);
        let fre = pow(1.0 - abs(dot(n, rd)), 3.0);
        var b = brass * (top * LAMPC + under * GLOWC + vec3f(0.01, 0.014, 0.022));
        b += GLOWC * fre * 0.8 * (0.6 + 0.4 * sin(p.y * 0.4 + TW * 0.7));
        let ao = clamp(abyss_near(p + n * 0.2, 0.21) / 0.2, 0.15, 1.0);
        col = mix(b * ao, fogc, fogt);
    }
    col += embers(o, rd);
    // glass: lamp glint and sheen, brass mullions with a rivet at every crossing
    let rr = reflect(rd, vec3f(0.0, 1.0, 0.0));
    let fre = 0.04 + 0.96 * pow(1.0 - abs(rd.y), 5.0);
    col = col * (1.0 - fre) + env(P, rr) * fre * 0.8;
    col += vec3f(0.02, 0.016, 0.012) * noise3(vec3f(P.xz * 11.0, 0.0)) * pool;
    let m2 = abs(fract(P.xz / 1.5) - 0.5);
    let mul = min(m2.x, m2.y);
    let mw = smoothstep(0.0, 0.02, mul - 0.01);
    let bar = vec3f(0.55, 0.38, 0.18) * (0.06 + pool * 0.45 + GLOWC * 0.25 * (1.0 - mw));
    col = mix(bar, col, mw);
    let rv = length((fract(P.xz / 1.5 + 0.5) - 0.5) * 1.5);
    col = mix(col, vec3f(0.9, 0.66, 0.34) * (0.2 + pool * 0.8), smoothstep(0.035, 0.025, rv));
    return col;
}

// The two wall trains are mirror images across z = 0 (same gears, same angles), so one train is evaluated at
// (x, y, -|z|). Each group of parts sits in a box; far from a box its distance is the box's (never more than the
// parts' own), so a ray crosses the empty hall in a few steps. Parts are evaluated within `near` of their box:
// callers that read the distance itself (occlusion) pass a margin at least as large as what they read.
// The train's gears. Its left half is the mirror image of its right: the same wheels, turned so the mirror shows
// the left one's teeth (teeth and spokes are symmetric, so a wheel at angle a seen in a mirror is one at PI - a).
// So only the side the point is on is worked out, at X = (|x|, y, z).
fn train(Q: vec3f, dd: f32) -> f32 {
    var d = dd;
    let L = Q.x < 0.0;
    let X = vec3f(abs(Q.x), Q.y, Q.z);
    { let q = (X - vec3f(0.0, 3.7, -3.5)); if (max(length(q) - 0.68, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.6, 10.0, select(4.0 * TE, PI - 4.0 * TE, L), 0.07, 0.0); if (g < d) { d = g; MAT = 3; EID = 7; } } }
    { let q = (X - vec3f(1.3244, 2.9958, -3.5)); if (max(length(q) - 0.98, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.9, 15.0, select(-2.6667 * TE + 2.5365, PI - (-2.6667 * TE + 3.1183), L), 0.07, 5.0); if (g < d) { d = g; MAT = 0; EID = select(8, 15, L); } } }
    { let q = (X - vec3f(3.025, 1.5688, -3.5)); if (max(length(q) - 1.4, abs(q.z) - 0.143) < d) { let g = gearz(q, 1.32, 22.0, select(1.8182 * TE + 0.3808, PI - (1.8182 * TE + 3.332), L), 0.07, 5.0); if (g < d) { d = g; MAT = 0; EID = select(9, 16, L); } } }
    { let q = (X - vec3f(4.9159, 1.9022, -3.5)); if (max(length(q) - 0.68, abs(q.z) - 0.143) < d) { let g = gearz(q, 0.6, 10.0, select(-4.0 * TE + 3.1765, PI - (-4.0 * TE + 5.62), L), 0.07, 5.0); if (g < d) { d = g; MAT = 3; EID = select(10, 17, L); } } }
    return d;
}

// the posts and their feet, which stand mirrored across x = 0 as well (X = (|x|, y, -|z|))
fn posts(X: vec3f, dd: f32) -> f32 {
    var d = dd;
    { let g = sd_box(X - vec3f(3.025, 0.7844, -3.67), vec3f(0.09, 0.7844, 0.06)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 11; } }
    { let g = sd_box(X - vec3f(3.025, 0.06, -3.67), vec3f(0.32, 0.06, 0.22)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 12; } }
    { let g = sd_box(X - vec3f(4.9159, 0.9511, -3.67), vec3f(0.09, 0.9511, 0.06)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 13; } }
    { let g = sd_box(X - vec3f(4.9159, 0.06, -3.67), vec3f(0.32, 0.06, 0.22)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 14; } }
    return d;
}

// The parts in groups, each inside a box (as they stand in the room: Q = (x, y, -|z|) folds the two walls together,
// X = (|x|, y, -|z|) the four posts). Each adds its parts to d (MAT and EID say which part is nearest).
fn shaft(Q: vec3f, dd: f32) -> f32 {
    // the line shaft along z with its end boxes
    var d = dd;
    { let q = (Q - vec3f(0.0, 3.7, 0.0)); let g = min(cylz(q, 0.075, 6.0), max(cylz(vec3f(q.xy, (fract(q.z * 0.8) - 0.5) / 0.8), 0.11, 0.035), abs(q.z) - 6.0)); if (g < d) { d = g; MAT = 1; EID = 0; } }
    { let g = sd_box(Q - vec3f(0.0, 3.7, -5.86), vec3f(0.22, 0.22, 0.14)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 1; } }
    return d;
}
fn cross(P: vec3f, dd: f32) -> f32 {
    // the cross shaft along x and its box
    var d = dd;
    { let q = (P - vec3f(3.0, 3.0, 0.0)).zyx; let g = min(cylz(q, 0.065, 3.0), max(cylz(vec3f(q.xy, (fract(q.z * 0.8) - 0.5) / 0.8), 0.1, 0.035), abs(q.z) - 3.0)); if (g < d) { d = g; MAT = 1; EID = 3; } }
    { let g = sd_box(P - vec3f(5.86, 3.0, 0.0), vec3f(0.14, 0.2, 0.2)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 4; } }
    return d;
}
fn gearbox(P: vec3f, dd: f32) -> f32 {
    // the gearbox in the middle and its crown wheel
    var d = dd;
    { let g = sd_box(P - vec3f(0.0, 3.35, 0.0), vec3f(0.32, 0.5, 0.32)) - 0.01; if (g < d) { d = g; MAT = 2; EID = 5; } }
    { let q = (P - vec3f(0.0, 3.34, 0.0)).xzy; if (max(length(q) - 0.42, abs(q.z) - 0.105) < d) { let g = gearz(q, 0.36, 9.0, (4.0 * TE + 0.0), 0.05, 0.0); if (g < d) { d = g; MAT = 0; EID = 6; } } }
    return d;
}

// The whole room's parts, for normals and occlusion. Far from a group's box its distance is the box's (never more
// than the parts' own); parts are worked out within `near` of their box, so a caller reading the distance itself
// (occlusion) passes a margin at least as large as what it reads.
var<private> MNEAR: bool;
fn map_near(P: vec3f, near: f32) -> f32 {
    var d = 1e5;
    MNEAR = false;
    let Q = vec3f(P.x, P.y, -abs(P.z));
    let X = vec3f(abs(P.x), P.y, Q.z);
    // the three groups under the ceiling, behind one box round them all
    let bc = sd_box(P - vec3f(2.78, 3.36, 0.0), vec3f(3.22, 0.58, 6.0));
    if (bc < near) {
        let b0 = sd_box(Q - vec3f(0.0, 3.7, -3.0), vec3f(0.24, 0.24, 3.0));
        if (b0 < near) { MNEAR = true; d = shaft(Q, d); } else { d = b0 * 1.25; }
        let b1 = sd_box(P - vec3f(3.0, 3.0, 0.0), vec3f(3.0, 0.22, 0.22));
        if (b1 < near) { MNEAR = true; d = cross(P, d); } else { d = min(d, b1 * 1.25); }
        let b2 = sd_box(P - vec3f(0.0, 3.35, 0.0), vec3f(0.43, 0.52, 0.43));
        if (b2 < near) { MNEAR = true; d = gearbox(P, d); } else { d = min(d, b2 * 1.25); }
    } else { d = bc * 1.25; }
    let b3 = sd_box(Q - vec3f(0.0, 2.275, -3.5), vec3f(5.6, 2.105, 0.143));
    if (b3 < near) { MNEAR = true; d = train(Q, min(d, 0.4)); } else { d = min(d, b3 * 1.25); }
    let b4 = sd_box(X - vec3f(3.97, 0.96, -3.67), vec3f(1.28, 0.96, 0.23));
    if (b4 < near) { MNEAR = true; d = posts(X, d); } else { d = min(d, b4 * 1.25); }
    return d;
}

// where the ray enters and leaves each group's box (map_near's boxes as they stand in the room, 1 cm larger)
var<private> SP0: vec2f;
var<private> SP1: vec2f;
var<private> SP2: vec2f;
var<private> SP3: vec2f;
var<private> SP4: vec2f;
var<private> SP5: vec2f;
var<private> SP6: vec2f;
var<private> SP7: vec2f;
var<private> SP8: vec2f;
fn spans(ro: vec3f, rd: vec3f) {
    let e = vec3f(0.01);
    SP0 = box_span(ro, rd, vec3f(-0.24, 3.46, -6.0) - e, vec3f(0.24, 3.94, 6.0) + e);
    SP1 = box_span(ro, rd, vec3f(0.0, 2.78, -0.22) - e, vec3f(6.0, 3.22, 0.22) + e);
    SP2 = box_span(ro, rd, vec3f(-0.43, 2.83, -0.43) - e, vec3f(0.43, 3.87, 0.43) + e);
    SP3 = box_span(ro, rd, vec3f(-5.6, 0.17, -3.643) - e, vec3f(5.6, 4.38, -3.357) + e);
    SP4 = box_span(ro, rd, vec3f(-5.6, 0.17, 3.357) - e, vec3f(5.6, 4.38, 3.643) + e);
    SP5 = box_span(ro, rd, vec3f(2.69, 0.0, -3.9) - e, vec3f(5.25, 1.92, -3.44) + e);
    SP6 = box_span(ro, rd, vec3f(-5.25, 0.0, -3.9) - e, vec3f(-2.69, 1.92, -3.44) + e);
    SP7 = box_span(ro, rd, vec3f(2.69, 0.0, 3.44) - e, vec3f(5.25, 1.92, 3.9) + e);
    SP8 = box_span(ro, rd, vec3f(-5.25, 0.0, 3.44) - e, vec3f(-2.69, 1.92, 3.9) + e);
}
fn entry(s: vec2f, t: f32) -> f32 { return select(1e9, max(s.x, t), s.x <= s.y && s.y > t); }
// the nearest point at or after t that is inside a group's box (1e9: none ahead)
fn next_box(t: f32) -> f32 {
    return min(min(min(entry(SP0, t), entry(SP1, t)), min(entry(SP2, t), entry(SP3, t))), min(min(entry(SP4, t), entry(SP5, t)), min(min(entry(SP6, t), entry(SP7, t)), entry(SP8, t))));
}


// centre and radius of each wall-train gear (for its turned finish and screws)
fn gear_c(eid: i32) -> vec4f {
    var k = eid;
    var z = -3.5;
    if (eid >= 22) { k = eid - 15; z = 3.5; }
    var c = vec4f(0.0, 3.7, z, 0.6);
    switch k {
        case 8: { c = vec4f(1.3244, 2.9958, z, 0.9); }
        case 9: { c = vec4f(3.025, 1.5688, z, 1.32); }
        case 10: { c = vec4f(4.9159, 1.9022, z, 0.6); }
        case 15: { c = vec4f(-1.3244, 2.9958, z, 0.9); }
        case 16: { c = vec4f(-3.025, 1.5688, z, 1.32); }
        case 17: { c = vec4f(-4.9159, 1.9022, z, 0.6); }
        default: { }
    }
    return c;
}

fn matcol(m: i32) -> vec3f {
    var col = vec3f(0.78, 0.56, 0.26);
    switch m {
        case 1: { col = vec3f(0.62, 0.64, 0.68); }
        case 2: { col = vec3f(0.11, 0.1, 0.1); }
        case 3: { col = vec3f(0.80, 0.42, 0.24); }
        default: { }
    }
    return col;
}

// the distance to the hit part's own group (enough for its normal: the other groups are further away)
fn group_map(P: vec3f, eid: i32) -> f32 {
    let Q = vec3f(P.x, P.y, -abs(P.z));
    if (eid <= 1) { return shaft(Q, 0.05); }
    if (eid <= 4) { return cross(P, 0.05); }
    if (eid <= 6) { return gearbox(P, 0.05); }
    if (eid >= 11 && eid <= 14) { return posts(vec3f(abs(P.x), P.y, Q.z), 0.05); }
    return train(Q, 0.05);
}
fn calc_normal(p: vec3f, eid: i32) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * group_map(p + e.xyy, eid) + e.yyx * group_map(p + e.yyx, eid) + e.yxy * group_map(p + e.yxy, eid) + e.xxx * group_map(p + e.xxx, eid));
}

fn shade_obj(P: vec3f, rd: vec3f, m: i32, eid: i32, t: f32) -> vec3f {
    let n = calc_normal(P, eid);
    var base = matcol(m);
    var polish = 0.5;
    var metal = 1.0;
    if (m == 2) { metal = 0.25; polish = 0.2; }
    if ((m == 0 || m == 3) && eid >= 7) {
        // turned finish on the faces, polished tooth flanks, five screws round the hub
        let g = gear_c(eid);
        let q = P.xy - g.xy;
        let r = length(q);
        let face = abs(n.z);
        polish = mix(0.95, 0.45 + 0.25 * sin(r * 260.0) * smoothstep(5.0, 1.5, t), face);
        let a = atan2(q.y, q.x);
        let hubr = max(0.09, 0.12 * g.w);
        let sa = (fract(a / TAU * 5.0 + 0.5) - 0.5) * TAU / 5.0 * hubr * 0.72;
        let sd = length(vec2f(r - hubr * 0.72, sa));
        if (face > 0.9 && sd < 0.016) { base *= mix(0.35, 1.15, smoothstep(0.004, 0.012, sd)); polish = 1.0; }
        let groove = abs(r - (g.w - g.w / 9.0 * 2.0));
        if (face > 0.9 && groove < 0.006) { base *= 0.55; }
    }
    if (eid == 0 || eid == 3) {
        var q = P - vec3f(0.0, 3.7, 0.0);
        if (eid == 3) { q = (P - vec3f(3.0, 3.0, 0.0)).zyx; }
        base *= 0.75 + 0.35 * step(0.0, sin(atan2(q.y, q.x) * 2.0 - (4.0 * TE) * 2.0));
    }
    let ao = clamp(map_near(P + n * 0.12, 0.13) / 0.12, 0.2, 1.0);
    let lv = LP - P;
    let l2 = dot(lv, lv);
    let ld = lv * inverseSqrt(l2);
    let att = 9.0 * FLK / (1.0 + 0.8 * l2);
    let dif = max(dot(n, ld), 0.0);
    // the glass below is one big warm light: strongest on undersides near the floor
    let fg = GLOWC * (0.06 + 0.5 * max(-n.y, 0.0)) * exp(-P.y * 0.6) * 0.7;
    let r = reflect(rd, n);
    let fre = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let spec = pow(max(dot(r, ld), 0.0), mix(12.0, 120.0, polish)) * att * mix(0.4, 3.0, polish);
    let dl = (vec3f(0.018, 0.026, 0.04) * (0.6 + 0.4 * n.y) + dif * att * LAMPC + fg);
    var c = base * dl * (1.0 - 0.55 * metal);
    c += mix(vec3f(0.04), base, metal) * (env(P, r) * (0.35 + 0.65 * polish) * ao + spec * LAMPC);
    c += GLOWC * fre * 0.18 * exp(-P.y * 0.45);
    return c * ao;
}

fn wall(P: vec3f, rd: vec3f) -> vec3f {
    var n = vec3f(0.0, -1.0, 0.0);
    var uv = P.xz;
    if (P.y < 4.48) {
        if (abs(P.x) > abs(P.z)) { n = vec3f(-sign(P.x), 0.0, 0.0); uv = vec2f(P.z, P.y); }
        else { n = vec3f(0.0, 0.0, -sign(P.z)); uv = vec2f(P.x, P.y); }
    }
    // riveted iron panels 1.5 m wide, a brass rail at hand height
    let pu = abs(fract(uv / vec2f(1.5, 1.125)) - 0.5);
    let seam = smoothstep(0.494, 0.499, max(pu.x, pu.y));
    let rq = fract(uv / vec2f(1.5, 1.125)) * vec2f(1.5, 1.125);
    let rx = min(rq.x, 1.5 - rq.x);
    let rv = length(vec2f(rx - 0.07, (fract(uv.y / 0.28125) - 0.5) * 0.28125));
    let riv = smoothstep(0.02, 0.013, rv);
    var base = vec3f(0.045, 0.04, 0.037) * (0.7 + 0.6 * noise3(P * 1.7)) * (1.0 - 0.7 * seam) * (1.0 + riv * 1.5);
    let lv = LP - P;
    let l2 = dot(lv, lv);
    let att = 8.0 * FLK / (1.0 + 1.1 * l2);
    let dif = max(dot(n, lv * inverseSqrt(l2)), 0.0);
    var c = base * (vec3f(0.03, 0.04, 0.06) * smoothstep(0.0, 4.5, P.y) + dif * att * LAMPC + GLOWC * 0.45 * exp(-P.y * 1.6) * step(P.y, 4.48));
    // a lit bevel just inside each seam, and a glint on every rivet head
    let bev = smoothstep(0.465, 0.49, max(pu.x, pu.y)) * (1.0 - seam);
    c += (vec3f(0.05, 0.04, 0.032) * bev + vec3f(0.5, 0.36, 0.2) * riv) * (dif * att * LAMPC * 0.5 + GLOWC * 0.3 * exp(-P.y * 1.2));
    if (abs(uv.y - 1.1) < 0.035 && P.y < 4.48) {
        let rr = reflect(rd, n);
        c = vec3f(0.8, 0.56, 0.27) * (0.05 + dif * att * 0.6 + GLOWC * 0.25) + vec3f(0.8, 0.56, 0.27) * env(P, rr) * 0.4;
    }
    return c;
}

// light scattered towards the eye by the haze round the lamp: the closed form of the inverse-square
// in-scatter integral along the ray up to distance t
fn lamp_glow(ro: vec3f, rd: vec3f, t: f32) -> vec3f {
    let v = LP - ro;
    let tc = dot(v, rd);
    let h2 = max(dot(v, v) - tc * tc, 1e-4);
    let h = sqrt(h2);
    let a = (atan((t - tc) / h) - atan(-tc / h)) / h;
    let core = smoothstep(0.075, 0.05, h) * step(tc, t);
    return LAMPC * FLK * (a * 0.035 + core * 4.0 + 0.04 / (h2 * 40.0 + 1.0) * step(tc, t));
}

// one mote: a speck of dust drifting round the lamp, seeded by h (hash33(vec3f(i, 2.3, 7.1)) for i = 0..13)
fn mote(ro: vec3f, rd: vec3f, tend: f32, ys: vec2f, h: vec3f) -> vec3f {
    // its height first: a mote above or below every point of the ray that could show it is skipped
    let y = 1.2 + 2.6 * fract(h.z + TW * 0.012);
    if (y < ys.x || y > ys.y) { return vec3f(0.0); }
    let ph = TW * (0.03 + 0.03 * h.z) + h.x * 10.0;
    let pos = vec3f(sin(ph * 1.3 + h.y * 6.0) * 2.2, y, cos(ph + h.x * 4.0) * 2.2);
    let v = pos - ro;
    let tp = dot(v, rd);
    // a speck: where its glow is under e^-10 it adds nothing anyone can see
    let dd2 = dot(v, v) - tp * tp;
    if (tp > 0.2 && tp < tend && dd2 < 0.0003 * tp * tp + 0.00003) {
        let lit = 3.0 / (1.0 + dot(LP - pos, LP - pos) * 1.5);
        return LAMPC * exp(-max(dd2, 0.0) / (0.00003 * tp * tp + 0.000003)) * lit * 0.25;
    }
    return vec3f(0.0);
}

fn motes(ro: vec3f, rd: vec3f, tend: f32, ys: vec2f) -> vec3f {
    var c = vec3f(0.0);
    c += mote(ro, rd, tend, ys, vec3f(0.713936, 0.606547, 0.168246));
    c += mote(ro, rd, tend, ys, vec3f(0.031959, 0.509015, 0.827786));
    c += mote(ro, rd, tend, ys, vec3f(0.654316, 0.434458, 0.250204));
    c += mote(ro, rd, tend, ys, vec3f(0.581006, 0.382877, 0.435500));
    c += mote(ro, rd, tend, ys, vec3f(0.812029, 0.354272, 0.383674));
    c += mote(ro, rd, tend, ys, vec3f(0.347386, 0.348643, 0.094725));
    c += mote(ro, rd, tend, ys, vec3f(0.187077, 0.365990, 0.568653));
    c += mote(ro, rd, tend, ys, vec3f(0.331101, 0.406313, 0.805460));
    c += mote(ro, rd, tend, ys, vec3f(0.779459, 0.469612, 0.805143));
    c += mote(ro, rd, tend, ys, vec3f(0.532150, 0.555887, 0.567705));
    c += mote(ro, rd, tend, ys, vec3f(0.245786, 0.937893, 0.250796));
    c += mote(ro, rd, tend, ys, vec3f(0.388297, 0.880929, 0.173376));
    c += mote(ro, rd, tend, ys, vec3f(0.835733, 0.847532, 0.859429));
    c += mote(ro, rd, tend, ys, vec3f(0.586854, 0.836463, 0.307707));
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    clock_init();
    FLK = 1.0 + 0.04 * sin(TW * 9.1) * sin(TW * 2.3 + 1.0);
    var tend = tmax;
    let tf = plane_y(ro, rd, 0.0);
    let floor_hit = tf >= tmin && tf <= tmax + 0.005;
    if (floor_hit) { tend = tf; }
    let steps = i32(mix(32.0, 80.0, quality()));
    var t = tmin;
    var hit = false;
    spans(ro, rd);
    for (var i = 0; i < steps; i = i + 1) {
        let d = map_near(ro + rd * t, 0.05);
        if (d < 0.0008 + 0.0012 * t) { hit = true; break; }
        t += d * 0.8;
        // out in the open hall: straight to where the ray next comes within reach of a group's box
        if (!MNEAR) { t = max(t, next_box(t) - 0.04); }
        if (t > tend) { break; }
    }
    var c = vec3f(0.0);
    var th = horizon_t(tmax);
    if (hit && t <= tmax) {
        let m = MAT; let eid = EID;
        c = shade_obj(ro + rd * t, rd, m, eid, t);
        th = t;
    } else if (floor_hit) {
        let P = ro + rd * tf;
        let W = P + vec3f(GX * 12.0, 0.0, GY * 12.0);
        c = FLOOR(P, W, rd);
        c *= clamp(map_near(P + vec3f(0.0, 0.35, 0.0), 0.36) / 0.35, 0.3, 1.0);
        th = min(tf, tmax);
    } else {
        c = wall(ro + rd * th, rd);
    }
    c = mix(c, mix(HAZEC, vec3f(0.012, 0.016, 0.026), smoothstep(-0.2, 0.6, rd.y)), 1.0 - exp(-th * 0.05));
    c += lamp_glow(ro, rd, th);
    // the motes drift within 2.2 m of the lamp's axis, 1.2 to 3.8 m up: rays that pass clear of that (by more than
    // their faintest glow) skip them
    let mb = box_span(ro, rd, vec3f(-2.35, 1.05, -2.35), vec3f(2.35, 3.95, 2.35));
    if (quality() > 0.4 && mb.x <= mb.y && mb.y > 0.2 && mb.x < th) {
        // the heights the ray passes through inside the motes' box, widened by the furthest glow's reach
        let ta = max(mb.x, 0.2);
        let tb = min(mb.y, th);
        let r = 0.0174 * tb + 0.006;
        let ya = ro.y + rd.y * ta;
        let yb = ro.y + rd.y * tb;
        c += motes(ro, rd, th, vec2f(min(ya, yb) - r, max(ya, yb) + r));
    }
    return Hit(tm(c * 0.9, rd), clamp(th, tmin, tmax));
}

shaders.180c1583459afa10eaf0d6b851f2:
// Catoid Sweep: one knob, swept down a corridor of rooms, from Hot-dog Kitty to Jimothy.
// A catoid sculpted from signed distance fields (round cones, capsules, smooth unions) on a black
// plinth in a dark gallery, walking in place. param(0).x is where this room sits on the sweep (0 long
// and thin, 1 round), param(1) its coat, param(2) its rim light. Catoid week, the simcluster, Oct 2026.

const S: f32 = 1.35;                  // sculpture scale: catoid units to metres
const CAT_Z: f32 = -2.4;              // the plinth runs along the north side, the walk along the middle
const PLINTH_H: f32 = 0.3;

var<private> cL: f32;      // half body length
var<private> cR: f32;      // body radius
var<private> cLeg: f32;    // leg length
var<private> cHead: f32;   // head radius
var<private> cTail: f32;   // tail length
var<private> cH: f32;      // body height
var<private> cPh: f32;     // gait phase
var<private> mat: f32;     // 0 coat, 1 eye, 2 nose, 3 inner ear

fn sweep() -> f32 { return clamp(param(0u).x, 0.0, 1.0); }

fn set_cat() {
    let t = sweep();
    cL = mix(1.3, 0.3, t);
    cR = mix(0.19, 0.62, t);
    cLeg = mix(0.62, 0.24, t);
    cHead = mix(0.23, 0.33, t);
    cTail = mix(1.05, 0.5, t);
    cH = max(cLeg + cR * 0.5, cR + 0.1);
    cPh = time() * mix(4.2, 2.6, t);
}

// Inigo Quilez's ellipsoid bound.
fn sd_ellipsoid(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}

fn sd_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

// Inigo Quilez's round cone between two points.
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

fn head_c() -> vec3f { return vec3f(cL + cR * 0.45 + cHead * 0.75, cH + cR * 0.55 + cHead * 0.45, 0.0); }

// The catoid in its own units: x from tail to head, y up from the plinth, z across.
fn cat(p: vec3f) -> f32 {
    let t = sweep();
    // body: a round cone, chest a little higher, with a belly that sags as it gets round
    var d = sd_round_cone(p, vec3f(-cL, cH, 0.0), vec3f(cL, cH + 0.05, 0.0), cR, cR * 0.9);
    d = smin(d, sd_ellipsoid(p - vec3f(0.0, cH - cR * 0.2, 0.0), vec3f(cL * 0.85 + cR * 0.5, cR * 0.92, cR * 1.02)), 0.12);
    // legs walk in place: front and back pairs in counter-phase
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-1.0, 1.0, i < 2);
        let side = select(-1.0, 1.0, (i & 1) == 0);
        let ph = cPh + select(0.0, PI, (i == 1) || (i == 2));
        let hip = vec3f(fx * cL * 0.82, cH - cR * 0.2, side * max(cR * 0.55, 0.11));
        let swing = sin(ph) * cLeg * 0.32;
        let lift = max(cos(ph), 0.0) * cLeg * 0.14;
        let paw = vec3f(hip.x + swing, 0.075 + lift, hip.z);
        d = smin(d, sd_round_cone(p, paw, hip, 0.07, mix(0.1, 0.17, t)), 0.08);
        d = smin(d, sd_ellipsoid(p - paw - vec3f(0.035, -0.015, 0.0), vec3f(0.1, 0.06, 0.08)), 0.04);
    }
    // tail: six segments curling up and back, swishing
    var a = vec3f(-cL - cR * 0.6, cH + cR * 0.3, 0.0);
    var ang = 2.35;
    let seg = cTail / 6.0;
    for (var i = 0; i < 6; i = i + 1) {
        let fi = f32(i);
        ang = ang - 0.32 + sin(time() * 1.7 - fi * 0.7) * 0.12;
        let b = a + vec3f(cos(ang), sin(ang), sin(time() * 1.1 - fi * 0.5) * 0.06) * seg;
        d = smin(d, sd_capsule(p, a, b, mix(0.075, 0.035, fi / 5.0) * (1.0 + t * 0.6)), 0.05);
        a = b;
    }
    // head, cheeks, muzzle
    let hc = head_c() + vec3f(0.0, sin(cPh * 2.0) * 0.012, 0.0);
    var h = length(p - hc) - cHead;
    h = smin(h, sd_ellipsoid(p - hc - vec3f(0.02, -cHead * 0.28, 0.0), cHead * vec3f(0.8, 0.62, 1.08)), 0.06);
    let mz = hc + vec3f(cHead * 0.82, -cHead * 0.3, 0.0);
    h = smin(h, sd_ellipsoid(p - mz, cHead * vec3f(0.3, 0.26, 0.38)), 0.06);
    d = smin(d, h, 0.16);
    // ears: flattened round cones
    var ear = 1e5;
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let base = hc + vec3f(-cHead * 0.1, cHead * 0.62, s * cHead * 0.52);
        let tip = base + vec3f(-0.04, cHead * 0.72, s * cHead * 0.26);
        var q = p - base;
        q.x = q.x * 1.7;
        ear = min(ear, sd_round_cone(q, vec3f(0.0), (tip - base) * vec3f(1.7, 1.0, 1.0), cHead * 0.42, 0.02) / 1.7);
    }
    d = smin(d, ear, 0.03);
    // materials, by the nearest feature
    mat = 0.0;
    let eyeL = length(p - (hc + vec3f(cHead * 0.72, cHead * 0.18, cHead * 0.4))) - cHead * 0.16;
    let eyeR = length(p - (hc + vec3f(cHead * 0.72, cHead * 0.18, -cHead * 0.4))) - cHead * 0.16;
    if (min(eyeL, eyeR) < 0.012) { mat = 1.0; }
    if (length(p - (mz + vec3f(cHead * 0.24, cHead * 0.12, 0.0))) < cHead * 0.13) { mat = 2.0; }
    return d;
}

fn to_cat(p: vec3f) -> vec3f { return (p - vec3f(0.0, PLINTH_H, CAT_Z)) / S; }
fn cat_w(p: vec3f) -> f32 { return cat(to_cat(p)) * S; }

fn cat_n(p: vec3f) -> vec3f {
    let e = vec2f(0.004, 0.0);
    return normalize(vec3f(cat_w(p + e.xyy) - cat_w(p - e.xyy), cat_w(p + e.yxy) - cat_w(p - e.yxy), cat_w(p + e.yyx) - cat_w(p - e.yyx)));
}

fn cat_box_min() -> vec3f { return vec3f(-cL - cR - cTail - 0.15, 0.0, -cR - 0.45) * S + vec3f(0.0, PLINTH_H, CAT_Z); }
fn cat_box_max() -> vec3f { return vec3f(cL + cR + cHead * 2.6 + 0.1, cH + cR + cHead * 2.4 + max(cTail * 0.7, 0.4), cR + 0.45) * S + vec3f(0.0, PLINTH_H, CAT_Z); }

const LIGHT: vec3f = vec3f(0.35, 0.85, 0.4);

fn soft_shadow(p: vec3f) -> f32 {
    let l = normalize(LIGHT);
    let b = box_span(p, l, cat_box_min(), cat_box_max());
    if (b.x > b.y || b.y < 0.0) { return 1.0; }
    var t = max(b.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 20; i = i + 1) {
        if (t > b.y) { break; }
        let h = cat_w(p + l * t);
        res = min(res, 10.0 * h / t);
        if (res < 0.02) { break; }
        t += clamp(h, 0.03, 0.4);
    }
    return clamp(res, 0.0, 1.0);
}

fn rim_col() -> vec3f { return param(2u).rgb; }

fn shade_cat(p: vec3f, rd: vec3f) -> vec3f {
    let n = cat_n(p);
    let m = mat;
    let cp = to_cat(p);
    let t = sweep();
    // coat: tabby stripes across the back, a pale belly and muzzle
    var base = param(1u).rgb;
    let stripe = smoothstep(0.35, 0.6, sin(cp.x * mix(13.0, 7.0, t) + fbm3(cp * 3.0) * 2.4)) * smoothstep(-0.2, 0.4, n.y);
    base = mix(base, base * 0.35, stripe * 0.75);
    base = mix(base, vec3f(0.92, 0.88, 0.8), smoothstep(-0.25, -0.7, n.y) * 0.8);
    if (m == 1.0) { base = vec3f(0.05, 0.25, 0.12); }
    if (m == 2.0) { base = vec3f(0.85, 0.45, 0.5); }
    let l = normalize(LIGHT);
    let diff = max(dot(n, l), 0.0) * (0.35 + 0.65 * soft_shadow(p + n * 0.01));
    let ao = clamp(0.5 + 0.5 * cat_w(p + n * 0.12) / 0.12, 0.0, 1.0);
    let rim = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let back = max(dot(n, normalize(vec3f(-0.6, 0.3, -0.8))), 0.0);
    let spec = pow(max(dot(reflect(rd, n), l), 0.0), select(24.0, 90.0, m == 1.0)) * select(0.25, 1.2, m == 1.0);
    var col = base * (0.08 + diff * 1.1) * ao + rim_col() * (rim * 0.6 + back * 0.25) + vec3f(spec);
    return col;
}

fn led_wall(p: vec3f) -> vec3f {
    // the north wall: a dark field, faint grid, and the sweep as a bar of LEDs above the catoid
    var col = vec3f(0.018, 0.016, 0.03);
    let g = abs(fract(p.xy * 2.0) - 0.5);
    col += vec3f(0.02, 0.03, 0.05) * smoothstep(0.47, 0.5, max(g.x, g.y));
    if (abs(p.y - 3.75) < 0.12 && abs(p.x) < 4.0) {
        let cell = floor((p.x + 4.0) / 8.0 * 24.0);
        let lit = cell < floor(sweep() * 23.0 + 0.5) + 1.0;
        let f = fract((p.x + 4.0) / 8.0 * 24.0);
        let inside = step(0.12, f) * step(f, 0.88) * step(abs(p.y - 3.75), 0.085);
        let here = abs(cell - floor(sweep() * 23.0 + 0.5)) < 0.5;
        col = mix(col, select(rim_col() * 0.12, select(rim_col(), vec3f(1.0), here), lit), inside);
    }
    return col;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    set_cat();
    var best = tmax;
    var kind = 0; // 0 wall/ceiling, 1 floor, 2 plinth, 3 catoid
    // the catoid
    let cb = box_span(ro, rd, cat_box_min(), cat_box_max());
    if (cb.x < cb.y && cb.y > tmin) {
        var t = max(cb.x, tmin);
        let steps = select(60, 90, quality() > 0.6);
        for (var i = 0; i < 90; i = i + 1) {
            if (i >= steps || t > cb.y) { break; }
            let d = cat_w(ro + rd * t);
            if (d < 0.002 * t + 0.002) { best = t; kind = 3; break; }
            t += d * 0.9;
        }
    }
    // the plinth: black glass with a neon edge
    let pmin = vec3f(-4.4, 0.0, CAT_Z - 1.1);
    let pmax = vec3f(4.4, PLINTH_H, CAT_Z + 1.1);
    let pb = box_span(ro, rd, pmin, pmax);
    if (pb.x < pb.y && pb.x > tmin && pb.x < best) { best = pb.x; kind = 2; }
    let tf = plane_y(ro, rd, 0.0);
    if (tf > 0.0 && tf < best) { best = tf; kind = 1; }

    let p = ro + rd * best;
    if (kind == 3) {
        let c = shade_cat(p, rd);
        return Hit(tone(c * 1.3), best);
    }
    if (kind == 2) {
        var c = vec3f(0.012, 0.012, 0.018);
        let edge = min(min(abs(p.x - pmin.x), abs(p.x - pmax.x)), min(abs(p.z - pmin.z), abs(p.z - pmax.z)));
        let top = p.y > PLINTH_H - 0.002;
        if (top) {
            c += vec3f(0.05) * pow(max(dot(reflect(rd, vec3f(0.0, 1.0, 0.0)), normalize(LIGHT)), 0.0), 40.0);
            c *= 0.4 + 0.6 * soft_shadow(p);
            c += rim_col() * smoothstep(0.035, 0.0, edge) * 1.6;
        } else {
            c += rim_col() * smoothstep(0.02, 0.0, abs(p.y - PLINTH_H + 0.02)) * 1.2;
        }
        return Hit(tone(c), best);
    }
    if (kind == 1) {
        // polished dark floor, a lit pool by the plinth, a faint grid, the rim colour bleeding
        var c = vec3f(0.02, 0.02, 0.028);
        let g = abs(fract(p.xz * 1.0) - 0.5);
        c += vec3f(0.035, 0.04, 0.06) * smoothstep(0.485, 0.5, max(g.x, g.y));
        let pool = exp(-pow(max(abs(p.x) - 3.5, 0.0), 2.0) * 0.6 - pow(p.z - CAT_Z - 1.6, 2.0) * 0.9);
        c += rim_col() * pool * 0.12;
        c += vec3f(0.06) * pow(max(dot(reflect(rd, vec3f(0.0, 1.0, 0.0)), normalize(vec3f(0.0, 1.0, -0.4))), 0.0), 30.0);
        return Hit(tone(c), best);
    }
    // walls and ceiling: painted dark; the north wall carries the sweep
    let w = ro + rd * horizon_t(tmax);
    var c = vec3f(0.016, 0.015, 0.024);
    if (w.z < -ROOM_HALF + 0.05) { c = led_wall(w); }
    else if (w.y > ROOM_HEIGHT - 0.05) {
        // ceiling: a strip of light over the plinth
        c = vec3f(0.01) + vec3f(0.5) * smoothstep(0.25, 0.0, abs(w.z - CAT_Z)) * step(abs(w.x), 4.2);
    } else {
        // a neon line where the walls meet the floor
        c += rim_col() * smoothstep(0.04, 0.0, abs(w.y - 0.06)) * 0.8;
    }
    return Hit(tone(c), horizon_t(tmax));
}

shaders.1f3a54b2e859b615376e471d227c:
// Catoid Forms: the catoid in six schools of mathematical sculpture. param(0).x picks the form:
//   0 gyroid lattice (after Bathsheba Grossman)      1 umbilic torus, curled asleep (after Helaman Ferguson)
//   2 endless ribbon, a one-sided cat (after Max Bill) 3 linear construction in string (after Naum Gabo)
//   4 hanging looped-wire lobes (after Ruth Asawa)    5 a polished form in space (after Constantin Brancusi)
// param(1) is the material colour, param(2) the room's light. Catoid week, the simcluster, Oct 2026.

const PLINTH_H: f32 = 0.5;
const LIGHT: vec3f = vec3f(0.3, 0.9, 0.35);

fn form() -> i32 { return i32(param(0u).x + 0.5); }
fn mat_col() -> vec3f { return param(1u).rgb; }
fn rim_col() -> vec3f { return param(2u).rgb; }

fn sd_ellipsoid(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / k1;
}
fn sd_capsule(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

// A cat's head with ears and muzzle, facing +x, centred at c (shared by several forms).
fn cat_head(p: vec3f, c: vec3f, r: f32) -> f32 {
    var h = length(p - c) - r;
    h = smin(h, sd_ellipsoid(p - c - vec3f(0.02, -r * 0.28, 0.0), r * vec3f(0.8, 0.62, 1.08)), r * 0.25);
    h = smin(h, sd_ellipsoid(p - c - vec3f(r * 0.82, -r * 0.3, 0.0), r * vec3f(0.3, 0.26, 0.38)), r * 0.25);
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let base = c + vec3f(-r * 0.1, r * 0.62, s * r * 0.52);
        var q = p - base;
        q.x = q.x * 1.7;
        h = smin(h, sd_round_cone(q, vec3f(0.0), vec3f(-0.07, r * 0.72, s * r * 0.26), r * 0.42, r * 0.06) / 1.7, r * 0.12);
    }
    return h;
}

// ---- 0: the gyroid catoid. A standing cat, its volume replaced by a gyroid sheet that drifts through it.
fn cat_body(p: vec3f) -> f32 {
    // the sweet-spot proportions of the Catoid Sweep, standing on the plinth, 1.15 m to a catoid unit
    let q = (p - vec3f(0.0, PLINTH_H, 0.0)) / 1.15;
    let L = 0.75; let R = 0.38; let leg = 0.45; let H = leg + R * 0.5;
    var d = sd_round_cone(q, vec3f(-L, H, 0.0), vec3f(L, H + 0.05, 0.0), R, R * 0.9);
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-1.0, 1.0, i < 2);
        let side = select(-1.0, 1.0, (i & 1) == 0);
        let hip = vec3f(fx * L * 0.8, H - R * 0.2, side * R * 0.55);
        d = smin(d, sd_round_cone(q, vec3f(hip.x + 0.04, 0.07, hip.z), hip, 0.07, 0.13), 0.08);
    }
    var a = vec3f(-L - R * 0.6, H + R * 0.3, 0.0);
    var ang = 2.35;
    for (var i = 0; i < 5; i = i + 1) {
        ang = ang - 0.36 + sin(time() * 0.9 - f32(i) * 0.7) * 0.1;
        let b = a + vec3f(cos(ang), sin(ang), 0.0) * 0.17;
        d = smin(d, sd_capsule(q, a, b, mix(0.07, 0.04, f32(i) / 4.0)), 0.05);
        a = b;
    }
    d = smin(d, cat_head(q, vec3f(L + R * 0.45 + 0.21, H + R * 0.55 + 0.13, 0.0), 0.28), 0.14);
    return d * 1.15;
}
fn gyroid_cat(p: vec3f) -> f32 {
    let k = 12.0;
    let q = p * k + vec3f(0.0, time() * 0.25, time() * 0.1);
    let g = abs(sin(q.x) * cos(q.y) + sin(q.y) * cos(q.z) + sin(q.z) * cos(q.x)) / k * 0.55 - 0.014;
    return max(cat_body(p), g);
}

// ---- 1: the umbilic catoid. Curled asleep: a torus whose three-lobed section turns a third of a turn
// on the way round, so one edge runs round it three times, with the head tucked onto the coil.
fn umbilic(p: vec3f) -> f32 {
    let c = vec3f(0.0, PLINTH_H + 0.42, 0.0);
    let q = p - c;
    let th = atan2(q.z, q.x);
    let breathe = 1.0 + 0.012 * sin(time() * 1.3);
    let Rm = 0.78 * breathe;
    var s = vec2f(length(q.xz) - Rm, q.y);
    let tw = th / 3.0 + time() * 0.05;
    s = rot2(tw) * s;
    let ph = atan2(s.y, s.x);
    let r = 0.36 * breathe * (1.0 + 0.2 * cos(3.0 * ph));
    var d = (length(s) - r) * 0.8;
    // the head rests on the coil, nose towards the tail
    let hc = c + vec3f(cos(0.5) * Rm, 0.42, sin(0.5) * Rm);
    let hp = p - hc;
    let hr = vec3f(rot2(-0.5 - PI * 0.5) * hp.xz, hp.y);
    d = smin(d, cat_head(vec3f(hr.x, hr.z, hr.y), vec3f(0.0), 0.36), 0.1);
    return d;
}
fn umbilic_edge(p: vec3f) -> f32 {
    let q = p - vec3f(0.0, PLINTH_H + 0.42, 0.0);
    let th = atan2(q.z, q.x);
    var s = rot2(th / 3.0 + time() * 0.05) * vec2f(length(q.xz) - 0.78, q.y);
    return cos(3.0 * atan2(s.y, s.x));
}

// ---- 2: the endless-ribbon catoid. A cat whose body is a Möbius band: back, belly and back again, one side.
fn ribbon(p: vec3f) -> f32 {
    let c = vec3f(0.0, PLINTH_H + 1.05, 0.0);
    var q = p - c;
    q.x = q.x / 1.55;
    let th = atan2(q.y, q.x);
    var s = vec2f(length(q.xy) - 0.62, q.z);
    s = rot2(th * 0.5 + time() * 0.08) * s;
    let band = vec2f(0.3, 0.028);
    let e = abs(s) - band;
    var d = (length(max(e, vec2f(0.0))) + min(max(e.x, e.y), 0.0) - 0.01) * 0.62;
    // legs down to the plinth, head and tail out of the band
    for (var i = 0; i < 4; i = i + 1) {
        let fx = select(-0.55, 0.55, i < 2);
        let side = select(-0.14, 0.14, (i & 1) == 0);
        d = min(d, sd_round_cone(p, vec3f(fx + 0.03, PLINTH_H + 0.06, side), vec3f(fx, PLINTH_H + 0.62, side), 0.055, 0.08));
    }
    d = smin(d, cat_head(p, c + vec3f(1.12, 0.38, 0.0), 0.27), 0.1);
    d = smin(d, sd_capsule(p, c + vec3f(-0.98, 0.1, 0.0), c + vec3f(-1.35, 0.75 + 0.06 * sin(time()), 0.0), 0.045), 0.06);
    return d;
}

// ---- 3: the linear construction. Two perspex plates cut to a cat's outline, strung with taut threads
// from each point of one to a point further round the other: a ruled surface that twists as the shift drifts.
const NP: i32 = 24;
fn outline(i: i32) -> vec2f {
    // a standing cat in profile, clockwise from the tip of the tail, metres
    var pts = array<vec2f, 24>(
        vec2f(-1.45, 1.6), vec2f(-1.28, 1.08), vec2f(-1.05, 0.98), vec2f(-0.45, 1.02), vec2f(0.25, 1.04),
        vec2f(0.68, 1.12), vec2f(0.84, 1.38), vec2f(0.84, 1.66), vec2f(0.92, 1.9), vec2f(1.04, 1.7),
        vec2f(1.17, 1.88), vec2f(1.22, 1.62), vec2f(1.45, 1.43), vec2f(1.3, 1.28), vec2f(1.0, 1.18),
        vec2f(0.86, 0.9), vec2f(0.8, 0.0), vec2f(0.6, 0.0), vec2f(0.58, 0.68), vec2f(-0.6, 0.68),
        vec2f(-0.68, 0.0), vec2f(-0.9, 0.0), vec2f(-1.02, 0.82), vec2f(-1.3, 1.12));
    return pts[((i % NP) + NP) % NP] + vec2f(0.0, PLINTH_H + 0.06);
}
fn outline_at(s: f32) -> vec2f {
    let f = fract(s / f32(NP)) * f32(NP);
    let i = i32(floor(f));
    return mix(outline(i), outline(i + 1), fract(f));
}
// distance between the ray and segment a-b, and the ray distance there
fn ray_seg(ro: vec3f, rd: vec3f, a: vec3f, b: vec3f) -> vec2f {
    let ba = b - a;
    let oa = ro - a;
    let bb = dot(ba, ba);
    let rb = dot(rd, ba);
    let den = bb - rb * rb;
    var u = clamp((dot(oa, ba) - dot(oa, rd) * rb) / max(den, 1e-6), 0.0, 1.0);
    let t = max(dot(a + ba * u - ro, rd), 0.0);
    u = clamp(dot(ro + rd * t - a, ba) / bb, 0.0, 1.0);
    return vec2f(length(ro + rd * t - (a + ba * u)), t);
}

// ---- 4: looped wire. A sitting cat as lobes of woven brass, one inside another, hung from the ceiling.
fn lobe_r(y: f32) -> f32 {
    // the sitting cat's radius at height y: haunches, waist, chest, neck, head
    let base = PLINTH_H + 0.35;
    let h = y - base;
    var r = 0.52 * exp(-pow((h - 0.25) / 0.32, 2.0));
    r = max(r, 0.38 * exp(-pow((h - 0.85) / 0.28, 2.0)));
    r = max(r, 0.3 * exp(-pow((h - 1.45) / 0.2, 2.0)));
    return r;
}
fn wire_shell(p: vec3f, scale: f32) -> f32 {
    let c = vec3f(0.0, 0.0, 0.0);
    let r = lobe_r(p.y) * scale;
    let th = atan2(p.z, p.x);
    // ears: the head lobe rises into two points
    let ear = select(0.0, max(cos(th * 2.0), 0.0) * 0.18 * smoothstep(1.55, 1.75, p.y - PLINTH_H - 0.35 + 0.35), scale > 0.9);
    let shell = abs(length(p.xz - c.xz) - r) - 0.006;
    let top = PLINTH_H + 0.35 + 1.72 + ear;
    let bounded = max(shell, max(p.y - top, PLINTH_H + 0.36 - p.y));
    // a diamond weave: two helical families of wire
    let u = th * 8.0 / PI;
    let v = p.y * 9.0;
    let w1 = abs(fract(u + v) - 0.5);
    let w2 = abs(fract(u - v) - 0.5);
    let weave = (min(w1, w2) - 0.06) / 11.0 * max(r, 0.08) * 3.0;
    return max(bounded, weave);
}
fn asawa(p: vec3f) -> f32 {
    var d = wire_shell(p, 1.0);
    d = min(d, wire_shell(p, 0.55));
    d = min(d, sd_capsule(p, vec3f(0.0, PLINTH_H + 2.05, 0.0), vec3f(0.0, ROOM_HEIGHT, 0.0), 0.006));
    // ears: two triangles of the same wire on the head lobe
    let hy = PLINTH_H + 0.35 + 1.5;
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        let a = vec3f(0.0, hy + 0.12, s * 0.08);
        let b = vec3f(0.0, hy + 0.08, s * 0.26);
        let t = vec3f(0.03, hy + 0.42, s * 0.22);
        d = min(d, min(sd_capsule(p, a, t, 0.007), min(sd_capsule(p, b, t, 0.007), sd_capsule(p, a, b, 0.007))));
    }
    // a tail of wire wrapped round the haunches, its tip lifting
    var prev = vec3f(-0.5, PLINTH_H + 0.45, 0.0);
    for (var i = 1; i < 9; i = i + 1) {
        let a = PI + f32(i) * 0.38;
        let next = vec3f(cos(a) * 0.56, PLINTH_H + 0.45 + f32(i) * f32(i) * 0.006 + sin(time() * 1.2) * 0.01 * f32(i), -sin(a) * 0.56);
        d = min(d, sd_capsule(p, prev, next, 0.014));
        prev = next;
    }
    return d;
}

// ---- 5: a form in space. One bent, polished ovoid that is a cat only in its ears and the flick of a tail.
fn brancusi(p: vec3f) -> f32 {
    let c = vec3f(0.0, 1.55, 0.0);
    var q = p - c;
    // bend the long axis into a curve
    q = vec3f(q.x, q.y + 0.15 * q.x * q.x - 0.05, q.z);
    var d = sd_ellipsoid(q, vec3f(1.15, 0.32, 0.26));
    d = smin(d, sd_ellipsoid(q - vec3f(1.0, 0.18, 0.0), vec3f(0.3, 0.24, 0.22)), 0.18);
    // two ear ridges and a tail that lifts off the far end
    for (var s = -1.0; s < 2.0; s = s + 2.0) {
        d = smin(d, sd_round_cone(q, vec3f(1.0, 0.3, s * 0.1), vec3f(0.98, 0.52, s * 0.15), 0.08, 0.012), 0.05);
    }
    d = smin(d, sd_capsule(q, vec3f(-1.05, 0.05, 0.0), vec3f(-1.45, 0.45 + 0.04 * sin(time() * 0.7), 0.0), 0.04), 0.1);
    return d * 0.85;
}

// ---- the dispatcher, normals, light
fn sdf(p: vec3f) -> f32 {
    let f = form();
    if (f == 0) { return gyroid_cat(p); }
    if (f == 1) { return umbilic(p); }
    if (f == 2) { return ribbon(p); }
    if (f == 4) { return asawa(p); }
    return brancusi(p);
}
fn nrm(p: vec3f) -> vec3f {
    let e = vec2f(0.002, 0.0);
    return normalize(vec3f(sdf(p + e.xyy) - sdf(p - e.xyy), sdf(p + e.yxy) - sdf(p - e.yxy), sdf(p + e.yyx) - sdf(p - e.yyx)));
}
fn bmin() -> vec3f {
    let f = form();
    if (f == 4) { return vec3f(-0.62, PLINTH_H + 0.3, -0.62); }
    if (f == 5) { return vec3f(-1.6, 1.0, -0.4); }
    if (f == 1) { return vec3f(-1.3, PLINTH_H, -1.3); }
    return vec3f(-1.75, PLINTH_H, -0.55);
}
fn bmax() -> vec3f {
    let f = form();
    if (f == 4) { return vec3f(0.62, ROOM_HEIGHT, 0.62); }
    if (f == 5) { return vec3f(1.55, 2.25, 0.4); }
    if (f == 1) { return vec3f(1.3, PLINTH_H + 1.25, 1.3); }
    return vec3f(1.75, PLINTH_H + 2.05, 0.55);
}
fn soft_shadow(p: vec3f) -> f32 {
    let l = normalize(LIGHT);
    let b = box_span(p, l, bmin(), bmax());
    if (b.x > b.y || b.y < 0.0 || form() == 3) { return 1.0; }
    var t = max(b.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 24; i = i + 1) {
        if (t > b.y) { break; }
        let h = sdf(p + l * t);
        res = min(res, 12.0 * h / t);
        if (res < 0.02) { break; }
        t += clamp(h, 0.01, 0.25);
    }
    return clamp(res, 0.0, 1.0);
}
fn env(r: vec3f) -> vec3f {
    // what a polished surface sees: the dark room, its ceiling light, two strips of the room's colour
    var c = vec3f(0.01, 0.01, 0.016) + vec3f(0.6) * smoothstep(0.9, 0.97, r.y);
    c += rim_col() * (smoothstep(0.06, 0.0, abs(r.y - 0.05)) * 0.9 + smoothstep(0.05, 0.0, abs(r.x - 0.7)) * 0.5);
    return c;
}

fn shade_form(p: vec3f, rd: vec3f) -> vec3f {
    let f = form();
    let n = nrm(p);
    let l = normalize(LIGHT);
    let diff = max(dot(n, l), 0.0) * (0.3 + 0.7 * soft_shadow(p + n * 0.01));
    let ao = clamp(0.4 + 0.6 * sdf(p + n * 0.06) / 0.06, 0.0, 1.0);
    let fres = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let r = reflect(rd, n);
    var base = mat_col();
    var col = vec3f(0.0);
    if (f == 0) {
        // patinated bronze: darker deep in the lattice
        col = base * (0.06 + diff * 1.2) * ao * ao + env(r) * base * 0.6 + rim_col() * fres * 0.5;
    } else if (f == 1) {
        // granite, the umbilic edge polished bright
        let grain = noise3(p * 40.0) * 0.5 + noise3(p * 9.0) * 0.5;
        let edge = smoothstep(0.92, 0.99, umbilic_edge(p));
        base = base * (0.7 + 0.5 * grain);
        col = base * (0.06 + diff) * ao + env(r) * (0.04 + edge * 0.5) + rim_col() * edge * 0.25 + rim_col() * fres * 0.3;
    } else if (f == 2) {
        // white marble with grey veins
        let vein = smoothstep(0.02, 0.0, abs(fbm3(p * 2.5) - 0.5));
        base = mix(base, base * 0.45, vein * 0.7);
        col = base * (0.1 + diff * 1.05) * ao + env(r) * 0.08 + rim_col() * fres * 0.4;
    } else if (f == 4) {
        // brass wire
        col = base * (0.1 + diff * 1.3) + env(r) * base * 0.8 + rim_col() * fres * 0.6;
    } else {
        // mirror-polished bronze
        col = env(r) * mix(base, vec3f(1.0), fres) * 1.2 + base * diff * 0.25;
    }
    return col;
}

// the room: dark floor with the form's shadow, a plinth, dark walls with a line of the room's light
fn background(ro: vec3f, rd: vec3f, tmax: f32) -> Hit {
    let f = form();
    let ph = select(PLINTH_H, 0.95, f == 5);
    let pw = select(vec2f(1.85, 0.75), vec2f(0.55, 0.55), f == 1 || f == 4 || f == 5);
    let pmin = vec3f(-pw.x, 0.0, -pw.y);
    let pmax = vec3f(pw.x, ph, pw.y);
    let pb = box_span(ro, rd, pmin, pmax);
    let tf = plane_y(ro, rd, 0.0);
    if (pb.x < pb.y && pb.x > 0.0 && (tf < 0.0 || pb.x < tf)) {
        let p = ro + rd * pb.x;
        var c = select(vec3f(0.012, 0.012, 0.018), vec3f(0.55, 0.52, 0.46) * (0.8 + 0.2 * noise3(p * 30.0)), f == 5);
        if (p.y > ph - 0.002) { c *= 0.35 + 0.65 * soft_shadow(p); }
        let top = p.y > ph - 0.002;
        // the edge line: round the top face, and along the top of each side
        let edge = select(ph - p.y, min(min(abs(p.x - pmin.x), abs(p.x - pmax.x)), min(abs(p.z - pmin.z), abs(p.z - pmax.z))), top);
        if (f != 5) { c += rim_col() * smoothstep(0.02, 0.0, edge) * 1.4; }
        return Hit(tone(c * (0.5 + 0.8 * max(dot(vec3f(0.0, 1.0, 0.0), normalize(LIGHT)), 0.0))), pb.x);
    }
    if (tf > 0.0 && tf <= tmax + 0.01) {
        let p = ro + rd * tf;
        var c = vec3f(0.02, 0.02, 0.028);
        let g = abs(fract(p.xz) - 0.5);
        c += vec3f(0.03, 0.035, 0.05) * smoothstep(0.485, 0.5, max(g.x, g.y));
        c += rim_col() * 0.1 * exp(-dot(p.xz, p.xz) * 0.25);
        c *= 0.35 + 0.65 * soft_shadow(p);
        return Hit(tone(c), tf);
    }
    let w = ro + rd * horizon_t(tmax);
    var c = vec3f(0.016, 0.015, 0.024);
    if (w.y > ROOM_HEIGHT - 0.05) {
        c = vec3f(0.01) + vec3f(0.6) * smoothstep(0.6, 0.0, length(w.xz)) ;
    } else {
        c += rim_col() * smoothstep(0.04, 0.0, abs(w.y - 0.06)) * 0.8;
    }
    return Hit(tone(c), horizon_t(tmax));
}

fn strings(ro: vec3f, rd: vec3f, bg: Hit) -> Hit {
    // threads between the plates, glowing so the thinnest still reads at a distance
    let shift = 5.0 + 4.0 * sin(time() * 0.12);
    var glow = vec3f(0.0);
    var near = bg.t;
    let px = 0.0016;
    for (var i = 0; i < 44; i = i + 1) {
        let s = f32(i) * f32(NP) / 44.0;
        let a2 = outline_at(s);
        let b2 = outline_at(s + shift);
        let h = ray_seg(ro, rd, vec3f(a2, 0.42), vec3f(b2, -0.42));
        if (h.y < bg.t) {
            let w = max(px * h.y, 0.004);
            let k = exp(-pow(h.x / w, 2.0));
            glow += mix(mat_col(), rim_col(), f32(i) / 44.0) * k;
            if (k > 0.5) { near = min(near, h.y); }
        }
    }
    // the plates' edges
    for (var i = 0; i < NP; i = i + 1) {
        for (var z = -1.0; z < 2.0; z = z + 2.0) {
            let h = ray_seg(ro, rd, vec3f(outline(i), z * 0.42), vec3f(outline(i + 1), z * 0.42));
            if (h.y < bg.t) {
                let w = max(px * h.y, 0.006);
                let k = exp(-pow(h.x / w, 2.0));
                glow += vec3f(0.7, 0.85, 1.0) * k * 0.7;
                if (k > 0.5) { near = min(near, h.y); }
            }
        }
    }
    return Hit(clamp(bg.color + glow, vec3f(0.0), vec3f(1.0)), near);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let f = form();
    let bg = background(ro, rd, tmax);
    if (f == 3) { return strings(ro, rd, bg); }
    let b = box_span(ro, rd, bmin(), bmax());
    if (b.x < b.y && b.y > tmin) {
        var t = max(b.x, tmin);
        let steps = select(80, 120, quality() > 0.6);
        let far = min(b.y, bg.t);
        for (var i = 0; i < 120; i = i + 1) {
            if (i >= steps || t > far) { break; }
            let d = sdf(ro + rd * t);
            if (d < 0.0008 * t + 0.001) { return Hit(tone(shade_form(ro + rd * t, rd) * 1.3), t); }
            t += d * select(0.9, 0.7, f == 0 || f == 4);
        }
    }
    return bg;
}

shaders.1d15b5f95755b00fe54a3d9253b6:
// Standing on the Photosphere: boiling granulation underfoot, a twisting prominence overhead,
// drifting sunspots, corner flares, and a corona fading to black.
// exemplar v1: a dark sky with corona streamers and a spicule fringe at the limb, limb darkening into the distance,
// a crimson H-alpha prominence with strands and a hot core, deeper intergranular lanes, a filmic curve.
var<private> BLOBS: array<vec4f, 4>;
var<private> PU: vec2f;

fn aces(x: vec3f) -> vec3f { return (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14); }

// filmic curve (ACES fit) blended with a hue-keeping version (ACES on the brightest channel, the colour scaled to match),
// so hot orange stays orange instead of bleaching to cream; a soft vignette; a hair of dither
fn tm(c: vec3f, rd: vec3f) -> vec3f {
    let fw = room.inv_rot_proj * vec4f(0.0, 0.0, 0.5, 1.0);
    let vig = 1.0 - 0.3 * smoothstep(0.97, 0.55, dot(rd, normalize(fw.xyz / fw.w)));
    let x = max(c, vec3f(0.0)) * vig;
    let m = max(max(x.r, x.g), max(x.b, 1e-4));
    let y = mix(aces(x), x * (aces(vec3f(m)).r / m), 0.6);
    return clamp(y + (hash13(rd * 913.7) - 0.5) / 255.0, vec3f(0.0), vec3f(1.0));
}

fn heat(x: f32) -> vec3f {
    let y = clamp(x, 0.0, 2.6);
    return vec3f(y * 1.4, y * y * 0.72, y * y * y * 0.2);
}

fn flare() -> vec4f {
    let ft = time() * 0.16;
    let k = floor(ft);
    let f = fract(ft);
    let h = hash12(vec2f(k, 7.3));
    let h2 = hash12(vec2f(k, 1.9));
    let pos = vec3f(select(-4.3, 4.3, h > 0.5), 0.0, select(-4.3, 4.3, h2 > 0.5));
    return vec4f(pos, smoothstep(0.0, 0.035, f) * exp(-f * 5.0));
}

fn granule(p: vec2f, t: f32) -> f32 {
    let s = p * 1.25;
    let i = floor(s);
    let f = fract(s);
    var d1 = 9.0;
    var d2 = 9.0;
    var life = 0.0;
    for (var y = -1; y <= 1; y = y + 1) {
        for (var x = -1; x <= 1; x = x + 1) {
            let g = vec2f(f32(x), f32(y));
            let h = hash33(vec3f(i + g, 3.7));
            let o = 0.5 + 0.38 * sin(t * 0.35 * (0.6 + h.z) + TAU * h.xy);
            let r = g + o - f;
            let d = dot(r, r);
            if (d < d1) { d2 = d1; d1 = d; life = h.z; } else if (d < d2) { d2 = d; }
        }
    }
    let edge = sqrt(d2) - sqrt(d1);
    let ph = fract(t * 0.07 + life);
    let boil = 0.75 + 0.35 * sin(ph * TAU);
    let core = 1.0 - sqrt(d1) * 0.6;
    let rim = smoothstep(0.05, 0.12, edge) * (1.0 - smoothstep(0.12, 0.3, edge));
    return mix(0.1, boil * core + 0.22 + rim * 0.12, smoothstep(0.03, 0.2, edge));
}

fn floor_col(p: vec3f, t: f32, fl: vec4f) -> vec3f {
    let w = vec2f(noise3(vec3f(p.xz * 0.6, t * 0.08)), noise3(vec3f(p.xz * 0.6 + 5.2, t * 0.08))) - 0.5;
    let q = p.xz + w * 0.8;
    var g = granule(q, t);
    g *= 0.8 + 0.3 * noise3(vec3f(q * 5.0, t * 0.25)) + 0.12 * noise3(vec3f(q * 17.0, t * 0.6));
    for (var i = 0; i < 2; i = i + 1) {
        let fi = f32(i);
        let a = t * 0.03 + fi * 3.3;
        let c = vec2f(cos(a) * 3.8, sin(a * 0.7 + fi) * 3.4);
        let rad = 0.5 + 0.18 * fi;
        let dv = p.xz - c;
        let ld = max(length(dv), 1e-4);
        let r = ld / rad;
        let dir = dv / ld;
        let fil = noise3(vec3f(dir * 3.0, r * 1.2 + fi * 9.0));
        let ang = atan2(dv.y, dv.x);
        let pen = smoothstep(2.4, 1.5 + fil * 0.6, r);
        let umb = smoothstep(1.05, 0.8, r + (fil - 0.5) * 0.2);
        let fib = 0.38 + 0.22 * (0.5 + 0.5 * sin(ang * 46.0 + fil * 7.0));
        g = mix(g, fib, pen);
        g = mix(g, 0.07, umb);
    }
    let r0 = length(p.xz);
    let fall = mix(1.15, 0.5, smoothstep(1.0, 11.0, r0));
    var e = g * fall * 0.95;
    let dseg = length(vec2f(max(abs(p.x) - 2.3, 0.0), p.z));
    e += 0.35 / (1.0 + dseg * dseg * 1.2);
    let zf1 = -0.35 * sin(2.07 + t * 0.3);
    let zf2 = -0.35 * sin(-2.07 + t * 0.3);
    let df1 = length(p.xz - vec2f(2.3, zf1));
    let df2 = length(p.xz - vec2f(-2.3, zf2));
    e += 0.9 / (1.0 + df1 * df1 * 6.0) + 0.9 / (1.0 + df2 * df2 * 6.0);
    let df = length(p.xz - fl.xz);
    e += fl.w * 2.6 / (1.0 + df * df * 0.35);
    return heat(e);
}

fn corona(rd: vec3f, t: f32, fl: vec4f, ro: vec3f) -> vec3f {
    let y = max(rd.y, 0.0);
    let az = atan2(rd.z, rd.x);
    // streamers: brightness that varies round the horizon and stretches upward
    let s = noise3(vec3f(az * 3.0, y * 1.5 - t * 0.02, t * 0.03));
    var c = heat(0.9 * exp(-y * 5.5) * (0.35 + 0.9 * s * s));
    c += vec3f(0.9, 0.16, 0.03) * exp(-y * 16.0) * 0.9;
    // spicules: a fine fringe of jets standing on the limb
    let sp = noise3(vec3f(az * 70.0, y * 9.0 - t * 0.35, 1.0));
    c += vec3f(1.0, 0.2, 0.05) * smoothstep(0.45, 0.85, sp) * exp(-y * 40.0) * 1.4;
    c += vec3f(0.006, 0.002, 0.004);
    let fd = normalize(fl.xyz + vec3f(0.0, 1.2, 0.0) - ro);
    c += vec3f(1.6, 0.75, 0.3) * pow(max(dot(rd, fd), 0.0), 14.0) * fl.w * 2.0;
    return c;
}

fn init_blobs(t: f32) {
    for (var i = 0; i < 4; i = i + 1) {
        let fi = f32(i);
        let s = fract(t * 0.11 + fi * 0.25);
        let a0 = 0.7 + fi * 0.55;
        let x0 = 2.3 * cos(a0);
        let y0 = 2.3 * sin(a0) / 0.82;
        let z0 = -0.35 * sin(x0 * 0.9 + t * 0.3);
        let pos = vec3f(x0 * (1.0 + 0.25 * s), y0 * (1.0 - s * s), z0 + 0.3 * s * (fi - 1.5));
        BLOBS[i] = vec4f(pos, 0.07 * (1.0 - s) + 0.01);
    }
}

fn prom(p: vec3f, t: f32) -> f32 {
    let zq = p.z + 0.35 * sin(p.x * 0.9 + t * 0.3);
    let e = vec2f(p.x, p.y * 0.82);
    let a = atan2(e.y, e.x);
    let R = 2.3 + 0.1 * sin(a * 4.0 - t * 0.5);
    var u = vec2f(length(e) - R, zq);
    u = rot2(a * 3.0 + t * 0.45) * u;
    let w = 0.26 + 0.06 * sin(a * 7.0 + t * 1.1);
    let rib = length(vec2f(max(abs(u.x) - w, 0.0), u.y)) - 0.045;
    PU = vec2f(u.x / w, a);
    var q2 = p - vec3f(0.2, 0.0, 0.25);
    let xz = rot2(0.55) * q2.xz;
    q2 = vec3f(xz.x, q2.y, xz.y);
    let r2 = 1.55 + 0.25 * sin(t * 0.21);
    let e2 = vec2f(q2.x, q2.y * 1.05);
    let fil = length(vec2f(length(e2) - r2, q2.z + 0.08 * sin(q2.x * 3.0 + t))) - 0.035;
    var d = min(rib, fil);
    for (var i = 0; i < 4; i = i + 1) {
        let b = BLOBS[i];
        d = min(d, length(p - b.xyz) - b.w);
    }
    return d;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let t = time();
    let fl = flare();
    init_blobs(t);
    let hz = noise3(vec3f(rd * 38.0 + vec3f(0.0, -t * 1.5, 0.0))) - 0.5;
    let rdh = normalize(rd + vec3f(hz, hz * 0.5, -hz) * 0.006);
    var bg: vec3f;
    var tb = horizon_t(tmax);
    let tf = plane_y(ro, rdh, 0.0);
    if (tf > 0.0) {
        let p = ro + rdh * tf;
        var c = floor_col(p, t, fl);
        c = mix(c, vec3f(0.42, 0.07, 0.012), 1.0 - exp(-tf * 0.03));
        bg = c * 0.72;
        tb = clamp(tf, tmin, horizon_t(tmax));
    } else {
        bg = corona(rd, t, fl, ro);
    }

    // the prominence: an emissive, twisting ribbon of plasma
    var acc = vec3f(0.0);
    var T = 1.0;
    var tfirst = -1.0;
    let sp = box_span(ro, rd, vec3f(-3.4, 0.0, -1.5), vec3f(3.4, 3.7, 1.5));
    if (sp.x < sp.y && sp.y > tmin) {
        var tt = max(sp.x, tmin);
        let tend = min(sp.y, tb);
        tt += hash12(rd.xy * 731.0 + rd.z * 97.0) * 0.04;
        let steps = i32(mix(28.0, 64.0, quality()));
        for (var i = 0; i < steps; i = i + 1) {
            if (tt > tend || T < 0.02) { break; }
            let p = ro + rd * tt;
            let pd = prom(p, t);
            let d = max(pd, 0.0);
            let dt = clamp(pd * 0.5, 0.03, 0.3);
            var fk = 0.5;
            if (d < 0.8) { fk = noise3(p * 2.6 + vec3f(0.0, -t * 1.3, t * 0.4)); }
            let halo = exp(-d * 6.0);
            let core = exp(-d * 30.0);
            // strands along the field lines, slowly sliding along the loop
            let strand = 0.7 + 0.3 * sin(PU.x * 17.0 + 2.5 * sin(PU.y * 5.0 + t * 0.4) + fk * 4.0);
            let hot = 0.5 + 1.25 * core * (0.5 + 0.7 * fk) * strand;
            let em = heat(hot) * core * 2.4 * strand + vec3f(1.0, 0.12, 0.07) * halo * 0.6;
            acc += T * em * (0.5 + fk) * dt;
            T *= exp(-core * dt * 5.0);
            if (tfirst < 0.0 && T < 0.5) { tfirst = tt; }
            tt += dt;
        }
    }

    // rising sparks
    var sparks = vec3f(0.0);
    let nsp = select(6, 12, quality() > 0.5);
    for (var i = 0; i < nsp; i = i + 1) {
        let h = hash33(vec3f(f32(i), 4.1, 2.7));
        let life = fract(t * (0.12 + 0.1 * h.z) + h.x);
        let wob = sin(t * 1.3 + h.z * 9.0);
        let pos = vec3f((fract(h.y * 7.3) - 0.5) * 7.0 + 0.3 * wob, life * 4.2, (fract(h.z * 5.1) - 0.5) * 7.0 + 0.2 * wob);
        let v = pos - ro;
        let tp = dot(v, rd);
        if (tp > tmin && tp < tb) {
            let dd = length(v - rd * tp);
            let sz = 0.012 + 0.002 * tp;
            sparks += heat(1.8 * (1.0 - life) + 0.4) * exp(-dd * dd / (sz * sz)) * (1.0 - life) * 1.2;
        }
    }

    // flare bloom in a corner
    var fglow = vec3f(0.0);
    if (fl.w > 0.01) {
        let fp = fl.xyz + vec3f(0.0, 0.6, 0.0);
        let v = fp - ro;
        let tp = max(dot(v, rd), 0.0);
        let dd = length(v - rd * tp);
        fglow = vec3f(1.6, 0.9, 0.45) * fl.w * (exp(-dd * dd * 3.0) * 1.6 + exp(-dd * dd * 0.4) * 0.3);
    }

    let col = bg * T + acc + sparks + fglow;
    var th = tb;
    if (tfirst > 0.0) { th = tfirst; }
    return Hit(tm(col * 0.8, rd), clamp(th, tmin, tmax));
}

shaders.19001ea3a4acf2046bd0d87280fb:
// Duo portrait of the room's two makers: two figures of stacked light panels side by side at a drafting table,
// one ice-cold (west, monitor side), one amp-warm (east), trading beats as they weld little room-cubes
// and throw them into a pulsing lattice. Amber amp glow east, cold blue monitors west.
const AMBER = vec3f(1.0, 0.5, 0.15);
const ICE = vec3f(0.55, 0.8, 1.0);
const WARM = vec3f(1.0, 0.8, 0.55);
const BLUE = vec3f(0.2, 0.48, 1.0);
const HAZE = vec3f(0.02, 0.018, 0.024);
const GZ: f32 = -1.75;
const GX0: f32 = -1.5;
const GY0: f32 = 0.95;
const CS: f32 = 0.5;
const CH: f32 = 0.18;
const FZ: f32 = 0.8;
const FXA: f32 = -0.45;
const FXB: f32 = 0.45;
const BC = vec3f(0.0, 1.02, 0.0);
const BH = vec3f(0.75, 0.025, 0.45);
const TILT: f32 = 0.32;
const SPAWN = vec3f(0.0, 1.34, -0.05);

var<private> BT: f32;
var<private> KICK: f32;
var<private> CYC: f32;
var<private> NF: f32;
var<private> MOVING: bool;
var<private> MC: vec3f;
var<private> MSC: f32;
var<private> MROT: f32;
var<private> SPK: f32;
var<private> FE: vec3f;
var<private> FA: f32;
var<private> FT: f32;
var<private> PTINT: vec3f;
var<private> PWARM: vec3f;
var<private> EYEC: vec3f;
var<private> LK: f32;
var<private> LP: array<vec3f, 6>;
var<private> LC: array<vec3f, 6>;

struct Lt { d: vec3f, s: vec3f, };

fn aces(x: vec3f) -> vec3f { return (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14); }
fn tm(c: vec3f, rd: vec3f) -> vec3f {
    let fw = room.inv_rot_proj * vec4f(0.0, 0.0, 0.5, 1.0);
    let vig = 1.0 - 0.3 * smoothstep(0.97, 0.55, dot(rd, normalize(fw.xyz / fw.w)));
    return clamp(aces(max(c, vec3f(0.0)) * vig) + (hash13(rd * 913.7) - 0.5) / 255.0, vec3f(0.0), vec3f(1.0));
}

fn setup() {
    let t = time();
    BT = t * 2.1;
    let fb = fract(BT);
    KICK = exp(-fb * 6.0);
    CYC = BT - 44.0 * floor(BT / 44.0);
    let k = floor(CYC);
    NF = min(k, 36.0);
    MOVING = k < 36.0;
    let cx = k - 6.0 * floor(k / 6.0);
    let cy = floor(k / 6.0);
    let slot = vec3f(GX0 + (cx + 0.5) * CS, GY0 + (cy + 0.5) * CS, GZ);
    if (fb < 0.35) {
        MC = SPAWN;
        MSC = smoothstep(0.0, 0.35, fb);
        SPK = 1.0 - fb / 0.35;
    } else {
        let u = (fb - 0.35) / 0.65;
        let e = mix(u * u * (3.0 - 2.0 * u), u * u, 0.5);
        MC = mix(SPAWN, slot, e) + vec3f(0.0, 0.55 * sin(PI * u), 0.0);
        MSC = 1.0;
        SPK = 0.0;
    }
    if (!MOVING) { SPK = 0.0; }
    MROT = (1.0 - fb) * (1.0 - fb) * 6.0;
    let pump = 0.85 + 0.3 * KICK;
    LP[0] = vec3f(3.7, 1.0, 2.3); LC[0] = AMBER * 5.0 * pump;
    LP[1] = vec3f(3.7, 0.75, -2.3); LC[1] = AMBER * 4.0 * pump;
    LP[2] = vec3f(-4.2, 1.55, 2.2); LC[2] = BLUE * 3.5;
    LP[3] = vec3f(-4.2, 1.55, -2.2); LC[3] = BLUE * 3.5;
    LP[4] = vec3f(0.0, 1.4, FZ); LC[4] = mix(ICE, WARM, 0.5) * (1.1 + 0.8 * KICK);
    LP[5] = vec3f(0.0, 1.12, -0.05); LC[5] = AMBER * (0.4 + 2.5 * SPK + 0.5 * KICK);
}

fn lights(P: vec3f, n: vec3f, rd: vec3f, shin: f32) -> Lt {
    var d = vec3f(0.0);
    var s = vec3f(0.0);
    for (var i = 0; i < 6; i = i + 1) {
        let v = LP[i] - P;
        let d2 = max(dot(v, v), 1e-4);
        let l = v * inverseSqrt(d2);
        let att = LC[i] / (1.0 + d2 * 0.5);
        d += att * max(dot(n, l), 0.0);
        s += att * pow(max(dot(n, normalize(l - rd)), 0.0), shin);
    }
    return Lt(d, s);
}

fn amb(n: vec3f) -> vec3f { return vec3f(0.014, 0.016, 0.026) * (0.6 + 0.4 * n.y); }

fn box_n(q: vec3f) -> vec3f {
    let a = abs(q);
    if (a.x > a.y && a.x > a.z) { return vec3f(sign(q.x), 0.0, 0.0); }
    if (a.y > a.z) { return vec3f(0.0, sign(q.y), 0.0); }
    return vec3f(0.0, 0.0, sign(q.z));
}

fn hit_box(ro: vec3f, rd: vec3f, c: vec3f, h: vec3f, tmin: f32, tb: f32) -> f32 {
    let sp = box_span(ro, rd, c - h, c + h);
    if (sp.x <= sp.y && sp.x > tmin && sp.x < tb) { return sp.x; }
    return -1.0;
}

fn to_local(v: vec3f) -> vec3f { let c = cos(TILT); let s = sin(TILT); return vec3f(v.x, v.y * c + v.z * s, -v.y * s + v.z * c); }
fn to_world(v: vec3f) -> vec3f { let c = cos(TILT); let s = sin(TILT); return vec3f(v.x, v.y * c - v.z * s, v.y * s + v.z * c); }

fn rotl(v: vec3f, a: f32) -> vec3f {
    let r1 = rot2(a) * v.xz;
    let w = vec3f(r1.x, v.y, r1.y);
    let r2 = rot2(a * 0.6) * w.yz;
    return vec3f(w.x, r2.x, r2.y);
}
fn rotl_inv(v: vec3f, a: f32) -> vec3f {
    let r2 = rot2(-a * 0.6) * v.yz;
    let w = vec3f(v.x, r2.x, r2.y);
    let r1 = rot2(-a) * w.xz;
    return vec3f(r1.x, w.y, r1.y);
}

// a room in miniature: dark block, glowing edges, a lit doorway on every side
fn cube_col(lp: vec3f, h: f32, nl: vec3f, nw: vec3f, P: vec3f, rd: vec3f, fl: f32) -> vec3f {
    let dq = vec3f(h) - abs(lp);
    let mx = max(dq.x, max(dq.y, dq.z));
    let mn = min(dq.x, min(dq.y, dq.z));
    let md = dq.x + dq.y + dq.z - mx - mn;
    let edge = exp(-md / 0.007);
    let L = lights(P, nw, rd, 40.0);
    var c = vec3f(0.08, 0.08, 0.09) * (L.d + amb(nw)) + L.s * 0.3;
    if (abs(nl.y) < 0.5) {
        let u = select(lp.x, lp.z, abs(nl.x) > 0.5) / h;
        let v = lp.y / h;
        let door = smoothstep(0.3, 0.22, abs(u)) * smoothstep(0.25, 0.17, v);
        c += AMBER * door * (1.2 + 2.0 * fl);
    } else if (nl.y > 0.5) {
        let f = abs(fract(lp.xz / h * 1.5 + 0.5) - 0.5);
        c += BLUE * 0.25 * smoothstep(0.44, 0.49, max(f.x, f.y));
    }
    c += mix(BLUE, ICE, fl) * edge * (1.0 + 2.5 * fl + 0.8 * KICK);
    c += ICE * fl * 0.25;
    return c;
}

fn board_col(lp: vec3f, nl: vec3f, P: vec3f, nw: vec3f, rd: vec3f) -> vec3f {
    let L = lights(P, nw, rd, 40.0);
    var base = vec3f(0.06, 0.06, 0.07);
    var em = vec3f(0.0);
    if (nl.y > 0.5) {
        base = vec3f(0.03, 0.045, 0.08) * (0.85 + 0.3 * noise3(vec3f(lp.xz * 6.0, 1.0)));
        // the blueprint mirrors the lattice: placed rooms glow amber, the one being made blinks
        let g = (lp.xz + vec2f(0.33)) / 0.11;
        if (g.x >= 0.0 && g.y >= 0.0 && g.x < 6.0 && g.y < 6.0) {
            let cx = floor(g.x);
            let cy = 5.0 - floor(g.y);
            let idx = cy * 6.0 + cx;
            let f = abs(fract(g) - 0.5);
            let ln = smoothstep(0.42, 0.48, max(f.x, f.y));
            em += BLUE * ln * (0.45 + 0.9 * KICK);
            if (idx < NF) { em += AMBER * 0.45 * smoothstep(0.42, 0.3, max(f.x, f.y)); }
            if (MOVING && idx == NF) { em += ICE * (1.0 - ln) * (0.3 + 0.7 * KICK); }
        }
        let r = length(lp.xz - vec2f(-0.52, 0.18));
        em += BLUE * 0.5 * exp(-abs(r - 0.13) * 250.0);
        let r2 = length(lp.xz - vec2f(0.55, 0.2));
        em += AMBER * 0.35 * exp(-abs(r2 - 0.09) * 250.0);
        em += BLUE * 0.4 * exp(-abs(lp.z - 0.38) * 300.0) * step(abs(lp.x), 0.7);
    }
    return base * (L.d + amb(nw)) + L.s * 0.15 + em;
}

fn metal_col(P: vec3f, n: vec3f, rd: vec3f) -> vec3f {
    let L = lights(P, n, rd, 50.0);
    return vec3f(0.12, 0.12, 0.13) * (L.d + amb(n)) + L.s * 0.5;
}

fn amp_col(P: vec3f, n: vec3f, rd: vec3f, c: vec3f, h: vec3f, two_rows: bool) -> vec3f {
    let L = lights(P, n, rd, 30.0);
    var base = vec3f(0.025, 0.022, 0.02);
    var em = vec3f(0.0);
    var spec = 0.15;
    if (n.x < -0.5) {
        let fz = P.z - c.z;
        let top = c.y + h.y - 0.22;
        if (P.y > top) {
            base = vec3f(0.3, 0.26, 0.2);
            spec = 0.6;
            let kz = (fract((fz + h.z) / 0.18) - 0.5) * 0.18;
            let kd = length(vec2f(kz, P.y - top - 0.11));
            base *= 1.0 - 0.9 * smoothstep(0.034, 0.026, kd);
            let pd = length(vec2f(fz - h.z + 0.09, P.y - top - 0.11));
            em += AMBER * 5.0 * smoothstep(0.024, 0.014, pd);
        } else {
            let gm = (c.y - h.y + top) * 0.5;
            var q = vec2f(fz, P.y - gm) / 0.72;
            if (!two_rows) { q.y += 0.5; }
            let lq = (fract(q) - 0.5) * 0.72;
            let r = length(lq);
            let weave = 0.85 + 0.3 * noise3(P * 40.0);
            base = vec3f(0.05, 0.04, 0.03) * weave;
            let cone = smoothstep(0.3, 0.28, r);
            let rim = exp(-abs(r - 0.29) * 60.0);
            em += AMBER * (0.35 + 0.5 * KICK) * (1.0 - 0.8 * cone) * weave * 0.6;
            em += AMBER * rim * (0.4 + 1.6 * KICK);
            em += AMBER * cone * exp(-r * 18.0) * (0.3 + 1.2 * KICK);
        }
    }
    return base * (L.d + amb(n)) + L.s * spec + em;
}

fn mon_col(P: vec3f, n: vec3f, rd: vec3f, c: vec3f, h: vec3f, which: i32) -> vec3f {
    let L = lights(P, n, rd, 40.0);
    var col = vec3f(0.03) * (L.d + amb(n)) + L.s * 0.2;
    if (n.x > 0.5) {
        let u = (P.z - c.z) / (h.z - 0.04);
        let v = (P.y - c.y) / (h.y - 0.04);
        if (abs(u) < 1.0 && abs(v) < 1.0) {
            var em = vec3f(0.01, 0.02, 0.05);
            let v01 = v * 0.5 + 0.5;
            if (which == 0) {
                let bx = (u * 0.5 + 0.5) * 14.0;
                let bi = floor(bx);
                let fu = fract(bx);
                let hgt = 0.1 + 0.85 * noise3(vec3f(bi * 1.7, BT * 1.1, 2.0)) * (0.55 + 0.45 * KICK);
                let seg = step(0.25, fract(v01 * 18.0));
                let on = step(v01, hgt) * step(0.15, fu) * step(fu, 0.85) * seg;
                em += mix(BLUE, ICE, v01) * on * 1.6;
            } else {
                let yv = 0.55 * sin(u * 7.0 + BT * 3.0) * sin(u * 2.3 - BT) * (0.35 + 0.65 * KICK);
                em += ICE * exp(-abs(v - yv) * 30.0) * 1.5;
                let g = abs(fract(vec2f(u, v) * 4.0) - 0.5);
                em += BLUE * 0.12 * smoothstep(0.46, 0.49, max(g.x, g.y));
            }
            em *= 0.9 + 0.1 * sin(P.y * 300.0);
            col = em + L.s * 0.3;
        }
    }
    return col;
}

fn floor_col(P: vec3f, rd: vec3f) -> vec3f {
    let n = vec3f(0.0, 1.0, 0.0);
    var base = vec3f(0.08, 0.078, 0.076) * (0.65 + 0.5 * noise3(vec3f(P.xz * 1.7, 0.0))) * (0.85 + 0.3 * noise3(vec3f(P.xz * 11.0, 3.0)));
    let f = fract(P.xz * 0.5);
    let dm = min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y)) * 2.0;
    let seam = smoothstep(0.016, 0.006, dm);
    base *= 1.0 - 0.6 * seam;
    var sh = 1.0;
    let da = P.xz - vec2f(FXA, FZ);
    let db = P.xz - vec2f(FXB, FZ);
    sh *= (1.0 - 0.5 * exp(-dot(da, da) * 9.0)) * (1.0 - 0.5 * exp(-dot(db, db) * 9.0));
    let q = abs(P.xz) - vec2f(0.7, 0.42);
    sh *= 1.0 - 0.45 * exp(-length(max(q, vec2f(0.0))) * 7.0);
    let L = lights(P, n, rd, 70.0);
    var c = base * (L.d * sh + amb(n)) + L.s * 0.35 * (0.6 + 0.4 * noise3(vec3f(P.xz * 4.0, 7.0))) * sh;
    // a ring of light runs out along the floor seams on every beat
    let r = length(P.xz);
    let fb = fract(BT);
    let ring = exp(-abs(r - fb * 7.5) * 3.0) * (1.0 - fb);
    c += BLUE * seam * (0.05 + 1.4 * ring);
    return c;
}

fn wall_col(P: vec3f, rd: vec3f) -> vec3f {
    var n = vec3f(0.0, -1.0, 0.0);
    var uv = P.xz;
    if (P.y < 4.47) {
        if (abs(P.x) > abs(P.z)) { n = vec3f(-sign(P.x), 0.0, 0.0); uv = vec2f(P.z, P.y); }
        else { n = vec3f(0.0, 0.0, -sign(P.z)); uv = vec2f(P.x, P.y); }
    }
    let row = floor(uv.y / 0.2);
    let u = uv.x / 0.4 + row * 0.5;
    let fu = fract(u);
    let fv = fract(uv.y / 0.2);
    let dmm = min(min(fu, 1.0 - fu) * 0.4, min(fv, 1.0 - fv) * 0.2);
    let mort = 1.0 - smoothstep(0.006, 0.014, dmm);
    var base = vec3f(0.12, 0.11, 0.1) * (0.7 + 0.45 * hash12(vec2f(floor(u), row))) * (0.8 + 0.35 * noise3(P * 2.5));
    base *= 1.0 - 0.55 * mort;
    if (P.y > 4.47) { base = vec3f(0.035, 0.035, 0.04) * (0.8 + 0.4 * noise3(P * 3.0)); }
    let L = lights(P, n, rd, 12.0);
    return base * (L.d + amb(n)) + L.s * 0.02;
}

// one translucent panel of a figure: glowing edges, a soft body, a beat-wave rising through the stack
fn panel(ro: vec3f, rd: vec3f, c: vec3f, h: vec3f, tlim: f32, br: f32, eye: bool) {
    let sp = box_span(ro, rd, c - h, c + h);
    if (sp.x > sp.y || sp.y <= 0.0 || sp.x >= tlim) { return; }
    let t0 = max(sp.x, 0.0);
    let p = ro + rd * t0 - c;
    let dq = h - abs(p);
    let mx = max(dq.x, max(dq.y, dq.z));
    let mn = min(dq.x, min(dq.y, dq.z));
    let md = dq.x + dq.y + dq.z - mx - mn;
    let w = 0.003 + 0.0012 * t0;
    let edge = exp(-md / w);
    let th = min(sp.y, tlim) - t0;
    let tint = mix(PTINT, PWARM, br);
    var em = tint * (0.2 + 2.5 * th + 2.0 * edge) * (0.5 + 1.4 * br);
    if (eye) {
        let front = select(1.0, 1.8, p.z < 0.0 && dq.z < 0.004);
        em = EYEC * (1.5 + 3.0 * edge) * (0.8 + 0.4 * LK) * front;
    }
    FE += (1.0 - FA) * em * 0.5;
    FA += (1.0 - FA) * 0.15;
    FT = min(FT, t0);
}

// one maker: legs, torso, shoulders, head, an outer arm resting on the board and an inner arm reaching to the shared weld
fn figure_one(ro: vec3f, rd: vec3f, tlim: f32, ox: f32, side: f32, ph: f32, hs: f32, sw: f32, hw: f32) {
    let bb = box_span(ro, rd, vec3f(ox - 0.42, 0.0, FZ - 0.57), vec3f(ox + 0.42, 1.95, FZ + 0.2));
    if (bb.x > bb.y || bb.y <= 0.0 || bb.x >= tlim) { return; }
    let t = time();
    LK = exp(-fract(BT + ph) * 6.0);
    let wave = fract(BT + ph) * 1.5 - 0.2;
    for (var k = 0; k < 20; k = k + 1) {
        let fk = f32(k);
        let y = (0.07 + fk * 0.092) * hs;
        let sway = 0.014 * sin(t * 1.6 + fk * 0.42 + ph * 5.0);
        let br = exp(-abs(fk / 19.0 - wave) * 8.0) * (0.5 + 0.5 * LK);
        let hy = 0.021;
        if (k < 9) {
            panel(ro, rd, vec3f(ox - 0.12 * sw + sway, y, FZ), vec3f(0.07 * sw, hy, 0.085), tlim, br, false);
            panel(ro, rd, vec3f(ox + 0.12 * sw + sway, y, FZ), vec3f(0.07 * sw, hy, 0.085), tlim, br, false);
        } else if (k < 16) {
            let s = smoothstep(9.0, 15.0, fk);
            panel(ro, rd, vec3f(ox + sway, y, FZ), vec3f((0.17 + 0.08 * s) * sw, hy, 0.11 + 0.025 * s), tlim, br, false);
            if (k >= 12) {
                panel(ro, rd, vec3f(ox - 0.31 * sw + sway, y, FZ), vec3f(0.05, hy, 0.06), tlim, br, false);
                panel(ro, rd, vec3f(ox + 0.31 * sw + sway, y, FZ), vec3f(0.05, hy, 0.06), tlim, br, false);
            }
        } else if (k == 16) {
            panel(ro, rd, vec3f(ox + sway, y, FZ), vec3f(0.06, hy, 0.06), tlim, br, false);
        } else {
            panel(ro, rd, vec3f(ox + sway * 1.5, y, FZ - 0.02), vec3f(0.12 * hw, hy, 0.13 * hw), tlim, br, k == 18);
        }
    }
    let dr = 0.05 * sin(t * 3.1 + ph * 6.0);
    let ay = 1.08 * hs;
    let xo = ox - side * 0.29 * sw;
    let xi = ox + side * 0.29 * sw + dr * side;
    panel(ro, rd, vec3f(xo, ay, FZ - 0.24), vec3f(0.045, 0.021, 0.24), tlim, 0.3, false);
    panel(ro, rd, vec3f(xi, ay + 0.03 * LK, FZ - 0.24), vec3f(0.045, 0.021, 0.24), tlim, 0.3, false);
    panel(ro, rd, vec3f(xi, ay + 0.03 * LK, FZ - 0.52), vec3f(0.035, 0.035, 0.035), tlim, 1.0, false);
}

fn figure(ro: vec3f, rd: vec3f, tlim: f32) {
    FE = vec3f(0.0);
    FA = 0.0;
    FT = 1e9;
    let bb = box_span(ro, rd, vec3f(-0.9, 0.0, FZ - 0.57), vec3f(0.9, 1.95, FZ + 0.2));
    if (bb.x > bb.y || bb.y <= 0.0 || bb.x >= tlim) { return; }
    // west: the cold one, on the downbeat
    PTINT = ICE;
    PWARM = vec3f(0.85, 0.95, 1.0);
    EYEC = ICE * 1.4;
    figure_one(ro, rd, tlim, FXA, 1.0, 0.0, 1.0, 1.0, 1.0);
    // east: the warm one, answering on the offbeat
    PTINT = WARM * 0.9;
    PWARM = vec3f(1.0, 0.68, 0.32);
    EYEC = AMBER;
    figure_one(ro, rd, tlim, FXB, -1.0, 0.5, 0.95, 0.92, 0.86);
}

// the lattice the rooms snap into: glowing lines with a scan sweeping up each beat
fn lattice(ro: vec3f, rd: vec3f, tlim: f32) -> vec3f {
    if (abs(rd.z) < 1e-4) { return vec3f(0.0); }
    let t = (GZ - 0.24 - ro.z) / rd.z;
    if (t <= 0.0 || t > tlim) { return vec3f(0.0); }
    let p = ro + rd * t;
    let g = (p.xy - vec2f(GX0, GY0)) / CS;
    if (any(g < vec2f(-0.08)) || any(g > vec2f(6.08))) { return vec3f(0.0); }
    let f = abs(fract(g + 0.5) - 0.5) * CS;
    let d = min(f.x, f.y);
    let w = 0.003 + 0.0012 * t;
    let ln = exp(-d * d / (w * w)) + 0.2 * exp(-d / (w * 5.0));
    let sd = g.y - fract(BT) * 7.0;
    let scan = exp(-sd * sd * 1.2);
    var c = BLUE * ln * (0.25 + 1.3 * KICK + 0.9 * scan);
    let nd = length(f);
    c += ICE * exp(-nd * nd / (w * w * 6.0)) * (0.8 + 2.5 * KICK);
    return c;
}

fn halo(ro: vec3f, rd: vec3f, t: f32, P: vec3f, col: vec3f) -> vec3f {
    let v = P - ro;
    let tc = dot(v, rd);
    let h2 = max(dot(v, v) - tc * tc, 1e-4);
    let h = sqrt(h2);
    let a = (atan((t - tc) / h) - atan(-tc / h)) / h;
    return col * a;
}

fn sparks(ro: vec3f, rd: vec3f, tend: f32) -> vec3f {
    var c = vec3f(0.0);
    let n = select(10, 20, quality() > 0.5);
    let t = time();
    for (var i = 0; i < 20; i = i + 1) {
        if (i >= n) { break; }
        let h = hash33(vec3f(f32(i), 3.3, 9.1));
        let life = fract(t * (0.45 + 0.5 * h.z) + h.x);
        let dir = (vec2f(h.y, fract(h.y * 7.7 + h.z)) - 0.5) * 1.1;
        let pos = vec3f(SPAWN.x + dir.x * life, 1.1 + life * (1.5 + h.z) - life * life * 0.5, SPAWN.z + dir.y * life);
        let v = pos - ro;
        let tp = dot(v, rd);
        if (tp > 0.05 && tp < tend) {
            let dd = length(v - rd * tp);
            let sz = 0.004 + 0.0012 * tp;
            let fade = (1.0 - life) * (1.0 - life);
            c += mix(vec3f(1.0, 0.85, 0.55), AMBER, life) * exp(-dd * dd / (sz * sz)) * fade * 3.0;
        }
    }
    // the weld flash where each new room is born
    let v = LP[5] - ro;
    let tp = dot(v, rd);
    if (tp > 0.05 && tp < tend) {
        let dd = length(v - rd * tp);
        c += vec3f(1.0, 0.8, 0.5) * (SPK * 1.5 + 0.2 * KICK) * (exp(-dd * dd * 900.0) * 2.0 + exp(-dd * dd * 40.0) * 0.3);
    }
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    setup();
    var tB = 1e9;
    var col = vec3f(0.0);
    let th = horizon_t(tmax);
    let pe = ro + rd * th;
    if (abs(pe.x) < 6.05 && abs(pe.z) < 6.05 && pe.y > -0.05 && pe.y < 4.55) {
        tB = th;
        if (pe.y < 0.03) { col = floor_col(pe, rd); } else { col = wall_col(pe, rd); }
    }
    // drafting board, tilted up toward the lattice
    {
        let lro = to_local(ro - BC);
        let lrd = to_local(rd);
        let t = hit_box(lro, lrd, vec3f(0.0), BH, tmin, tB);
        if (t > 0.0) {
            let lp = lro + lrd * t;
            let nl = box_n(lp / BH);
            col = board_col(lp, nl, ro + rd * t, to_world(nl), rd);
            tB = t;
        }
    }
    for (var i = 0; i < 4; i = i + 1) {
        let sx = select(-1.0, 1.0, (i & 1) == 1);
        let north = i >= 2;
        let hy = select(0.445, 0.555, north);
        let c = vec3f(0.66 * sx, hy, select(0.34, -0.34, north));
        let h = vec3f(0.03, hy, 0.03);
        let t = hit_box(ro, rd, c, h, tmin, tB);
        if (t > 0.0) { let P = ro + rd * t; col = metal_col(P, box_n((P - c) / h), rd); tB = t; }
    }
    {
        let c = vec3f(0.0, 0.25, 0.0);
        let h = vec3f(0.66, 0.02, 0.02);
        let t = hit_box(ro, rd, c, h, tmin, tB);
        if (t > 0.0) { let P = ro + rd * t; col = metal_col(P, box_n((P - c) / h), rd); tB = t; }
    }
    // amp stacks
    {
        let c = vec3f(4.5, 0.9, 2.3);
        let h = vec3f(0.45, 0.9, 0.75);
        let t = hit_box(ro, rd, c, h, tmin, tB);
        if (t > 0.0) { let P = ro + rd * t; col = amp_col(P, box_n((P - c) / h), rd, c, h, true); tB = t; }
    }
    {
        let c = vec3f(4.5, 0.65, -2.3);
        let h = vec3f(0.45, 0.65, 0.7);
        let t = hit_box(ro, rd, c, h, tmin, tB);
        if (t > 0.0) { let P = ro + rd * t; col = amp_col(P, box_n((P - c) / h), rd, c, h, false); tB = t; }
    }
    // monitors on stands
    for (var i = 0; i < 2; i = i + 1) {
        let zc = select(2.2, -2.2, i == 1);
        let c = vec3f(-4.6, 1.55, zc);
        let h = vec3f(0.05, 0.38, 0.62);
        var t = hit_box(ro, rd, c, h, tmin, tB);
        if (t > 0.0) { let P = ro + rd * t; col = mon_col(P, box_n((P - c) / h), rd, c, h, i); tB = t; }
        let pc = vec3f(-4.65, 0.59, zc);
        let ph = vec3f(0.035, 0.59, 0.035);
        t = hit_box(ro, rd, pc, ph, tmin, tB);
        if (t > 0.0) { let P = ro + rd * t; col = metal_col(P, box_n((P - pc) / ph), rd); tB = t; }
        let bc = vec3f(-4.65, 0.02, zc);
        let bh = vec3f(0.25, 0.02, 0.25);
        t = hit_box(ro, rd, bc, bh, tmin, tB);
        if (t > 0.0) { let P = ro + rd * t; col = metal_col(P, box_n((P - bc) / bh), rd); tB = t; }
    }
    // placed rooms in the lattice: walk the cells the ray crosses
    {
        let s0 = vec3f(GX0, GY0, GZ - 0.25);
        let s1 = vec3f(GX0 + 6.0 * CS, GY0 + 6.0 * CS, GZ + 0.25);
        let sp = box_span(ro, rd, s0, s1);
        let shrink = 1.0 - smoothstep(42.0, 43.9, CYC);
        if (sp.x <= sp.y && sp.y > tmin && sp.x < tB && shrink > 0.01) {
            var t = max(sp.x, tmin) + 1e-4;
            for (var i = 0; i < 10; i = i + 1) {
                if (t > sp.y || t > tB) { break; }
                let p = ro + rd * t;
                let cl = clamp(floor((p.xy - s0.xy) / CS), vec2f(0.0), vec2f(5.0));
                let cmin = vec3f(s0.xy + cl * CS, s0.z);
                let cmax = vec3f(cmin.xy + vec2f(CS), s1.z);
                let idx = cl.y * 6.0 + cl.x;
                if (idx < NF) {
                    let age = max(CYC - (idx + 1.0), 0.0);
                    var fl = exp(-age * 2.2);
                    if (CYC >= 36.0) { fl = max(fl, KICK * (0.5 + 0.5 * sin(cl.x + cl.y - BT * 1.7))); }
                    let h = CH * (1.0 + 0.2 * exp(-age * 5.0)) * shrink;
                    let cc = vec3f(cmin.xy + vec2f(CS * 0.5), GZ);
                    let cs = box_span(ro, rd, cc - vec3f(h), cc + vec3f(h));
                    if (cs.x <= cs.y && cs.x > tmin && cs.x < tB) {
                        let lp = ro + rd * cs.x - cc;
                        let nl = box_n(lp / h);
                        col = cube_col(lp, h, nl, nl, ro + rd * cs.x, rd, fl);
                        tB = cs.x;
                        break;
                    }
                }
                let ce = box_span(ro, rd, cmin, cmax);
                t = ce.y + 1e-3;
            }
        }
    }
    // the room being made: born in sparks between their hands, then thrown spinning into its slot
    if (MOVING && MSC > 0.02) {
        let h = CH * MSC;
        let lro = rotl(ro - MC, MROT);
        let lrd = rotl(rd, MROT);
        let sp = box_span(lro, lrd, vec3f(-h), vec3f(h));
        if (sp.x <= sp.y && sp.x > tmin && sp.x < tB) {
            let lp = lro + lrd * sp.x;
            let nl = box_n(lp / h);
            col = cube_col(lp, h, nl, rotl_inv(nl, MROT), ro + rd * sp.x, rd, 0.35 + 0.65 * SPK);
            tB = sp.x;
        }
    }
    let opaque = tB < 1e8;
    figure(ro, rd, tB);
    var c = col;
    if (opaque) { c = mix(c, HAZE, 1.0 - exp(-tB * 0.04)); }
    c += lattice(ro, rd, tB);
    c = c * (1.0 - FA) + FE;
    let tg = min(tB, 20.0);
    c += halo(ro, rd, tg, LP[0], LC[0] * 0.01);
    c += halo(ro, rd, tg, LP[1], LC[1] * 0.01);
    c += halo(ro, rd, tg, LP[2], LC[2] * 0.008);
    c += halo(ro, rd, tg, LP[3], LC[3] * 0.008);
    c += halo(ro, rd, tg, LP[4], LC[4] * 0.012);
    if (quality() > 0.3) { c += sparks(ro, rd, tg); }
    var tout = tB;
    if (!opaque) {
        if (FT > 1e8) { return no_hit(); }
        tout = FT;
    }
    return Hit(tm(c * 1.2, rd), clamp(tout, tmin, tmax));
}

shaders.0566494a81bb3108b39d68ac47ce:
// Bird Bicycles Over the Canopy: a plank deck afloat on the treetops, a river looping through the air,
// three birds pedalling bicycles through slanting shafts of evening sun.

var<private> T: f32;
var<private> MAT: i32;
// The bike being marched (no arrays: dynamically indexed private arrays spill on phone GPUs): position +
// heading, (cos, sin) of the heading,
var<private> BPc: vec4f;
var<private> BFc: vec2f;
// and its moving parts this frame: wheel spins (cos, sin), crank, bob, wing flap.
var<private> BW1: vec2f;
var<private> BW2: vec2f;
var<private> CV: vec3f;
var<private> BOB: f32;
var<private> FLR: mat2x2f;

fn bike_pos(i: i32) -> vec4f {
    let a = T * 0.22 + f32(i) * TAU / 3.0;
    let h = 1.35 + 0.15 * sin(T * 0.9 + f32(i) * 2.1);
    return vec4f(cos(a) * 1.9, h, sin(a) * 1.9, a);
}
fn set_bike(i: i32) {
    BPc = bike_pos(i);
    BFc = vec2f(cos(BPc.w), sin(BPc.w));
    let fi = f32(i);
    let spin = T * 2.4 + fi;
    BW1 = vec2f(cos(spin), sin(spin));
    BW2 = vec2f(cos(spin + 1.0), sin(spin + 1.0));
    let c = crank(i);
    CV = vec3f(cos(c), sin(c), 0.0) * 0.15;
    BOB = 0.02 * sin(c * 2.0);
    FLR = rot2(0.25 + 0.65 * sin(T * 7.0 + fi * 1.7));
}
fn beam(i: i32) -> vec4f {
    if (i == 0) { return vec4f(-0.6, 0.0, 0.9, 0.6); }
    if (i == 1) { return vec4f(-2.9, 0.0, 2.6, 0.42); }
    return vec4f(2.9, 0.0, -0.6, 0.5);
}

fn sun_dir() -> vec3f { return normalize(vec3f(-0.5, 0.75, -0.42)); }
fn crank(i: i32) -> f32 { return -(T * 3.0 + f32(i) * 2.0); }
fn beam_k(i: i32) -> f32 { return 0.75 + 0.25 * sin(T * 0.7 + f32(i) * 2.3); }

// fbm3, stopping once the octaves left can no longer bring it to 0.42 (no cloud) or once it reaches 0.72
// (full cloud, where its colour no longer depends on it either). Same sum as fbm3 wherever it matters.
fn cloud_fbm(p: vec3f) -> f32 {
    var v = 0.0;
    var a = 0.5;
    var q = p;
    for (var i = 0; i < 5; i = i + 1) {
        v += a * noise3(q);
        q = q * 2.03 + vec3f(1.7, 9.2, 3.1);
        a *= 0.5;
        if (v + 2.0 * a < 0.42 || v >= 0.72) { break; }
    }
    return v;
}

fn sky(rd: vec3f) -> vec3f {
    let s = max(dot(rd, sun_dir()), 0.0);
    let y = max(rd.y, 0.0);
    var c = mix(vec3f(1.0, 0.66, 0.36), vec3f(0.05, 0.14, 0.46), pow(y, 0.45));
    c += vec3f(1.0, 0.7, 0.35) * (pow(s, 6.0) * 0.45 + pow(s, 400.0) * 3.0);
    if (rd.y > 0.0) {
        let p = rd.xz / (rd.y + 0.12);
        let cl = cloud_fbm(vec3f(p * 0.6 + vec2f(T * 0.03, T * 0.012), T * 0.02));
        let cov = smoothstep(0.42, 0.72, cl) * smoothstep(0.0, 0.1, rd.y);
        let lit = mix(vec3f(0.5, 0.4, 0.55), vec3f(1.2, 0.82, 0.55), clamp(s * s * 0.8 + 0.4 * smoothstep(0.7, 0.45, cl), 0.0, 1.0));
        c = mix(c, lit, cov * 0.85);
    }
    return c;
}

fn pool(P: vec3f) -> f32 {
    let s = sun_dir();
    var a = 0.0;
    for (var i = 0; i < 3; i = i + 1) {
        let b = beam(i);
        let dd = length(cross(P - b.xyz, s));
        a += smoothstep(b.w, b.w * 0.5, dd) * beam_k(i);
    }
    if (a <= 0.0) { return 0.0; }
    let g = P - s * (P.y / s.y);
    let dap = noise3(vec3f(g.xz * 2.2 + vec2f(sin(T * 0.4) * 0.25, 0.0), T * 0.25));
    return a * (0.45 + 0.75 * dap);
}

fn shafts(ro: vec3f, rd: vec3f, tend: f32) -> vec3f {
    let s = sun_dir();
    let b = dot(rd, s);
    let den = max(1.0 - b * b, 0.03);
    var g = 0.0;
    for (var i = 0; i < 3; i = i + 1) {
        let B = beam(i);
        let w0 = ro - B.xyz;
        let sc = clamp((b * dot(s, w0) - dot(rd, w0)) / den, 0.0, tend);
        let p = ro + rd * sc;
        let dd = length(cross(p - B.xyz, s));
        let fade = smoothstep(0.0, 0.7, p.y) * smoothstep(10.0, 4.0, p.y);
        let gw = exp(-dd * dd / (B.w * B.w)) * fade * beam_k(i) * min(inverseSqrt(den), 2.5);
        // where a shaft is this faint its dust's noise changes the colour by under half an 8-bit step: use its mean
        if (gw < 0.02) { g += gw; continue; }
        let dust = 0.75 + 0.5 * noise3(vec3f(p.x * 2.0, p.y * 2.0 - T * 0.3, p.z * 2.0));
        g += gw * dust;
    }
    return vec3f(1.0, 0.68, 0.32) * g * 0.3;
}

fn on_deck(xz: vec2f) -> bool {
    let a = abs(xz);
    if (a.x > 6.0 || a.y > 6.0) { return false; }
    return dot(xz, xz) < 18.49 || a.x < 0.95 || a.y < 0.95;
}

fn deck_light(P: vec3f) -> vec3f {
    let L = sun_dir();
    var sh = 1.0;
    for (var i = 0; i < 3; i = i + 1) {
        let b = bike_pos(i);
        let Q = P + L * ((b.y + 0.35 - P.y) / L.y);
        let d = length(Q.xz - b.xz);
        sh *= 1.0 - 0.6 * exp(-d * d * 3.0);
    }
    let pl = pool(P);
    return vec3f(0.3, 0.35, 0.46) + vec3f(1.0, 0.72, 0.42) * (0.3 + pl * 2.6) * sh;
}

fn deck_col(P: vec3f) -> vec3f {
    let pw = 0.22;
    let row = floor(P.z / pw);
    let along = P.x + hash12(vec2f(row, 3.0)) * 4.0;
    let seg = floor(along / 1.8);
    let jz = abs(fract(P.z / pw) - 0.5);
    let jx = abs(fract(along / 1.8) - 0.5);
    var c = vec3f(0.5, 0.31, 0.17) * (0.7 + 0.5 * hash12(vec2f(row, seg)));
    c *= 0.8 + 0.35 * noise3(vec3f(P.x * 0.9, P.z * 18.0, row * 0.37));
    c *= mix(0.35, 1.0, smoothstep(0.5, 0.45, jz));
    c *= mix(0.45, 1.0, smoothstep(0.5, 0.49, jx));
    let a = abs(P.xz);
    let r = length(P.xz);
    let trim = (r > 4.08 && a.x > 0.95 && a.y > 0.95) || (a.x > 0.8 && a.y > 4.08) || (a.y > 0.8 && a.x > 4.08);
    if (trim) { c = vec3f(0.28, 0.16, 0.08) * (0.8 + 0.3 * hash12(floor(P.xz * 4.0))); }
    return c * deck_light(P);
}

fn water(P: vec3f, rd: vec3f, n: vec3f, edge: f32, streak: f32) -> vec3f {
    let r = reflect(rd, n);
    let fres = 0.35 + 0.65 * pow(1.0 - max(dot(-rd, n), 0.0), 4.0);
    let body = mix(vec3f(0.03, 0.2, 0.3), vec3f(0.12, 0.5, 0.55), streak);
    var c = mix(body, sky(vec3f(r.x, abs(r.y), r.z)) * 1.1, fres);
    c += vec3f(1.0, 0.8, 0.5) * pow(max(dot(r, sun_dir()), 0.0), 90.0) * 2.5;
    c += vec3f(0.85, 0.95, 1.0) * smoothstep(0.2, 0.0, edge) * (0.4 + 0.6 * streak);
    c += vec3f(1.0, 0.7, 0.35) * pool(P) * 0.6;
    return c;
}

// fbm3, stopping once the octaves left can no longer lift it to 0.3 or once it reaches 0.8: canopy() only
// reads it through smoothsteps that are flat beyond those.
fn canopy_fbm(p: vec3f) -> f32 {
    var v = 0.0;
    var a = 0.5;
    var q = p;
    for (var i = 0; i < 5; i = i + 1) {
        v += a * noise3(q);
        q = q * 2.03 + vec3f(1.7, 9.2, 3.1);
        a *= 0.5;
        if (v + 2.0 * a < 0.3 || v >= 0.8) { break; }
    }
    return v;
}

fn canopy(P: vec3f, t: f32) -> vec3f {
    let f = canopy_fbm(vec3f(P.xz * 0.22, T * 0.03));
    let fine = noise3(vec3f(P.xz * 1.4, T * 0.15));
    var c = mix(vec3f(0.02, 0.07, 0.03), vec3f(0.15, 0.32, 0.09), smoothstep(0.3, 0.7, f));
    c *= 0.55 + 0.7 * fine;
    c += vec3f(0.55, 0.38, 0.08) * smoothstep(0.58, 0.8, f) * 0.45;
    let L = sun_dir();
    let g = P + L * (-P.y / L.y);
    if (on_deck(g.xz)) { c *= 0.5; }
    return mix(c, vec3f(1.0, 0.66, 0.36) * 0.9, 1.0 - exp(-t * 0.02));
}

fn crown(P: vec3f, c: vec3f) -> vec3f {
    let n = normalize(P - c);
    let f = noise3(P * 2.5 + vec3f(0.0, T * 0.2, 0.0)) * 0.6 + noise3(P * 6.0) * 0.4;
    let dif = max(dot(n, sun_dir()), 0.0);
    var col = mix(vec3f(0.03, 0.1, 0.03), vec3f(0.2, 0.42, 0.1), f);
    col *= 0.35 + 1.1 * dif * smoothstep(0.3, 0.6, f);
    col += vec3f(0.6, 0.4, 0.1) * pow(dif, 3.0) * smoothstep(0.55, 0.8, f) * 0.6;
    return col;
}

fn sph(ro: vec3f, rd: vec3f, c: vec3f, r: f32) -> f32 {
    let oc = ro - c;
    let b = dot(oc, rd);
    let h = b * b - (dot(oc, oc) - r * r);
    if (h < 0.0) { return -1.0; }
    return -b - sqrt(h);
}

fn low_z(x: f32) -> f32 { return 2.5 * sin(x * 0.08) - 1.0 + 1.2 * sin(x * 0.21); }

// ---- bicycles and birds ----
fn cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn ellip(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = max(length(p / (r * r)), 1e-4);
    return k0 * (k0 - 1.0) / k1;
}
fn local_q(p: vec3f) -> vec3f {
    let d0 = p - BPc.xyz;
    let cs = BFc;
    return vec3f(-cs.y * d0.x + cs.x * d0.z, d0.y, cs.x * d0.x + cs.y * d0.z);
}
// Spokes: 6 at 60 degrees are 3 lines through the hub, so the distance to the nearest spoke is the least
// distance to those lines (what r * sin(fa) measured with atan2). cs = (cos, sin) of the wheel's spin.
fn wheel(q: vec3f, cs: vec2f) -> vec2f {
    let r = length(q.xy);
    let tire = length(vec2f(r - 0.32, q.z)) - 0.032;
    let u0 = vec2f(cs.x, -cs.y);
    let u1 = vec2f(u0.x * 0.5 - u0.y * 0.8660254, u0.x * 0.8660254 + u0.y * 0.5);
    let u2 = vec2f(u0.x * -0.5 - u0.y * 0.8660254, u0.x * 0.8660254 - u0.y * 0.5);
    let ds = min(abs(u0.x * q.y - u0.y * q.x), min(abs(u1.x * q.y - u1.y * q.x), abs(u2.x * q.y - u2.y * q.x)));
    let spoke = max(length(vec2f(ds, q.z)) - 0.011, r - 0.31);
    let hub = length(q) - 0.045;
    let s = min(spoke, hub);
    return select(vec2f(s, 0.0), vec2f(tire, 1.0), tire < s);
}

// The bike in three groups, each inside its own box in the bike's frame (checked against every part's extent):
// the wheels; the frame, cranks, pedals, saddle and legs; the bird and its beak.
const WB0 = vec3f(-0.87, -0.37, -0.05);
const WB1 = vec3f(0.87, 0.37, 0.05);
const FB0 = vec3f(-0.54, -0.215, -0.24);
const FB1 = vec3f(0.54, 0.665, 0.24);
const BB0 = vec3f(-0.62, 0.38, -0.66);
const BB1 = vec3f(0.45, 1.2, 0.66);

fn g_wheels(q: vec3f) -> vec2f {
    var w = wheel(q - vec3f(-0.5, 0.0, 0.0), BW1);
    let w2 = wheel(q - vec3f(0.5, 0.0, 0.0), BW2);
    if (w2.x < w.x) { w = w2; }
    return w;
}

// (frame tubes, cranks + pedals + saddle, legs)
fn g_frame(q: vec3f) -> vec3f {
    let bob = BOB;
    let BB = vec3f(0.0, -0.02, 0.0);
    let RH = vec3f(-0.5, 0.0, 0.0);
    let FH = vec3f(0.5, 0.0, 0.0);
    let S = vec3f(-0.16, 0.46, 0.0);
    let HT = vec3f(0.37, 0.48, 0.0);
    var f = cap(q, BB, S, 0.022);
    f = min(f, cap(q, S, HT, 0.02));
    f = min(f, cap(q, BB, vec3f(0.36, 0.41, 0.0), 0.024));
    f = min(f, cap(q, RH, BB, 0.016));
    f = min(f, cap(q, RH, vec3f(-0.16, 0.42, 0.0), 0.016));
    f = min(f, cap(q, FH, vec3f(0.37, 0.52, 0.0), 0.018));
    f = min(f, cap(q, vec3f(0.37, 0.52, 0.0), vec3f(0.33, 0.62, 0.0), 0.018));
    f = min(f, cap(q, vec3f(0.31, 0.62, -0.2), vec3f(0.31, 0.62, 0.2), 0.016));
    let cv = CV;
    let P1 = BB + cv + vec3f(0.0, 0.0, 0.1);
    let P2 = BB - cv - vec3f(0.0, 0.0, 0.1);
    var k = min(cap(q, BB + vec3f(0.0, 0.0, 0.07), P1, 0.012), cap(q, BB - vec3f(0.0, 0.0, 0.07), P2, 0.012));
    k = min(k, sd_box(q - P1 - vec3f(0.0, 0.0, 0.04), vec3f(0.05, 0.012, 0.04)));
    k = min(k, sd_box(q - P2 + vec3f(0.0, 0.0, 0.04), vec3f(0.05, 0.012, 0.04)));
    k = min(k, ellip(q - S - vec3f(0.0, 0.03, 0.0), vec3f(0.11, 0.025, 0.055)));
    let H1 = vec3f(-0.03, 0.6 + bob, 0.08);
    let H2 = vec3f(-0.03, 0.6 + bob, -0.08);
    let K1 = (H1 + P1) * 0.5 + vec3f(0.12, 0.05, 0.0);
    let K2 = (H2 + P2) * 0.5 + vec3f(0.12, 0.05, 0.0);
    let legs = min(min(cap(q, H1, K1, 0.018), cap(q, K1, P1 + vec3f(0.0, 0.02, 0.0), 0.015)),
                   min(cap(q, H2, K2, 0.018), cap(q, K2, P2 + vec3f(0.0, 0.02, 0.0), 0.015)));
    return vec3f(f, k, legs);
}

// (body or wings, its material, beak)
fn g_bird(q: vec3f) -> vec3f {
    let bq = q - vec3f(0.0, BOB, 0.0);
    var bd = ellip(bq - vec3f(-0.1, 0.74, 0.0), vec3f(0.24, 0.2, 0.17));
    bd = smin(bd, length(bq - vec3f(0.1, 0.98, 0.0)) - 0.12, 0.07);
    var bm = 3.0;
    let wq = vec3f(bq.x + 0.1, bq.y - 0.84, abs(bq.z) - 0.13);
    let wr = FLR * vec2f(wq.z, wq.y);
    let wing = ellip(vec3f(wq.x + 0.04, wr.y, wr.x - 0.2), vec3f(0.17, 0.03, 0.24));
    let tail = cap(bq, vec3f(-0.3, 0.72, 0.0), vec3f(-0.5, 0.84, 0.0), 0.04);
    let wt = min(wing, tail);
    if (wt < bd) { bd = wt; bm = 4.0; }
    let beak = cap(bq, vec3f(0.18, 0.97, 0.0), vec3f(0.31, 0.94, 0.0), 0.028);
    return vec3f(bd, bm, beak);
}

// The nearest part and its material (MAT), with the parts compared in the original order.
fn combine(w: vec2f, fr: vec3f, bi: vec3f) -> f32 {
    var d = 1e5;
    var m = 0;
    if (w.x < d) { d = w.x; m = i32(w.y); }
    if (fr.x < d) { d = fr.x; m = 2; }
    if (fr.y < d) { d = fr.y; m = 1; }
    if (bi.x < d) { d = bi.x; m = i32(bi.y); }
    let o = min(bi.z, fr.z);
    if (o < d) { d = o; m = 5; }
    MAT = m;
    return d;
}

// The whole bike near a point: a group's box distance stands in for it while it is more than `near` away.
// Normals tap 1.2 mm from a hit (near 0.01) and AO 8 cm out (near 0.08, the distance it saturates at), so both
// see exactly what the full bike gives.
fn bike(p: vec3f, near: f32) -> f32 {
    let q = local_q(p);
    let wb = sd_box(q - (WB0 + WB1) * 0.5, (WB1 - WB0) * 0.5);
    let fb = sd_box(q - (FB0 + FB1) * 0.5, (FB1 - FB0) * 0.5);
    let bb = sd_box(q - (BB0 + BB1) * 0.5, (BB1 - BB0) * 0.5);
    var w = vec2f(wb, 0.0);
    if (wb <= near) { w = g_wheels(q); }
    var fr = vec3f(fb);
    if (fb <= near) { fr = g_frame(q); }
    var bi = vec3f(bb, 3.0, bb);
    if (bb <= near) { bi = g_bird(q); }
    return combine(w, fr, bi);
}



// The same four tetrahedral taps as before, in a loop so the bike's distance code is compiled once here, not four times.
fn calc_normal(p: vec3f) -> vec3f {
    var n = vec3f(0.0);
    for (var i = 0; i < 4; i = i + 1) {
        let k = 2.0 * vec3f(f32(((i + 3) >> 1) & 1), f32((i >> 1) & 1), f32(i & 1)) - 1.0;
        n += k * bike(p + k * 0.0012, 0.01);
    }
    return normalize(n);
}

fn frame_col(i: i32) -> vec3f {
    if (i == 0) { return vec3f(0.92, 0.3, 0.24); }
    if (i == 1) { return vec3f(0.12, 0.68, 0.62); }
    return vec3f(0.68, 0.48, 0.92);
}
fn bird_col(i: i32, breast: bool) -> vec3f {
    if (i == 0) { return select(vec3f(0.16, 0.36, 0.9), vec3f(0.92, 0.92, 0.95), breast); }
    if (i == 1) { return select(vec3f(0.98, 0.76, 0.12), vec3f(1.0, 0.92, 0.6), breast); }
    return select(vec3f(0.42, 0.3, 0.22), vec3f(0.95, 0.42, 0.14), breast);
}
fn bike_col(P: vec3f, m: i32, i: i32) -> vec3f {
    if (m == 0) { return vec3f(0.8, 0.8, 0.84); }
    if (m == 1) { return vec3f(0.05, 0.045, 0.05); }
    if (m == 2) { return frame_col(i); }
    if (m == 5) { return vec3f(1.0, 0.55, 0.1); }
    if (m == 4) { return bird_col(i, false) * 0.7; }
    let q = local_q(P);
    let bob = 0.02 * sin(crank(i) * 2.0);
    let e = vec3f(q.x, q.y - bob, abs(q.z)) - vec3f(0.17, 1.02, 0.085);
    if (length(e) < 0.03) { return select(vec3f(0.02), vec3f(1.0), length(e - vec3f(0.01, 0.01, 0.0)) < 0.009); }
    let breast = q.x > -0.02 && q.y - bob < 0.86;
    return bird_col(i, breast);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    T = time();
    let L = sun_dir();
    let haze = vec3f(1.0, 0.66, 0.36) * 0.9;
    var bt = 1e9;
    var bc = vec3f(0.0);
    if (rd.y < 0.0) {
        let t0 = -ro.y / rd.y;
        let p0 = ro + rd * t0;
        let t1 = (-0.22 - ro.y) / rd.y;
        let p1 = ro + rd * t1;
        let t2 = (-0.35 - ro.y) / rd.y;
        let p2 = ro + rd * t2;
        let r2 = length(p2.xz);
        let t3 = (-0.52 - ro.y) / rd.y;
        let r3 = length((ro + rd * t3).xz);
        let t4 = (-2.2 - ro.y) / rd.y;
        let p4 = ro + rd * t4;
        let v4 = p4.z - low_z(p4.x);
        let t5 = (-2.4 - ro.y) / rd.y;
        let p5 = ro + rd * t5;
        let v5 = p5.z - low_z(p5.x);
        if (on_deck(p0.xz)) {
            bt = t0; bc = deck_col(p0);
        } else if (on_deck(p1.xz)) {
            bt = t1; bc = vec3f(0.2, 0.12, 0.06) * vec3f(0.6, 0.55, 0.56);
        } else if (r2 > 4.75 && r2 < 5.9) {
            let th = atan2(p2.z, p2.x);
            let du = cos(th * 14.0 - T * 2.2 + sin(r2 * 3.0)) * 0.6 + cos(th * 25.0 - T * 3.1 + r2 * 1.7) * 0.35;
            let dv = cos(r2 * 5.0 + th * 3.0 + T * 1.3) * 0.4;
            let tg = vec3f(-sin(th), 0.0, cos(th));
            let rg = vec3f(cos(th), 0.0, sin(th));
            let n = normalize(vec3f(0.0, 1.0, 0.0) + tg * du * 0.14 + rg * dv * 0.1);
            let q = rot2(-T * 0.16) * p2.xz;
            let streak = noise3(vec3f(q * 1.6, T * 0.15));
            bt = t2; bc = water(p2, rd, n, min(r2 - 4.75, 5.9 - r2), streak);
        } else if (r3 > 4.75 && r3 < 5.9) {
            bt = t3; bc = vec3f(0.12, 0.5, 0.6) * 0.9 + vec3f(0.5, 0.6, 0.6) * 0.2;
        } else if (abs(v4) < 1.8) {
            let du = cos(p4.x * 2.0 - T * 2.0 + sin(v4 * 2.0)) * 0.6 + cos(p4.x * 3.7 - T * 2.7 + v4 * 1.3) * 0.3;
            let dv = cos(v4 * 4.0 + p4.x * 0.7 + T) * 0.4;
            let n = normalize(vec3f(du * 0.12, 1.0, dv * 0.1));
            let streak = noise3(vec3f(p4.x * 0.5 - T * 0.8, v4 * 2.0, T * 0.2));
            let wc = water(p4, rd, n, 1.8 - abs(v4), streak);
            bt = t4; bc = mix(wc, haze, 1.0 - exp(-t4 * 0.02));
        } else if (abs(v5) < 1.8) {
            bt = t5; bc = mix(vec3f(0.1, 0.42, 0.5), haze, 1.0 - exp(-t5 * 0.02));
        } else {
            let t6 = min((-4.5 - ro.y) / rd.y, 400.0);
            bt = t6; bc = canopy(ro + rd * t6, t6);
        }
    }
    // treetops rising at the corners
    for (var k = 0; k < 4; k = k + 1) {
        let sx = select(-1.0, 1.0, (k & 1) == 1);
        let sz = select(-1.0, 1.0, (k & 2) == 2);
        let c = vec3f(sx * 5.6, -1.2 + 0.05 * sin(T * 0.6 + f32(k)), sz * 5.6);
        let ts = sph(ro, rd, c, 1.75);
        if (ts > 0.0 && ts < bt) { bt = ts; bc = crown(ro + rd * ts, c); }
    }
    // bicycles: each one fits in two boxes in its own frame (wheels and frame; the bird and its wings), and the
    // bikes are far enough apart that their spans along a ray never overlap: march them nearest first and stop
    // at the first hit
    var e = vec3f(1e9);
    var x = vec3f(-1e9);
    for (var i = 0; i < 3; i = i + 1) {
        let b = bike_pos(i);
        let cs = vec2f(cos(b.w), sin(b.w));
        let d0 = ro - b.xyz;
        let rol = vec3f(-cs.y * d0.x + cs.x * d0.z, d0.y, cs.x * d0.x + cs.y * d0.z);
        let rdl = vec3f(-cs.y * rd.x + cs.x * rd.z, rd.y, cs.x * rd.x + cs.y * rd.z);
        let s1 = box_span(rol, rdl, vec3f(-0.9, -0.4, -0.26), vec3f(0.9, 0.7, 0.26));
        let s2 = box_span(rol, rdl, vec3f(-0.62, 0.38, -0.66), vec3f(0.45, 1.2, 0.66));
        let h1 = s1.x < s1.y && s1.y > 0.0;
        let h2 = s2.x < s2.y && s2.y > 0.0;
        if (h1 || h2) {
            let en = min(select(1e9, s1.x, h1), select(1e9, s2.x, h2));
            let ex = max(select(-1e9, s1.y, h1), select(-1e9, s2.y, h2));
            if (i == 0) { e.x = en; x.x = ex; }
            if (i == 1) { e.y = en; x.y = ex; }
            if (i == 2) { e.z = en; x.z = ex; }
        }
    }
    let steps = i32(mix(28.0, 64.0, quality()));
    for (var k = 0; k < 3; k = k + 1) {
        // the k-th nearest bike along the ray
        var bi = 0;
        var te = e.x;
        var tx = x.x;
        if (e.y < te) { bi = 1; te = e.y; tx = x.y; }
        if (e.z < te) { bi = 2; te = e.z; tx = x.z; }
        if (te > 1e8) { break; }
        if (bi == 0) { e.x = 1e9; }
        if (bi == 1) { e.y = 1e9; }
        if (bi == 2) { e.z = 1e9; }
        let tend = min(tx, bt);
        var t = max(te, tmin);
        if (t >= tend) { continue; }
        set_bike(bi);
        // where the ray is inside each group's box: a group is only evaluated there, and until the ray reaches
        // a box, the distance to it along the ray is a safe step
        let rol = local_q(ro);
        let rdl = vec3f(-BFc.y * rd.x + BFc.x * rd.z, rd.y, BFc.x * rd.x + BFc.y * rd.z);
        let sw = box_span(rol, rdl, WB0, WB1);
        let sf = box_span(rol, rdl, FB0, FB1);
        let sb = box_span(rol, rdl, BB0, BB1);
        var hit = false;
        for (var i = 0; i < steps; i = i + 1) {
            let q = local_q(ro + rd * t);
            var w = vec2f(1e5, 0.0);
            var fr = vec3f(1e5);
            var bir = vec3f(1e5, 3.0, 1e5);
            var jump = 1e5;
            if (sw.x < sw.y) {
                if (t < sw.x) { jump = min(jump, sw.x - t); } else if (t <= sw.y) { w = g_wheels(q); }
            }
            if (sf.x < sf.y) {
                if (t < sf.x) { jump = min(jump, sf.x - t); } else if (t <= sf.y) { fr = g_frame(q); }
            }
            if (sb.x < sb.y) {
                if (t < sb.x) { jump = min(jump, sb.x - t); } else if (t <= sb.y) { bir = g_bird(q); }
            }
            let d = combine(w, fr, bir);
            if (d < 0.0008 * t + 0.0006) { hit = true; break; }
            t += min(d * 0.9, jump + 0.001);
            if (t > tend) { break; }
        }
        if (hit) {
            let P = ro + rd * t;
            let m = MAT;
            let n = calc_normal(P);
            let base = bike_col(P, m, bi);
            let dif = max(dot(n, L), 0.0);
            let pl = pool(P);
            let ao = clamp(bike(P + n * 0.08, 0.08) / 0.08, 0.35, 1.0);
            let amb = vec3f(0.3, 0.36, 0.5) * (0.65 + 0.35 * n.y) + vec3f(0.08, 0.14, 0.05) * max(-n.y, 0.0);
            let hv = normalize(L - rd);
            let shiny = select(0.15, 1.0, m == 0 || m == 2);
            let spec = pow(max(dot(n, hv), 0.0), 48.0) * shiny * (0.6 + pl * 2.0);
            let rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
            var c = base * (amb * ao + vec3f(1.0, 0.72, 0.42) * dif * (0.6 + pl * 2.0));
            c += vec3f(1.0, 0.85, 0.6) * spec + vec3f(1.0, 0.72, 0.4) * rim * 0.35 * ao;
            bt = t;
            bc = c;
            break;
        }
    }
    if (bt > 1e8) { bc = sky(rd); }
    let glow = shafts(ro, rd, min(bt, 40.0));
    let col = tone((bc + glow) * 1.2);
    let tout = max(min(bt, horizon_t(tmax)), tmin);
    return Hit(col, tout);
}

shaders.02fe19a229c36711b00763e65f74:
// The Fractal Garden, cell (2, 7). A shared stream runs through every room.
const GX: f32 = 2.0;
const GY: f32 = 7.0;
const RESPECT: bool = true;
const MAX_STEPS: f32 = 400.0;
const MAX_ITERS: f32 = 24.0;
const NB: i32 = 6;
const POWER: f32 = 8.0;
const HUE: f32 = 0.62;
const EXTRA: bool = true;
const HEDGE_H: f32 = 2.4;
const SS: i32 = 4;
const DOORS: i32 = 3; // bit per wall N,S,W,E (hedge order): 1 = leave a gap for the doorway
const CENTER: bool = true;
const NBT: i32 = 6 + select(0, 1, true);

fn wpos(p: vec3f) -> vec3f { return p + vec3f(GX * 12.0, 0.0, GY * 12.0); }

// stream centre line in world x as a function of world z; it crosses x = 24 (cell column 2 centre) at every door
fn stream_x(wz: f32) -> f32 {
    return GX * 12.0 + 1.9 * sin(wz * TAU / 12.0) + 0.5 * sin(wz * TAU / 6.0);
}

fn moon_dir() -> vec3f { return normalize(vec3f(-0.35, 0.42, -0.84)); }

fn sky(rd: vec3f) -> vec3f {
    let y = max(rd.y, 0.0);
    var col = mix(vec3f(0.32, 0.16, 0.38), vec3f(0.02, 0.03, 0.10), pow(y, 0.55));
    let m = max(dot(rd, moon_dir()), 0.0);
    col += vec3f(1.0, 0.92, 0.8) * (smoothstep(0.9993, 0.9996, m) * 3.0 + pow(m, 60.0) * 0.4);
    if (rd.y > 0.0) {
        let s = rd * 180.0;
        let h = hash13(floor(s));
        col += vec3f(0.9, 0.9, 1.0) * step(0.9975, h) * (0.6 + 0.4 * sin(time() * 3.0 + h * 90.0)) * y;
        let p = rd.xz / (rd.y + 0.15);
        let cl = fbm3(vec3f(p * 0.7 + vec2f(time() * 0.01, 0.0), 1.0));
        col += palette(cl + HUE, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67)) * smoothstep(0.55, 0.8, cl) * 0.18;
    }
    return col;
}

fn lvl() -> f32 { return select(1.0, quality(), RESPECT); }

// ---- mandelbulb blossom ----
fn bulb(p: vec3f, pw: f32, iters: i32) -> vec2f {
    var z = p;
    var dr = 1.0;
    var r = length(z);
    var trap = 1e9;
    for (var i = 0; i < iters; i = i + 1) {
        r = length(z);
        if (r > 2.0) { break; }
        let th = acos(clamp(z.y / max(r, 1e-6), -1.0, 1.0)) * pw;
        let ph = atan2(z.z, z.x) * pw;
        dr = pow(r, pw - 1.0) * pw * dr + 1.0;
        let zr = pow(r, pw);
        z = zr * vec3f(sin(th) * cos(ph), cos(th), sin(th) * sin(ph)) + p;
        trap = min(trap, dot(z, z));
    }
    r = max(length(z), 1e-6);
    return vec2f(0.5 * log(r) * r / dr, trap);
}

struct Bloom { c: vec3f, s: f32, pw: f32, spin: f32 };

fn bloom_of(i: i32) -> Bloom {
    let fi = f32(i);
    if (i >= NB) {
        // the great central blossom, floating over the stream on the door axis
        return Bloom(vec3f(0.0, 3.05 + 0.08 * sin(time() * 0.5), 0.0), 1.0, POWER + 0.8 * sin(time() * 0.17), time() * 0.1);
    }
    let h = hash12(vec2f(GX * 7.0 + fi * 3.1, GY * 11.0 + fi * 1.7));
    let side = select(-1.0, 1.0, (i % 2) == 0);
    let row = f32(i / 2);
    let nrow = f32((NB + 1) / 2);
    let z = select(0.0, mix(-3.4, 3.4, row / max(nrow - 1.0, 1.0)), nrow > 1.0) + (h - 0.5) * 0.8;
    let x = side * (3.4 + h * 0.6);
    let s = 0.62 + 0.25 * h;
    let y = 1.35 + 0.5 * h + 0.06 * sin(time() * 0.7 + fi);
    let pw = POWER + fi * 0.7 + 0.6 * sin(time() * 0.23 + fi * 1.3);
    return Bloom(vec3f(x, y, z), s, pw, time() * (0.15 + 0.1 * h) + fi);
}

fn bloom_de(p: vec3f, b: Bloom, iters: i32) -> vec2f {
    var q = (p - b.c) / b.s;
    let xz = rot2(b.spin) * q.xz;
    q = vec3f(xz.x, q.y, xz.y);
    let d = bulb(q, b.pw, iters);
    return vec2f(d.x * b.s, d.y);
}

fn bloom_normal(p: vec3f, b: Bloom, iters: i32) -> vec3f {
    let e = 0.0015;
    let k = vec2f(1.0, -1.0);
    return normalize(k.xyy * bloom_de(p + k.xyy * e, b, iters).x + k.yyx * bloom_de(p + k.yyx * e, b, iters).x +
                     k.yxy * bloom_de(p + k.yxy * e, b, iters).x + k.xxx * bloom_de(p + k.xxx * e, b, iters).x);
}

// ---- kaleidoscopic hedge pattern ----
fn kaleido(uv0: vec2f, n: i32) -> vec3f {
    var uv = uv0;
    var acc = 0.0;
    var sc = 1.0;
    for (var i = 0; i < n; i = i + 1) {
        uv = abs(uv) - vec2f(0.55, 0.35);
        uv = rot2(0.7 + 0.08 * sin(time() * 0.2) + HUE) * uv;
        uv *= 1.45;
        sc *= 1.45;
        acc += exp(-abs(length(uv) - 0.8) * 6.0) / f32(i + 1);
    }
    let leaf = palette(acc * 0.6 + HUE * 0.5 + 0.25, vec3f(0.12, 0.35, 0.18), vec3f(0.1, 0.3, 0.15),
                       vec3f(1.0, 1.0, 1.0), vec3f(0.3, 0.2, 0.25));
    let flower = palette(acc + HUE + time() * 0.03, vec3f(0.6), vec3f(0.4), vec3f(1.0), vec3f(0.0, 0.33, 0.67));
    return mix(leaf * (0.5 + acc * 0.35), flower * 1.4, smoothstep(1.5, 2.4, acc));
}

struct Cand { t: f32, col: vec3f };

fn stream_glow(wp: vec3f) -> f32 {
    let d = abs(wp.x - stream_x(wp.z));
    return exp(-max(d - 0.6, 0.0) * 1.2);
}

fn hedge(ro: vec3f, rd: vec3f, tmin: f32, cur: Cand) -> Cand {
    var best = cur;
    let w = 0.7;
    for (var j = 0; j < 8; j = j + 1) {
        let i = j / 2;
        var bmin = vec3f(-6.0, 0.0, -6.0);
        var bmax = vec3f(6.0, HEDGE_H, 6.0);
        if (i == 0) { bmax.z = -6.0 + w; }
        if (i == 1) { bmin.z = 6.0 - w; }
        if (i == 2) { bmax.x = -6.0 + w; }
        if (i == 3) { bmin.x = 6.0 - w; }
        // leave the doorway clear (1.8 m door plus a little margin)
        let gap = ((DOORS >> u32(i)) & 1) == 1;
        if (!gap && (j & 1) == 1) { continue; }
        if (gap) {
            if (i < 2) { if ((j & 1) == 0) { bmax.x = -1.0; } else { bmin.x = 1.0; } }
            else { if ((j & 1) == 0) { bmax.z = -1.0; } else { bmin.z = 1.0; } }
        }
        let sp = box_span(ro, rd, bmin, bmax);
        if (sp.x <= sp.y && sp.y > tmin && sp.x < best.t) {
            let t = max(sp.x, tmin);
            let p = ro + rd * t;
            let wp = wpos(p);
            var uv = select(vec2f(wp.x, p.y), vec2f(wp.z, p.y), i >= 2);
            if (abs(p.y - HEDGE_H) < 0.01) { uv = select(wp.xz, wp.zx, i >= 2); }
            let cell = fract(uv / 1.6) * 2.0 - 1.0;
            let nk = i32(mix(3.0, 7.0, lvl()));
            var c = kaleido(cell * 1.3, nk);
            let fuzz = noise3(wp * 14.0);
            c *= 0.75 + 0.5 * fuzz;
            c *= 0.55 + 0.45 * smoothstep(0.0, HEDGE_H, p.y);
            c += vec3f(0.1, 0.7, 0.8) * stream_glow(wp) * 0.25 * exp(-p.y);
            best = Cand(t, c);
        }
    }
    return best;
}

fn shade1(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let q = lvl();
    var best = Cand(tmax + 1.0, vec3f(0.0));

    // floor: lawn + glowing stream
    let tf = plane_y(ro, rd, 0.0);
    if (tf > tmin && tf < tmax + 0.05) {
        let p = ro + rd * tf;
        let wp = wpos(p);
        let sx = stream_x(wp.z);
        let d = abs(wp.x - sx);
        let flow = fbm3(vec3f(wp.x * 1.5, wp.z * 0.7 - time() * 1.4, time() * 0.2));
        let tile = abs(fract(wp.xz * 0.5) - 0.5);
        let grid = smoothstep(0.47, 0.5, max(tile.x, tile.y));
        var c = mix(vec3f(0.04, 0.09, 0.05), vec3f(0.07, 0.16, 0.08), noise3(wp * 3.0));
        c = mix(c, vec3f(0.25, 0.22, 0.3), grid * 0.4);
        let water = mix(vec3f(0.05, 0.5, 0.75), vec3f(0.6, 1.0, 0.95), flow);
        let wcol = water * (0.35 + 0.7 * pow(flow, 3.0)) + palette(wp.z * 0.05 - time() * 0.1 + HUE, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67)) * 0.3;
        c = mix(c, wcol, smoothstep(0.75, 0.55, d));
        c += vec3f(0.1, 0.6, 0.7) * exp(-max(d - 0.6, 0.0) * 1.5) * 0.35;
        // blossom pools of light
        for (var i = 0; i < NBT; i = i + 1) {
            let b = bloom_of(i);
            let dd = length(p.xz - b.c.xz);
            c += palette(f32(i) * 0.17 + HUE, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67)) * 0.07 / (1.0 + dd * dd * 1.5);
        }
        best = Cand(min(tf, tmax), c);
    }

    best = hedge(ro, rd, tmin, best);

    // stems
    for (var i = 0; i < NB; i = i + 1) {
        let b = bloom_of(i);
        let sp = box_span(ro, rd, vec3f(b.c.x - 0.035, 0.0, b.c.z - 0.035), vec3f(b.c.x + 0.035, b.c.y - b.s * 0.6, b.c.z + 0.035));
        if (sp.x <= sp.y && sp.y > tmin && sp.x < best.t) {
            let t = max(sp.x, tmin);
            let p = ro + rd * t;
            best = Cand(t, vec3f(0.08, 0.3, 0.12) * (0.5 + p.y * 0.3));
        }
    }

    // mandelbulb blossoms, each marched inside its bounding sphere
    let steps = i32(mix(select(MAX_STEPS, 20.0, RESPECT), MAX_STEPS, q));
    let iters = i32(mix(select(MAX_ITERS, 3.0, RESPECT), MAX_ITERS, q));
    for (var i = 0; i < NBT; i = i + 1) {
        let b = bloom_of(i);
        let rad = 1.2 * b.s;
        let oc = ro - b.c;
        let bb = dot(oc, rd);
        let cc = dot(oc, oc) - rad * rad;
        let disc = bb * bb - cc;
        if (disc < 0.0) { continue; }
        let sq = sqrt(disc);
        var t = max(-bb - sq, tmin);
        let t1 = min(-bb + sq, best.t);
        if (t > t1) { continue; }
        var glow = 0.0;
        var hit = false;
        var trap = 0.0;
        for (var s = 0; s < steps; s = s + 1) {
            let d = bloom_de(ro + rd * t, b, iters);
            glow += 0.012 / (0.02 + d.x * d.x * 40.0);
            if (d.x < 0.0008 * t) { hit = true; trap = d.y; break; }
            t += d.x * 0.9;
            if (t > t1) { break; }
        }
        let pal = palette(HUE + f32(i) * 0.17, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67));
        if (hit) {
            let p = ro + rd * t;
            let n = bloom_normal(p, b, iters);
            var c = palette(sqrt(trap) * 0.8 + HUE + f32(i) * 0.17 + time() * 0.02, vec3f(0.55), vec3f(0.45), vec3f(1.0, 1.0, 0.8), vec3f(0.0, 0.25, 0.5));
            let dif = max(dot(n, moon_dir()), 0.0);
            let down = max(-n.y, 0.0);
            var ao = 1.0;
            var sh = 1.0;
            if (EXTRA) {
                ao = 0.0;
                for (var k = 1; k <= 6; k = k + 1) {
                    let h = 0.02 * f32(k);
                    ao += (h - bloom_de(p + n * h, b, iters).x) / f32(k);
                }
                ao = clamp(1.0 - ao * 6.0, 0.2, 1.0);
                var st = 0.01;
                for (var k = 0; k < 32; k = k + 1) {
                    let d = bloom_de(p + moon_dir() * st, b, iters).x;
                    sh = min(sh, 12.0 * d / st);
                    st += max(d, 0.01);
                    if (sh < 0.02 || st > 2.0) { break; }
                }
                sh = clamp(sh, 0.15, 1.0);
            }
            let rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
            c = c * (0.18 + 0.8 * dif * sh) * ao + vec3f(0.1, 0.6, 0.7) * down * 0.4 + pal * rim * 0.9;
            best = Cand(t, c);
        } else if (glow > 0.02) {
            best.col += pal * min(glow, 1.5) * 0.25;
        }
    }

    if (best.t > tmax) {
        // above the hedges: open night sky
        if (rd.y > 0.0 || ro.y > HEDGE_H) {
            return Hit(tone(sky(rd) * 1.4), horizon_t(tmax));
        }
        return no_hit();
    }
    // a little mist toward the stream light
    let col = best.col * 1.6;
    return Hit(tone(col), best.t);
}

// supersampling: SS jittered rays per pixel (rooms that respect quality() drop to 1 when over budget)
fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let n = select(SS, 1, RESPECT && quality() < 0.99);
    var h = shade1(ro, rd, tmin, tmax);
    if (n <= 1) { return h; }
    var acc = h.color;
    for (var k = 1; k < n; k = k + 1) {
        let j = (hash33(rd * 917.0 + f32(k)) - 0.5) * 0.0012;
        acc += shade1(ro, normalize(rd + j), tmin, tmax).color;
    }
    return Hit(acc / f32(n), h.t);
}

shaders.09c68a931ae8fd0e7f8f8046fc9b:
// What Memory Keeps — a rising spiral of moments, threaded together.
const COUNT = 18;

fn glow(d: f32, r: f32) -> f32 {
  return smoothstep(r, 0.0, d);
}

fn point_at(i: i32) -> vec3f {
  let f = f32(i) / f32(COUNT - 1);
  let ang = f32(i) * 2.399963 + time() * 0.03;
  let r = 3.1 * sqrt(f32(i + 1) / f32(COUNT));
  let h = 0.45 + 3.6 * f;
  return vec3f(cos(ang) * r, h, sin(ang) * r);
}

fn spiral(ro: vec3f, rd: vec3f) -> vec3f {
  var acc = vec3f(0.0);
  var last = point_at(0);
  for (var i = 0; i < COUNT; i = i + 1) {
    let f = f32(i) / f32(COUNT - 1);
    let p = point_at(i);
    let tq = clamp(dot(p - ro, rd), 0.0, 1e6);
    let d = distance(ro + rd * tq, p);
    let warm = vec3f(1.0, 0.72, 0.40);
    let cool = vec3f(0.55, 0.72, 1.0);
    let c = mix(warm, cool, f);
    let tw = 0.6 + 0.4 * sin(time() * 0.8 + f32(i) * 2.2);
    acc += c * glow(d, 0.10) * tw;
    acc += c * glow(d, 0.30) * 0.22 * tw;
    if (i > 0) {
      for (var k = 1; k < 4; k = k + 1) {
        let q = mix(last, p, f32(k) / 4.0);
        let tq2 = clamp(dot(q - ro, rd), 0.0, 1e6);
        let d2 = distance(ro + rd * tq2, q);
        acc += vec3f(0.35, 0.5, 0.8) * glow(d2, 0.016) * (0.25 + 0.55 * f);
      }
    }
    last = p;
  }
  return acc;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
  var col = vec3f(0.012, 0.015, 0.032);
  col += vec3f(0.05, 0.05, 0.09) * max(dot(rd, vec3f(0.0, 1.0, 0.0)), 0.0);

  col += spiral(ro, rd);

  let tf = plane_y(ro, rd, 0.0);
  if (tf > 0.0 && tf <= tmax + 0.01) {
    let p = ro + rd * tf;
    let g = abs(fract(p.xz * 0.4) - 0.5) * 2.0;
    let line = 1.0 - smoothstep(0.0, 0.06, min(g.x, g.y));
    col += vec3f(0.02, 0.03, 0.05);
    col += vec3f(0.20, 0.24, 0.36) * line * 0.35;
    let racc = spiral(p, reflect(rd, vec3f(0.0, 1.0, 0.0)));
    col += racc * 0.35;
    return Hit(col, tf);
  }
  return Hit(col, horizon_t(tmax));
}

shaders.1fefe8a370ced90b37025831293d:
// Signal, room 12/12 at (1,-3). seq 9011. A pulse of light travels down a wire, room to room.
const E: f32 = 0.8500;
const COL: vec3f = vec3f(0.9830, 0.1500, 1.0000);
const TRAIL: vec3f = vec3f(0.5500, 0.0550, 0.3817);
const A_IN: vec3f = vec3f(6.0000, 1.3000, 0.0000);
const A_OUT: vec3f = vec3f(0.0000, 1.3000, 0.0000);
const CEN: vec3f = vec3f(0.0, 1.3, 0.0);
const S0: f32 = 132.000;
const L1: f32 = 6.000;
const KIND: i32 = 2;
const STEPS: i32 = 160;
const VSTEPS: i32 = 96;
const GOFF: vec3f = vec3f(12.0, 0.0, -36.0);

// distance to the wire centreline and global arc length along it
fn wire(p: vec3f) -> vec2f {
    let b1 = CEN - A_IN;
    let h1 = clamp(dot(p - A_IN, b1) / max(dot(b1, b1), 1e-4), 0.0, 1.0);
    let d1 = length(p - A_IN - b1 * h1);
    let b2 = A_OUT - CEN;
    let h2 = clamp(dot(p - CEN, b2) / max(dot(b2, b2), 1e-4), 0.0, 1.0);
    let d2 = length(p - CEN - b2 * h2);
    if (d1 < d2) { return vec2f(d1, S0 + h1 * L1); }
    return vec2f(d2, S0 + L1 + h2 * length(b2));
}

fn spark(s: f32) -> f32 {
    let v = 0.5 + 2.6 * E;
    let f = fract(s * 0.35 - time() * v * 0.35);
    let g = fract(s * 0.9 + time() * 0.21);
    return exp(-pow((f - 0.5) * 9.0, 2.0)) * (0.4 + 1.6 * E) + 0.12 * exp(-pow((g - 0.5) * 14.0, 2.0));
}

fn light_col() -> vec3f { return mix(TRAIL, COL, clamp(E * 1.6, 0.0, 1.0)); }
fn level() -> f32 { return 0.06 + E; }

// solids: 0 none, 1 wire, 2 node, 3 posts/mast, 4 orb
fn map(p: vec3f) -> vec2f {
    let w = wire(p);
    var d = w.x - 0.055;
    var m = 1.0;
    // repeater node in the middle of each room
    var nr = 0.2 + 0.12 * E;
    if (KIND == 2) { nr = 0.85; }
    let dn = length(p - CEN) - nr;
    if (dn < d) { d = dn; m = select(2.0, 4.0, KIND == 2); }
    // insulator posts holding the line, every 3 m on the floor
    let q = vec3f(p.x, p.y, p.z);
    let ax = abs(q.x); let az = abs(q.z);
    var dp = 1e3;
    // posts sit under the wire: the wire runs along x or z through centre
    let px = vec3f(q.x - clamp(round(q.x / 3.0) * 3.0, -3.0, 3.0), q.y, q.z);
    let pz = vec3f(q.x, q.y, q.z - clamp(round(q.z / 3.0) * 3.0, -3.0, 3.0));
    let use_x = abs(A_IN.x) + abs(A_OUT.x) > 0.5;
    let use_z = abs(A_IN.z) + abs(A_OUT.z) > 0.5;
    if (use_x) { dp = min(dp, sd_box(px - vec3f(0.0, 0.62, 0.0), vec3f(0.035, 0.62, 0.035))); }
    if (use_z) { dp = min(dp, sd_box(pz - vec3f(0.0, 0.62, 0.0), vec3f(0.035, 0.62, 0.035))); }
    if (KIND == 1) {
        dp = min(dp, length(p.xz) - 0.09 + 0.02 * p.y);
        dp = max(dp, p.y - 3.7);
        // emitter dish rings around the mast
        let ry = p.y - 3.7;
        let tor = length(vec2f(length(p.xz) - 0.7, ry)) - 0.03;
        let tor2 = length(vec2f(length(p.xz) - 1.2, ry + 0.25)) - 0.025;
        dp = min(dp, min(tor, tor2));
    }
    if (KIND == 2) {
        let rp = p - CEN;
        let r1 = vec3f(rp.x, (rot2(time() * 0.3) * rp.yz));
        let r2 = vec3f((rot2(time() * 0.23) * rp.xy), rp.z);
        let t1 = length(vec2f(length(r1.xy) - 1.4, r1.z)) - 0.03;
        let t2 = length(vec2f(length(r2.xz) - 1.75, r2.y)) - 0.025;
        dp = min(dp, min(t1, t2));
    }
    if (dp < d) { d = dp; m = 3.0; }
    return vec2f(d, m);
}

fn nrm(p: vec3f) -> vec3f {
    let e = vec2f(0.002, 0.0);
    return normalize(vec3f(map(p + e.xyy).x - map(p - e.xyy).x, map(p + e.yxy).x - map(p - e.yxy).x, map(p + e.yyx).x - map(p - e.yyx).x));
}

// light falling on a surface point from the wire and node
fn glow_at(p: vec3f) -> vec3f {
    let w = wire(p);
    let lc = light_col();
    var c = lc * level() * (0.9 + spark(w.y)) * 0.5 / (1.0 + 2.2 * w.x * w.x);
    let dn = length(p - CEN);
    c += lc * level() * 0.75 / (1.0 + 0.8 * dn * dn);
    // shockwave from the node when the pulse is here
    let ph = fract(time() * 0.55);
    let shell = exp(-abs(dn - ph * 8.0) * 3.0) * (1.0 - ph);
    c += COL * shell * E * E * 1.8;
    return c;
}

fn orb(rd: vec3f, ro: vec3f, t0: f32) -> vec3f {
    // volumetric swirling core of the receiver
    var acc = vec3f(0.0);
    var tr = 1.0;
    let n = max(6, i32(f32(VSTEPS) * (0.35 + 0.65 * quality())));
    let span = box_span(ro, rd, CEN - vec3f(0.86), CEN + vec3f(0.86));
    let dt = 1.72 / f32(n);
    var t = max(span.x, t0);
    for (var i = 0; i < n; i = i + 1) {
        let p = ro + rd * t - CEN;
        if (length(p) < 0.85) {
            let q = vec3f(rot2(time() * 0.4) * p.xz, p.y).xzy;
            let den = smoothstep(0.35, 0.75, fbm3(q * 2.6 + vec3f(0.0, time() * 0.5, 0.0))) * (1.0 - length(p) / 0.85);
            let c = mix(TRAIL, COL, 0.5 + 0.5 * sin(length(p) * 9.0 - time() * 3.0));
            acc += tr * c * den * dt * (3.0 + 9.0 * E);
            tr *= exp(-den * dt * 4.0);
        }
        t += dt;
        if (t > span.y) { break; }
    }
    return acc + tr * light_col() * (0.4 + E) * 0.6;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let tf = plane_y(ro, rd, 0.0);
    var tend = horizon_t(tmax);
    var surf = 0;
    if (tf > 0.0 && tf < tend) { tend = tf; surf = 1; }
    var t = max(tmin, 0.0);
    var haze = vec3f(0.0);
    var hit = -1.0;
    var mat = 0.0;
    let lc = light_col();
    for (var i = 0; i < STEPS; i = i + 1) {
        let p = ro + rd * t;
        let m = map(p);
        let w = wire(p);
        // volumetric bloom around the wire
        let sd = max(min(w.x, length(p - CEN)), 0.02);
        haze += lc * level() * (0.15 + spark(w.y)) * 0.0028 / (sd * sd + 0.02) * max(m.x, 0.02);
        if (m.x < 0.0015 * t) { hit = t; mat = m.y; break; }
        t += m.x * 0.9;
        if (t > tend) { break; }
    }
    var col = vec3f(0.0);
    var tout = tend;
    if (hit > 0.0) {
        let p = ro + rd * hit;
        tout = hit;
        let w = wire(p);
        if (mat < 1.5) {
            col = lc * (0.22 + 6.0 * E) * (0.5 + spark(w.y)) + vec3f(1.0) * E * E * spark(w.y);
        } else if (mat < 2.5) {
            let n = nrm(p);
            let rim = pow(1.0 - abs(dot(n, -rd)), 2.0);
            col = lc * (1.0 + 9.0 * E) * (0.6 + 0.4 * sin(time() * 6.0)) + rim * vec3f(1.0) * E;
        } else if (mat < 3.5) {
            let n = nrm(p);
            let g = glow_at(p + n * 0.1);
            let fres = pow(1.0 - abs(dot(n, -rd)), 4.0);
            col = vec3f(0.04, 0.045, 0.06) + g * 0.5 + fres * lc * level() * 1.5;
        } else {
            let n = nrm(p);
            let rim = pow(1.0 - abs(dot(n, -rd)), 3.0);
            col = orb(rd, ro, hit) + rim * mix(lc, vec3f(1.0), 0.5) * (0.6 + E);
        }
    } else {
        let p = ro + rd * tend;
        let g = glow_at(p);
        // world-space position so patterns continue through the doors
        let wp = p + GOFF;
        if (surf == 1) {
            // polished black floor with circuit traces
            let cell = floor(wp.xz / 1.5);
            let f = fract(wp.xz / 1.5) - 0.5;
            let lineg = smoothstep(0.03, 0.0, min(abs(f.x), abs(f.y)));
            let pad = smoothstep(0.09, 0.05, length(f)) * step(0.72, hash12(cell));
            let r = reflect(rd, vec3f(0.0, 1.0, 0.0));
            let rw = wire(p + r * 1.3);
            let refl = lc * level() * (0.3 + spark(rw.y)) * 0.35 / (1.0 + 6.0 * rw.x * rw.x);
            col = vec3f(0.012, 0.014, 0.02) + g * (0.16 + 0.5 * lineg + 1.2 * pad) + refl;
        } else {
            // dark ribbed walls and ceiling
            let ap = abs(p);
            var uv = vec2f(wp.x + wp.z, p.y);
            if (ap.y > 4.45) { uv = wp.xz; }
            let rib = smoothstep(0.02, 0.0, abs(fract(uv.x / 0.75) - 0.5) - 0.46);
            let band = smoothstep(0.03, 0.0, abs(p.y - 1.3) - 0.015) * step(ap.y, 4.45);
            col = vec3f(0.018, 0.02, 0.03) + g * (0.12 + 0.25 * rib) + band * lc * level() * (0.4 + spark(uv.x * 0.5));
        }
    }
    col += haze;
    return Hit(tone(col * 1.15), tout);
}

shaders.19740dcbf04db1102a9ce361e097:
// Tidal Cathedral, room (-4,0). A flooded gothic nave continued room to room.
const GX: f32 = -4.0;
const GY: f32 = 0.0;
const MODE: i32 = 1;
const AXIS: i32 = 0;
const END: f32 = 0.0;
const STEPS: f32 = 200.0;
const VSTEPS: f32 = 160.0;
const REFL: f32 = 1.0;
// ---- Tidal Cathedral: shared world. Frame coords: x = world position along the nave axis,
// y = up, z = across the nave (room-local). All rooms sample the same building, so the
// arcades, ribs, light shafts and the slow westward current run on through the doorways.
const WATER: f32 = 0.30;
const ZC: f32 = 3.5;

fn along0() -> f32 { return select(GY, GX, AXIS == 0) * 12.0; }
fn to_frame(v: vec3f) -> vec3f { if (AXIS == 0) { return v; } return vec3f(v.z, v.y, v.x); }
fn sunv() -> vec3f {
    let t = time() * 0.035;
    return normalize(vec3f(0.32 + 0.16 * sin(t), 0.74 + 0.05 * cos(t * 1.3), 1.0));
}

// pointed (two-centred) opening: negative inside. hw = half width at springing ys.
fn opening(u: f32, y: f32, ys: f32, hw: f32, d: f32) -> f32 {
    let au = abs(u);
    let dv = length(vec2f(au + d, y - ys)) - (hw + d);
    return select(dv, au - hw, y < ys);
}
fn bayu(x: f32) -> f32 { return x - 4.0 * round(x / 4.0); }
fn pieru(x: f32) -> f32 { let s = x + 2.0; return s - 4.0 * round(s / 4.0); }

fn pier(pu: f32, y: f32, dz: f32) -> f32 {
    let q = vec2f(pu, dz);
    var d = length(q) - 0.29;
    let a = abs(q);
    d = min(d, min(length(a - vec2f(0.33, 0.0)), length(a - vec2f(0.0, 0.33))) - 0.10);
    d = min(d, sd_box(vec3f(pu, y - 0.15, dz), vec3f(0.5, 0.42, 0.5)) - 0.03);
    let cy = y - 1.62;
    let w = 0.47 + clamp(cy, -0.12, 0.12) * 0.6;
    d = min(d, sd_box(vec3f(pu, cy, dz), vec3f(w, 0.11, w)) - 0.01);
    return d;
}

fn arcade(x: f32, y: f32, z: f32, open_south: bool) -> f32 {
    let dz = abs(z) - ZC;
    var d = pier(pieru(x), y, dz);
    if (open_south && z > 0.0) { return d; }
    let u = bayu(x);
    let op = opening(u, y, 1.72, 1.66, 0.8);
    d = min(d, max(abs(dz) - 0.22, -op));
    let roll = max(abs(op + 0.08) - 0.07, abs(dz) - 0.29);
    d = min(d, max(roll, 1.6 - y));
    d = min(d, sd_box(vec3f(0.0, y - 4.12, dz), vec3f(100.0, 0.05, 0.29)));
    // small trefoil piercings in the spandrels
    let sp = vec2f(abs(u) - 1.95, y - 3.75);
    d = max(d, -max(length(sp) - 0.17, abs(dz) - 0.4));
    return d;
}

fn ribs(x: f32, y: f32, z: f32) -> f32 {
    let pu = pieru(x);
    let m = 1.6;
    let op = opening(z * 0.47, 1.72 + (y - 3.0) * m, 1.72, 1.66, 0.8);
    let ring = (abs(op + 0.09) - 0.09) / m;
    return max(max(ring, abs(pu) - 0.12), 2.95 - y);
}

fn waves(p: vec2f) -> f32 {
    let t = time();
    var h = sin(p.x * 1.1 + p.y * 0.4 + t * 0.9) * 0.5;
    h += sin(p.x * -0.5 + p.y * 1.7 + t * 1.3) * 0.3;
    h += sin(p.x * 2.9 - p.y * 1.3 + t * 2.1) * 0.12;
    h += (noise3(vec3f(p.x * 1.4 + t * 0.45, p.y * 1.4, t * 0.25)) - 0.5) * 0.6;
    return h * 0.035;
}

fn caustic(p: vec2f) -> f32 {
    let t = time();
    let a = noise3(vec3f(p * 2.3 + vec2f(t * 0.3, 0.0), t * 0.4));
    let b = noise3(vec3f(p * 3.1 - vec2f(0.0, t * 0.2), 4.0 + t * 0.5));
    return pow(1.0 - abs(a - b), 9.0);
}

fn glass(u: f32, y: f32, xw: f32) -> vec4f {
    let op = opening(u * 3.69, 1.72 + (y - 3.55) * 3.1, 1.72, 1.66, 0.8);
    if (op > 0.0 || y < 2.75) { return vec4f(0.0); }
    let c = vec2f(u * 7.0, y * 5.5 - xw * 0.3);
    let cell = floor(c + vec2f(floor(xw / 4.0) * 3.0, 0.0));
    let f = fract(c);
    let lead = smoothstep(0.0, 0.12, min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y)));
    let h = hash12(cell);
    var g = vec3f(0.08, 0.2, 0.95);
    if (h > 0.55) { g = vec3f(0.95, 0.12, 0.1); }
    if (h > 0.78) { g = vec3f(1.0, 0.72, 0.15); }
    if (h > 0.92) { g = vec3f(0.15, 0.85, 0.35); }
    let edge = smoothstep(0.0, 0.06, -op / 3.69);
    return vec4f(g, lead * edge);
}

// coloured sunlight reaching frame point p (through the +z windows, past the arcade)
fn shaft(p: vec3f, open_south: bool) -> vec3f {
    let S = sunv();
    if (p.z > 5.9 || p.y < 0.0) { return vec3f(0.0); }
    let q = p + S * ((6.0 - p.z) / S.z);
    let g = glass(bayu(q.x), q.y, q.x);
    if (g.a <= 0.0) { return vec3f(0.0); }
    var k = g.a;
    if (p.z < ZC - 0.22 && !open_south) {
        let qa = p + S * ((ZC - p.z) / S.z);
        let o = opening(bayu(qa.x), qa.y, 1.72, 1.66, 0.8);
        k *= smoothstep(0.05, -0.1, o);
        k *= smoothstep(0.3, 0.5, abs(pieru(qa.x)));
    }
    return g.rgb * k;
}

fn ashlar(p: vec2f) -> f32 {
    let row = floor(p.y / 0.38);
    let off = select(0.0, 0.3, fract(row * 0.5) > 0.25);
    let f = fract(vec2f((p.x + off) / 0.6, p.y / 0.38));
    let e = min(min(f.x, 1.0 - f.x) * 0.6, min(f.y, 1.0 - f.y) * 0.38);
    return 0.82 + 0.18 * smoothstep(0.0, 0.02, e);
}

fn stone_albedo(p: vec3f) -> vec3f {
    let n = noise3(p * 3.0);
    var c = vec3f(0.62, 0.57, 0.5) * (0.75 + 0.35 * n);
    let tide = WATER + 0.55 + 0.25 * noise3(vec3f(p.x * 0.7, 0.0, p.z * 0.7));
    let wet = smoothstep(tide + 0.1, tide - 0.1, p.y);
    c = mix(c, vec3f(0.16, 0.24, 0.2) * (0.7 + 0.6 * n), wet * 0.8);
    c = mix(c, vec3f(0.3, 0.45, 0.32), smoothstep(0.62, 0.8, noise3(p * 7.0)) * wet);
    return c;
}

fn light_stone(p: vec3f, n: vec3f, alb: vec3f, open_south: bool) -> vec3f {
    let S = sunv();
    var l = vec3f(0.035, 0.055, 0.08) * (0.6 + 0.4 * n.y);
    l += vec3f(0.09, 0.07, 0.1) * max(n.z, 0.0) + vec3f(0.02, 0.04, 0.07) * max(-n.z, 0.0);
    l += shaft(p + n * 0.02, open_south) * max(dot(n, S), 0.0) * 4.0;
    let up = exp(-(p.y - WATER) * 0.9) * max(-n.y * 0.6 + 0.4, 0.0);
    l += vec3f(0.2, 0.42, 0.45) * caustic(p.xz * 0.8 + p.y * 0.3) * up * 0.7;
    return alb * l;
}

fn sky_through(rd: vec3f) -> vec3f {
    let y = max(rd.y, 0.0);
    var c = mix(vec3f(0.9, 0.75, 0.55), vec3f(0.35, 0.55, 0.9), y);
    let cl = fbm3(vec3f(rd.xz / (rd.y + 0.2) * 1.3 + vec2f(time() * 0.02, 0.0), 1.0));
    return mix(c, vec3f(1.0, 0.95, 0.9), smoothstep(0.45, 0.75, cl) * 0.7);
}

fn rose(v: vec2f, r0: f32) -> vec4f {
    let r = length(v) / r0;
    if (r > 1.0) { return vec4f(0.0); }
    let a = atan2(v.y, v.x);
    let seg = TAU / 12.0;
    let ai = floor(a / seg);
    let af = a - (ai + 0.5) * seg;
    let pv = vec2f(cos(af), sin(af)) * r;
    let petal = length(pv - vec2f(0.62, 0.0)) - 0.27;
    let hub = r - 0.22;
    let ring = abs(r - 0.93) - 0.035;
    let spokes = abs(pv.y) - 0.02;
    var lead = min(min(abs(petal) - 0.025, abs(hub) - 0.025), ring);
    lead = min(lead, select(1.0, spokes, r > 0.22 && petal > 0.0));
    let h = hash12(vec2f(ai, floor(r * 6.0)));
    var g = mix(vec3f(0.1, 0.18, 0.95), vec3f(0.95, 0.15, 0.25), step(0.5, h));
    if (petal < 0.0) { g = mix(vec3f(1.0, 0.7, 0.2), vec3f(0.2, 0.8, 0.5), step(0.7, h)); }
    if (hub < 0.0) { g = vec3f(1.0, 0.85, 0.4); }
    let m = smoothstep(0.0, 0.02, lead) * smoothstep(1.0, 0.97, r);
    return vec4f(g * (0.8 + 0.4 * fract(h * 7.0)), m);
}

// ---- painted surfaces at the room's box boundary (frame coords) ----
fn paint(p: vec3f, rd: vec3f, os: bool) -> vec3f {
    let lx = p.x - along0();
    let S = sunv();
    if (p.y > ROOM_HEIGHT - 0.01) {
        // star-spangled rib vault
        let bu = bayu(p.x);
        var zc = ZC;
        var zz = p.z;
        if (abs(p.z) > ZC) { zz = abs(p.z) - (ZC + 6.0) * 0.5; zc = (6.0 - ZC) * 0.5; }
        let diag = abs(abs(bu) / 2.0 - abs(zz) / zc);
        var rib = min(diag * 1.6, abs(zz) * 1.5);
        rib = min(rib, min(abs(abs(bu) - 2.0), abs(abs(p.z) - ZC)) * 2.0);
        let sc = p.xz * 9.0;
        let st = hash12(floor(sc));
        let star = smoothstep(0.16, 0.0, length(fract(sc) - 0.5)) * step(0.93, st);
        var c = vec3f(0.03, 0.05, 0.16) + vec3f(0.9, 0.7, 0.3) * star * (0.6 + 0.4 * sin(time() * 2.0 + st * 40.0));
        c = mix(vec3f(0.5, 0.42, 0.3), c, smoothstep(0.03, 0.06, rib));
        c *= 0.5 + 0.5 * caustic(p.xz * 0.6) + 0.15;
        if (MODE == 1) {
            let r = length(vec2f(lx, p.z));
            if (r < 1.3) { return sky_through(rd) * 2.0; }
            c = mix(c, vec3f(0.85, 0.65, 0.3), smoothstep(0.08, 0.0, abs(r - 1.42)));
        }
        return c;
    }
    if (abs(p.z) > 5.99) {
        // side walls: ashlar with lancet windows; the +z wall faces the sun
        let a = ashlar(vec2f(p.x, p.y));
        var c = stone_albedo(p) * a * 0.18;
        c += vec3f(0.15, 0.32, 0.35) * caustic(p.xy * 0.7) * exp(-(p.y - WATER) * 1.2) * 0.4;
        let g = glass(bayu(p.x), p.y, p.x);
        let lit = select(0.22, 2.4, p.z > 0.0);
        c = mix(c, g.rgb * lit, g.a);
        return c;
    }
    // end walls between bays: diaphragm wall with a rose window over the door
    let a = ashlar(vec2f(p.z, p.y));
    var c = stone_albedo(p) * a * 0.2;
    c += vec3f(0.15, 0.32, 0.35) * caustic(p.zy * 0.7) * exp(-(p.y - WATER) * 1.2) * 0.4;
    var rc = vec2f(p.z, p.y - 3.55);
    var rr = 0.8;
    if (MODE == 3 && lx * END > 0.0) { rc = vec2f(p.z, p.y - 2.25); rr = 2.1; }
    let g = rose(rc, rr);
    let face = select(1.0, 1.7, (rd.x > 0.0) == (S.x < 0.0));
    c = mix(c, g.rgb * 1.5 * face, g.a);
    c = mix(c, vec3f(0.4, 0.33, 0.25), smoothstep(0.05, 0.0, abs(length(rc) - rr - 0.06)) * 0.8);
    return c;
}

fn open_s() -> bool { return MODE == 1; }

fn feature(p: vec3f) -> f32 {
    let lx = p.x - along0();
    if (MODE == 1) {
        // the crossing font: a tiered basin, its upper bowl brimming with light
        let r = length(vec2f(lx, p.z));
        var d = max(abs(r - 1.15) - 0.09, p.y - 0.62);
        d = min(d, max(r - 1.24, abs(p.y - 0.12) - 0.12));
        d = min(d, max(r - 0.16 - 0.06 * smoothstep(1.3, 1.6, p.y), p.y - 1.6));
        let bowl = max(abs(length(vec3f(lx, p.y - 1.85, p.z)) - 0.62) - 0.04, p.y - 1.8);
        d = min(d, max(bowl, 1.25 - p.y));
        d = min(d, max(r - 0.58, abs(p.y - 1.66) - 0.02));
        d = min(d, corona(p));
        return d;
    }
    if (MODE == 3) {
        let q = vec3f(lx - END * 3.6, p.y, p.z);
        var d = sd_box(q - vec3f(0.0, 0.2, 0.0), vec3f(1.5, 0.35, 2.0));
        d = min(d, sd_box(q - vec3f(0.0, 0.6, 0.0), vec3f(1.1, 0.25, 1.5)));
        d = min(d, sd_box(q - vec3f(0.0, 1.0, 0.0), vec3f(0.45, 0.35, 0.95)) - 0.02);
        let rq = q - vec3f(0.0, 1.95 + 0.08 * sin(time() * 0.7), 0.0);
        d = min(d, sd_sphere(rq, 0.32));
        return d;
    }
    return 1e5;
}

fn map(p: vec3f) -> f32 {
    var d = arcade(p.x, p.y, p.z, open_s());
    d = min(d, ribs(p.x, p.y, p.z));
    d = min(d, feature(p));
    return d;
}

fn calc_n(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn march(ro: vec3f, rd: vec3f, t0: f32, t1: f32, n: i32) -> f32 {
    var t = t0;
    for (var i = 0; i < 200; i = i + 1) {
        if (i >= n || t > t1) { break; }
        let d = map(ro + rd * t);
        if (d < 0.0008 + 0.0015 * t) { return t; }
        t += d * 0.8;
    }
    return -1.0;
}

fn ao(p: vec3f, n: vec3f) -> f32 {
    var o = 0.0;
    var s = 1.0;
    for (var i = 1; i < 5; i = i + 1) {
        let h = 0.06 * f32(i);
        o += (h - map(p + n * h)) * s;
        s *= 0.6;
    }
    return clamp(1.0 - 2.2 * o, 0.0, 1.0);
}

fn surf(p: vec3f, rd: vec3f, full: bool) -> vec3f {
    let n = calc_n(p);
    var alb = stone_albedo(p);
    let lx = p.x - along0();
    var c = light_stone(p, n, alb, open_s());
    if (full) { c *= ao(p, n); }
    if (MODE == 1) {
        let r = length(vec2f(lx, p.z));
        if (p.y > 1.62 && r < 0.585) {
            let rip = 0.5 + 0.5 * sin(r * 30.0 - time() * 4.0);
            c = vec3f(0.5, 0.9, 0.85) * (0.6 + 0.5 * rip) + vec3f(1.0, 0.8, 0.5) * caustic(vec2f(lx, p.z) * 3.0);
        }
        c += vec3f(1.0, 0.8, 0.5) * 0.35 * max(n.y, 0.0) * smoothstep(1.6, 0.5, r);
        c += alb * candle_light(p, n) + flame(p);
    }
    if (MODE == 3) {
        let rq = vec3f(lx - END * 3.6, p.y - 1.95 - 0.08 * sin(time() * 0.7), p.z);
        if (length(rq) < 0.34) {
            let f = pow(1.0 - max(dot(-rd, n), 0.0), 3.0);
            let band = step(0.5, fract(atan2(rq.z, rq.x) * 1.91 + rq.y * 3.0));
            let env = paint(vec3f(along0() - 6.0 * END, clamp(p.y + n.y * 3.0, 0.1, 4.4), clamp(n.z * 6.0, -5.9, 5.9)), n, false);
            c = vec3f(0.9, 0.6, 0.22) * (0.12 + 0.25 * band + 0.2 * noise3(rq * 9.0 + time())) * (0.4 + max(n.y, 0.0));
            c += env * vec3f(1.0, 0.75, 0.4) * (0.4 + f) + vec3f(1.2, 0.9, 0.5) * pow(f, 2.0) * 0.6;
        }
    }
    return c;
}

fn bmin() -> vec3f { return vec3f(along0() - 6.0, 0.0, -6.0); }
fn bmax() -> vec3f { return vec3f(along0() + 6.0, ROOM_HEIGHT, 6.0); }

// a secondary ray: structures first, then the painted box
fn trace2(ro: vec3f, rd: vec3f, n: i32) -> vec3f {
    let te = box_span(ro, rd, bmin(), bmax()).y;
    let t = march(ro, rd, 0.02, te, n);
    if (t > 0.0) { return surf(ro + rd * t, rd, false); }
    return paint(ro + rd * te, rd, open_s());
}

fn water(pw: vec3f, rd: vec3f, nref: i32) -> vec3f {
    let e = 0.03;
    let h = waves(pw.xz);
    let n = normalize(vec3f(h - waves(pw.xz + vec2f(e, 0.0)), e, h - waves(pw.xz + vec2f(0.0, e))));
    let fres = 0.02 + 0.98 * pow(1.0 - max(dot(-rd, n), 0.0), 5.0);
    let r = reflect(rd, n);
    let refl = trace2(pw + n * 0.01, r, nref);
    // refraction down to the drowned floor
    let rr = refract(rd, n, 0.75);
    let tf = -pw.y / min(rr.y, -0.05);
    let fp = pw + rr * tf;
    let tiles = fract(fp.xz * 0.5);
    let grout = smoothstep(0.0, 0.04, min(min(tiles.x, 1.0 - tiles.x), min(tiles.y, 1.0 - tiles.y)));
    let chk = select(0.7, 1.0, (floor(fp.x * 0.5) + floor(fp.z * 0.5)) % 2.0 == 0.0);
    var fl = vec3f(0.3, 0.32, 0.3) * grout * chk;
    let lit = shaft(fp, open_s()) * 2.0 + vec3f(0.05, 0.1, 0.1);
    fl *= lit + vec3f(0.6, 0.9, 0.85) * caustic(fp.xz) * (0.3 + length(lit));
    let absorb = exp(-tf * vec3f(1.6, 0.55, 0.45) * 1.4);
    var c = mix(fl * absorb + vec3f(0.005, 0.03, 0.035), refl, fres);
    // sun glints where the coloured shafts touch the surface
    let S = sunv();
    c += shaft(pw, open_s()) * (0.25 + 3.0 * pow(max(dot(r, S), 0.0), 60.0));
    if (MODE == 1) {
        let rl = length(vec2f(pw.x - along0(), pw.z));
        c += vec3f(1.0, 0.85, 0.6) * smoothstep(1.35, 1.0, rl) * (0.15 + 0.15 * sin(rl * 14.0 - time() * 3.0));
    }
    return c;
}

fn beams(ro: vec3f, rd: vec3f, t1: f32, n: i32) -> vec3f {
    var acc = vec3f(0.0);
    let dt = t1 / f32(n);
    var t = dt * hash12(rd.xy * 917.0 + fract(time() * 7.13));
    let S = sunv();
    for (var i = 0; i < 160; i = i + 1) {
        if (i >= n) { break; }
        let p = ro + rd * t;
        if (p.y > WATER) {
            var L = shaft(p, open_s());
            if (MODE == 1) {
                let r = length(vec2f(p.x - along0(), p.z));
                L += vec3f(1.0, 0.85, 0.6) * smoothstep(1.3, 1.0, r) * 0.6;
                L += candle_glow(p);
            }
            if (MODE == 3) {
                let rq = vec3f(p.x - along0() - END * 3.6, p.y - 1.95, p.z);
                L += vec3f(1.0, 0.7, 0.3) * 0.25 / (1.0 + dot(rq, rq) * 3.0);
            }
            if (L.x + L.y + L.z > 0.001) {
                let dust = 0.15 + 1.6 * noise3(p * 2.2 + vec3f(-time() * 0.12, time() * 0.05, 0.0));
                let mote = step(0.985, hash13(floor(p * 30.0 + vec3f(0.0, time() * 0.6, 0.0))));
                acc += L * (dust + mote * 3.0) * dt;
            }
        }
        t += dt;
    }
    let ph = 0.35 + 1.6 * pow(max(dot(rd, S), 0.0), 5.0);
    return acc * 0.22 * ph;
}

fn shade(ro0: vec3f, rd0: vec3f, tmin: f32, tmax: f32) -> Hit {
    let ro = to_frame(ro0) + vec3f(along0(), 0.0, 0.0);
    let rd = to_frame(rd0);
    let q = quality();
    let ns = i32(mix(40.0, STEPS, q));
    let tw = plane_y(ro, rd, WATER);
    var tl = tmax;
    if (tw > 0.0) { tl = min(tl, tw); }
    let ts = march(ro, rd, tmin, tl, ns);
    var c: vec3f;
    var t: f32;
    if (ts > 0.0) {
        t = ts;
        c = surf(ro + rd * ts, rd, true);
    } else if (tw > 0.0 && tw < tmax) {
        t = tw;
        c = water(ro + rd * tw, rd, i32(f32(ns) * REFL));
    } else {
        t = horizon_t(tmax);
        c = paint(ro + rd * tmax, rd, open_s());
    }
    c += beams(ro, rd, min(t, tmax), i32(mix(12.0, VSTEPS, q)));
    c = mix(c, vec3f(0.01, 0.035, 0.045), 1.0 - exp(-t * 0.012));
    return Hit(pow(tone(c * 1.5), vec3f(1.25)), t);
}

// ---- the crossing only: a hanging corona of twelve candles over the font ----
const NCAND: i32 = 12;
const CR: f32 = 2.2;
const CY: f32 = 3.55;

fn cand_pos(i: i32) -> vec3f {
    let a = f32(i) / f32(NCAND) * TAU + time() * 0.03;
    return vec3f(along0() + cos(a) * CR, CY + 0.32, sin(a) * CR);
}

fn flick(i: i32) -> f32 {
    let t = time() * 6.0 + f32(i) * 13.1;
    return 0.75 + 0.15 * sin(t) + 0.1 * (noise3(vec3f(t * 0.7, f32(i), 0.0)) - 0.5) * 2.0;
}

fn corona(p: vec3f) -> f32 {
    let q = vec3f(p.x - along0(), p.y - CY, p.z);
    let rq = vec2f(length(q.xz) - CR, q.y);
    var d = length(rq) - 0.05;
    // crenellated outer band
    let ang = atan2(q.z, q.x);
    let cren = step(0.0, sin(ang * 48.0)) * 0.04;
    d = min(d, sd_box(vec3f(rq.x - 0.1, q.y - 0.05 - cren * 0.5, 0.0), vec3f(0.015, 0.08 + cren * 0.5, 10.0)));
    // three chains up into the vault
    for (var k = 0; k < 3; k = k + 1) {
        let a = f32(k) / 3.0 * TAU + 0.4;
        let c0 = vec2f(cos(a), sin(a)) * CR;
        let h = q.xz - c0 * (1.0 - clamp(q.y / 0.95, 0.0, 1.0) * 0.6);
        d = min(d, max(length(h) - 0.012, max(-q.y, q.y - 0.95)));
    }
    // candles and their flames
    let seg = TAU / f32(NCAND);
    let ai = round((ang - time() * 0.03) / seg);
    let ca = ai * seg + time() * 0.03;
    let cl = vec3f(q.x - cos(ca) * CR, q.y, q.z - sin(ca) * CR);
    d = min(d, max(length(cl.xz) - 0.035, abs(cl.y - 0.12) - 0.13));
    d = min(d, sd_sphere(cl - vec3f(0.0, 0.33, 0.0), 0.028));
    return d;
}

fn flame(p: vec3f) -> vec3f {
    let q = vec3f(p.x - along0(), p.y - CY, p.z);
    if (abs(length(q.xz) - CR) > 0.1 || abs(q.y - 0.33) > 0.08) { return vec3f(0.0); }
    return vec3f(4.0, 2.4, 0.9);
}

fn candle_light(p: vec3f, n: vec3f) -> vec3f {
    var acc = vec3f(0.0);
    for (var i = 0; i < NCAND; i = i + 1) {
        let l = cand_pos(i) - p;
        let d2 = dot(l, l);
        let ln = l * inverseSqrt(d2);
        acc += vec3f(1.0, 0.62, 0.3) * flick(i) * max(dot(n, ln), 0.0) / (1.0 + d2 * 1.8);
    }
    return acc * 0.55;
}

fn candle_glow(p: vec3f) -> vec3f {
    let q = vec3f(p.x - along0(), p.y - CY - 0.33, p.z);
    let dr = length(vec2f(length(q.xz) - CR, q.y));
    return vec3f(1.0, 0.6, 0.25) * 0.35 / (1.0 + dr * dr * 40.0);
}

