// Leviathan Spine: the skeleton of a colossal sky creature lying across rooms (4..9, 1..2)
// under an aurora. One shared world; this room samples it at its grid offset.
const GOFF: vec3f = vec3f(84.0, 0.0, 24.0);
const AUR_A: vec3f = vec3f(0.16, 1.0, 0.58);
const AUR_B: vec3f = vec3f(0.5, 0.34, 1.0);
const HORIZON: vec3f = vec3f(0.03, 0.045, 0.1);
const BONE: vec3f = vec3f(0.97, 0.86, 0.64);

fn breath() -> f32 { return 0.5 + 0.5 * sin(time() * 0.75); }

fn sd_cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

fn sd_ell(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / max(k1, 1e-4);
}

// Spine path in the xz plane: tail tip (46,28) north to (46,20), quarter arc to (54,12), then east to the skull at x=104.
// Returns (u along the spine from the tail tip, signed lateral offset).
fn spine_frame(w: vec2f) -> vec2f {
    if (w.x >= 54.0) { return vec2f(20.566 + (w.x - 54.0), w.y - 12.0); }
    if (w.y <= 20.0) {
        let d = w - vec2f(54.0, 20.0);
        var a = atan2(d.y, d.x);
        if (a < 0.0) { a = a + TAU; }
        a = clamp(a, PI, 1.5 * PI);
        return vec2f(8.0 + 8.0 * (a - PI), length(d) - 8.0);
    }
    return vec2f(28.0 - w.y, w.x - 46.0);
}

fn spine_h(u: f32) -> f32 {
    return mix(0.72, 2.4, smoothstep(0.0, 22.0, u)) + 0.07 * sin(u * 0.31 - time() * 0.75) - 0.15 * smoothstep(64.0, 71.0, u);
}

fn spine_s(u: f32) -> f32 {
    return mix(0.33, 1.0, smoothstep(0.0, 30.0, u)) * (1.0 + 0.04 * breath());
}

fn vert_q(w: vec3f, f: vec2f) -> vec4f {
    let k = clamp(round(f.x / 0.8), 1.0, 88.0);
    let uk = k * 0.8;
    return vec4f(f.x - uk, w.y - spine_h(uk), f.y, uk);
}

fn vertebrae(w: vec3f, f: vec2f) -> f32 {
    let bound = abs(f.y) - 1.4;
    if (bound > 0.4) { return bound; }
    let vq = vert_q(w, f);
    let s = spine_s(vq.w);
    let q = vq.xyz;
    let r = 0.27 * s + 0.03;
    let dc = vec2f(length(q.yz) - r, abs(q.x) - 0.29);
    let cent = min(max(dc.x, dc.y), 0.0) + length(max(dc, vec2f(0.0))) - 0.04;
    let ns = sd_box(vec3f(q.x + 0.28 * (q.y - 0.3 * s), q.y - 0.6 * s, q.z), vec3f(0.05 + 0.04 * s, 0.48 * s, 0.045)) - 0.025;
    let tp = sd_box(vec3f(q.x, q.y + 0.04 + 0.1 * q.z * q.z, q.z), vec3f(0.055, 0.045, 0.66 * s)) - 0.02;
    let hm = sd_box(vec3f(q.x, q.y + 0.42 * s, q.z), vec3f(0.04, 0.2 * s, 0.035));
    return smin(cent, min(min(ns, tp), hm), 0.07);
}

fn ribs(w: vec3f, f: vec2f) -> f32 {
    let bx = max(57.0 - w.x, w.x - 103.0);
    if (bx > 0.3) { return bx; }
    let xk = clamp(0.75 + 1.5 * round((w.x - 0.75) / 1.5), 57.75, 102.75);
    let dx = w.x - xk;
    let sr = (0.7 + 0.3 * smoothstep(57.0, 74.0, xk)) * (1.0 - 0.28 * smoothstep(93.0, 103.0, xk));
    let br = 0.5 + 0.5 * sin(time() * 0.75 - xk * 0.06);
    let a = (4.45 + 0.4 * br) * sr;
    let b = 2.8 * mix(0.92, 1.0, sr);
    let q2 = vec2f(f.y, w.y + 0.32);
    let k0 = length(q2 / vec2f(a, b));
    let k1 = length(q2 / vec2f(a * a, b * b));
    let de = k0 * (k0 - 1.0) / max(k1, 1e-4);
    let th = mix(0.06, 0.13, clamp(w.y / 2.3, 0.0, 1.0));
    return max(length(vec2f(de, dx * 1.25)) - th, -w.y - 0.05);
}

fn skull(w: vec3f) -> f32 {
    let p = w - vec3f(108.0, 0.0, 12.0);
    let bb = sd_box(p - vec3f(0.0, 2.0, 0.0), vec3f(6.4, 2.1, 2.6));
    if (bb > 0.4) { return bb; }
    let pz = vec3f(p.x, p.y, abs(p.z));
    let cran = sd_ell(p - vec3f(-2.6, 2.25, 0.0), vec3f(2.3, 1.25, 1.75));
    let ros = sd_ell(p - vec3f(1.9, 1.95, 0.0), vec3f(4.3, 0.42, 0.98));
    var d = smin(cran, ros, 0.5);
    let eye = sd_sphere(pz - vec3f(-1.5, 2.45, 1.45), 0.62);
    d = max(d, -eye);
    let nost = sd_ell(pz - vec3f(-0.9, 2.4, 0.35), vec3f(0.6, 0.3, 0.18));
    d = max(d, -nost);
    let jaw = sd_cap(pz, vec3f(-4.1, 1.45, 1.15), vec3f(5.9, 0.16, 0.5), 0.16);
    d = min(d, jaw);
    if (p.x > -0.6 && p.x < 5.6) {
        let c = p.x - 0.32 * round(p.x / 0.32);
        let wdt = 0.9 * sqrt(max(1.0 - pow((p.x - 1.9) / 4.3, 2.0), 0.0));
        let tooth = sd_cap(vec3f(c, p.y, abs(p.z)), vec3f(0.0, 1.75, wdt * 0.8), vec3f(0.0, 1.32, wdt * 0.72), 0.035);
        d = min(d, tooth);
    }
    return d;
}

fn fin(w: vec3f) -> f32 {
    let bb = sd_box(w - vec3f(84.0, 1.2, 21.0), vec3f(4.5, 1.4, 8.5));
    if (bb > 0.4) { return bb; }
    let br = breath();
    var d = sd_cap(w, vec3f(84.0, 2.1, 13.2), vec3f(84.0, 0.62, 19.6), 0.24);
    d = smin(d, sd_sphere(w - vec3f(84.0, 0.62, 19.6), 0.36), 0.15);
    let wz = vec3f(abs(w.x - 84.0), w.y, w.z);
    d = min(d, sd_cap(wz, vec3f(0.28, 0.58, 19.8), vec3f(0.36, 0.32, 22.5), 0.15));
    for (var i = 0; i < 5; i = i + 1) {
        let fi = f32(i) - 2.0;
        let ang = fi * (0.3 + 0.05 * br);
        let dir = vec3f(sin(ang), 0.0, cos(ang));
        let base = vec3f(84.0 + fi * 0.28, 0.3, 22.6);
        let len = 5.5 - 0.55 * abs(fi);
        for (var j = 0; j < 4; j = j + 1) {
            let fj = f32(j);
            let a = base + dir * len * fj * 0.25 + vec3f(0.0, 0.06 * fj, 0.0);
            let b = base + dir * len * (fj + 0.88) * 0.25 + vec3f(0.0, 0.06 * fj, 0.0);
            let r = 0.12 * (1.0 - 0.17 * fj);
            d = min(d, sd_cap(w, a, b, r));
        }
    }
    return d;
}

fn fluke(w: vec3f) -> f32 {
    let bb = sd_box(w - vec3f(46.0, 0.5, 28.6), vec3f(3.2, 0.7, 1.6));
    if (bb > 0.4) { return bb; }
    let base = vec3f(46.0, 0.42, 28.15);
    var d = 1e3;
    for (var i = 0; i < 9; i = i + 1) {
        let t = (f32(i) - 4.0) / 4.0;
        let ang = t * 1.45;
        let len = 1.5 + 1.25 * abs(t);
        let dir = vec3f(sin(ang), 0.06, cos(ang) * 0.75);
        d = min(d, sd_cap(w, base, base + dir * len, 0.07 - 0.02 * abs(t)));
    }
    return d;
}

// Fallen ribs half-buried in the snow of the southern rooms.
fn fallen(w: vec3f) -> f32 {
    let cell = floor(w.xz / 12.0 + 0.5);
    if (cell.y < 1.5 || cell.x < 4.5) { return 1e3; }
    let cc = vec3f(cell.x * 12.0, 0.0, cell.y * 12.0);
    var d = 1e3;
    for (var i = 0; i < 3; i = i + 1) {
        let h = hash33(vec3f(cell, f32(i) * 7.13));
        if (cell.x > 6.5 && cell.x < 7.5 && i > 0) { break; }
        let R = 1.8 + 1.5 * h.z;
        let c = cc + vec3f((h.x - 0.5) * 6.0 + select(-2.6, 2.6, h.x > 0.5), -R * 0.38, (h.y - 0.5) * 5.0);
        var p = w - c;
        let rx = rot2(h.x * 5.0 + h.y * 3.0) * p.xz;
        p = vec3f(rx.x, p.y, rx.y);
        let q = vec2f(length(p.xy) - R, p.z);
        d = min(d, length(q * vec2f(1.0, 0.8)) - 0.1 - 0.04 * h.y);
    }
    return d;
}

fn map(w: vec3f) -> f32 {
    let f = spine_frame(w.xz);
    var d = vertebrae(w, f);
    d = min(d, ribs(w, f));
    d = min(d, skull(w));
    d = min(d, fin(w));
    d = min(d, fluke(w));
    d = min(d, fallen(w));
    return d;
}

fn aur_tint(w: vec3f) -> vec3f {
    return mix(AUR_A, AUR_B, 0.5 + 0.5 * sin(w.x * 0.045 + w.z * 0.03 + time() * 0.12));
}

// Light that pools in the gaps between vertebrae and in the skull's eyes: a pulse runs head to tail as it breathes.
fn glow_at(w: vec3f) -> vec3f {
    let f = spine_frame(w.xz);
    var g = vec3f(0.0);
    if (abs(f.y) < 1.2) {
        let vq = vert_q(w, f);
        let gap = length(vec3f(abs(vq.x) - 0.4, vq.y, vq.z));
        let pulse = 0.25 + 2.2 * pow(0.5 + 0.5 * sin(vq.w * 0.22 + time() * 1.5), 8.0);
        g += aur_tint(w) * exp(-gap * 7.0) * pulse * (0.6 + 0.6 * breath());
    }
    let pe = vec3f(w.x - 106.5, w.y - 2.45, abs(w.z - 12.0) - 1.45);
    g += vec3f(0.25, 1.0, 0.7) * exp(-length(pe) * 3.2) * (0.6 + 0.8 * breath());
    return g;
}

fn calc_normal(p: vec3f) -> vec3f {
    let e = vec2f(0.0025, -0.0025);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn curtains(rd: vec3f) -> vec3f {
    if (rd.y < 0.01) { return vec3f(0.0); }
    var acc = vec3f(0.0);
    let steps = i32(mix(6.0, 14.0, quality()));
    for (var i = 0; i < 18; i = i + 1) {
        if (i >= steps) { break; }
        let fi = f32(i) / f32(steps);
        let h = 0.6 + fi * 0.9;
        let p = rd.xz * (h / rd.y);
        let warp = noise3(vec3f(p * 0.12, time() * 0.05)) * 6.0;
        let band = pow(0.5 + 0.5 * sin(p.x * 0.33 + p.y * 0.12 + warp + time() * 0.15), 6.0);
        let fade = noise3(vec3f(p * 0.4 + vec2f(time() * 0.07, 0.0), fi));
        acc += mix(AUR_A, AUR_B, fi) * band * fade * (1.0 - fi) * (2.9 / f32(steps));
    }
    return acc * smoothstep(0.01, 0.2, rd.y) * (0.8 + 0.3 * breath());
}

fn sky(rd: vec3f) -> vec3f {
    var col = mix(vec3f(0.03, 0.045, 0.1), vec3f(0.003, 0.006, 0.022), clamp(rd.y * 1.5, 0.0, 1.0));
    let q = rd * 160.0;
    let h = hash13(floor(q));
    if (h > 0.995 && rd.y > 0.0) { col += vec3f(0.85) * smoothstep(0.35, 0.0, length(fract(q) - 0.5)) * (0.6 + 0.4 * sin(time() * 2.0 + h * 90.0)); }
    return col + curtains(rd);
}

fn ground(ro: vec3f, rd: vec3f, tg: f32) -> vec3f {
    let w = ro + rd * tg + GOFF;
    let n = fbm3(vec3f(w.xz * 0.35, 0.0));
    var col = vec3f(0.15, 0.18, 0.26) * (0.75 + 0.5 * n);
    col += curtains(reflect(rd, vec3f(0.0, 1.0, 0.0))) * 0.3 * step(tg, 14.0);
    let sp = floor(w.xz * 30.0);
    if (hash12(sp) > 0.993) { col += vec3f(0.7, 0.8, 1.0) * (0.5 + 0.5 * sin(dot(rd, vec3f(31.0, 17.0, 23.0)) + hash12(sp) * 50.0)); }
    let occ = clamp(map(w + vec3f(0.0, 0.3, 0.0)) / 0.3, 0.0, 1.0);
    col *= 0.35 + 0.65 * occ;
    col += glow_at(w + vec3f(0.0, 0.5, 0.0)) * 0.25;
    return mix(col, HORIZON, 1.0 - exp(-tg * 0.02));
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let tg = plane_y(ro, rd, 0.0);
    var tend = tmax;
    if (tg > 0.0) { tend = min(tg, tmax); }
    var t = tmin;
    let steps = i32(mix(36.0, 96.0, quality()));
    var hit = false;
    var glow = vec3f(0.0);
    for (var i = 0; i < 96; i = i + 1) {
        if (i >= steps) { break; }
        let w = ro + rd * t + GOFF;
        let d = map(w);
        glow += glow_at(w) * clamp(d, 0.03, 0.35);
        if (d < 0.0015 * t + 0.002) { hit = true; break; }
        t += d * 0.95;
        if (t > tend) { break; }
    }
    if (hit) {
        let w = ro + rd * t + GOFF;
        let n = calc_normal(w);
        let l = normalize(vec3f(0.35, 1.0, -0.45));
        let dif = clamp(dot(n, l), 0.0, 1.0);
        let ao = clamp(0.35 + 0.65 * map(w + n * 0.22) / 0.22, 0.0, 1.0);
        let tint = aur_tint(w);
        let grain = 0.85 + 0.3 * noise3(w * 6.0);
        let bounce = vec3f(0.42, 0.44, 0.52) * (0.6 - 0.4 * n.y);
        let fill = vec3f(0.3, 0.27, 0.24) * clamp(dot(n, -rd), 0.0, 1.0);
        var col = BONE * grain * (vec3f(0.05, 0.06, 0.09) + dif * vec3f(0.95, 0.86, 0.72) + bounce + fill + tint * (0.05 + 0.08 * max(n.y, 0.0)));
        col *= ao;
        let rim = pow(1.0 - clamp(dot(-rd, n), 0.0, 1.0), 3.0);
        col += tint * rim * 0.12;
        col += glow * 0.6;
        col = mix(col, HORIZON, 1.0 - exp(-t * 0.012));
        return Hit(tone(col * 1.25), t);
    }
    if (tg > 0.0) {
        let gc = ground(ro, rd, tg) + glow * 0.6;
        return Hit(tone(gc * 1.2), min(tg, horizon_t(tmax)));
    }
    return Hit(tone(sky(rd) * 1.2 + glow * 0.6), horizon_t(tmax));
}

shaders.00ae613178f71217eac8bbd82921:
fn jelly_glow(ro: vec3f, rd: vec3f, i: i32, t: f32) -> vec3f {
  let fi = f32(i);
  let h = hash33(vec3f(fi * 7.31, 3.7, 1.9));
  var c = vec3f((h.x - 0.5) * 9.0, 1.4 + h.y * 2.2, (h.z - 0.5) * 9.0);
  c.x += sin(t * 0.13 + fi * 2.1) * 1.4;
  c.z += cos(t * 0.11 + fi * 1.3) * 1.4;
  let pulse = sin(t * 1.4 + fi * 1.7);
  c.y += pulse * 0.25 + sin(t * 0.07 + fi) * 0.5;
  let sc = 0.75 + h.y * 0.5;
  let s0 = max(dot(c - vec3f(0.0, 0.5 * sc, 0.0) - ro, rd), 0.0);
  var acc = vec3f(0.0);
  let hue = fract(0.5 + h.x * 0.45);
  let col = palette(hue, vec3f(0.5), vec3f(0.5), vec3f(1.0), vec3f(0.0, 0.33, 0.67));
  for (var k = 0; k < 3; k++) {
    let s = max(s0 + (f32(k) - 1.0) * 0.35 * sc, 0.0);
    let q = (ro + rd * s - c) / sc;
    let r = length(vec3f(q.x, q.y * 1.6, q.z)) / (1.0 + 0.1 * pulse);
    let shell = exp(-pow(r - 0.5, 2.0) * 70.0) * smoothstep(-0.2, 0.15, q.y) * (1.0 - smoothstep(0.35, 0.55, q.y));
    let core = exp(-r * r * 9.0) * 0.5 * smoothstep(-0.2, 0.1, q.y);
    let rad = length(q.xz);
    let w = sin(q.y * 5.0 - t * 2.0 + fi) * 0.07;
    let ten = exp(-pow(rad - 0.3 - w, 2.0) * 260.0) * smoothstep(-1.9, -0.1, q.y) * (1.0 - smoothstep(-0.15, 0.0, q.y))
              * (0.45 + 0.55 * sin(q.y * 22.0 - t * 3.0));
    let fil = exp(-rad * rad * 700.0) * smoothstep(-2.2, -0.1, q.y) * (1.0 - smoothstep(-0.2, 0.0, q.y)) * 0.8;
    acc += col * (shell * 1.1 + core * 0.9 + ten * 0.35 + fil * 0.3);
    acc += vec3f(0.9, 1.0, 1.0) * shell * 0.15;
  }
  return acc * 0.55;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
  let t = time();
  let up = clamp(rd.y, -1.0, 1.0);
  var col = mix(vec3f(0.0, 0.012, 0.03), vec3f(0.0, 0.05, 0.09), smoothstep(-0.3, 1.0, up));

  if (rd.y > 0.03) {
    let tp = (9.0 - ro.y) / rd.y;
    let p = ro + rd * tp;
    let a = p.x * 0.33 + sin(p.z * 0.21 + t * 0.07) * 1.6 + t * 0.04;
    let b = p.z * 0.27 + cos(p.x * 0.19 - t * 0.05) * 1.4;
    var ray = pow(0.5 + 0.5 * sin(a * 3.0), 3.0) * (0.5 + 0.5 * sin(b * 2.0 + 1.0));
    ray += 0.4 * pow(0.5 + 0.5 * sin(a * 7.0 + b), 4.0);
    col += vec3f(0.05, 0.28, 0.36) * ray * smoothstep(0.03, 0.55, rd.y) * 0.5;
  }
  col += vec3f(0.0, 0.05, 0.07) * pow(max(up, 0.0), 2.0);

  if (rd.y < -0.01) {
    let tf = -ro.y / rd.y;
    let p = ro + rd * tf;
    let n = fbm3(vec3f(p.x * 0.5, 0.0, p.z * 0.5));
    let fog = exp(-tf * 0.09);
    var f = vec3f(0.01, 0.03, 0.04) * (0.4 + n);
    let cell = floor(p.xz * 2.5);
    let hh = hash12(cell);
    let lf = length(fract(p.xz * 2.5) - 0.5);
    let spot = step(0.9, hh) * exp(-lf * lf * 80.0) * (0.5 + 0.5 * sin(t * 1.5 + hh * 60.0));
    f += vec3f(0.1, 0.9, 0.7) * spot * 0.7;
    col = mix(col, f, fog);
  }

  var glow = vec3f(0.0);
  let nj = 4 + i32(quality() * 3.0);
  for (var i = 0; i < nj; i++) { glow += jelly_glow(ro, rd, i, t); }
  col += glow;

  let g = rd * 26.0 + vec3f(0.0, -t * 0.25, t * 0.05) + ro * 0.5;
  let hs = hash33(floor(g));
  let d = length(fract(g) - hs);
  col += vec3f(0.5, 0.8, 0.9) * step(0.8, hs.x) * exp(-d * d * 120.0) * 0.25;

  return Hit(tone(col), horizon_t(tmax));
}

shaders.0b7089432f7d5606c4f6b8461468:
// The Long Clock VI: Orrery Train - part of one machine spanning 8 rooms; all motion derives from one escape wheel.
const GX: f32 = -1.0;
const GY: f32 = -2.0;

var<private> TE: f32;
var<private> TW: f32;
var<private> MAT: i32;
var<private> EID: i32;

fn clock_init() {
    TW = time() - (GX * 7.0 + GY * 13.0);
    let k = floor(TW);
    let fr = TW - k;
    TE = (k + smoothstep(0.0, 0.14, fr)) * TAU / 60.0;
}
fn sd2box(p: vec2f, b: vec2f) -> f32 {
    let q = abs(p) - b;
    return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0);
}
fn ext(d: f32, z: f32, w: f32) -> f32 {
    let e = vec2f(d, abs(z) - w);
    return min(max(e.x, e.y), 0.0) + length(max(e, vec2f(0.0)));
}
fn gear2(q: vec2f, R: f32, N: f32, ang: f32, spokes: f32) -> f32 {
    let m = R / N;
    let r = length(q);
    let a = atan2(q.y, q.x) - ang;
    let seg = TAU / N;
