fn calc_normal(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn light(P: vec3f, n: vec3f, rd: vec3f, base: vec3f, metal: f32) -> vec3f {
    let lp = vec3f(0.0, 4.3, 0.0);
    let lv = lp - P;
    let ld = normalize(lv);
    let att = 3.2 / (1.0 + 0.04 * dot(lv, lv));
    let dif = max(dot(n, ld), 0.0);
    let key = normalize(vec3f(-0.5, 0.9, 0.35));
    let dif2 = max(dot(n, key), 0.0);
    let h = normalize(ld - rd);
    let sp = pow(max(dot(n, h), 0.0), 40.0);
    let fre = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    let amb = 0.22 + 0.12 * n.y;
    var c = base * (amb + dif * att * vec3f(1.0, 0.85, 0.62) + dif2 * 0.35 * vec3f(0.6, 0.7, 0.9));
    c += mix(vec3f(0.25), base * 1.4, metal) * (sp * att * 1.6 + fre * 0.25);
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    clock_init();
    var tend = tmax;
    let tf = plane_y(ro, rd, 0.0);
    let floor_hit = tf >= tmin && tf <= tmax + 0.005;
    if (floor_hit) { tend = tf; }
    let steps = i32(mix(32.0, 80.0, quality()));
    var t = tmin;
    var hit = false;
    for (var i = 0; i < steps; i = i + 1) {
        let d = map(ro + rd * t);
        if (d < 0.0008 + 0.0012 * t) { hit = true; break; }
        t += d * 0.8;
        if (t > tend) { break; }
    }
    if (hit && t <= tmax) {
        let P = ro + rd * t;
        let m = MAT; let eid = EID;
        let n = calc_normal(P);
        let base = matcol(P, m, eid);
        let ao = clamp(map(P + n * 0.12) / 0.12, 0.25, 1.0);
        var metal = 1.0;
        if (m == 5 || m == 6 || m >= 10) { metal = 0.2; }
        var c = light(P, n, rd, base, metal) * ao;
        c = mix(c, vec3f(0.05, 0.035, 0.02), clamp(t / 30.0, 0.0, 0.5));
        return Hit(tone(c * 1.3), t);
    }
    if (floor_hit) {
        let P = ro + rd * tf;
        let W = P + vec3f(GX * 12.0, 0.0, GY * 12.0);
        var c = FLOOR(P, W, rd);
        let occ = clamp(map(P + vec3f(0.0, 0.35, 0.0)) / 0.35, 0.3, 1.0);
        c *= occ;
        return Hit(tone(c * 1.3), min(tf, tmax));
    }
    return no_hit();
}

fn FLOOR(P: vec3f, W: vec3f, rd: vec3f) -> vec3f {
    // dark oak boards running north-south, brass inlay under every line shaft (continuous through rooms)
    let bw = 0.3;
    let bi = floor(W.x / bw);
    let along = W.z + hash12(vec2f(bi, 3.0)) * 7.0;
    let joint = min(abs(fract(W.x / bw) - 0.5), abs(fract(along / 2.4) - 0.5) * 8.0);
    var c = vec3f(0.17, 0.10, 0.06) * (0.75 + 0.5 * hash12(vec2f(bi, floor(along / 2.4))));
    c *= 0.8 + 0.2 * noise3(vec3f(W.x * 30.0, 0.0, W.z * 1.5));
    c *= mix(0.55, 1.0, smoothstep(0.42, 0.47, 0.5 - joint));
    let lx = abs(P.x);
    let lz = abs(P.z);
    if (lx < 0.06 || (lz < 0.06 && ((GX > -0.5 && P.x < 0.0) || (GX < -0.5 && P.x > 0.0) || (GX > -1.5 && GX < -0.5 && GY > -3.5 && GY < -2.5)))) { c = vec3f(0.7, 0.5, 0.22); }
    // engraved dial ring in each room, with 60 ticks; the tick under the second hand lights
    let r = length(P.xz);
    let a = atan2(P.x, -P.z);
    let ring = abs(r - 2.6);
    if (ring < 0.03) { c = vec3f(0.6, 0.42, 0.18); }
    let tk = fract(a / TAU * 60.0 + 0.5) - 0.5;
    if (abs(tk) < 0.07 && r > 2.66 && r < 2.9) {
        let idx = floor(a / TAU * 60.0 + 0.5);
        let sec = floor(TE / TAU * 60.0 + 0.5);
        let on = abs(fract((idx - sec) / 60.0 + 0.5) - 0.5) < 0.005;
        c = select(vec3f(0.55, 0.4, 0.17), vec3f(1.4, 0.9, 0.4), on);
    }
    let l = 3.0 / (1.0 + 0.05 * dot(P - vec3f(0.0, 4.3, 0.0), P - vec3f(0.0, 4.3, 0.0)));
    return c * (0.3 + l);
}

